(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("josephus-war-3-e", [{"sp": "HDR", "t": "Ἱστορία Ἰουδαϊκοῦ πολέμου πρὸς Ῥωμαίους"}, {"sp": "HDR", "t": "Βιβλίον Εʹ", "st": "5"}, {"sp": "N", "t": "Ὁ μὲν Τίτος ὃν προειρήκαμεν τρόπον διοδεύσας τὴν ὑπὲρ Αἰγύπτου μέχρι Συρίας ἐρημίαν εἰς Καισάρειαν παρῆν ταύτῃ διεγνωκὼς προσυντάξασθαι τὰς δυνάμεις. ἔτι δ’ αὐτοῦ κατὰ τὴν Ἀλεξάνδρειαν συγκαθισταμένου τῷ πατρὶ τὴν ἡγεμονίαν νέον αὐτοῖς ἐγκεχειρισμένην ὑπὸ τοῦ θεοῦ συνέβη καὶ τὴν ἐν [τοῖς] Ἱεροσολύμοις στάσιν ἀνακμάσασαν τριμερῆ γενέσθαι καὶ καθ’ αὑτοῦ θάτερον ἐπιστρέψαι μέρος, ὅπερ ἄν τις ὡς ἐν κακοῖς ἀγαθὸν εἴποι καὶ δίκης ἔργον. ἡ μὲν γὰρ κατὰ τοῦ δήμου τῶν ζηλωτῶν ἐπίθεσις, ἥπερ κατῆρξεν ἁλώσεως τῇ πόλει, προδεδήλωται μετὰ ἀκριβείας ὅθεν τε ἔφυ καὶ πρὸς ὅσον κακῶν ηὐξήθη· ταύτην δ’ οὐκ ἂν ἁμάρτοι τις εἰπὼν στάσει στάσιν ἐγγενέσθαι, καὶ καθάπερ θηρίον λυσσῆσαν ἐνδείᾳ τῶν ἔξωθεν ἐπὶ τὰς ἰδίας ἤδη σάρκας ὁρμᾷ,", "st": "5.1.1"}, {"sp": "N", "t": "οὕτως Ἐλεάζαρος ὁ τοῦ Σίμωνος, ὃς δὴ καὶ τὰ πρῶτα τοῦ δήμου τοὺς ζηλωτὰς ἀπέστησεν εἰς τὸ τέμενος ὡς ἀγανακτῶν δῆθεν ἐπὶ τοῖς ὁσημέραι τῷ Ἰωάννῃ τολμωμένοις, οὐ γὰρ ἀνεπαύετο φονῶν οὗτος, τὸ δ’ ἀληθὲς αὑτοῦ μεταγενεστέρῳ τυράννῳ μὴ φέρων ὑποτετάχθαι, πόθῳ τῶν ὅλων καὶ δυναστείας ἰδίας ἐπιθυμίᾳ διίσταται, παραλαβὼν Ἰούδην τε τὸν Χέλικα καὶ Σίμωνα τὸν Ἐσρῶνος τῶν δυνατῶν, πρὸς οἷς Ἐζεκίας Χωβαρεῖ παῖς οὐκ ἄσημος. καθ’ ἕκαστον δὲ οὐκ ὀλίγοι τῶν ζηλωτῶν ἠκολούθησαν, καὶ καταλαβόμενοι τὸν ἐνδότερον τοῦ νεὼ περίβολον ὑπὲρ τὰς ἱερὰς πύλας ἐπὶ τῶν ἁγίων μετώπων τίθενται τὰ ὅπλα. πλήρεις μὲν οὖν ἐπιτηδείων ὄντες ἐθάρρουν, καὶ γὰρ ἀφθονία τῶν ἱερῶν ἐγίνετο πραγμάτων τοῖς γε μηδὲν ἀσεβὲς ἡγουμένοις, ὀλιγότητι δὲ τῇ κατὰ σφᾶς ὀρρωδοῦντες ἐγκαθήμενοι τὰ πολλὰ κατὰ χώραν ἔμενον. ὁ δὲ Ἰωάννης ὅσον ἀνδρῶν ὑπερεῖχε πλήθει, τοσοῦτον ἐλείπετο τῷ τόπῳ καὶ κατὰ κορυφὴν ἔχων τοὺς πολεμίους οὔτ’ ἀδεεῖς ἐποιεῖτο τὰς προσβολὰς οὔτε δι’ ὀργὴν ἠρέμει, κακούμενος δὲ πλέον ἤπερ διατιθεὶς τοὺς περὶ τὸν Ἐλεάζαρον ὅμως οὐκ ἀνίει, συνεχεῖς δ’ ἐκδρομαὶ καὶ βελῶν ἀφέσεις ἐγίνοντο, καὶ φόνοις ἐμιαίνετο πανταχοῦ τὸ ἱερόν.", "st": "5.1.2"}, {"sp": "N", "t": "Ὁ δὲ τοῦ Γιώρα Σίμων, ὃν ἐν ταῖς ἀμηχανίαις ἐπίκλητον αὑτῷ τύραννον ὁ δῆμος ἐλπίδι βοηθείας προσεισήγαγε, τήν τε ἄνω πόλιν ἔχων καὶ τῆς κάτω πολὺ μέρος ἐρρωμενέστερον ἤδη τοῖς περὶ τὸν Ἰωάννην προσέβαλλεν ὡς ἂν καὶ καθύπερθεν πολεμουμένοις· ἦν δ’ ὑπὸ χεῖρα προσιὼν αὐτοῖς, ὥσπερ ἐκεῖνοι τοῖς ἄνωθεν. καὶ τῷ Ἰωάννῃ διχόθεν πολεμουμένῳ συνέβαινε βλάπτεσθαί τε καὶ βλάπτειν εὐκόλως, καὶ καθ’ ὅσον ἡττᾶτο τῶν ἀμφὶ τὸν Ἐλεάζαρον ὢν ταπεινότερος, τοσοῦτον ἐπλεονέκτει τῷ ὑψηλῷ τοῦ Σίμωνος. παρὸ καὶ χειρὶ μὲν τὰς κάτωθεν προσβολὰς ἰσχυρῶς εἶργε, τοὺς δὲ ἄνωθεν ἀπὸ τοῦ ἱεροῦ κατακοντίζοντας ἀνέστελλε τοῖς ὀργάνοις· ὀξυβελεῖς τε γὰρ αὐτῷ καὶ καταπέλται παρῆσαν οὐκ ὀλίγοι καὶ λιθοβόλοι, δι’ ὧν οὐ μόνον ἠμύνετο τοὺς πολεμοῦντας, ἀλλὰ καὶ πολλοὺς τῶν ἱερουργούντων ἀνῄρει. καίπερ γὰρ πρὸς πᾶσαν ἀσέβειαν ἐκλελυσσηκότες, ὅμως τοὺς θύειν ἐθέλοντας εἰσηφίεσαν, μεθ’ ὑποψιῶν μὲν καὶ φυλακῆς τοὺς ἐπιχωρίους, διερευνώμενοι δὲ τοὺς ξένους· οἳ καίπερ περὶ τὰς εἰσόδους δυσωπήσαντες αὐτῶν τὴν ὠμότητα παρανάλωμα τῆς στάσεως ἐγίνοντο. τὰ γὰρ ἀπὸ τῶν ὀργάνων βέλη μέχρι τοῦ βωμοῦ καὶ τοῦ νεὼ διὰ τὴν βίαν ὑπερφερόμενα τοῖς τε ἱερεῦσι καὶ τοῖς ἱερουργοῦσιν ἐνέπιπτε, καὶ πολλοὶ σπεύσαντες ἀπὸ γῆς περάτων περὶ τὸν διώνυμον καὶ πᾶσιν ἀνθρώποις χῶρον ἅγιον πρὸ τῶν θυμάτων ἔπεσον αὐτοὶ καὶ τὸν Ἕλλησι πᾶσι καὶ βαρβάροις σεβάσμιον βωμὸν κατέσπεισαν ἰδίῳ φόνῳ, νεκροῖς δ’ ἐπιχωρίοις ἀλλόφυλοι καὶ ἱερεῦσι βέβηλοι συνεφύροντο, καὶ παντοδαπῶν αἷμα πτωμάτων ἐν τοῖς θείοις περιβόλοις ἐλιμνάζετο. τί τηλικοῦτον, ὦ τλημονεστάτη πόλις, πέπονθας ὑπὸ Ῥωμαίων, οἵ σου τὰ ἐμφύλια μύση πυρὶ καθαροῦντες εἰσῆλθον· θεοῦ μὲν γὰρ οὔτε ἦς ἔτι χῶρος οὔτε μένειν ἐδύνασο, τάφος οἰκείων γενομένη σωμάτων καὶ πολέμου τὸν ναὸν ἐμφυλίου ποιήσασα πολυάνδριον· δύναιο δ’ ἂν γενέσθαι πάλιν ἀμείνων, εἴγε ποτὲ τὸν πορθήσαντα θεὸν ἐξιλάσῃ. ἀλλὰ καθεκτέον γὰρ καὶ τὰ πάθη τῷ νόμῳ τῆς γραφῆς, ὡς οὐκ ὀλοφυρμῶν οἰκείων ὁ καιρός, ἀλλ’ ἀφηγήσεως πραγμάτων. δίειμι δὲ τὰ ἑξῆς ἔργα τῆς στάσεως.", "st": "5.1.3"}, {"sp": "N", "t": "Τριχῇ τῶν ἐπιβούλων τῆς πόλεως διῃρημένων οἱ μὲν περὶ τὸν Ἐλεάζαρον τὰς ἱερὰς ἀπαρχὰς διαφυλάσσοντες κατὰ τοῦ Ἰωάννου τὴν μέθην ἔφερον, οἱ δὲ σὺν τούτῳ διαρπάζοντες τοὺς δημότας ἠγείροντο κατὰ τοῦ Σίμωνος· ἦν δὲ κἀκείνῳ τροφὴ κατὰ τῶν ἀντιστασιαστῶν ἡ πόλις. ὁπότε μὲν οὖν ἀμφοτέρωθεν ἐπιχειροῖτο, τοὺς συνόντας ὁ Ἰωάννης ἀντέστρεφε, καὶ τοὺς μὲν ἐκ τῆς πόλεως ἀνιόντας ἀπὸ τῶν στοῶν βάλλων, τοὺς δ’ ἀπὸ τοῦ ἱεροῦ κατακοντίζοντας ἠμύνετο τοῖς ὀργάνοις· εἰ δ’ ἐλευθερωθείη ποτὲ τῶν καθύπερθεν ἐπικειμένων, διανέπαυε δ’ αὐτοὺς πολλάκις μέθη καὶ κάματος, ἀδεέστερον τοῖς περὶ τὸν Σίμωνα μετὰ πλειόνων ἐπεξέθεεν. ἀεὶ δ’ ἐφ’ ὅσον τρέψαιτο τῆς πόλεως ὑπεπίμπρη τὰς οἰκίας σίτου μεστὰς καὶ παντοδαπῶν ἐπιτηδείων· τὸ δ’ αὐτὸ πάλιν ὑποχωροῦντος ἐπιὼν ὁ Σίμων ἔπραττεν, ὥσπερ ἐπίτηδες Ῥωμαίοις διαφθείροντες ἃ παρεσκευάσατο πρὸς πολιορκίαν ἡ πόλις, καὶ τὰ νεῦρα τῆς αὐτῶν ὑποκόπτοντες δυνάμεως. συνέβη γοῦν τὰ μὲν περὶ τὸ ἱερὸν πάντα συμφλεγῆναι καὶ μεταίχμιον ἐρημίας γενέσθαι παρατάξεως οἰκείας τὴν πόλιν, κατακαῆναι δὲ πλὴν ὀλίγου πάντα τὸν σῖτον, ὃς ἂν αὐτοῖς οὐκ ἐπ’ ὀλίγα διήρκεσεν ἔτη πολιορκουμένοις. λιμῷ γοῦν ἑάλωσαν, ὅπερ ἥκιστα δυνατὸν ἦν, εἰ μὴ τοῦτον αὑτοῖς προπαρεσκεύασαν.", "st": "5.1.4"}, {"sp": "N", "t": "Πανταχόθεν δὲ τῆς πόλεως πολεμουμένης ὑπὸ τῶν ἐπιβούλων καὶ συγκλύδων μέσος ὁ δῆμος ὥσπερ μέγα σῶμα διεσπαράσσετο. γηραιοὶ δὲ καὶ γυναῖκες ὑπ’ ἀμηχανίας τῶν εἴσω κακῶν ηὔχοντο Ῥωμαίοις καὶ τὸν ἔξωθεν πόλεμον ἐπ’ ἐλευθερίᾳ τῶν εἴσω κακῶν ἐκαραδόκουν. κατάπληξις δὲ δεινὴ καὶ δέος ἦν τοῖς γνησίοις, καὶ οὔτε βουλῆς καιρὸς εἰς μεταβολὴν οὔτε συμβάσεως ἐλπὶς οὔτε φυγὴ τοῖς ἐθέλουσιν· ἐφρουρεῖτο γὰρ πάντα, καὶ τὰ λοιπὰ στασιάζοντες οἱ ἀρχιλῃσταὶ τοὺς εἰρηνικὰ Ῥωμαίοις φρονοῦντας ἢ πρὸς αὐτομολίαν ὑπόπτους ὡς κοινοὺς πολεμίους ἀνῄρουν καὶ μόνον ὡμονόουν τὸ φονεύειν τοὺς σωτηρίας ἀξίους. καὶ τῶν μὲν μαχομένων ἀδιάλειπτος ἦν κραυγὴ μεθ’ ἡμέραν τε καὶ νύκτωρ, δεινότεροι δὲ οἱ τῶν πενθούντων ὀδυρμοὶ δέει. καὶ θρήνων μὲν αἰτίας ἐπαλλήλους αἱ συμφοραὶ προσέφερον, τὰς δ’ οἰμωγὰς ἐνέκλειεν ἡ κατάπληξις αὐτῶν, φιμούμενοι δὲ τά γε πάθη τῷ φόβῳ μεμυκόσι τοῖς στεναγμοῖς ἐβασανίζοντο. καὶ οὔτε πρὸς τοὺς ζῶντας ἦν αἰδὼς ἔτι τοῖς προσήκουσιν οὔτε πρόνοια τῶν ἀπολωλότων ταφῆς. αἴτιον δὲ ἀμφοτέρων ἡ καθ’ ἑαυτὸν ἀπόγνωσις ἑκάστου· παρεῖσαν γὰρ εἰς πάντα τὰς προθυμίας οἱ μὴ στασιάζοντες ὡς ἀπολούμενοι πάντως ὅσον οὐδέπω. πατοῦντες δὴ τοὺς νεκροὺς ἐπ’ ἀλλήλοις σεσωρευμένους οἱ στασιασταὶ συνεπλέκοντο καὶ τὴν ἀπόνοιαν ἀπὸ τῶν ἐν ποσὶ πτωμάτων σπῶντες ἦσαν ἀγριώτεροι. προσεξευρίσκοντες δ’ ἀεί τι καθ’ αὑτῶν ὀλέθριον καὶ πᾶν τὸ δοχθὲν ἀφειδῶς δρῶντες οὐδεμίαν οὔτ’ αἰκίας ὁδὸν οὔτε ὠμότητος παρέλειπον. ἀμέλει Ἰωάννης τὴν ἱερὰν ὕλην εἰς πολεμιστηρίων κατασκευὴν ὀργάνων ἀπεχρήσατο· δόξαν γάρ ποτε τῷ λαῷ καὶ τοῖς ἀρχιερεῦσιν ὑποστηρίξαντας τὸν ναὸν εἴκοσι πήχεις προσυψῶσαι, κατάγει μὲν ἀπὸ τοῦ Λιβάνου μεγίστοις ἀναλώμασι καὶ πόνοις τὴν χρήσιμον ὕλην ὁ βασιλεὺς Ἀγρίππας, ξύλα θέας ἄξια τήν τε εὐθύτητα καὶ τὸ μέγεθος· μεσολαβήσαντος δὲ τοῦ πολέμου τὸ ἔργον Ἰωάννης τεμὼν αὐτὰ πύργους κατεσκεύασεν ἐξαρκοῦν τὸ μῆκος εὑρὼν πρὸς τοὺς ἀπὸ τοῦ καθύπερθεν ἱεροῦ μαχομένους, ἵστησί τε προσαγαγὼν κατόπιν τοῦ περιβόλου τῆς πρὸς δύσιν ἐξέδρας ἄντικρυς, ᾗπερ καὶ μόνῃ δυνατὸν ἦν τῶν ἄλλων μερῶν βαθμοῖς πόρρωθεν διειλημμένων.", "st": "5.1.5"}, {"sp": "N", "t": "Καὶ ὁ μὲν τοῖς κατασκευασθεῖσιν ἐξ ἀσεβείας ὀργάνοις κρατήσειν ἤλπισε τῶν ἐχθρῶν, ὁ δὲ θεὸς ἄχρηστον αὐτῷ τὸν πόνον ἀπέδειξε πρὶν ἐπιστῆσαί τινα τῶν πύργων Ῥωμαίους ἐπαγαγών. ὁ γὰρ δὴ Τίτος ἐπειδὴ τὰ μὲν συνήγαγε τῆς δυνάμεως πρὸς αὑτόν, τοῖς δὲ ἐπὶ Ἱεροσολύμων συναντᾶν ἐπέστειλεν, ἐξήλαυνε τῆς Καισαρείας. ἦν δὲ τρία μὲν τὰ πρότερον αὐτοῦ τῷ πατρὶ συνδῃώσαντα τὴν Ἰουδαίαν τάγματα καὶ τὸ πάλαι σὺν Κεστίῳ πταῖσαν δωδέκατον, ὅπερ καὶ ἄλλως ἐπίσημον δι’ ἀνδρείαν ὑπάρχον τότε κατὰ μνήμην ὧν ἔπαθεν εἰς ἄμυναν ᾔει προθυμότερον. τούτων μὲν οὖν τὸ πέμπτον δι’ Ἀμμαοῦς ἐκέλευσεν αὐτῷ συναντᾶν καὶ διὰ Ἱεριχοῦντος τὸ δέκατον ἀναβαίνειν, αὐτὸς δ’ ἀνέζευξε μετὰ τῶν λοιπῶν, πρὸς οἷς αἵ τε τῶν βασιλέων συμμαχίαι πολὺ πλείους καὶ συχνοὶ τῶν ἀπὸ τῆς Συρίας ἐπίκουροι συνῆλθον. ἀνεπληρώθη δὲ καὶ τῶν τεσσάρων ταγμάτων ὅσον Οὐεσπασιανὸς ἐπιλέξας Μουκιανῷ συνέπεμψεν εἰς Ἰταλίαν ἐκ τῶν ἐπελθόντων μετὰ Τίτου. δισχίλιοι μὲν γὰρ αὐτῷ τῶν ἀπ’ Ἀλεξανδρείας στρατευμάτων ἐπίλεκτοι, τρισχίλιοι δὲ συνείποντο τῶν ἀπ’ Εὐφράτου φυλάκων. φίλων δὲ δοκιμώτατος εὔνοιάν τε καὶ σύνεσιν Τιβέριος Ἀλέξανδρος, πρότερον μὲν αὐτοῖς τὴν Αἴγυπτον διέπων, τότε δὲ τῶν στρατευμάτων ἄρχων, κριθεὶς ἄξιος ἐξ ὧν ἐδεξιώσατο πρῶτος ἐγειρομένην ἄρτι τὴν ἡγεμονίαν καὶ μετὰ πίστεως λαμπρᾶς ἐξ ἀδήλου τῇ τύχῃ προσέθετο, σύμβουλός γε μὴν ταῖς τοῦ πολέμου χρείαις ἡλικίᾳ τε προύχων καὶ κατ’ ἐμπειρίαν εἵπετο.", "st": "5.1.6"}, {"sp": "N", "t": "Προϊόντι δὲ εἰς τὴν πολεμίαν Τίτῳ προῆγον μὲν οἱ βασιλικοὶ καὶ πᾶν τὸ συμμαχικόν, ἐφ’ οἷς ὁδοποιοὶ καὶ μετρηταὶ στρατοπέδων, ἔπειτα τὰ τῶν ἡγεμόνων σκευοφόρα καὶ μετὰ τοὺς τούτων ὁπλίτας αὐτὸς τούς τε ἄλλους ἐπιλέκτους καὶ τοὺς λογχοφόρους ἔχων, κατόπιν δ’ αὐτῷ τοῦ τάγματος τὸ ἱππικόν· οὗτοι δὲ πρὸ τῶν μηχανημάτων, κἀπ’ ἐκείνοις μετ’ ἐπιλέκτων χιλίαρχοι καὶ σπειρῶν ἔπαρχοι, μετὰ δὲ τούτους περὶ τὸν αἰετὸν αἱ σημαῖαι, καὶ ἔμπροσθεν οἱ σαλπικταὶ τῶν σημαιῶν, ἐπὶ δὲ τούτοις ἡ φάλαγξ τὸ στῖφος εἰς ἓξ πλατύνασα. τὸ δ’ οἰκετικὸν ἑκάστου τάγματος ὀπίσω καὶ πρὸ τούτων τὰ σκευοφόρα, τελευταῖοι δὲ πάντων οἱ μίσθιοι καὶ τούτων φύλακες οὐραγοί. προάγων δὲ τὴν δύναμιν ἐν κόσμῳ, καθὰ Ῥωμαίοις σύνηθες, ἐμβάλλει διὰ τῆς Σαμαρείτιδος εἰς Γόφνα κατειλημμένην τε πρότερον ὑπὸ τοῦ πατρὸς καὶ τότε φρουρουμένην· ἔνθα μίαν ἑσπέραν αὐλισάμενος ὑπὸ τὴν ἕω πρόεισι, καὶ διανύσας ἡμέρας σταθμὸν στρατοπεδεύεται κατὰ τὸν ὑπὸ Ἰουδαίων πατρίως Ἀκανθῶν αὐλῶνα καλούμενον πρός τινι κώμῃ Γαβὰθ Σαοὺλ λεγομένῃ, σημαίνει δὲ τοῦτο λόφον Σαούλου, διέχων ἀπὸ τῶν Ἱεροσολύμων ὅσον ἀπὸ τριάκοντα σταδίων. ἀναλαβὼν δ’ ἐντεῦθεν ὅσον εἰς ἑξακοσίους τῶν ἐπιλέκτων ἱππέων ᾔει τήν τε πόλιν περισκεψόμενος, ὅπως ὀχυρότητος ἔχοι, καὶ τὰ φρονήματα τῶν Ἰουδαίων, εἰ πρὸς τὴν ὄψιν αὐτοῦ πρὶν εἰς χεῖρας ἐλθεῖν ὑποδείσαντες ἐνδοῖεν· πέπυστο γάρ, ὅπερ ἦν ἀληθές, τοῖς στασιώδεσι καὶ λῃστρικοῖς τὸν δῆμον ὑποπεπτηχότα ποθεῖν μὲν εἰρήνην, ἀσθενέστερον δὲ ὄντα τῆς ἐπαναστάσεως ἠρεμεῖν.", "st": "5.2.1"}, {"sp": "N", "t": "Ἕως μὲν οὖν ὄρθιον ἱππάζετο τὴν λεωφόρον κατατείνουσαν πρὸς τὸ τεῖχος οὐδεὶς προυφαίνετο τῶν πυλῶν, ἐπεὶ δ’ ἐκ τῆς ὁδοῦ πρὸς τὸν Ψήφινον πύργον ἀποκλίνας πλάγιον ἦγε τὸ τῶν ἱππέων στῖφος, προπηδήσαντες ἐξαίφνης ἄπειροι κατὰ τοὺς Γυναικείους καλουμένους πύργους διὰ τῆς ἀντικρὺ τῶν Ἑλένης μνημείων πύλης διεκπαίουσι τῆς ἵππου, καὶ τοὺς μὲν ἔτι κατὰ τὴν ὁδὸν θέοντας ἀντιμέτωποι στάντες ἐκώλυσαν συνάψαι τοῖς ἐκκλίνασι, τὸν δὲ Τίτον ἀποτέμνονται σὺν ὀλίγοις. τῷ δὲ πρόσω μὲν ἦν χωρεῖν ἀδύνατον· ἐκτετάφρευτο γὰρ ἀπὸ τοῦ τείχους περὶ τὰς κηπείας ἅπαντα τοίχοις τε ἐπικαρσίοις καὶ πολλοῖς ἕρκεσι διειλημμένα· τὴν δὲ πρὸς τοὺς σφετέρους ἀναδρομὴν πλήθει τῶν ἐν μέσῳ πολεμίων ἀμήχανον ἑώρα καὶ τραπέντας τοὺς ἀνὰ τὴν λεωφόρον, ὧν οἱ πολλοὶ μηδὲ γινώσκοντες τὸν τοῦ βασιλέως κίνδυνον, ἀλλ’ οἰόμενοι συναναστραφῆναι κἀκεῖνον ἀνέφευγον. ὁ δὲ κατιδὼν ὡς ἐν μόνῃ τῇ καθ’ αὑτὸν ἀλκῇ κεῖται τὸ σώζεσθαι τόν τε ἵππον ἐπιστρέφει καὶ τοῖς περὶ αὐτὸν ἐμβοήσας ἕπεσθαι μέσοις ἐμπηδᾷ τοῖς πολεμίοις διεκπαῖσαι πρὸς τοὺς σφετέρους βιαζόμενος. ἔνθα δὴ μάλιστα παρέστη νοεῖν, ὅτι καὶ πολέμων ῥοπαὶ καὶ βασιλέων κίνδυνοι μέλονται θεῷ· τοσούτων γὰρ ἐπὶ τὸν Τίτον ἀφιεμένων βελῶν μήτε κράνος ἔχοντα μήτε θώρακα, προῆλθε γὰρ ὡς ἔφην οὐ πολεμιστὴς ἀλλὰ κατάσκοπος, οὐδὲν ἥψατο τοῦ σώματος, κενὰ δ’ ὥσπερ ἐπίτηδες ἀστοχούντων παρερροιζεῖτο πάντα. ὁ δὲ ξίφει τοὺς κατὰ πλευρὸν ἀεὶ διαστέλλων καὶ πολλοὺς τῶν ἀντιπροσώπων ἀνατρέπων ἤλαυνεν ὑπὲρ τοὺς ἐρειπομένους τὸν ἵππον. τῶν δὲ κραυγή τε ἦν πρὸς τὸ παράστημα τοῦ Καίσαρος καὶ παρακέλευσις ὁρμᾶν ἐπ’ αὐτόν, φυγὴ δὲ καὶ χωρισμὸς ἄθρους καθ’ οὓς ἐπελαύνων γένοιτο. συνῆπτον δὲ οἱ τοῦ κινδύνου μετέχοντες κατὰ νῶτα καὶ κατὰ πλευρὰν νυσσόμενοι· μία γὰρ ἐλπὶς ἦν σωτηρίας ἑκάστῳ τὸ συνεξανύτειν τῷ Τίτῳ καὶ μὴ φθάσαντα κυκλωθῆναι. δύο γοῦν τῶν ἀπωτέρω τὸν μὲν σὺν τῷ ἵππῳ περισχόντες κατηκόντισαν, θάτερον δὲ καταπηδήσαντα διαφθείραντες τὸν ἵππον ἀπήγαγον, μετὰ δὲ τῶν λοιπῶν Τίτος ἐπὶ τὸ στρατόπεδον διασώζεται. τοῖς μὲν οὖν Ἰουδαίοις πλεονεκτήσασι κατὰ τὴν πρώτην ἐπίθεσιν ἐπήγειρε τὰς διανοίας ἄσκεπτος ἐλπίς, καὶ πολὺ θάρσος αὐτοῖς εἰς τὸ μέλλον ἡ πρόσκαιρος ῥοπὴ προυξένει.", "st": "5.2.2"}, {"sp": "N", "t": "Καῖσαρ δ’ ὡς αὐτῷ συνέμιξε διὰ νυκτὸς τὸ ἀπὸ τῆς Ἀμμαοῦς τάγμα, μεθ’ ἡμέραν ἐκεῖθεν ἄρας ἐπὶ τὸν Σκοπὸν καλούμενον πρόεισιν, ἔνθεν ἥ τε πόλις ἤδη κατεφαίνετο καὶ τὸ τοῦ ναοῦ μέγεθος ἐκλάμπον, καθὰ τῷ βορείῳ κλίματι τῆς πόλεως χθαμαλὸς συνάπτων ὁ χῶρος ἐτύμως Σκοπὸς ὠνόμασται. τῆς δὲ πόλεως σταδίους ἑπτὰ διέχων ἐκέλευσε περιβαλέσθαι στρατόπεδον τοῖς δύο τάγμασιν ὁμοῦ, τὸ δὲ πέμπτον τούτων ὀπίσω τρισὶ σταδίοις· κόπῳ γὰρ τῆς διὰ νυκτὸς πορείας τετρυμένους ἐδόκει σκέπης ἀξίους εἶναι, ὡς ἂν ἀδεέστερον τειχίσαιντο. καταρχομένων δ’ ἄρτι τῆς δομήσεως καὶ τὸ δέκατον τάγμα διὰ Ἱεριχοῦντος ἤδη παρῆν, ἔνθα καθῆστό τις ὁπλιτικὴ μοῖρα φρουροῦσα τὴν ἐμβολὴν ὑπὸ Οὐεσπασιανοῦ προκατειλημμένην. προσετέτακτο δ’ αὐτοῖς ἓξ ἀπέχοντας τῶν Ἱεροσολύμων σταδίους στρατοπεδεύσασθαι κατὰ τὸ Ἐλαιῶν καλούμενον ὄρος, ὃ τῇ πόλει πρὸς ἀνατολὴν ἀντίκειται μέσῃ φάραγγι βαθείᾳ διειργόμενον, ἣ Κεδρὼν ὠνόμασται.", "st": "5.2.3"}, {"sp": "N", "t": "Τῶν δ’ ἀνὰ τὸ ἄστυ συρρηγνυμένων ἀδιαλείπτως τότε πρῶτον ἀνέπαυσεν τὴν ἐπ’ ἀλλήλοις ἔριν ὁ ἔξωθεν πόλεμος ἐξαίφνης πολὺς ἐπελθών· καὶ μετ’ ἐκπλήξεως οἱ στασιασταὶ τοὺς Ῥωμαίους ἀφορῶντες στρατοπεδευομένους τριχῆ κακῆς ὁμονοίας κατήρχοντο καὶ λόγον ἀλλήλοις ἐδίδοσαν, τί μένοιεν ἢ τί παθόντες ἀνέχοιντο τρία ταῖς ἀναπνοαῖς αὐτῶν ἐπιφρασσόμενα τείχη, καὶ τοῦ πολέμου μετ’ ἀδείας ἀντιπολίζοντος ἑαυτόν, οἱ δ’ ὥσπερ θεαταὶ καλῶν καὶ συμφόρων ἔργων καθέζοιντο τειχήρεις τὼ χεῖρε καὶ τὰς πανοπλίας παρέντες; καθ’ αὑτῶν ἄρα γενναῖοι μόνον ἡμεῖς, ἐξεβόησαν, Ῥωμαῖοι δὲ ἐκ τῆς ἡμετέρας στάσεως κερδήσουσιν ἀναιμωτὶ τὴν πόλιν. τούτοις ἀθροίζοντες ἀλλήλους παρεκρότουν, καὶ τὰς πανοπλίας ἁρπάσαντες αἰφνιδίως ἐπεκθέουσι τῷ δεκάτῳ τάγματι καὶ διὰ τῆς φάραγγος ᾄξαντες μετὰ κραυγῆς ἐξαισίου τειχιζομένοις προσπίπτουσι τοῖς πολεμίοις. οἱ δὲ πρὸς τὸ ἔργον διῃρημένοι καὶ διὰ τοῦτο τὰ πολλὰ τεθεικότες τῶν ὅπλων, οὔτε γὰρ θαρρήσειν τοὺς Ἰουδαίους πρὸς ἐκδρομὴν ὑπελάμβανον καὶ προθυμουμένων περισπασθήσεσθαι τὰς ὁρμὰς τῇ στάσει, συνεταράχθησαν ἀδοκήτως, καὶ τῶν ἔργων ἀφέμενοι τινὲς μὲν ἀνεχώρουν εὐθέως, πολλοὶ δ’ ἐπὶ τὰ ὅπλα θέοντες πρὶν ἐπιστραφῆναι πρὸς τοὺς ἐχθροὺς ἐφθάνοντο παιόμενοι. προσεγίνοντο δὲ τοῖς Ἰουδαίοις ἀεὶ πλείους ἐπὶ τῷ κρατεῖν τοὺς πρώτους τεθαρρηκότες, καὶ τῶν ὄντων πολλαπλασίους ἐδόκουν σφίσι τε καὶ τοῖς πολεμίοις δεξιᾷ χρώμενοι τῇ τύχῃ. μάλιστα δὲ τοὺς ἐν ἔθει συντάξεως ὄντας καὶ μετὰ κόσμου καὶ παραγγελμάτων πολεμεῖν εἰδότας ἀταξία φθάσασα θορυβεῖ. διὸ καὶ τότε προληφθέντες οἱ Ῥωμαῖοι ταῖς ἐμβολαῖς εἶκον. καὶ ὁπότε μὲν ἐπιστραφεῖεν οἱ καταλαμβανόμενοι, τοῦ τε δρόμου τοὺς Ἰουδαίους ἐπεῖχον καὶ διὰ τὴν ὁρμὴν ἧττον φυλαττομένους ἐτίτρωσκον, ἀεὶ δὲ πληθυούσης τῆς ἐκδρομῆς μᾶλλον ταραττόμενοι τελευταῖον ἀπὸ τοῦ στρατοπέδου τρέπονται. καὶ δοκεῖ τότε ἂν κινδυνεῦσαι τὸ τάγμα πᾶν, εἰ μὴ Τίτος ἀγγελθὲν αὐτῷ τάχος ἐπεβοήθησε, καὶ πολλὰ ὀνειδίσας εἰς ἀνανδρίαν ἐπιστρέφει μὲν τοὺς φεύγοντας, αὐτὸς δὲ πλαγίοις τοῖς Ἰουδαίοις προσπεσὼν μεθ’ ὧν ἧκεν ἐπιλέκτων συχνοὺς μὲν ἀναιρεῖ, τιτρώσκει δὲ πλείους, τρέπεται δὲ πάντας καὶ συνωθεῖ κατὰ τῆς φάραγγος. οἱ δ’ ἐν τῷ κατάντει πολλὰ κακωθέντες ὡς διεξέπεσον, ἄντικρυς ἐπιστρέφονται καὶ μέσην ἔχοντες τὴν χαράδραν τοῖς Ῥωμαίοις διεμάχοντο. μέχρι μὲν δὴ μέσης ἡμέρας οὕτως ἐπολέμουν, ὀλίγον δ’ ἀπὸ μεσημβρίας ἐκκλίνοντος ἤδη, Τίτος τοὺς μεθ’ αὑτοῦ προσβοηθήσαντας καὶ τοὺς ἀπὸ τῶν σπειρῶν τοῖς ἐκτρέχουσιν ἀντιπαρατάξας τὸ λοιπὸν τάγμα πρὸς τὸν τειχισμὸν ἀνέπεμπεν εἰς τὴν ἀκρώρειαν.", "st": "5.2.4"}, {"sp": "N", "t": "Ἰουδαίοις δὲ τοῦτ’ ἐδόκει φυγή, καὶ τοῦ σκοποῦ κατασείσαντος θοιμάτιον, ὃς αὐτοῖς ἐπὶ τοῦ τείχους καθῆστο, προπηδῶσι πλῆθος ἀκραιφνέστερον μετὰ τοσαύτης ὁρμῆς, ὡς τὸν δρόμον αὐτῶν τοῖς ἀγριωτάτοις εἰκάζειν θηρίοις. ἀμέλει τῶν ἀντιπαραταχθέντων οὐδεὶς ἔμεινεν τὴν συμβολήν, ἀλλ’ ὥσπερ ἐξ ὀργάνου παιόμενοι διέρρηξαν τὴν τάξιν καὶ πρὸς τὸ ὄρος τραπέντες ἀνέφευγον. λείπεται δ’ ἐν μέσῳ τῷ προσάντει Τίτος μετ’ ὀλίγων, καὶ πολλὰ τῶν φίλων παραινούντων, ὅσοι δι’ αἰδῶ τὴν πρὸς τὸν ἡγεμόνα τοῦ κινδύνου καταφρονήσαντες ἔστησαν, εἶξαι θανατῶσιν Ἰουδαίοις καὶ μὴ προκινδυνεύειν τούτων, οὓς ἐχρῆν πρὸ αὐτοῦ μένειν, λαμβάνειν δὲ ἔννοιαν τῆς καθ’ αὑτὸν τύχης καὶ μὴ στρατιώτου τάξιν ἀποπληροῦν ὄντα καὶ τοῦ πολέμου καὶ τῆς οἰκουμένης δεσπότην, μηδ’ ὀξεῖαν οὕτως ὑφίστασθαι ῥοπὴν ἐν ᾧ σαλεύει τὰ πάντα, τούτων οὐδ’ ἀκούειν ἔδοξε, τοῖς δὲ καθ’ αὑτὸν ἀνατρέχουσιν ἀνθίσταται καὶ κατὰ στόμα παίων βιαζομένους ἀνῄρει κατά τε τοῦ πρανοῦς ἀθρόοις ἐμπίπτων ἀνεώθει τὸ πλῆθος. οἱ δὲ πρός τε τὸ παράστημα καὶ τὴν ἰσχὺν καταπλαγέντες οὐδ’ οὕτως μὲν ἀνέφευγον εἰς τὴν πόλιν, καθ’ ἕτερον δ’ ἐκκλίνοντες ἀπ’ αὐτοῦ τοῖς ἀνωτέρω φεύγουσι προσέκειντο. καὶ τούτοις δὲ κατὰ πλευρὰν προσβάλλων τὰς ὁρμὰς ὑπετέμνετο. κἀν τούτῳ καὶ τοῖς ἄνω τειχίζουσι τὸ στρατόπεδον, ὡς ἐθεάσαντο τοὺς κάτω φεύγοντας, πάλιν ἐμπίπτει ταραχὴ καὶ δέος, καὶ διασκίδναται πᾶν τὸ τάγμα, δοκούντων ἀνυπόστατον μὲν εἶναι τὴν τῶν Ἰουδαίων ἐκδρομήν, τετράφθαι δ’ αὐτὸν Τίτον· οὐ γὰρ ἄν ποτε τοὺς ἄλλους φεύγειν ἐκείνου μένοντος. καὶ καθάπερ πανικῷ δείματι κυκλωθέντες ἄλλος ἀλλαχῆ διεφέροντο, μέχρι τινὲς κατιδόντες ἐν μέσῳ τοῦ πολέμου τὸν ἡγεμόνα στρεφόμενον καὶ μέγα δείσαντες ἀμφ’ αὐτῷ διαβοῶσι τὸν κίνδυνον ὅλῳ τῷ τάγματι. τοὺς δ’ αἰδὼς ἐπέστρεφε, καὶ πλεῖόν τι φυγῆς κακίζοντες ἀλλήλους ἐπὶ τῷ καταλιπεῖν Καίσαρα πάσῃ βίᾳ κατὰ τῶν Ἰουδαίων ἐχρῶντο καὶ κλίναντες ἅπαξ ἀπὸ τοῦ κατάντους συνώθουν αὐτοὺς εἰς τὸ κοῖλον. οἱ δ’ ὑπὸ πόδα χωροῦντες ἐμάχοντο, καὶ πλεονεκτοῦντες οἱ Ῥωμαῖοι τῷ καθύπερθεν εἶναι συνελαύνουσι πάντας εἰς τὴν φάραγγα. προσέκειτο δὲ τοῖς καθ’ αὑτὸν ὁ Τίτος καὶ τὸ μὲν τάγμα πάλιν ἐπὶ τὴν τειχοποιίαν ἔπεμψεν, αὐτὸς δὲ σὺν οἷς πρότερον ἀντιστὰς εἶργε τοὺς πολεμίους· ὥστ’, εἰ χρὴ μήτε θεραπείᾳ τι προστιθέντα μήθ’ ὑφελόντα φθόνῳ τἀληθὲς εἰπεῖν, αὐτὸς Καῖσαρ δὶς μὲν ἐρρύσατο κινδυνεῦσαν ὅλον τὸ τάγμα καὶ τοῦ περιβαλέσθαι τὸ στρατόπεδον αὐτοῖς ἄδειαν παρέσχε.", "st": "5.2.5"}, {"sp": "N", "t": "Λωφήσαντος δὲ πρὸς βραχὺ τοῦ θύραζε πολέμου πάλιν τὸν ἔνδον ἡ στάσις ἐπήγειρεν. καὶ τῆς τῶν ἀζύμων ἐνστάσης ἡμέρας τεσσαρεσκαιδεκάτῃ Ξανθικοῦ μηνός, ἐν ᾗ δοκοῦσιν Ἰουδαῖοι τὸν πρῶτον ἀπαλλαγῆναι καιρὸν Αἰγυπτίων, οἱ μὲν περὶ τὸν Ἐλεάζαρον παρανοίγοντες τὰς πύλας ἐδέχοντο ἐκ τοῦ δήμου τοὺς προσκυνεῖν ἐθέλοντας εἴσω, Ἰωάννης δὲ προκάλυμμα τῆς ἐπιβουλῆς ποιησάμενος τὴν ἑορτὴν τῶν σὺν αὐτῷ κρυπτοῖς ὅπλοις ἐνσκευάσας τοὺς ἀσημοτέρους, ὧν οἱ πλείους ἦσαν ἄναγνοι, διὰ σπουδῆς παρεισπέμπει προκαταληψομένους τὸ ἱερόν. οἱ δ’ ὡς ἔνδον ἐγένοντο, τὰς ἐσθῆτας ἀπορρίψαντες ἐφάνησαν ἐξαπίνης ὁπλῖται. ταραχὴ δὲ μεγίστη περὶ τὸν ναὸν αὐτίκα καὶ θόρυβος ἦν, τοῦ μὲν ἔξω τῆς στάσεως λαοῦ κατὰ πάντων ἄκριτον οἰομένων εἶναι τὴν ἐπίθεσιν, τῶν δὲ ζηλωτῶν ἐπὶ σφίσι μόνοις. ἀλλ’ οἱ μὲν ἀφέμενοι τὸ φρουρεῖν ἔτι τὰς πύλας καὶ τῶν ἐπάλξεων καταπηδήσαντες πρὶν εἰς χεῖρας ἐλθεῖν εἰς τοὺς ὑπονόμους τοῦ ἱεροῦ κατέφυγον· οἱ δ’ ἀπὸ τοῦ δήμου πρὸς τῷ βωμῷ καταπτήσσοντες καὶ περὶ τὸν ναὸν συνειλούμενοι κατεπατοῦντο ξύλοις τε ἀνέδην παιόμενοι καὶ σιδήρῳ. πολλοὺς δὲ τῶν ἡσυχίων κατ’ ἔχθραν καὶ μῖσος ἴδιον ὡς ἀντιστασιαστὰς ἀνῄρουν οἱ διάφοροι, καὶ πᾶς ὁ προσκρούσας τῳ τῶν ἐπιβούλων πάλαι τηνικαῦτα ἐπιγνωσθεὶς ὡς ζηλωτὴς πρὸς αἰκίαν ἀνήγετο. πολλὰ δὲ δεινὰ τοὺς ἀναιτίους διαθέντες ἐκεχειρίαν τοῖς αἰτίοις ἔδοσαν, καὶ προελθόντας ἐκ τῶν ὑπονόμων διίεσαν. αὐτοὶ δὲ καὶ τὸ ἐνδότερον ἱερὸν κατασχόντες καὶ τὰς ἐν αὐτῷ παρασκευὰς πάσας κατεθάρρουν ἤδη τοῦ Σίμωνος. ἡ μὲν οὖν στάσις οὕτω τριμερὴς οὖσα πρότερον εἰς δύο μοίρας περιίσταται.", "st": "5.3.1"}, {"sp": "N", "t": "Ὁ δὲ Τίτος ἔγγιον ἀπὸ τοῦ Σκοποῦ τῇ πόλει παραστρατοπεδεύσασθαι προαιρούμενος πρὸς μὲν τοὺς ἐκτρέχοντας ἔστησεν ἐπιλέξας ἱππέων τε καὶ πεζῶν ὅσους ἀρκέσειν ὑπελάμβανεν, τῇ δ’ ὅλῃ δυνάμει προσέταξεν ἐξομαλίζειν τὸ μέχρι τοῦ τείχους διάστημα. καταβληθέντος δὲ παντὸς ἕρκους καὶ περιφράγματος, ὅσα κήπων προανεστήσαντο καὶ δένδρων οἱ οἰκήτορες, ὕλης τε ἡμέρου τῆς μεταξὺ πάσης ἐκκοπείσης ἀνεπλήσθη μὲν τὰ κοῖλα καὶ χαραδρώδη τοῦ τόπου, τὰς δὲ πετρώδεις ἐξοχὰς σιδήρῳ κατεργαζόμενοι χθαμαλὸν ἐποίουν πάντα τὸν τόπον ἀπὸ τοῦ Σκοποῦ μέχρι τῶν Ἡρώδου μνημείων, ἃ προσέχει τῇ τῶν ὄφεων ἐπικαλουμένῃ κολυμβήθρᾳ.", "st": "5.3.2"}, {"sp": "N", "t": "Καὶ κατὰ ταύτας τὰς ἡμέρας ἐνέδραν οἱ Ἰουδαῖοι κατὰ τῶν Ῥωμαίων συσκευάζονται τοιάνδε. τῶν στασιαστῶν οἱ τολμηροὶ προελθόντες ἔξω τῶν Γυναικείων καλουμένων πύργων, ὡς ἐκβεβλημένοι δῆθεν ὑπὸ τῶν εἰρηνικὰ φρονούντων καὶ δεδοικότες τὴν τῶν Ῥωμαίων ἔφοδον ἀνειλοῦντο καὶ παρ’ ἀλλήλους ὑπέπτησσον. οἱ δὲ διαστάντες ἐπὶ τοῦ τείχους δῆμος εἶναι δοκῶν εἰρήνην ἐβόων καὶ δεξιὰν ᾐτοῦντο καὶ τοὺς Ῥωμαίους ἐκάλουν ἀνοίξειν ὑπισχνούμενοι τὰς πύλας· ἅμα δὲ ταῦτα κεκραγότες καὶ τοὺς σφετέρους ἔβαλλον λίθοις ὡς ἀπελαύνοντες τῶν πυλῶν. κἀκεῖνοι βιάζεσθαι τὰς εἰσόδους ὑπεκρίνοντο καὶ τοὺς ἔνδον ἱκετεύειν, συνεχῶς τε πρὸς τοὺς Ῥωμαίους ὁρμήσαντας ἐπιστρεφόμενοι ταραττομένοις προσεῴκεισαν. παρὰ μὲν οὖν τοῖς στρατιώταις τὸ πανοῦργον αὐτῶν οὐκ ἐλείπετο πίστεως, ἀλλ’ ὡς τοὺς μὲν ἐν χερσὶν ἔχοντες ἑτοίμους πρὸς τιμωρίαν, τοὺς δὲ ἀνοίξειν τὴν πόλιν ἐλπίζοντες ἐχώρουν ἐπὶ τὴν πρᾶξιν. Τίτῳ δὲ δι’ ὑποψίας ἦν τὸ τῆς ἐπικλήσεως παράλογον· καὶ γὰρ πρὸ μιᾶς ἡμέρας προκαλούμενος αὐτοὺς ἐπὶ συμβάσεις διὰ τοῦ Ἰωσήπου μέτριον οὐδὲν εὕρισκε· καὶ τότε τοὺς στρατιώτας κατὰ χώραν μένειν ἐκέλευσεν. ἔφθασαν δέ τινες τῶν ἐπὶ τοῖς ἔργοις προτεταγμένων ἁρπάσαντες τὰ ὅπλα πρὸς τὰς πύλας ἐκδραμεῖν. τούτοις οἱ μὲν ἐκβεβλῆσθαι δοκοῦντες τὸ πρῶτον ὑπεχώρουν, ἐπεὶ δὲ μεταξὺ τῶν τῆς πύλης ἐγίνοντο πύργων, ἐκθέοντες ἐκυκλοῦντό σφας καὶ προσέκειντο κατόπιν· οἱ δ’ ἀπὸ τοῦ τείχους πλῆθος χερμάδων καὶ βελῶν παντοίων ἄθρουν κατέχεαν, ὡς συχνοὺς μὲν ἀνελεῖν, τρῶσαι δὲ πλείστους. ἦν γὰρ οὐ ῥᾴδιον τοῦ τείχους διαφυγεῖν τῶν κατόπιν βιαζομένων, καὶ ἄλλως αἰδὼς τῆς διαμαρτίας καὶ τῶν ἡγεμόνων δέος παρεκελεύετο τῷ πταίσματι προσλιπαρεῖν. διὸ δὴ μέχρι πλείστου διαδορατιζόμενοι καὶ πολλὰς ὑπὸ τῶν Ἰουδαίων λαμβάνοντες πληγάς, ἀμέλει δ’ οὐκ ἐλάττους ἀντιδιδόντες, τέλος ἀνωθοῦσι τοὺς κυκλωσαμένους· ὑποχωροῦσι δ’ αὐτοῖς οἱ Ἰουδαῖοι καὶ μέχρι τῶν Ἑλένης μνημείων εἵποντο βάλλοντες.", "st": "5.3.3"}, {"sp": "N", "t": "Ἔπειθ’ οἱ μὲν ἀπειροκάλως ἐξυβρίζοντες εἰς τὴν τύχην ἔσκωπτόν τε τοὺς Ῥωμαίους δελεασθέντας ἀπάτῃ καὶ τοὺς θυρεοὺς ἀνασείοντες ἐσκίρτων καὶ μετὰ χαρᾶς ἀνεβόων. τοὺς δὲ στρατιώτας ἀπειλή τε τῶν ταξιάρχων καὶ χαλεπαίνων Καῖσαρ τούτοις ἐξεδέχετο, φάσκων ὡς Ἰουδαῖοι μέν, οἷς ἀπόνοια μόνη στρατηγεῖ, πάντα μετὰ προνοίας πράττουσι καὶ σκέψεως ἐπιβουλάς τε συντάσσοντες καὶ λόχους, ἕπεται δ’ αὐτῶν ταῖς ἐνέδραις καὶ τύχη διὰ τὸ πειθήνιον καὶ τὴν πρὸς ἀλλήλους εὔνοιάν τε καὶ πίστιν· Ῥωμαῖοι δέ, οἷς δι’ εὐταξίαν καὶ τὸ πρὸς τοὺς ἡγεμόνας εὐπειθὲς ἀεὶ δουλεύει καὶ τύχη, νῦν ὑπὸ τῶν ἐναντίων πταίουσι καὶ διὰ χειρῶν ἀκρασίαν ἁλίσκονται, τὸ πάντων αἴσχιστον, ἀστρατήγητοι μαχόμενοι παρόντος Καίσαρος. ἦ μεγάλα μὲν στενάξειν ἔφη τοὺς τῆς στρατείας νόμους, μεγάλα δὲ αὐτοῦ τὸν πατέρα τήνδε τὴν πληγὴν πυθόμενον, εἴ γε ὁ μὲν ἐν πολέμοις γηράσας οὐδέποτ’ ἔπταισεν οὕτως, οἱ νόμοι δ’ ἀεὶ καὶ τοὺς βραχύ τι τῆς τάξεως παρακινήσαντας θανάτῳ κολάζουσιν, νῦν δ’ ὅλην στρατιὰν ἑωράκασι λιποτάκτην. γνώσεσθαί γε μὴν αὐτίκα τοὺς ἀπαυθαδισαμένους, ὅτι καὶ τὸ νικᾶν παρὰ Ῥωμαίοις δίχα παραγγέλματος ἀδοξεῖται. τοιαῦτα διατεινάμενος πρὸς τοὺς ἡγεμόνας δῆλος ἦν κατὰ πάντων χρήσεσθαι τῷ νόμῳ. καὶ οἱ μὲν παρεῖσαν τὰς ψυχὰς ὡς ὅσον οὔπω τεθνηξόμενοι δικαίως, περιχυθέντα δὲ τὰ τάγματα τῷ Τίτῳ περὶ τῶν συστρατιωτῶν ἱκέτευε καὶ τὴν ὀλίγων προπέτειαν χαρίσασθαι τῇ πάντων εὐπειθείᾳ κατηντιβόλουν· ἀναλήψεσθαι γὰρ τὸ παρὸν πταῖσμα ταῖς εἰς τὸ μέλλον ἀρεταῖς.", "st": "5.3.4"}, {"sp": "N", "t": "Πείθεται Καῖσαρ ἅμα ταῖς τε ἱκεσίαις καὶ τῷ συμφέροντι· τὴν μὲν γὰρ καθ’ ἑνὸς τιμωρίαν ᾤετο χρῆναι μέχρις ἔργου προκόπτειν, τὴν δ’ ἐπὶ πλήθους μέχρι λόγου. τοῖς μὲν οὖν στρατιώταις διηλλάττετο πολλὰ νουθετήσας αὖθις εἶναι φρονιμωτέρους, αὐτὸς δ’ ὅπως ἀμυνεῖται τὴν Ἰουδαίων ἐπιβουλὴν ἐσκόπει. τέσσαρσι δ’ ἡμέραις ἐξισωθέντος τοῦ μέχρι τῶν τειχῶν διαστήματος, βουλόμενος μετὰ ἀσφαλείας τάς τε ἀποσκευὰς καὶ τὸ λοιπὸν πλῆθος παράγειν τὸ καρτερώτατον τῆς δυνάμεως ἀντιπαρεξέτεινεν τῷ τείχει κατὰ τὸ βόρειον κλίμα καὶ πρὸς ἑσπέραν ἐφ’ ἑπτὰ βαθύνας τὴν φάλαγγα, τῶν τε πεζῶν προτεταγμένων καὶ κατόπιν τῶν ἱππέων, τριστοίχων ἑκατέρων, ἕβδομοι κατὰ μέσον εἱστήκεσαν οἱ τοξόται. τοσούτῳ δὲ στίφει πεφραγμένων Ἰουδαίοις τῶν ἐκδρομῶν τά τε ὑποζύγια τῶν τριῶν ταγμάτων καὶ ἡ πληθὺς ἀδεῶς παρώδευσεν. αὐτὸς μὲν οὖν Τίτος ἀπέχων ὅσον εἰς σταδίους δύο τοῦ τείχους κατὰ τὸ γωνιαῖον αὐτοῦ μέρος ἀντικρὺ τοῦ καλουμένου Ψηφίνου πύργου στρατοπεδεύεται, πρὸς ὃν ὁ κύκλος τοῦ τείχους ἀπ’ ἄρκτων καθήκων ἀνακάμπτει πρὸς δύσιν· ἡ δ’ ἑτέρα μοῖρα τῆς στρατιᾶς κατὰ τὸν Ἱππικὸν προσαγορευθέντα πύργον τειχίζεται διεστῶσα τῆς πόλεως ὁμοίως δύο σταδίους. τὸ μέντοι δέκατον τάγμα κατὰ χώραν ἐπὶ τοῦ Ἐλαιῶν ὄρους ἔμενε.", "st": "5.3.5"}, {"sp": "N", "t": "Τρισὶ δ’ ὠχυρωμένη τείχεσιν ἡ πόλις καθ’ ἣν μὴ ταῖς ἀβάτοις φάραγξι κεκύκλωτο, ταύτῃ γὰρ εἷς ἦν περίβολος, αὐτὴ μὲν ὑπὲρ δύο λόφων ἀντιπρόσωπος ἔκτιστο μέσῃ φάραγγι διῃρημένων, εἰς ἣν ἐπάλληλοι κατέληγον αἱ οἰκίαι. τῶν δὲ λόφων ὁ μὲν τὴν ἄνω πόλιν ἔχων ὑψηλότερός τε πολλῷ καὶ τὸ μῆκος ἰθύτερος ἦν· διὰ γοῦν τὴν ὀχυρότητα φρούριον μὲν ὑπὸ Δαυίδου τοῦ βασιλέως ἐκαλεῖτο, πατὴρ Σολομῶνος ἦν οὗτος τοῦ τὸν πρῶτον ναὸν κτίσαντος, ἡ ἄνω δὲ ἀγορὰ πρὸς ἡμῶν· ἅτερος δὲ ὁ καλούμενος Ἄκρα καὶ τὴν κάτω πόλιν ὑφεστὼς ἀμφίκυρτος. τούτου δ’ ἄντικρυς τρίτος ἦν λόφος, ταπεινότερός τε φύσει τῆς Ἄκρας καὶ πλατείᾳ φάραγγι διειργόμενος ἄλλῃ πρότερον. αὖθίς γε μὴν καθ’ οὓς οἱ Ἀσαμωναῖοι χρόνους ἐβασίλευον τήν τε φάραγγα ἔχωσαν συνάψαι βουλόμενοι τῷ ἱερῷ τὴν πόλιν καὶ τῆς Ἄκρας κατεργασάμενοι τὸ ὕψος ἐποίησαν χθαμαλώτερον, ὡς ὑπερφαίνοιτο καὶ ταύτῃ τὸ ἱερόν. ἡ δὲ τῶν τυροποιῶν προσαγορευομένη φάραγξ, ἣν ἔφαμεν τόν τε τῆς ἄνω πόλεως καὶ τὸν κάτω λόφον διαστέλλειν, καθήκει μέχρι Σιλωᾶς· οὕτω γὰρ τὴν πηγὴν γλυκεῖάν τε καὶ πολλὴν οὖσαν ἐκαλοῦμεν. ἔξωθεν δ’ οἱ τῆς πόλεως δύο λόφοι βαθείαις φάραγξιν περιείχοντο, καὶ διὰ τοὺς ἑκατέρωθεν κρημνοὺς προσιτὸν οὐδαμόθεν ἦν.", "st": "5.4.1"}, {"sp": "N", "t": "Τῶν δὲ τριῶν τειχῶν τὸ μὲν ἀρχαῖον διά τε τὰς φάραγγας καὶ τὸν ὑπὲρ τούτων λόφον, ἐφ’ οὗ κατεσκεύαστο, δυσάλωτον ἦν· πρὸς δὲ τῷ πλεονεκτήματι τοῦ τόπου καὶ καρτερῶς ἐδεδόμητο, Δαυίδου τε καὶ Σολομῶνος, ἔτι δὲ τῶν μεταξὺ τούτων βασιλέων φιλοτιμηθέντων περὶ τὸ ἔργον. ἀρχόμενον δὲ κατὰ βορρᾶν ἀπὸ τοῦ Ἱππικοῦ καλουμένου πύργου καὶ διατεῖνον ἐπὶ τὸν ξυστόν, ἔπειτα τῇ βουλῇ συνάπτον ἐπὶ τὴν ἑσπέριον τοῦ ἱεροῦ στοὰν ἀπηρτίζετο. κατὰ θάτερα δὲ πρὸς δύσιν, ἀπὸ ταὐτοῦ μὲν ἀρχόμενον, διὰ δὲ τοῦ Βησοῦ καλουμένου χώρου κατατεῖνον ἐπὶ τὴν Ἐσσηνῶν πύλην, κἄπειτα πρὸς νότον ὑπὲρ τὴν Σιλωὰν ἐπιστρέφον πηγήν, ἔνθεν τε πάλιν ἐκκλίνον πρὸς ἀνατολὴν ἐπὶ τὴν Σολομῶνος κολυμβήθραν καὶ διῆκον μέχρι χώρου τινός, ὃν καλοῦσιν Ὀφλάς, τῇ πρὸς ἀνατολὴν στοᾷ τοῦ ἱεροῦ συνῆπτε. τὸ δὲ δεύτερον τὴν μὲν ἀρχὴν ἀπὸ πύλης εἶχεν, ἣν Γενὰθ ἐκάλουν τοῦ πρώτου τείχους οὖσαν, κυκλούμενον δὲ τὸ προσάρκτιον κλίμα μόνον ἀνῄει μέχρι τῆς Ἀντωνίας. τῷ τρίτῳ δ’ ἀρχὴ ἦν ὁ Ἱππικὸς πύργος, ὅθεν μέχρι τοῦ βορείου κλίματος κατατεῖνον ἐπὶ τὸν Ψήφινον πύργον, ἔπειτα καθῆκον ἀντικρὺ τῶν Ἑλένης μνημείων, Ἀδιαβηνὴ βασιλὶς ἦν αὕτη Ἰζάτου βασιλέως θυγάτηρ, καὶ διὰ σπηλαίων βασιλικῶν μηκυνόμενον ἐκάμπτετο μὲν γωνιαίῳ πύργῳ κατὰ τὸ τοῦ Γναφέως προσαγορευόμενον μνῆμα, τῷ δ’ ἀρχαίῳ περιβόλῳ συνάπτον εἰς τὴν Κεδρῶνα καλουμένην φάραγγα κατέληγεν. τοῦτο τῇ προσκτισθείσῃ πόλει περιέθηκεν Ἀγρίππας, ἥπερ ἦν πᾶσα γυμνή· πλήθει γὰρ ὑπερχεομένη κατὰ μικρὸν ἐξεῖρπε τῶν περιβόλων. καὶ τοῦ ἱεροῦ τὰ προσάρκτια πρὸς τῷ λόφῳ συμπολίζοντες ἐπ’ οὐκ ὀλίγον προῆλθον καὶ τέταρτον περιοικηθῆναι λόφον, ὃς καλεῖται Βεζεθά, κείμενος μὲν ἀντικρὺ τῆς Ἀντωνίας, ἀποτεμνόμενος δὲ ὀρύγματι βαθεῖ· διεταφρεύθη γὰρ ἐπίτηδες, ὡς μὴ τῷ λόφῳ συνάπτοντες οἱ θεμέλιοι τῆς Ἀντωνίας εὐπρόσιτοί τε εἶεν καὶ ἧττον ὑψηλοί· διὸ δὴ καὶ πλεῖστον ὕψος τοῖς πύργοις προσεδίδου τὸ βάθος τῆς τάφρου. ἐκλήθη δ’ ἐπιχωρίως Βεζεθὰ τὸ νεόκτιστον μέρος, ὃ μεθερμηνευόμενον Ἑλλάδι γλώσσῃ καινὴ λέγοιτ’ ἂν πόλις. δεομένων οὖν τῶν ταύτῃ σκέπης ὁ πατὴρ τοῦ νῦν βασιλέως καὶ ὁμώνυμος Ἀγρίππας ἄρχεται μὲν οὗ προείπομεν τείχους, δείσας δὲ Κλαύδιον Καίσαρα, μὴ τὸ μέγεθος τῆς κατασκευῆς ἐπὶ νεωτερισμῷ πραγμάτων ὑπονοήσῃ καὶ στάσεως, παύεται θεμελίους μόνον βαλόμενος. καὶ γὰρ οὐδ’ ἂν ἦν ἁλώσιμος ἡ πόλις, εἰ προύκοπτε τὸ τεῖχος ὡς ἤρξατο· λίθοις μὲν γὰρ εἰκοσαπήχεσι τὸ μῆκος καὶ τὸ εὖρος δεκαπήχεσι συνηρμόζετο μήθ’ ὑπορυγῆναι σιδήρῳ ῥᾳδίως μήθ’ ὑπ’ ὀργάνοις διασεισθῆναι δυνάμενον, δέκα δὲ πήχεις αὐτῷ καὶ τὸ τεῖχος ἐπλατύνετο, καὶ τὸ ὕψος πλεῖον μὲν ἄν, ὡς εἰκός, ἔσχε μὴ διακωλυθείσης τῆς τοῦ καταρξαμένου φιλοτιμίας. αὖθις δὲ καίτοι μετὰ σπουδῆς ἐγειρόμενον ὑπὸ Ἰουδαίων εἰς εἴκοσι πήχεις ἀνέστη, καὶ διπήχεις μὲν τὰς ἐπάλξεις, τριπήχεις δὲ τοὺς προμαχῶνας εἶχεν, ὡς τὸ πᾶν ὕψος εἰς εἰκοσιπέντε πήχεις ἀνατετάσθαι.", "st": "5.4.2"}, {"sp": "N", "t": "Τοῦ δὲ τείχους ὑπερεῖχον οἱ πύργοι πήχεις εἴκοσι μὲν εἰς εὖρος, εἴκοσι δὲ εἰς ὕψος, τετράγωνοί τε καὶ πλήρεις ὥσπερ αὐτὸ τὸ τεῖχος ὄντες· ἥ γε μὴν ἁρμονία καὶ τὸ κάλλος τῶν λίθων οὐδὲν ἀπέδει ναοῦ. μετὰ δὲ τὸ ναστὸν ὕψος τῶν πύργων, ὅπερ ἦν εἰκοσάπηχυ, πολυτελεῖς ἦσαν οἶκοι, καὶ καθύπερθεν ὑπερῷα, δεξαμεναί τε πρὸς τὰς τῶν ὑετῶν ὑποδοχάς, ἕλικές τε καὶ πλατεῖαι καθ’ ἕκαστον ἄνοδοι. τοιούτους μὲν οὖν πύργους τὸ τρίτον τεῖχος εἶχεν ἐνενήκοντα, τὰ μεταπύργια δὲ τούτων ἀνὰ πήχεις διακοσίους· τὸ δ’ αὖ μέσον εἰς τέσσαρας καὶ δέκα πύργους, τὸ δ’ ἀρχαῖον εἰς ἑξήκοντα μεμέριστο. τῆς πόλεως δ’ ὁ πᾶς κύκλος σταδίων ἦν τριακοντατριῶν. θαυμασίου δ’ ὄντος ὅλου τοῦ τρίτου τείχους θαυμασιώτερος ἀνεῖχε κατὰ γωνίαν βόρειός τε καὶ πρὸς δύσιν ὁ Ψήφινος πύργος, καθ’ ὃν ἐστρατοπεδεύσατο Τίτος. ἐπὶ γὰρ ἑβδομήκοντα πήχεις ὑψηλὸς ὢν Ἀραβίαν τε ἀνίσχοντος ἡλίου παρεῖχεν ἀφορᾶν καὶ μέχρι θαλάττης τὰ τῆς Ἑβραίων κληρουχίας ἔσχατα· ὀκτάγωνος δὲ ἦν. τούτου δ’ ἄντικρυς ὁ Ἱππικὸς καὶ παρ’ αὐτὸν δύο κατεσκευάσθησαν μὲν ὑφ’ Ἡρώδου βασιλέως ἐν τῷ ἀρχαίῳ τείχει, μέγεθος δὲ καὶ κάλλος ἦσαν καὶ ὀχυρότητα τῶν κατὰ τὴν οἰκουμένην διάφοροι· πρὸς γὰρ τῷ φύσει μεγαλοψύχῳ καὶ τῇ περὶ τὴν πόλιν φιλοτιμίᾳ τὴν ὑπεροχὴν τῶν ἔργων ὁ βασιλεὺς πάθεσιν οἰκείοις ἐχαρίζετο καὶ τρισὶ τοῖς ἡδίστοις προσώποις, ἀφ’ ὧν ὠνόμασε τοὺς πύργους, ἀδελφῷ καὶ φίλῳ καὶ γυναικί, τὴν μνήμην ἀνέθηκε, τὴν μὲν ὡς προειρήκαμεν κτείνας δι’ ἔρωτα, τοὺς δὲ ἀποβαλὼν ἐν πολέμῳ γενναίως ἀγωνισαμένους. ὁ μὲν οὖν Ἱππικὸς ἀπὸ τοῦ φίλου προσαγορευθεὶς τετράγωνος μὲν ἦν, εὖρος δὲ καὶ μῆκος εἰκοσιπέντε πηχῶν ἕκαστον καὶ ὕψος τριάκοντα, οὐδαμοῦ διάκενος. ὑπὲρ δὲ τὸ πλῆρες καὶ ταῖς πέτραις συνηνωμένον εἰς ἐκδοχὴν ὄμβρων εἰκοσάπηχυς λάκκος ἦν τὸ βάθος, ἐπάνω δὲ τούτου δίστεγος οἶκος ἦν εἴκοσι καὶ πέντε πηχῶν τὸ ὕψος εἰς ποικίλα τέγη διῃρημένος, ὑπὲρ ὃν τύρσεις μὲν διπήχεις προμαχῶνες δὲ περιβέβληντο τριπήχεις, ὡς τὸ πᾶν ὕψος εἰς ὀγδοήκοντα πήχεις συναριθμεῖσθαι. ὁ δὲ δεύτερος πύργος, ὃν ὠνόμασεν ἀπὸ τἀδελφοῦ Φασάηλον, τὸ μὲν πλάτος καὶ τὸ μῆκος ἴσον εἶχεν, τεσσαράκοντα πηχῶν ἕκαστον, ἐπὶ τεσσαράκοντα δ’ αὐτοῦ τὸ ναστὸν ἦν ὕψος. ἐπάνω δὲ αὐτοῦ περιῄει στοὰ δεκάπηχυς τὸ ὕψος θωρακίοις τε καὶ προβόλοις σκεπομένη. μέσην δὲ ὑπερῳκοδόμητο τὴν στοὰν πύργος ἕτερος εἴς τε οἴκους πολυτελεῖς καὶ δὴ καὶ βαλανεῖον διῃρημένος, ὡς μηδὲν ἐνδέοι τῷ πύργῳ βασίλειον δοκεῖν. τὰ δ’ ἄκρα τοῖς προμαχῶσι καὶ ταῖς τύρσεσιν † ἡ περιαυτοῦ κεκόσμητο. πηχῶν δ’ ἦν τὸ πᾶν ὕψος ὡς ἐνενήκοντα, καὶ τὸ μὲν σχῆμα παρεῴκει τῷ κατὰ τὴν Φάρον ἐκπυρσεύοντι τοῖς ἐπὶ Ἀλεξανδρείας πλέουσι, τῇ περιοχῇ δὲ πολὺ μείζων ἦν· τηνικαῦτά γε μὴν τυραννεῖον ἀπεδείχθη τοῦ Σίμωνος. ὁ δὲ τρίτος πύργος ἡ Μαριάμμη, τοῦτο γὰρ ἡ βασιλὶς ἐκαλεῖτο, μέχρι μὲν εἴκοσι πηχῶν ναστὸς ἦν, εἴκοσι δὲ πήχεις εἰς εὖρος διέβαινε καὶ μῆκος ἴσον, πολυτελεστέραν δὲ καὶ ποικιλωτέραν τῶν ἄλλων τὴν οἴκησιν εἶχεν ἐπάνω, τοῦ βασιλέως οἰκεῖον ὑπολαβόντος τὸν ἀπὸ γυναικὸς ὀνομασθέντα κεκοσμῆσθαι πλέον ἢ τοὺς ἀπ’ ἀνδρῶν, ὥσπερ ἐκείνους τοῦ τῆς γυναικὸς ἰσχυροτέρους. τούτου τὸ πᾶν ὕψος πεντήκοντα καὶ πέντε πηχῶν ἦν.", "st": "5.4.3"}, {"sp": "N", "t": "Τηλικοῦτοι δ’ ὄντες οἱ τρεῖς τὸ μέγεθος πολὺ μείζονες ἐφαίνοντο διὰ τὸν τόπον· αὐτό τε γὰρ τὸ ἀρχαῖον τεῖχος, ἐν ᾧ ἦσαν, ἐφ’ ὑψηλῷ λόφῳ δεδόμητο, καὶ τοῦ λόφου καθάπερ κορυφή τις ὑψηλοτέρα προανεῖχεν εἰς τριάκοντα πήχεις, ὑπὲρ ἣν οἱ πύργοι κείμενοι πολὺ δή τι τοῦ μετεώρου προσελάμβανον. θαυμάσιον δὲ καὶ τῶν λίθων ἦν τὸ μέγεθος· οὐ γὰρ ἐξ εἰκαίας χερμάδος οὐδὲ φορητῶν ἀνθρώποις πετρῶν συνειστήκεσαν, λευκὴ δὲ μάρμαρος ἐτμήθη· καὶ τὸ μὲν μῆκος ἑκάστης πηχῶν ἦν εἴκοσι, δέκα δὲ εὖρος καὶ βάθος πέντε, συνήνωντο δ’ ἐπ’ ἀλλήλοις ὡς δοκεῖν ἕκαστον πύργον μίαν εἶναι πέτραν ἀναπεφυκυῖαν, ἔπειτα δὲ περιεξέσθαι χερσὶ τεχνιτῶν εἰς σχῆμα καὶ γωνίας· οὕτως οὐδαμόθεν ἡ συνάφεια τῆς ἁρμονίας διεφαίνετο. κειμένοις δὲ πρὸς ἄρκτον αὐτοῖς ἔνδοθεν ἡ τοῦ βασιλέως αὐλὴ προσέζευκτο, παντὸς λόγου κρείσσων· οὔτε γὰρ πολυτελείας οὔτε κατασκευῆς τινος ἔλειπεν ὑπερβολήν, ἀλλὰ τετείχιστο μὲν ἅπασα τριάκοντα πήχεις τὸ ὕψος κύκλῳ κατ’ ἴσον διάστημα, κεκοσμημένοις δὲ πύργοις διείληπτο ἀνδρῶσί τε μεγίστοις καὶ εἰς ξενῶνας ἑκατοντακλίνους· ἐν οἷς ἀδιήγητος μὲν ἡ ποικιλία τῶν λίθων ἦν, συνῆκτο γὰρ πολὺς ὁ πανταχοῦ σπάνιος, θαυμασταὶ δὲ ὀροφαὶ μήκει τε δοκῶν καὶ λαμπρότητι προκοσμημάτων, οἴκων δὲ πλῆθος καὶ διαφοραὶ σχημάτων περὶ τούτους μυρίαι, πᾶσίν γε μὴν ἀποσκευαὶ πλήρεις, καὶ τὰ πλείω τῶν ἐν ἑκάστοις κειμένων ἐξ ἀργύρου τε καὶ χρυσοῦ. περίστοα δὲ δι’ ἀλλήλων ἐν κύκλῳ πολλά, καὶ στῦλοι πρὸς ἑκάστῳ διάφοροι, τά γε μὴν τούτων ὕπαιθρα πάντα χλοερά, καὶ ποικίλαι μὲν ὕλαι μακροὶ δὲ δι’ αὐτῶν περίπατοι καὶ περὶ τούτους εὔριποι βαθεῖς δεξαμεναί τε πανταχοῦ χαλκουργημάτων περίπλεοι, δι’ ὧν τὸ ὕδωρ ἐξεχεῖτο, καὶ πολλοὶ περὶ τὰ νάματα πύργοι πελειάδων ἡμέρων. ἀλλὰ γὰρ οὔθ’ ἑρμηνεῦσαι δυνατὸν ἀξίως τὰ βασίλεια, καὶ φέρει βάσανον ἡ μνήμη τὰς τοῦ λῃστρικοῦ πυρὸς δαπάνας ἀναφέρουσα· οὐ γὰρ ταῦτα Ῥωμαῖοι κατέφλεξαν, ἀλλ’ ὑπὸ τῶν ἔνδον ἐπιβούλων, ὡς προειρήκαμεν, ἐν ἀρχῇ τῆς ἀποστάσεως ἀπὸ μὲν τῆς Ἀντωνίας ἤρξατο τὸ πῦρ, μετέβη δ’ ἐπὶ τὰ βασίλεια καὶ τῶν τριῶν πύργων τὰς στέγας ἐπενεμήθη.", "st": "5.4.4"}, {"sp": "N", "t": "Τὸ δ’ ἱερὸν ἵδρυτο μέν, ὥσπερ ἔφην, ἐπὶ λόφου καρτεροῦ, κατ’ ἀρχὰς δὲ μόλις ἐξήρκει τὸ ἀνωτάτω χθαμαλὸν αὐτοῦ τῷ τε ναῷ καὶ τῷ βωμῷ· τὰ γὰρ πέριξ ἀπόκρημνος ἦν καὶ κατάντης. τοῦ δὲ βασιλέως Σολομῶνος, ὃς δὴ καὶ τὸν ναὸν ἔκτισεν, τὸ κατ’ ἀνατολὰς μέρος ἐκτειχίσαντος, ἐπετέθη μία στοὰ τῷ χώματι· καὶ κατά γε τὰ λοιπὰ μέρη γυμνὸς ὁ ναὸς ἦν. τοῖς δ’ ἑξῆς αἰῶσιν ἀεί τι τοῦ λαοῦ προσχωννύντος ἀνισούμενος ὁ λόφος ηὐρύνετο. διακόψαντες δὲ καὶ τὸ προσάρκτιον τεῖχος τοσοῦτον προσελάμβανον ὅσον ὕστερον ἐπεῖχεν ὁ τοῦ παντὸς ἱεροῦ περίβολος. τειχίσαντες δ’ ἐκ ῥίζης τριχῆ κυκλόθεν τὸν λόφον καὶ μεῖζον ἐλπίδος ἐκπονήσαντες ἔργον, εἰς ὃ μακροὶ μὲν ἐξαναλώθησαν αἰῶνες αὐτοῖς καὶ οἱ ἱεροὶ δὲ θησαυροὶ πάντες, οὓς ἀνεπίμπλασαν οἱ παρὰ τῆς οἰκουμένης δασμοὶ πεμπόμενοι τῷ θεῷ, τούς τε ἄνω περιβόλους καὶ τὸ κάτω ἱερὸν ἀμφεδείμαντο. τούτου τὸ ταπεινότατον ἀπὸ τριακοσίων ἀνετειχίσαντο πηχῶν, κατὰ δέ τινας τόπους καὶ πλείονος. οὐ μέντοι πᾶν τὸ βάθος ἐφαίνετο τῶν θεμελίων· ἐπὶ πολὺ γὰρ ἔχωσαν τὰς φάραγγας ἀνισοῦν βουλόμενοι τοὺς στενωποὺς τοῦ ἄστεος. πέτραι δὲ τεσσαρακονταπήχεις τὸ μέγεθος ἦσαν τοῦ δομήματος· ἥ τε γὰρ δαψίλεια τῶν χρημάτων καὶ τοῦ λαοῦ φιλοτιμία λόγου μείζονας ἐποιεῖτο τὰς ἐπιβολάς, καὶ τὸ μηδὲ ἐλπισθὲν ἕξειν πέρας ἐπιμονῇ καὶ χρόνοις ἦν ἀνύσιμον.", "st": "5.5.1"}, {"sp": "N", "t": "Ἦν δὲ ἄξια τῶν τηλικούτων θεμελίων καὶ τὰ ὑπὲρ αὐτῶν ἔργα διπλαῖ μὲν γὰρ αἱ στοαὶ πᾶσαι, κίονες δ’ αὐταῖς εἰκοσιπέντε πηχῶν τὸ ὕψος ἐφεστήκεσαν μονόλιθοι λευκοτάτης μαρμάρου, κεδρίνοις δὲ φατνώμασιν ὠρόφωντο. τούτων ἡ μὲν φυσικὴ πολυτέλεια καὶ τὸ εὔξεστον καὶ τὸ ἁρμόνιον παρεῖχε θεωρίαν ἀξιόλογον, οὐδενὶ δὲ ἔξωθεν οὔτε ζωγραφίας οὔτε γλυφίδος ἔργῳ προσηγλάιστο. καὶ πλατεῖαι μὲν ἦσαν ἐπὶ τριάκοντα πήχεις, ὁ δὲ πᾶς κύκλος αὐτῶν εἰς ἓξ σταδίους συνεμετρεῖτο περιλαμβανομένης καὶ τῆς Ἀντωνίας· τὸ δ’ ὕπαιθρον ἅπαν πεποίκιλτο παντοδαπῷ λίθῳ κατεστρωμένον. διὰ τούτου προϊόντων ἐπὶ τὸ δεύτερον ἱερὸν δρύφακτος περιβέβλητο λίθινος, τρίπηχυς μὲν ὕψος, πάνυ δὲ χαριέντως διειργασμένος· ἐν αὐτῷ δὲ εἱστήκεσαν ἐξ ἴσου διαστήματος στῆλαι τὸν τῆς ἁγνείας προσημαίνουσαι νόμον αἱ μὲν Ἑλληνικοῖς αἱ δὲ Ῥωμαϊκοῖς γράμμασιν μηδένα ἀλλόφυλον ἐντὸς τοῦ ἁγίου παριέναι· τὸ γὰρ δεύτερον ἱερὸν ἅγιον ἐκαλεῖτο. καὶ τεσσαρεσκαίδεκα [μὲν] βαθμοῖς ἦν ἀναβατὸν ἀπὸ τοῦ πρώτου, τετράγωνον δὲ ἄνω καὶ τείχει περιπεφραγμένον ἰδίῳ. τούτου τὸ μὲν ἔξωθεν ὕψος καίπερ τεσσαράκοντα πηχῶν ὑπάρχον ὑπὸ τῶν βαθμῶν ἐκαλύπτετο, τὸ δὲ ἔνδον εἴκοσι καὶ πέντε πηχῶν ἦν· πρὸς γὰρ ὑψηλοτέρῳ δεδομημένου τοῦ βαθμοῦ οὐκέτ’ ἦν ἅπαν εἴσω καταφανὲς καλυπτόμενον ὑπὸ τοῦ λόφου. μετὰ δὲ τοὺς δεκατέσσαρας βαθμοὺς τὸ μέχρι τοῦ τείχους διάστημα πηχῶν ἦν δέκα, πᾶν ἰσόπεδον. ἔνθεν ἄλλοι πάλιν πεντέβαθμοι κλίμακες ἀνῆγον ἐπὶ τὰς πύλας, αἳ ἀπὸ μὲν ἄρκτου καὶ μεσημβρίας ὀκτώ, καθ’ ἑκάτερον τέσσαρες, δύο δ’ ἦσαν ἐξ ἀνατολῆς κατ’ ἀνάγκην· διατετειχισμένου γὰρ κατὰ τοῦτο τὸ κλίμα ταῖς γυναιξὶν ἰδίου πρὸς θρησκείαν χώρου ἔδει δευτέραν εἶναι πύλην· τέτμητο δ’ αὕτη τῆς πρώτης ἄντικρυς. κἀκ τῶν ἄλλων δὲ κλιμάτων μία μεσημβρινὴ πύλη καὶ μία βόρειος, δι’ ἧς εἰς τὴν γυναικωνῖτιν εἰσῆγον· κατὰ γὰρ τὰς ἄλλας οὐκ ἐξῆν παρελθεῖν γυναιξίν, ἀλλ’ οὐδὲ κατὰ τὴν σφετέραν ὑπερβῆναι τὸ διατείχισμα. ἀνεῖτό γε μὴν ταῖς τ’ ἐπιχωρίοις καὶ ταῖς ἔξωθεν ὁμοφύλοις ἐν ἴσῳ πρὸς θρησκείαν ὁ χῶρος. τὸ δὲ πρὸς δύσιν μέρος οὐκ εἶχε πύλην, ἀλλὰ διηνεκὲς ἐδεδόμητο ταύτῃ τὸ τεῖχος. αἱ στοαὶ δὲ μεταξὺ τῶν πυλῶν ἀπὸ τοῦ τείχους ἔνδον ἐστραμμέναι πρὸ τῶν γαζοφυλακίων σφόδρα μὲν καλοῖς καὶ μεγάλοις ἀνείχοντο κίοσιν, ἦσαν δ’ ἁπλαῖ, καὶ πλὴν τοῦ μεγέθους τῶν κάτω κατ’ οὐδὲν ἀπελείποντο.", "st": "5.5.2"}, {"sp": "N", "t": "Τῶν δὲ πυλῶν αἱ μὲν ἐννέα χρυσῷ καὶ ἀργύρῳ κεκαλυμμέναι πανταχόθεν ἦσαν ὁμοίως τε αἵ τε παραστάδες καὶ τὰ ὑπέρθυρα, μία δ’ ἡ ἔξωθεν τοῦ νεὼ Κορινθίου χαλκοῦ πολὺ τῇ τιμῇ τὰς καταργύρους καὶ περιχρύσους ὑπεράγουσα. καὶ δύο μὲν ἑκάστου πυλῶνος θύραι, τριάκοντα δὲ πηχῶν τὸ ὕψος ἑκάστης καὶ τὸ πλάτος ἦν πεντεκαίδεκα. μετὰ μέντοι τὰς εἰσόδους ἐνδοτέρω πλατυνόμενοι παρ’ ἑκάτερον τριακονταπήχεις ἐξέδρας εἶχον εὖρός τε καὶ μῆκος πυργοειδεῖς, ὑψηλὰς δ’ ὑπὲρ τεσσαράκοντα πήχεις· δύο δ’ ἀνεῖχον ἑκάστην κίονες δώδεκα πηχῶν τὴν περιοχὴν ἔχοντες. καὶ τῶν μὲν ἄλλων ἴσον ἦν τὸ μέγεθος, ἡ δ’ ὑπὲρ τὴν Κορινθίαν ἀπὸ τῆς γυναικωνίτιδος ἐξ ἀνατολῆς ἀνοιγομένη τῆς τοῦ ναοῦ πύλης ἀντικρὺ πολὺ μείζων· πεντήκοντα γὰρ πηχῶν οὖσα τὴν ἀνάστασιν τεσσαρακονταπήχεις τὰς θύρας εἶχε καὶ τὸν κόσμον πολυτελέστερον ἐπὶ δαψιλὲς πάχος ἀργύρου τε καὶ χρυσοῦ. τοῦτον δὲ ταῖς ἐννέα πύλαις ἐπέχεεν ὁ Τιβερίου πατὴρ Ἀλέξανδρος. βαθμοὶ δὲ δεκαπέντε πρὸς τὴν μείζονα πύλην ἀπὸ τοῦ τῶν γυναικῶν διατειχίσματος ἀνῆγον· τῶν γὰρ κατὰ τὰς ἄλλας πέντε βαθμῶν ἦσαν βραχύτεροι.", "st": "5.5.3"}, {"sp": "N", "t": "Αὐτὸς δὲ ὁ ναὸς κατὰ μέσον κείμενος, τὸ ἅγιον ἱερόν, δώδεκα βαθμοῖς ἦν ἀναβατός, καὶ τὸ μὲν κατὰ πρόσωπον ὕψος τε καὶ εὖρος ἴσον ἀνὰ πήχεις ἑκατόν, κατόπιν δὲ τεσσαράκοντα πήχεσι στενότερος· ἔμπροσθεν γὰρ ὥσπερ ὦμοι παρ’ ἑκάτερον εἰκοσαπήχεις διέβαινον. ἡ πρώτη δ’ αὐτοῦ πύλη πηχῶν ἑβδομήκοντα τὸ ὕψος οὖσα καὶ εὖρος εἴκοσι καὶ πέντε, θύρας οὐκ εἶχε· τοῦ γὰρ οὐρανοῦ τὸ ἀφανὲς καὶ ἀδιάκλειστον ἐνέφαινε· κεχρύσωτο δὲ τὰ μέτωπα πάντα, καὶ δι’ αὐτῆς ὅ τε πρῶτος οἶκος ἔξωθεν πᾶς κατεφαίνετο μέγιστος ὤν, καὶ τὰ περὶ τὴν εἴσω πύλην πάντα λαμπόμενα χρυσῷ τοῖς ὁρῶσιν ὑπέπιπτεν. τοῦ δὲ ναοῦ ὄντος εἴσω διστέγου μόνος ὁ πρῶτος οἶκος προύκειτο καὶ διηνεκὲς εἰς τὸ ὕψος, ἀνατεινόμενος μὲν ἐπ’ ἐνενήκοντα πήχεις, μηκυνόμενος δὲ ἐπὶ πεντήκοντα καὶ διαβαίνων ἐπ’ εἴκοσιν. ἡ δὲ διὰ τοῦ οἴκου πύλη κεχρύσωτο μέν, ὡς ἔφην, πᾶσα καὶ ὅλος ὁ περὶ αὐτὴν τοῖχος, εἶχε δὲ καὶ τὰς χρυσᾶς ὑπὲρ αὐτῆς ἀμπέλους, ἀφ’ ὧν βότρυες ἀνδρομήκεις κατεκρέμαντο. ὄντος δὲ ἤδη τοῦ ναοῦ διστέγου, ταπεινοτέρα τῆς ἔξωθεν ὄψεως ἡ ἔνδον ἦν καὶ θύρας εἶχε χρυσᾶς πεντηκονταπέντε πήχεων τὸ ὕψος εὖρος δ’ ἑκκαίδεκα. πρὸ δὲ τούτων ἰσόμηκες καταπέτασμα πέπλος ἦν Βαβυλώνιος ποικιλτὸς ἐξ ὑακίνθου καὶ βύσσου κόκκου τε καὶ πορφύρας, θαυμαστῶς μὲν εἰργασμένος, οὐκ ἀθεώρητον δὲ τῆς ὕλης τὴν κρᾶσιν ἔχων, ἀλλ’ ὥσπερ εἰκόνα τῶν ὅλων· ἐδόκει γὰρ αἰνίττεσθαι τῇ κόκκῳ μὲν τὸ πῦρ, τῇ βύσσῳ δὲ τὴν γῆν, τῇ δ’ ὑακίνθῳ τὸν ἀέρα, καὶ τῇ πορφύρᾳ τὴν θάλασσαν, τῶν μὲν ἐκ τῆς χροίας ὁμοιουμένων, τῆς δὲ βύσσου καὶ τῆς πορφύρας διὰ τὴν γένεσιν, ἐπειδὴ τὴν μὲν ἀναδίδωσιν ἡ γῆ, τὴν δ’ ἡ θάλασσα. κατεγέγραπτο δ’ ὁ πέπλος ἅπασαν τὴν οὐράνιον θεωρίαν πλὴν ζῳδίων.", "st": "5.5.4"}, {"sp": "N", "t": "Παριόντας δ’ εἴσω τὸ ἐπίπεδον τοῦ ναοῦ μέρος ἐξεδέχετο. τούτου τοίνυν τὸ μὲν ὕψος ἑξήκοντα πηχῶν καὶ τὸ μῆκος ἴσον, εἴκοσι δὲ πηχῶν τὸ πλάτος ἦν. τὸ δ’ ἑξηκοντάπηχυ πάλιν διῄρητο, καὶ τὸ μὲν πρῶτον μέρος ἀποτετμημένον ἐπὶ τεσσαράκοντα πήχεις εἶχεν ἐν αὑτῷ τρία θαυμασιώτατα καὶ περιβόητα πᾶσιν ἀνθρώποις ἔργα, λυχνίαν τράπεζαν θυμιατήριον. ἐνέφαινον δ’ οἱ μὲν ἑπτὰ λύχνοι τοὺς πλανήτας· τοσοῦτοι γὰρ ἀπ’ αὐτῆς διῄρηντο τῆς λυχνίας· οἱ δὲ ἐπὶ τῆς τραπέζης ἄρτοι δώδεκα τὸν ζῳδιακὸν κύκλον καὶ τὸν ἐνιαυτόν. τὸ θυμιατήριον δὲ διὰ τῶν τρισκαίδεκα θυμιαμάτων, οἷς ἐκ θαλάσσης ἀνεπίμπλατο καὶ τῆς τε ἀοικήτου καὶ οἰκουμένης, ἐσήμαινεν ὅτι τοῦ θεοῦ πάντα καὶ τῷ θεῷ. τὸ δ’ ἐνδοτάτω μέρος εἴκοσι μὲν πηχῶν ἦν· διείργετο δὲ ὁμοίως καταπετάσματι πρὸς τὸ ἔξωθεν. ἔκειτο δὲ οὐδὲν ὅλως ἐν αὐτῷ, ἄβατον δὲ καὶ ἄχραντον καὶ ἀθέατον ἦν πᾶσιν, ἁγίου δὲ ἅγιον ἐκαλεῖτο. περὶ δὲ τὰ πλευρὰ τοῦ κάτω ναοῦ δι’ ἀλλήλων ἦσαν οἶκοι τρίστεγοι πολλοί, καὶ παρ’ ἑκάτερον εἰς αὐτοὺς ἀπὸ τῆς πύλης εἴσοδοι. τὸ δ’ ὑπερῷον μέρος τούτους μὲν οὐκέτι εἶχεν τοὺς οἴκους παρόσον ἦν καὶ στενότερον, ὑψηλὸν δ’ ἐπὶ τεσσαράκοντα πήχεις καὶ λιτότερον τοῦ κάτω· συνάγεται γὰρ οὕτως πρὸς ἑξήκοντα τοῖς τοῦ ἐπιπέδου πηχῶν ἑκατὸν τὸ πᾶν ὕψος.", "st": "5.5.5"}, {"sp": "N", "t": "Τὸ δ’ ἔξωθεν αὐτοῦ πρόσωπον οὐδὲν οὔτ’ εἰς ψυχῆς οὔτ’ εἰς ὀμμάτων ἔκπληξιν ἀπέλειπεν· πλαξὶ γὰρ χρυσοῦ στιβαραῖς κεκαλυμμένος πάντοθεν ὑπὸ τὰς πρώτας ἀνατολὰς πυρωδεστάτην ἀπέπαλλεν αὐγὴν καὶ τῶν βιαζομένων ἰδεῖν τὰς ὄψεις ὥσπερ ἡλιακαῖς ἀκτῖσιν ἀπέστρεφεν. τοῖς γε μὴν ἀφικνουμένοις ξένοις πόρρωθεν ὅμοιος ὄρει χιόνος πλήρει κατεφαίνετο· καὶ γὰρ καθὰ μὴ κεχρύσωτο λευκότατος ἦν. κατὰ κορυφὴν δὲ χρυσέους ὀβελοὺς ἀνεῖχεν τεθηγμένους, ὡς μή τινι προσκαθεζομένῳ μολύνοιτο τῶν ὀρνέων. τῶν δ’ ἐν αὐτῷ λίθων ἔνιοι μῆκος πέντε καὶ τεσσαράκοντα πηχῶν ἦσαν, ὕψος πέντε, εὖρος δ’ ἕξ. πρὸ αὐτοῦ δ’ ὁ βωμὸς πεντεκαίδεκα μὲν ὕψος ἦν πήχεων, εὖρος δὲ καὶ μῆκος ἐκτείνων ἴσον ἀνὰ πεντήκοντα πήχεις τετράγωνος ἵδρυτο, κερατοειδεῖς προανέχων γωνίας, καὶ ἀπὸ μεσημβρίας ἐπ’ αὐτὸν ἄνοδος ἠρέμα προσάντης ὑπτίαστο. κατεσκευάσθη δὲ ἄνευ σιδήρου, καὶ οὐδέποτ’ ἔψαυεν αὐτοῦ σίδηρος. περιέστεφε δὲ τόν τε ναὸν καὶ τὸν βωμὸν εὔλιθόν τι καὶ χαρίεν γείσιον ὅσον πηχυαῖον ὕψος, ὃ διεῖργεν ἐξωτέρω τὸν δῆμον ἀπὸ τῶν ἱερέων. γονορροίοις μὲν δὴ καὶ λεπροῖς ἡ πόλις ὅλη, τὸ δ’ ἱερὸν γυναικῶν ἐμμήνοις ἀπεκέκλειστο, παρελθεῖν δὲ ταύταις οὐδὲ καθαραῖς ἐξῆν ὃν προείπαμεν ὅρον. ἀνδρῶν δ’ οἱ μὴ καθάπαν ἡγνευκότες εἴργοντο τῆς ἔνδον αὐλῆς, καὶ τῶν ἱερέων πάλιν οἱ [μὴ] καθαρεύοντες εἴργοντο.", "st": "5.5.6"}, {"sp": "N", "t": "Τῶν δ’ ἀπὸ γένους ἱερέων ὅσοι διὰ πήρωσιν οὐκ ἐλειτούργουν παρῆσάν τε ἅμα τοῖς ὁλοκλήροις ἐνδοτέρω τοῦ γεισίου καὶ τὰς ἀπὸ τοῦ γένους ἐλάμβανον μερίδας, ταῖς γε μὴν ἐσθῆσιν ἰδιωτικαῖς ἐχρῶντο· τὴν γὰρ ἱερὰν ὁ λειτουργῶν ἠμφιέννυτο μόνος. ἐπὶ δὲ τὸ θυσιαστήριον καὶ τὸν ναὸν ἀνέβαινον οἱ τῶν ἱερέων ἄμωμοι, βύσσον μὲν ἀμπεχόμενοι, μάλιστα δὲ ἀπὸ ἀκράτου νήφοντες δέει τῆς θρησκείας, ὡς μή τι παραβαῖεν ἐν τῇ λειτουργίᾳ. ὁ δὲ ἀρχιερεὺς ἀνῄει μὲν σὺν αὐτοῖς, ἀλλ’ οὐκ ἀεί, ταῖς δ’ ἑβδομάσι καὶ νουμηνίαις καὶ εἴ τις ἑορτὴ πάτριος ἢ πανήγυρις ἦν πάνδημος ἀγομένη δι’ ἔτους. ἐλειτούργει δὲ τοὺς μηροὺς μέχρις αἰδοίου διαζώματι καλύπτων λινοῦν τε ὑποδύτην ἔνδοθεν λαμβάνων καὶ ποδήρη καθύπερθεν ὑακίνθινον, ἔνδυμα στρογγύλον θυσανωτόν· τῶν δὲ θυσάνων ἀπήρτηντο κώδωνες χρύσεοι καὶ ῥοαὶ παράλληλοι, βροντῆς μὲν οἱ κώδωνες, ἀστραπῆς δ’ αἱ ῥοαὶ σημεῖον. ἡ δὲ τὸ ἔνδυμα τῷ στέρνῳ προσηλοῦσα ταινία πέντε διηνθισμένη ζώναις πεποίκιλτο, χρυσοῦ τε καὶ πορφύρας καὶ κόκκου πρὸς δὲ βύσσου καὶ ὑακίνθου, δι’ ὧν ἔφαμεν καὶ τὰ τοῦ ναοῦ καταπετάσματα συνυφάνθαι. τούτοις δὲ καὶ ἐπωμίδα κεκραμένην εἶχεν, ἐν ᾗ πλείων χρυσὸς ἦν. σχῆμα μὲν οὖν ἐνδυτοῦ θώρακος εἶχεν, δύο δ’ αὐτὴν ἐνεπόρπων ἀσπιδίσκαι χρυσαῖ, κατεκέκλειντο δ’ ἐν ταύταις κάλλιστοί τε καὶ μέγιστοι σαρδόνυχες, τοὺς ἐπωνύμους τῶν τοῦ ἔθνους φυλῶν ἐπιγεγραμμέναι. κατὰ δὲ θάτερον ἄλλοι προσήρτηντο λίθοι δώδεκα, κατὰ τρεῖς εἰς τέσσαρα μέρη διῃρημένοι, σάρδιον τόπαζος σμάραγδος, ἄνθραξ ἴασπις σάπφειρος, ἀχάτης ἀμέθυστος λιγύριον, ὄνυξ βήρυλλος χρυσόλιθος, ὧν ἐφ’ ἑκάστου πάλιν εἷς τῶν ἐπωνύμων ἐγέγραπτο. τὴν δὲ κεφαλὴν βυσσίνη μὲν ἔσκεπεν τιάρα, κατέστεπτο δ’ ὑακίνθῳ, περὶ ἣν χρυσοῦς ἄλλος ἦν στέφανος ἔκτυπα φέρων τὰ ἱερὰ γράμματα· ταῦτα δ’ ἐστὶ φωνήεντα τέσσαρα. ταύτην μὲν οὖν τὴν ἐσθῆτα οὐκ ἐφόρει χρόνιον, λιτοτέραν δ’ ἀνελάμβανεν, ὁπότε δ’ εἰσίοι εἰς τὸ ἄδυτον· εἰσῄει δ’ ἅπαξ κατ’ ἐνιαυτὸν μόνος ἐν ᾗ νηστεύειν ἔθος ἡμέρᾳ πάντας τῷ θεῷ. καὶ τὰ μὲν περὶ τῆς πόλεως καὶ τοῦ ναοῦ τῶν τε περὶ τοῦτον ἐθῶν καὶ νόμων αὖθις ἀκριβέστερον ἐροῦμεν· οὐ γὰρ ὀλίγος περὶ αὐτῶν καταλείπεται λόγος.", "st": "5.5.7"}, {"sp": "N", "t": "Ἡ δ’ Ἀντωνία κατὰ γωνίαν μὲν δύο στοῶν ἔκειτο τοῦ πρώτου ἱεροῦ, τῆς τε πρὸς ἑσπέραν καὶ τῆς πρὸς ἄρκτον, δεδόμητο δὲ ὑπὲρ πέτρας πεντηκονταπήχους μὲν ὕψος, περικρήμνου δὲ πάσης· ἔργον δ’ ἦν Ἡρώδου τοῦ βασιλέως, ἐν ᾧ μάλιστα τὸ φύσει μεγαλόνουν ἐπεδείξατο. πρῶτον μὲν γὰρ ἐκ ῥίζης ἡ πέτρα πλαξὶ κεκάλυπτο λείαις λίθων, εἴς τε κάλλος καὶ ὡς ἀπολισθάνοι πᾶς ὁ προσβαίνειν ἢ κατιέναι πειρώμενος. ἔπειτα πρὸ τῆς τοῦ πύργου δομήσεως τριῶν πηχῶν τεῖχος ἦν, ἐνδοτέρω δὲ τούτου τὸ πᾶν ἀνάστημα τῆς Ἀντωνίας ἐπὶ τεσσαράκοντα πήχεις ἠγείρετο. τὸ δ’ ἔνδον βασιλείων εἶχε χώραν καὶ διάθεσιν· μεμέριστο γὰρ εἰς πᾶσαν οἴκων ἰδέαν τε καὶ χρῆσιν περίστοά τε καὶ βαλανεῖα καὶ στρατοπέδων αὐλαῖς πλατείαις, ὡς τῷ μὲν πάντ’ ἔχειν τὰ χρειώδη πόλις εἶναι δοκεῖν, τῇ πολυτελείᾳ δὲ βασίλειον. πυργοειδὴς δὲ οὖσα τὸ πᾶν σχῆμα κατὰ γωνίαν τέσσαρσιν ἑτέροις διείληπτο πύργοις, ὧν οἱ μὲν ἄλλοι πεντήκοντα τὸ ὕψος, ὁ δ’ ἐπὶ τῇ μεσημβρινῇ καὶ κατὰ ἀνατολὴν γωνίᾳ κείμενος ἑβδομήκοντα πηχῶν ἦν, ὡς καθορᾶν ὅλον ἀπ’ αὐτοῦ τὸ ἱερόν. καθὰ δὲ συνῆπτε ταῖς τοῦ ἱεροῦ στοαῖς εἰς ἀμφοτέρας εἶχε καταβάσεις, δι’ ὧν κατῄεσαν οἱ φρουροί· καθῆστο γὰρ [ἀεὶ] ἐπ’ αὐτῆς τάγμα Ῥωμαίων, καὶ διιστάμενοι περὶ τὰς στοὰς μετὰ τῶν ὅπλων ἐν ταῖς ἑορταῖς τὸν δῆμον, ὡς μή τι νεωτερισθείη, παρεφύλαττον· φρούριον γὰρ ἐπέκειτο τῇ πόλει μὲν τὸ ἱερόν, τῷ ἱερῷ δ’ ἡ Ἀντωνία, κατὰ δὲ ταύτην οἱ τῶν τριῶν φύλακες ἦσαν· καὶ τῆς ἄνω δὲ πόλεως ἴδιον φρούριον ἦν τὰ Ἡρώδου βασίλεια. ἡ Βεζαθὰ δὲ λόφος διῄρητο μέν, ὡς ἔφην, ἀπὸ τῆς Ἀντωνίας, πάντων δ’ ὑψηλότατος ὢν μέρει τῆς καινῆς πόλεως προσῴκιστο. καὶ μόνος τὸ ἱερὸν κατ’ ἄρκτον ἐπεσκότει. περὶ μὲν δὴ τῆς πόλεως καὶ τῶν τειχῶν αὖθις εἰπεῖν ἀκριβέστερον ἕκαστα προτεθειμένοις ἐπὶ τοῦ παρόντος ἀπόχρη.", "st": "5.5.8"}, {"sp": "N", "t": "Τὸ μάχιμον δ’ ἐν αὐτῇ καὶ στασιάζον πλῆθος περὶ Σίμωνα μὲν ἦσαν μύριοι δίχα τῶν Ἰδουμαίων, πεντήκοντα δ’ ἡγεμόνες τῶν μυρίων, ἐφ’ οἷς οὗτος κύριος τῶν ὅλων. Ἰδουμαῖοι δ’ αὐτῷ συντελοῦντες εἰς πεντακισχιλίους ἄρχοντας εἶχον δέκα· τούτων προύχειν ἐδόκουν ὅ τε τοῦ Σωσᾶ Ἰάκωβος καὶ Σίμων υἱὸς Καθλᾶ. Ἰωάννης δὲ τὸ ἱερὸν κατειληφὼς ἑξακισχιλίους ὁπλίτας εἶχεν ὑφ’ ἡγεμόνας εἴκοσι. προσεγένοντο δὲ αὐτῷ τότε καὶ οἱ ζηλωταὶ παυσάμενοι τοῦ διαφέρεσθαι, δισχίλιοι μὲν ὄντες καὶ τετρακόσιοι, χρώμενοι δ’ ἄρχοντι τῷ καὶ πρότερον Ἐλεαζάρῳ καὶ Σίμωνι τῷ τοῦ Ἀρινοῦ. πολεμούντων δὲ τούτων, ὡς ἔφαμεν, ἆθλον ὁ δῆμος ἦν ἑκατέρων, καὶ τὸ μὴ συναδικοῦν τοῦ λαοῦ μέρος ὑπ’ ἀμφοῖν διηρπάζετο. κατεῖχεν δ’ ὁ μὲν Σίμων τήν τε ἄνω πόλιν καὶ τὸ μέγα τεῖχος ἄχρι τοῦ Κεδρῶνος τοῦ τε ἀρχαίου τείχους ὅσον ἀπὸ τῆς Σιλωᾶς ἀνακάμπτον εἰς ἀνατολὴν μέχρι τῆς Μονοβάζου κατέβαινεν αὐλῆς· βασιλεὺς δ’ οὗτος ἦν τῶν ὑπὲρ Εὐφράτην Ἀδιαβηνῶν· κατεῖχε δὲ καὶ τὴν πηγὴν καὶ τῆς Ἄκρας, αὕτη δ’ ἦν ἡ κάτω πόλις, τὰ μέχρι τῶν Ἑλένης βασιλείων τῆς τοῦ Μονοβάζου μητρός, ὁ δ’ Ἰωάννης τό θ’ ἱερὸν καὶ τὰ πέριξ ἐπ’ οὐκ ὀλίγον τόν τε Ὀφλᾶν καὶ τὴν Κεδρῶνα καλουμένην φάραγγα. τὸ μεταξὺ δὲ τούτων ἐμπρήσαντες τῷ πρὸς ἀλλήλους πολέμῳ χώραν ἀνεῖσαν· οὐδὲ γὰρ πρὸς τοῖς τείχεσιν ἐστρατοπεδευμένων Ῥωμαίων ἔνδον ἡ στάσις ἠρέμει, βραχὺ δὲ πρὸς τὴν πρώτην ὑπονήψαντες ἐκδρομὴν ἀνενόσουν καὶ κατὰ σφᾶς πάλιν διαστάντες ἐμάχοντο, τὰ κατ’ εὐχήν τε πάντα τοῖς πολιορκοῦσιν ἔπραττον. οὔτε γοῦν αὐτοί τι χεῖρον ὑπὸ Ῥωμαίων ἔπαθον ὧν ἀλλήλους ἔδρασαν, οὔτε μετὰ τούτους ἡ πόλις ἐπειράθη καινοτέρου πάθους, ἀλλ’ ἡ μὲν χαλεπώτερόν τι πρὸ τοῦ πεσεῖν ἠτύχησεν, οἱ δ’ ἑλόντες αὐτὴν κατώρθωσάν τι μεῖζον. φημὶ γὰρ ὡς τὴν μὲν πόλιν ἡ στάσις, Ῥωμαῖοι δ’ εἷλον τὴν στάσιν, ἥπερ ἦν πολὺ τῶν τειχῶν ὀχυρωτέρα· καὶ τὸ μὲν σκυθρωπὸν τοῖς οἰκείοις, τὸ δίκαιον δ’ ἄν τις εὐλόγως Ῥωμαίοις προσγράφοι. νοείτω δὲ ὅπῃ τοῖς πράγμασιν ἕκαστος ἄγεται.", "st": "5.6.1"}, {"sp": "N", "t": "Τῶν γε μὴν ἔνδον οὕτως διακειμένων ὁ Τίτος μετ’ ἐπιλέκτων ἱππέων περιιὼν ἔξωθεν ᾗ προσβάλλοι τοῖς τείχεσι κατεσκέπτετο. ἀπορουμένῳ δὲ πάντοθεν, οὔτε γὰρ κατὰ τὰς φάραγγας ἦν προσιτὸν καὶ κατὰ θάτερα τὸ πρῶτον τεῖχος ἐφαίνετο τῶν ὀργάνων στερεώτερον, ἐδόκει κατὰ τὸ Ἰωάννου τοῦ ἀρχιερέως μνημεῖον προσβαλεῖν· ταύτῃ γὰρ τό τε πρῶτον ἦν ἔρυμα χθαμαλώτερον καὶ τὸ δεύτερον οὐ συνῆπτεν ἀμελησάντων καθὰ μὴ λίαν ἡ καινὴ πόλις συνῴκιστο τειχίζειν, ἀλλ’ ἐπὶ τὸ τρίτον ἦν εὐπέτεια, δι’ οὗ τὴν ἄνω πόλιν καὶ διὰ τῆς Ἀντωνίας τὸ ἱερὸν αἱρήσειν ἐπενόει. ἐν δὲ τούτῳ περιιόντος αὐτοῦ τοξεύεταί τις τῶν φίλων, ὄνομα Νικάνωρ, κατὰ τὸν λαιὸν ὦμον, ἔγγιον μετὰ τοῦ Ἰωσήπου προσελθὼν καὶ πειρώμενος εἰρηνικὰ τοῖς ἐπὶ τοῦ τείχους, οὐ γὰρ ἄγνωστος ἦν, διαλέγεσθαι. διὰ τούτου τὰς ὁρμὰς αὐτῶν ἐπιγνοὺς Καῖσαρ, εἰ μηδὲ τῶν ἐπὶ σωτηρίᾳ προσιόντων ἀπέχοιντο, παροξύνεται πρὸς τὴν πολιορκίαν, ἅμα τε καὶ τοῖς τάγμασι δῃοῦν τὰ πρὸ τῆς πόλεως ἠφίει καὶ συμφέροντας ἐκέλευσε τὴν ὕλην ἐγείρειν χώματα. τριχῆ δὲ διατάξας τὴν στρατιὰν πρὸς τὰ ἔργα μέσους ἵστησι τῶν χωμάτων τούς τε ἀκοντιστὰς καὶ τοξότας καὶ πρὸ τούτων τοὺς ὀξυβελεῖς καὶ καταπέλτας καὶ τὰς λιθοβόλους μηχανάς, ὡς τάς τε ἐκδρομὰς εἴργοι τῶν πολεμίων ἐπὶ τὰ ἔργα καὶ τοὺς ἀπὸ τοῦ τείχους κωλύειν πειρωμένους. κοπτομένων δὲ τῶν δένδρων τὰ προάστεια μὲν ἐν τάχει γεγύμνωτο, συμφερομένων δ’ ἐπὶ τὰ χώματα τῶν ξύλων καὶ τῆς στρατιᾶς ἁπάσης ἐπὶ τὸ ἔργον ὡρμημένης οὐδὲ τὰ παρὰ τῶν Ἰουδαίων ἠρέμει. τὸν μὲν οὖν δῆμον ἐν ἁρπαγαῖς ὄντα καὶ φόνοις συνέβαινε τότε θαρρεῖν· ἀναπνεύσειν τε γὰρ περισπωμένων πρὸς τοὺς ἔξωθεν ὑπελάμβανον καὶ λήψεσθαι παρὰ τῶν αἰτίων αὐτοὶ δίκας, εἰ Ῥωμαῖοι περιγένοιντο.", "st": "5.6.2"}, {"sp": "N", "t": "Ἰωάννης δὲ καίτοι χωρεῖν ἐπὶ τοὺς ἔξωθεν πολεμίους τῶν περὶ αὐτὸν ὡρμημένων, δέει τοῦ Σίμωνος ἔμενεν. οὐ μὴν ὁ Σίμων ἠρέμει, καὶ γὰρ ἦν ἐγγίων τῇ πολιορκίᾳ, τὰ δ’ ἀφετήρια διίστησιν ἐπὶ τοῦ τείχους, ὅσα Κέστιόν τε ἀφῄρηντο πρότερον καὶ τὴν ἐπὶ τῆς Ἀντωνίας φρουρὰν ἑλόντες ἔλαβον. ἀλλὰ τούτων μὲν τοῖς πολλοῖς ἀχρεῖος ἡ κτῆσις ἦν δι’ ἀπειρίαν· ὀλίγοι δ’ ὑπὸ τῶν αὐτομόλων διδαχθέντες ἐχρῶντο κακῶς τοῖς ὀργάνοις, χερμάσι δὲ καὶ τόξοις τοὺς χωννύντας ἔβαλλον ἀπὸ τοῦ τείχους καὶ κατὰ συντάξεις ἐκτρέχοντες αὐτοῖς συνεπλέκοντο. τοῖς δὲ ἐργαζομένοις ἀπὸ μὲν τῶν βελῶν ἦν σκέπη γέρρα τῶν χαρακωμάτων ὑπερτεταμένα, τὰ δ’ ἀφετήρια πρὸς τοὺς ἐκθέοντας· θαυμαστὰ δὲ πᾶσι μὲν κατεσκεύαστο τοῖς τάγμασι, διαφόρως δὲ τῷ δεκάτῳ βιαιότεροί τε ὀξυβελεῖς καὶ μείζονα λιθοβόλα, δι’ ὧν οὐ μόνον τὰς ἐκδρομὰς ἀλλὰ καὶ τοὺς ἐπὶ τοῦ τείχους ἀνέτρεπον. ταλαντιαῖοι μὲν γὰρ ἦσαν αἱ βαλλόμεναι πέτραι, δύο δὲ καὶ πλείονας ᾔεσαν σταδίους· ἡ πληγὴ δ’ οὐ τοῖς προεντυχοῦσι μόνον, ἐπὶ πολὺ δὲ καὶ τοῖς μετ’ ἐκείνους ἦν ἀνυπόστατος. οἵ γε μὴν Ἰουδαῖοι τὸ πρῶτον ἐφυλάττοντο τὴν πέτραν· λευκὴ γὰρ ἦν, ὥστε μὴ τῷ ῥοίζῳ σημαίνεσθαι μόνον, ἀλλὰ καὶ τῇ λαμπρότητι προορᾶσθαι. σκοποὶ οὖν αὐτοῖς ἐπὶ τῶν πύργων καθεζόμενοι προεμήνυον, ὁπότε σχασθείη τὸ ὄργανον καὶ ἡ πέτρα φέροιτο, τῇ πατρίῳ γλώσσῃ βοῶντες ὁ υἱὸς ἔρχεται. διίσταντο δὲ καθ’ οὓς ᾔει καὶ προκατεκλίνοντο, καὶ συνέβαινε φυλαττομένων ἄπρακτον διεκπίπτειν τὴν πέτραν. ἀντεπινοοῦσι δὲ Ῥωμαῖοι μελαίνειν αὐτήν· τότε γὰρ οὐκέθ’ ὁμοίως προορωμένης εὐστόχουν καὶ πολλοὺς ἅμα βολῇ μιᾷ διέφθειρον. ἀλλ’ οὐδὲ κακούμενοι μετ’ ἀδείας παρεῖχον Ῥωμαίοις ἐγείρειν τὰ χώματα, πάσῃ δ’ ἐπινοίᾳ καὶ τόλμῃ χρώμενοι καὶ νύκτωρ καὶ μεθ’ ἡμέραν εἶργον.", "st": "5.6.3"}, {"sp": "N", "t": "Τῶν δ’ ἔργων συντετελεσμένων μολιβίδι μὲν καὶ λίνῳ διαμετροῦσιν οἱ τέκτονες τὸ διάστημα πρὸς τὸ τεῖχος, ἀπὸ τῶν χωμάτων ῥίψαντες· οὐ γὰρ ἐνῆν ἄλλως ἄνωθεν βαλλομένοις· εὑρόντες δ’ ἐξικνεῖσθαι δυναμένας τὰς ἑλεπόλεις προσῆγον. καὶ Τίτος ἐγγυτέρω τὰ ἀφετήρια διαστήσας, ὡς μὴ τοὺς κριοὺς εἴργοιεν ἀπὸ τοῦ τείχους, ἐκέλευσε τύπτειν. τριχόθεν δ’ ἐξαισίου κτύπου περιηχήσαντος αἰφνιδίως τὴν πόλιν κραυγή τε παρὰ τῶν ἔνδον ἤρθη καὶ τοῖς στασιασταῖς ἴσον ἐμπίπτει δέος. κοινὸν δ’ ἑκάτεροι τὸν κίνδυνον ἰδόντες κοινὴν ἐπενόουν ἤδη ποιεῖσθαι καὶ τὴν ἄμυναν. διαβοώντων δὲ πρὸς ἀλλήλους τῶν διαφόρων ὡς πάντα πράττοιεν ὑπὲρ τῶν πολεμίων, δέον, εἰ καὶ μὴ διηνεκῆ δίδωσιν αὐτοῖς ὁμόνοιαν ὁ θεός, ἐν γοῦν τῷ παρόντι τὴν πρὸς ἀλλήλους φιλονεικίαν ὑπερθεμένους κατὰ Ῥωμαίων συνελθεῖν, κηρύσσει μὲν ἄδειαν ὁ Σίμων τοῖς ἀπὸ τοῦ ἱεροῦ παρελθεῖν ἐπὶ τὸ τεῖχος, ἐπιτρέπει δὲ καίπερ ἀπιστῶν ὁ Ἰωάννης. οἱ δὲ τοῦ μίσους καὶ τῶν ἰδίων διαφόρων λαβόντες ἀμνηστίαν ἓν σῶμα γίνονται, καὶ τὸ μὲν τεῖχος περισχόντες ἀπ’ αὐτοῦ πυρά τε παμπληθῆ κατὰ τῶν μηχανημάτων ἵεσαν καὶ τοὺς ἐπιβρίθοντας τὰς ἑλεπόλεις ἀδιαλείπτως ἔβαλλον, οἱ τολμηρότεροι δὲ κατὰ στίφη προπηδῶντες τὰ γέρρα τῶν μηχανημάτων ἐσπάραττον καὶ τοῖς ἐπ’ αὐτῶν προσπίπτοντες ἐπιστήμῃ μὲν ὀλίγα, τόλμῃ δὲ τὰ πλείω περιεγίνοντο. προσεβοήθει δὲ τοῖς πονοῦσιν αὐτὸς ἀεὶ Τίτος, καὶ παρ’ ἑκάτερον τῶν ὀργάνων τούς τε ἱππέας καὶ τοὺς τοξότας διαστήσας εἶργεν μὲν τοὺς τὸ πῦρ ἐπιφέροντας, ἀνέστελλεν δὲ τοὺς ἀπὸ τῶν πύργων βάλλοντας, ἐνεργοὺς δ’ ἐποίει τὰς ἑλεπόλεις. οὐ μὴν ταῖς πληγαῖς ὑπήκουε τὸ τεῖχος, εἰ μὴ καθόσον ὁ τοῦ πεντεκαιδεκάτου τάγματος κριὸς γωνίαν διεκίνησε πύργου. τὸ δὲ τεῖχος ἀκέραιον ἦν· οὐδὲ γὰρ εὐθέως συνεκινδύνευε τῷ πύργῳ προύχοντι πολὺ καὶ μὴ δυναμένῳ συναπορρῆξαί τι ῥᾳδίως τοῦ περιβόλου.", "st": "5.6.4"}, {"sp": "N", "t": "Παυσάμενοι δὲ τῶν ἐκδρομῶν πρὸς ὀλίγον καὶ τοὺς Ῥωμαίους ἐπιτηρήσαντες ἐσκεδασμένους ἐπὶ τὰ ἔργα καὶ κατὰ τὰ στρατόπεδα, καμάτῳ γὰρ ἀναχωρῆσαι καὶ δέει τοὺς Ἰουδαίους ἠξίουν, ἐκθέουσι κατὰ τὸν Ἱππικὸν πύργον διὰ πύλης ἀφανοῦς πάντες πῦρ τε τοῖς ἔργοις ἐπιφέροντες καὶ μέχρι τῶν ἐρυμάτων ἐπὶ τοὺς Ῥωμαίους προελθεῖν ὡρμημένοι. πρὸς δὲ τὴν κραυγὴν αὐτῶν οἵ τε πλησίον συνίσταντο ταχέως καὶ οἱ πόρρωθεν συνέθεον. ἔφθανε δ’ ἡ Ἰουδαίων τόλμα τὴν Ῥωμαίων εὐταξίαν, καὶ τοὺς προεντυγχάνοντας τρεψάμενοι προσέκειντο καὶ τοῖς συλλεγομένοις. δεινὴ δὲ περὶ τὰς μηχανὰς συμπίπτει μάχη, τῶν μὲν ὑποπιμπράναι, τῶν δὲ κωλύειν βιαζομένων, κραυγή τε παρ’ ἀμφοτέρων ἀσήμαντος ἦν, καὶ πολλοὶ τῶν προαγωνιζομένων ἔπιπτον. Ἰουδαῖοι δ’ ὑπερεῖχον ἀπονοίᾳ, καὶ τῶν ἔργων ἥπτετο τὸ πῦρ, καταφλεγῆναί τ’ ἂν ἐκινδύνευσε πάντα μετὰ τῶν ὀργάνων, εἰ μὴ τῶν ἀπ’ Ἀλεξανδρείας ἐπιλέκτων ἀντέστησαν οἱ πολλοὶ παρὰ τὴν σφετέραν ὑπόληψιν ἀνδρισάμενοι· καὶ γὰρ τῶν ἐνδοξοτέρων διήνεγκαν κατὰ ταύτην τὴν μάχην· μέχρι Καῖσαρ τοὺς τῶν ἱππέων δυνατωτάτους ἀναλαβὼν ἐμβάλλει τοῖς πολεμίοις. καὶ δώδεκα μὲν αὐτὸς τῶν προμάχων ἀναιρεῖ, πρὸς δὲ τὸ τούτων πάθος ἐγκλίνοντος τοῦ λοιποῦ πλήθους ἑπόμενος συνελαύνει πάντας εἰς τὴν πόλιν κἀκ τοῦ πυρὸς διασώζει τὰ ἔργα. συνέβη δ’ ἐν ταύτῃ τῇ μάχῃ καὶ ζωγρηθῆναί τινα τῶν Ἰουδαίων, ὃν ὁ Τίτος ἀνασταυρῶσαι πρὸ τοῦ τείχους ἐκέλευσεν, εἴ τι πρὸς τὴν ὄψιν ἐνδοῖεν οἱ λοιποὶ καταπλαγέντες. μετὰ δὲ τὴν ἀναχώρησιν καὶ Ἰωάννης ὁ τῶν Ἰδουμαίων ἡγεμὼν πρὸ τοῦ τείχους γνωρίμῳ τινὶ στρατιώτῃ διαλεγόμενος ὑπό τινος τῶν Ἀράβων κατὰ τοῦ στέρνου τοξεύεται καὶ παραχρῆμα θνήσκει, μέγιστον τοῖς τε Ἰδουμαίοις πένθος καὶ λύπην τοῖς στασιασταῖς ἀπολιπών· καὶ γὰρ κατά τε χεῖρα καὶ συνέσει διάσημος ἦν.", "st": "5.6.5"}, {"sp": "N", "t": "Τῇ δ’ ἐπιούσῃ νυκτὶ ταραχὴ καὶ τοῖς Ῥωμαίοις ἐμπίπτει παράλογος. τοῦ γὰρ Τίτου πύργους τρεῖς κατασκευάσαι κελεύσαντος πεντηκονταπήχεις, ἵν’ ἑκάστου χώματος ἐπιστήσας ἀπὸ τούτων τοὺς ἐπὶ τοῦ τείχους τρέποιτο, συνέβη πεσεῖν αὐτομάτως ἕνα μέσης νυκτός. μεγίστου δὲ ἀρθέντος ψόφου δέος ἐμπίπτει τῷ στρατῷ, καὶ τοὺς πολεμίους ἐπιχειρεῖν σφίσι δόξαντες ἐπὶ τὰ ὅπλα πάντες ἔθεον. ταραχὴ δὲ τῶν ταγμάτων καὶ θόρυβος ἦν, καὶ τὸ συμβὰν οὐδενὸς εἰπεῖν ἔχοντος ἐπὶ πλεῖστον ἀποδυρόμενοι διεφέροντο μηδενός τε φαινομένου πολεμίου δι’ ἀλλήλων ἐπτοοῦντο, καὶ τὸ σύνθημα μετὰ σπουδῆς ἕκαστος τὸν πλησίον ἐπηρώτα καθάπερ Ἰουδαίων ἐμβεβληκότων εἰς τὰ στρατόπεδα, πανικῷ τε δείματι κυκλουμένοις παρεῴκεσαν, ἄχρι μαθὼν τὸ συμβὰν Τίτος διαγγέλλειν ἐκέλευσε πᾶσι, καὶ μόλις ἐπαύσαντο τῆς ταραχῆς.", "st": "5.7.1"}, {"sp": "N", "t": "Ἰουδαίους γε μὴν πρὸς τὰ λοιπὰ καρτερῶς ἀντέχοντας ἐκάκωσαν οἱ πύργοι· καὶ γὰρ τῶν ὀργάνων τοῖς κουφοτέροις ἀπ’ αὐτῶν ἐβάλλοντο καὶ τοῖς ἀκοντισταῖς καὶ τοξόταις καὶ λιθοβόλοις. οὔτε δὲ τούτων αὐτοὶ διὰ τὸ ὕψος ἐφικνοῦντο καὶ τοὺς πύργους ἦν ἀμήχανον ἑλεῖν, μήτ’ ἀνατραπῆναι ῥᾳδίως διὰ τὸ βρῖθος μήτ’ ἐμπρησθῆναι διὰ τὸν σίδηρον δυναμένους, ᾧ κατεκαλύπτοντο. τρεπόμενοι δὲ ἐξωτέρω βέλους οὐκέτι ἐκώλυον τῶν κριῶν τὰς ἐμβολάς, οἳ ἀδιαλείπτως παίοντες ἤνυον κατ’ ὀλίγον. ἤδη δὲ τῷ Νίκωνι τοῦ τείχους ἐνδιδόντος, αὐτοὶ γὰρ τοῦτο Ἰουδαῖοι τὴν μεγίστην ἐκάλεσαν Ῥωμαίων ἑλέπολιν ἀπὸ τοῦ πάντα νικᾶν, ἀπέκαμνον μὲν πάλαι πρός τε τὰς μάχας καὶ τὰς φυλακὰς πόρρωθεν τῆς πόλεως διανυκτερεύοντες, ἄλλως δ’ ὑπὸ ῥᾳστώνης καὶ τοῦ βουλεύεσθαι πάντα κακῶς περιττὸν αὐτοῖς δόξαν τὸ τεῖχος ἑτέρων μετ’ αὐτὸ λειπομένων δύο, μαλακισθέντες ἀνεχώρουν οἱ πολλοί. καὶ τῶν Ῥωμαίων ἐπιβάντων καθὸ παρέρρηξεν ὁ Νίκων, καταλιπόντες τὰς φυλακὰς πάντες εἰς τὸ δεύτερον τεῖχος ἀναφεύγουσιν. οἱ δ’ ὑπερβάντες τὰς πύλας ἀνοίξαντες πᾶσαν εἰσδέχονται τὴν στρατιάν. καὶ Ῥωμαῖοι μὲν οὕτω τοῦ πρώτου τείχους πεντεκαιδεκάτῃ κρατήσαντες ἡμέρᾳ, ἑβδόμη δὲ ἦν Ἀρτεμισίου μηνός, αὐτοῦ τε πολὺ κατασκάπτουσι καὶ τὰ προσάρκτια τῆς πόλεως, ἃ καὶ πρότερον Κέστιος.", "st": "5.7.2"}, {"sp": "N", "t": "Μεταστρατοπεδεύεται δὲ Τίτος εἴσω κατὰ τὴν Ἀσσυρίων παρεμβολὴν καλουμένην, ἐπισχὼν πᾶν τὸ μεταξὺ μέχρι τοῦ Κεδρῶνος, ἀπὸ δὲ τοῦ δευτέρου τείχους ὅσον ἐξωτέρω βέλους εἶναι· προσβολὰς δ’ εὐθέως ἐποιεῖτο. ἐμμερισθέντες δὲ οἱ Ἰουδαῖοι καρτερῶς ἀπημύναντο τοῦ τείχους, οἱ μὲν περὶ τὸν Ἰωάννην ἀπό τε τῆς Ἀντωνίας καὶ τῆς προσαρκτίου στοᾶς τοῦ ἱεροῦ καὶ πρὸ τῶν Ἀλεξάνδρου τοῦ βασιλέως αὐτῶν μνημείων μαχόμενοι, τὸ δὲ τοῦ Σίμωνος τάγμα τὴν παρὰ τὸ Ἰωάννου τοῦ ἀρχιερέως μνημεῖον ἐμβολὴν διαλαβόντες ἐφράξαντο μέχρι πύλης καθ’ ἣν τὸ ὕδωρ ἐπὶ τὸν Ἱππικὸν πύργον εἰσῆκτο. προπηδῶντές τε πολλάκις ἐκ τῶν πυλῶν συστάδην ἐπολέμουν καὶ συνδιωχθέντες ἀπὸ τοῦ τείχους κατὰ μὲν τὰς συμπλοκὰς ἡττῶντο τῆς Ῥωμαίων ἐπιστήμης ὄντες ἄπειροι, περιῆσαν δ’ ἐν ταῖς τειχομαχίαις. καὶ τοὺς μὲν μετ’ ἰσχύος ἐμπειρία παρεκρότει, Ἰουδαίους δὲ τόλμα δέει τρεφομένη καὶ τὸ φύσει καρτερικὸν ἐν συμφοραῖς· προσῆν δ’ ἐλπὶς ἔτι σωτηρίας ἡ καὶ Ῥωμαίοις τοῦ ταχέως κρατήσειν. οὐδετέρων δὲ ἥπτετο κόπος, ἀλλὰ προσβολαὶ καὶ τειχομαχίαι καὶ κατὰ λόχους ἐκδρομαὶ συνεχεῖς δι’ ὅλης ἡμέρας ἦσαν, οὐδ’ ἔστιν ἥτις ἰδέα μάχης ἀπελείπετο. νὺξ δὲ ἀνέπαυε μόλις ἕωθεν ἀρχομένους· ἦν δ’ ἄυπνος ἀμφοτέροις καὶ χαλεπωτέρα τῆς ἡμέρας, δέει τῶν μὲν ὅσον οὔπω καταληφθήσεσθαι τὸ τεῖχος, τῶν δ’ ἐπιθήσεσθαι Ἰουδαίους τοῖς στρατοπέδοις, ἔν τε τοῖς ὅπλοις ἑκάτεροι διανυκτερεύοντες ὑπὸ τὰς πρώτας αὐγὰς ἕτοιμοι πρὸς μάχην ἦσαν. καὶ παρὰ μὲν Ἰουδαίοις ἔρις ἦν ὅστις προκινδυνεύσας χαρίσαιτο τοῖς ἡγεμόσιν, μάλιστα δὲ τοῦ Σίμωνος αἰδὼς ἦν καὶ δέος, οὕτως τε προσεῖχεν ἕκαστος αὐτῷ τῶν ὑποτεταγμένων, ὡς καὶ πρὸς αὐτοχειρίαν ἑτοιμότατος εἶναι κελεύσαντος· Ῥωμαίοις δὲ ἐπ’ ἀνδρείαν ἦν προτροπὴ τοῦ τε κρατεῖν ἔθος καὶ ἥττης ἀήθεια συνεχής τε στρατεία καὶ διηνεκεῖς μελέται καὶ μέγεθος ἡγεμονίας, πρὸ δὲ πάντων Τίτος ἀεὶ πᾶσιν πανταχοῦ παρατυγχάνων. τό τε γὰρ μαλακισθῆναι παρόντος καὶ συναγωνιζομένου Καίσαρος δεινὸν ἐδόκει, καὶ τῷ καλῶς ἀγωνισαμένῳ μάρτυς αὐτὸς ὁ καὶ τιμήσων παρῆν· κέρδος δ’ ἦν ἤδη καὶ τὸ γνωσθῆναι Καίσαρι γενναῖον ὄντα. διὰ τοῦτο πολλοὶ τῆς κατὰ σφᾶς ἰσχύος ἀμείνους τῇ προθυμίᾳ διεφάνησαν. παραταξαμένων γοῦν κατὰ ταύτας τὰς ἡμέρας τῶν Ἰουδαίων πρὸ τοῦ τείχους καρτερῷ στίφει καὶ διακοντιζομένων ἔτι πόρρωθεν τῶν ταγμάτων ἑκατέρων Λογγῖνός τις τῶν ἱππέων ἐξαλλόμενος τῆς Ῥωμαϊκῆς τάξεως ἐμπηδᾷ μέσῃ τῇ τῶν Ἰουδαίων φάλαγγι, καὶ διασκεδασθέντων πρὸς τὴν ἐμβολὴν δύο τοὺς γενναιοτάτους ἀναιρεῖ, τὸν μὲν κατὰ στόμα πλήξας ὑπαντιάσαντα, τὸν δ’ ἀνασπάσας ἐκ τοῦ προτέρου τὸ δόρυ κατὰ πλευρὰν διαπείρει τραπόμενον, ἐκ μέσων τε τῶν πολεμίων ἄτρωτος εἰς τοὺς σφετέρους ἔδραμεν. ὁ μὲν οὖν δι’ ἀρετὴν ἐπίσημος ἦν, ζηλωταὶ δὲ τῆς ἀνδρείας ἐγίνοντο πολλοί. καὶ Ἰουδαῖοι μὲν ἀμελοῦντες τοῦ παθεῖν τὸ διαθεῖναι μόνον ἐσκόπουν, ὅ τε θάνατος αὐτοῖς ἐδόκει κουφότατος εἰ μετὰ τοῦ κτεῖναί τινα τῶν πολεμίων προσπέσοι· Τίτος δὲ τῆς τῶν στρατιωτῶν ἀσφαλείας οὐχ ἧττον τοῦ κρατεῖν προυνόει, καὶ τὴν μὲν ἀπερίσκεπτον ὁρμὴν ἀπόνοιαν λέγων, μόνην δ’ ἀρετὴν τὴν μετὰ προνοίας καὶ τοῦ μηδὲν τὸν δρῶντα παθεῖν, ἐν ἀκινδύνῳ τῷ κατὰ σφᾶς ἐκέλευσεν ἀνδρίζεσθαι.", "st": "5.7.3"}, {"sp": "N", "t": "Προσάγει δ’ αὐτὸς τοῦ βορείου τείχους τῷ μέσῳ πύργῳ τὴν ἑλέπολιν, ἐν ᾧ τῶν Ἰουδαίων τις ἀνὴρ γόης ὄνομα Κάστωρ ἐλόχα μεθ’ ὁμοίων δέκα, τῶν λοιπῶν φυγόντων διὰ τοὺς τοξότας. οὗτοι μέχρι μέν τινος ὑπεπτηχότες τοῖς θωρακίοις ἠρέμουν, λυομένου δὲ τοῦ πύργου διανίστανται, καὶ προτείνας ὁ Κάστωρ τὰς χεῖρας ὡς ἱκετεύων δῆθεν ἐκάλει τὸν Καίσαρα καὶ τῇ φωνῇ κατοικτιζόμενος ἐλεῆσαι σφᾶς παρεκάλει. πιστεύσας δ’ ἐξ ἁπλότητος ὁ Τίτος καὶ μετανοεῖν ἤδη τοὺς Ἰουδαίους ἐλπίσας, ἐπέχει μὲν τοῦ κριοῦ τὴν ἐμβολὴν κωλύει τε τοξεύειν τοὺς ἱκέτας, λέγειν δ’ ἐκέλευσεν ὅ τι βούλεται τῷ Κάστορι. τοῦ δ’ εἰπόντος ἐπὶ δεξιᾷ καταβῆναι θέλειν, ὁ Τίτος συνήδεσθαι μὲν αὐτῷ τῆς εὐβουλίας ἔφη, συνήδεσθαι δὲ εἰ πάντες ταῦτα ἤδη φρονοῦσι καὶ τῇ πόλει διδόναι τε πίστιν ἑτοίμως. τῶν δέκα δὲ οἱ πέντε μὲν αὐτῷ συνυπεκρίνοντο τὴν ἱκετηρίαν, οἱ λοιποὶ δ’ οὐκ ἄν ποτε δουλεύσειν Ῥωμαίοις ἐβόων παρὸν ἐλευθέρους ἀποθανεῖν. καὶ μέχρι πολλοῦ διαφερομένων ἐτρίβετο μὲν ἡ προσβολή, πέμπων δ’ ὁ Κάστωρ πρὸς τὸν Σίμωνα σχολῇ βουλεύεσθαι περὶ τῶν ἐπειγόντων ἔλεγεν, ὡς οὐκ ἐπ’ ὀλίγον αὐτὸς διαπαίζοι τὴν Ῥωμαίων ἀρχήν. ἅμα δὲ ταῦτα πέμπων καταφανὴς ἦν καὶ τοὺς ἀπειθοῦντας ἐπὶ τὴν δεξιὰν παρακαλῶν. οἱ δὲ ὥσπερ ἀγανακτοῦντες ὑπὲρ τὰ θωράκια διῄρουν τε τὰ ξίφη γυμνὰ καὶ τοὺς θώρακας αὑτῶν πλήξαντες ὡς ἀπεσφαγμένοι κατέπεσον. θάμβος δὲ τὸν Τίτον καὶ τοὺς περὶ αὐτὸν εἰσῄει τοῦ τῶν ἀνδρῶν παραστήματος, καὶ μὴ δυνάμενοι κάτωθεν ἀκριβῶς τὸ γεγενημένον ἰδεῖν ἐθαύμαζόν τε τῆς εὐτολμίας αὐτοὺς καὶ τοῦ πάθους ἠλέουν. τοξεύει δέ τις ἐν τούτῳ παρὰ τὴν ῥῖνα τὸν Κάστορα, κἀκεῖνος εὐθέως ἀνασπάσας τὸ βέλος ἐπεδείκνυ τῷ Τίτῳ καὶ ὡς οὐ δίκαια πάσχων κατεμέμφετο. πρὸς δὲ τὸν βαλόντα σχετλιάσας Καῖσαρ ἔπεμπε παρεστῶτα τὸν Ἰώσηπον δοῦναι τῷ Κάστορι δεξιάν. ἀλλ’ ὁ μὲν οὔτ’ αὐτὸς ἔφη προσελεύσεσθαι, φρονεῖν γὰρ οὐδὲν ὑγιὲς τοὺς δεομένους, καὶ τοὺς ὡρμημένους τῶν φίλων κατέσχεν· Αἰνείας δέ τις τῶν αὐτομόλων αὐτὸς ἔφη προσελεύσεσθαι. καὶ τοῦ Κάστορος καλοῦντος, ὅπως δέξαιτό τις καὶ τὸ ἀργύριον ὃ φέροι μεθ’ αὑτοῦ, σπουδαιότερον ὁ Αἰνείας διαπετάσας τὸν κόλπον προσέδραμεν. ἀράμενος δὲ ὁ Κάστωρ πέτραν ἐπαφίησιν αὐτῷ, καὶ τούτου μὲν διήμαρτε φυλαξαμένου, τιτρώσκει δὲ στρατιώτην ἕτερον προσελθόντα. συννοήσας δὲ Καῖσαρ τὴν ἀπάτην πρὸς βλάβης μὲν ἔγνω τὸν ἐν πολέμοις ἔλεον, τὸ γὰρ ἀπηνέστερον ἧττον ὑποπίπτειν τῷ πανούργῳ, τὰς δ’ ἐμβολὰς τῆς ἑλεπόλεως ὀργῇ τῆς χλεύης ἐποιεῖτο δυνατωτέρας. ὑποδιδόντα δὲ τὸν πύργον ἐμπιπρᾶσιν οἱ περὶ τὸν Κάστορα, καὶ διὰ τῆς φλογὸς εἰς τὴν ὑπ’ αὐτῷ κρυπτὴν ἁλλόμενοι πάλιν δόξαν ἀνδρείας Ῥωμαίοις παρέσχον ὡς ῥίψαντες σφᾶς αὐτοὺς εἰς τὸ πῦρ.", "st": "5.7.4"}, {"sp": "N", "t": "Αἱρεῖ δὲ Καῖσαρ ταύτῃ τὸ τεῖχος ἡμέρᾳ πέμπτῃ μετὰ τὸ πρῶτον, καὶ τῶν Ἰουδαίων φυγόντων ἀπ’ αὐτοῦ παρέρχεται μετὰ χιλίων ἔνδον ὁπλιτῶν καὶ τῶν περὶ αὐτὸν ἐπιλέκτων, καθὸ καὶ τῆς καινῆς πόλεως ἐριοπώλιά τε ἦν καὶ χαλκεῖα καὶ ἱματίων ἀγορά, πρός τε τὸ τεῖχος πλάγιοι κατέτεινον οἱ στενωποί. εἰ μὲν οὖν ἢ τοῦ τείχους εὐθέως πλέον διέλυσεν ἢ πολέμου νόμῳ παρελθὼν ἐπόρθει τὸ ληφθέν, οὐκ ἂν οἶμαί τις ἐμίγη βλάβη τῷ κράτει. νῦν δὲ Ἰουδαίους μὲν ἐλπίσας δυσωπήσειν ἐξὸν κακοῦν τῷ μὴ θέλειν, πρὸς δ’ ἀναχώρησιν εὐμαρῆ τὴν εἰσβολὴν οὐκ ἐπλάτυνεν· οὐ γὰρ ἐπιβουλεύσειν οὓς εὐεργετεῖν ὑπελάμβανεν. παρελθὼν γοῦν οὔτε κτείνειν τινὰ τῶν καταλαμβανομένων ἐπέτρεψεν οὔτε ὑποπιμπράναι τὰς οἰκίας, ἀλλὰ τοῖς μὲν στασιασταῖς εἰ βούλοιντο μάχεσθαι δίχα τῆς τοῦ δήμου βλάβης ἄδειαν ἐξόδου, τῷ δήμῳ δὲ τὰς κτήσεις ὑπισχνεῖτο δώσειν· περὶ πλείστου γὰρ ἐποιεῖτο σῶσαι τὴν μὲν πόλιν αὑτῷ, τὸν δὲ ναὸν τῇ πόλει. τὸν μὲν οὖν λαὸν ἕτοιμον εἶχεν εἰς ἃ προύτρεπεν καὶ πάλαι, τοῖς μαχίμοις δ’ ἐδόκει τὸ φιλάνθρωπον ἀσθένεια, καὶ τὸν Τίτον ἀδυναμίᾳ τοῦ τὴν ἄλλην πόλιν ἑλεῖν ταῦτα προτείνειν ὑπελάμβανον. διαπειλοῦντες δὲ τοῖς δημόταις θάνατον, εἰ περὶ παραδόσεως μνησθείη τις αὐτῶν, καὶ τοὺς παραφθεγγομένους εἰρήνην ἀποσφάττοντες, ἐπιτίθενται καὶ τοῖς εἰσελθοῦσι Ῥωμαίων, οἱ μὲν κατὰ τοὺς στενωποὺς ὑπαντιάσαντες, οἱ δ’ ἀπὸ τῶν οἰκιῶν, ἄλλοι δ’ ἔξω τοῦ τείχους κατὰ τὰς ἄνω προπηδήσαντες πύλας. πρὸς οὓς ταραχθέντες οἱ φρουροὶ τοῦ τείχους καθαλλόμενοι τῶν πύργων ἀνεχώρουν εἰς τὰ στρατόπεδα. κραυγὴ δ’ ἦν τῶν μὲν εἴσω πάντοθεν πολεμίοις κεκυκλωμένων, τῶν δ’ ἔξωθεν περὶ τοῖς ἀπολειφθεῖσι δεδοικότων. πληθύνοντες δ’ ἀεὶ Ἰουδαῖοι καὶ πολλὰ πλεονεκτοῦντες κατ’ ἐμπειρίαν τῶν στενωπῶν ἐτίτρωσκόν τε πολλοὺς καὶ προσπίπτοντες ἐξώθουν. οἱ δὲ κατ’ ἀνάγκην τὸ πλέον ἀντεῖχον, οὐ γὰρ ἦν ἀθρόους διαφυγεῖν διὰ στενοῦ τοῦ τείχους, δοκοῦσί τε ἂν κατακοπῆναι πάντες οἱ παρελθόντες μὴ προσαμύναντος τοῦ Τίτου. διαστήσας γὰρ ἐπ’ ἄκροις τοῖς στενωποῖς τοὺς τοξότας καὶ κατὰ τὸν μάλιστα πληθύοντα σταθεὶς αὐτός, ἀνέστελλε τοῖς βέλεσι τοὺς πολεμίους, καὶ σὺν αὐτῷ Δομέτιος Σαβῖνος, ἀνὴρ ἀγαθὸς καὶ κατὰ ταύτην φανεὶς τὴν μάχην. παρέμεινε δὲ συνεχῶς τοξεύων Καῖσαρ καὶ τοὺς Ἰουδαίους κωλύων παρελθεῖν, μέχρι πάντες ἀνεχώρησαν οἱ στρατιῶται.", "st": "5.8.1"}, {"sp": "N", "t": "Ῥωμαῖοι μὲν οὕτως κρατήσαντες τοῦ δευτέρου τείχους ἐξεώσθησαν, τῶν δ’ ἀνὰ τὸ ἄστυ μαχίμων ἐπήρθη τὰ φρονήματα, καὶ μετέωροι πρὸς τὴν εὐπραγίαν ἦσαν, οὔτ’ ἂν Ῥωμαίους εἰς τὴν πόλιν τολμήσειν ἔτι παρελθεῖν οὔτ’ αὐτοὶ παρελθόντων ἡττηθήσεσθαι δοκοῦντες. ἐπεσκότει γὰρ αὐτῶν ταῖς γνώμαις διὰ τὰς παρανομίας ὁ θεός, καὶ οὔτε τὴν Ῥωμαίων ἰσχὺν ὅσῳ πλείων κατελείπετο τῆς ἐξελαθείσης ἔβλεπον οὔτε τὸν ὑφέρποντα λιμὸν αὐτοῖς· ἔτι γὰρ παρῆν ἐσθίειν ἐκ τῶν δημοσίων κακῶν καὶ τὸ τῆς πόλεως αἷμα πίνειν· ἔνδεια δὲ τοὺς ἀγαθοὺς ἐπεῖχε πάλαι, καὶ σπάνει τῶν ἐπιτηδείων διελύοντο πολλοί. τὴν δὲ τοῦ λαοῦ φθορὰν ἑαυτῶν οἱ στασιασταὶ κουφισμὸν ὑπελάμβανον· μόνους γὰρ ἠξίουν σώζεσθαι τοὺς μὴ ζητοῦντας εἰρήνην καὶ κατὰ Ῥωμαίων ζῆν προῃρημένους, τὸ δ’ ἐναντίον πλῆθος ὥσπερ βάρβαρον ἥδοντο δαπανώμενον. τοιοῦτοι μὲν δὴ πρὸς τοὺς ἔνδον ἦσαν· Ῥωμαίους δὲ πάλιν τῆς εἰσόδου πειρωμένους ἐκώλυον φραξάμενοι καὶ τὸ καταρριφθὲν ἀντιτειχίσαντες τοῖς σώμασι τρισὶ μὲν ἀντέσχον ἡμέραις καρτερῶς ἀμυνόμενοι, τῇ τετάρτῃ δὲ προσβαλόντα γενναίως Τίτον οὐκ ἤνεγκαν, ἀλλὰ βιασθέντες ᾗ καὶ πρότερον ἀναφεύγουσιν. ὁ δὲ πάλιν τοῦ τείχους κρατήσας τὸ προσάρκτιον μὲν εὐθέως κατέρριψε πᾶν, ἐπὶ δὲ τοῦ κατὰ μεσημβρίαν φρουρὰς τοῖς πύργοις ἐγκαταστήσας τῷ τρίτῳ προσβάλλειν ἐπενόει.", "st": "5.8.2"}, {"sp": "N", "t": "Δόξαν δ’ ἐπανεῖναι πρὸς ὀλίγον τὴν πολιορκίαν καὶ διωρίαν βουλῆς τοῖς στασιασταῖς παρέχειν, εἴ τι πρὸς τὴν καθαίρεσιν ἐνδοῖεν τοῦ δευτέρου τείχους ἢ καὶ τὸν λιμὸν ὑποδείσαντες, οὐ γὰρ εἰς πολὺ τὰς ἁρπαγὰς αὐτοῖς ἐξαρκέσειν, εἰς δέον κατεχρῆτο τὴν ἄνεσιν· ἐνστάσης γὰρ τῆς προθεσμίας, καθ’ ἣν ἔδει διαδοῦναι τοῖς στρατιώταις τροφάς, ἐν ἀπόπτῳ τοῖς πολεμίοις ἐκέλευσε τοὺς ἡγεμόνας ἐκτάξαντας τὴν δύναμιν ἀπαριθμεῖν ἑκάστῳ τἀργύριον. οἱ δέ, ὥσπερ ἔθος, ἀποκαλύψαντες τὰ ὅπλα θήκαις ἐσκεπασμένα τέως κατάφρακτοι προῄεσαν καὶ τοὺς ἵππους ἄγοντες οἱ ἱππεῖς κεκοσμημένους. ἐπὶ πλεῖστον δὲ τὰ πρὸ τῆς πόλεως ἀργύρῳ καὶ χρυσῷ περιελάμπετο, καὶ τῆς ὄψεως ἐκείνης οὐδὲν οὔτε τοῖς σφετέροις ἐπιτερπέστερον οὔτε τοῖς πολεμίοις παρέστη φοβερώτερον. κατεπλήσθη γὰρ ἀφορώντων τό τε ἀρχαῖον τεῖχος ἅπαν καὶ τοῦ ἱεροῦ τὸ βόρειον κλίμα, τάς τε οἰκίας μεστὰς ἦν προκυπτόντων ἰδεῖν, καὶ τῆς πόλεως οὐδὲν ὃ μὴ κεκάλυπτο πλήθει διεφαίνετο. κατάπληξις δὲ δεινὴ καὶ τοῖς τολμηροτάτοις ἐνέπεσε τήν τε δύναμιν ἐπὶ ταὐτὸ πᾶσαν ὁρῶσι καὶ τὸ κάλλος τῶν ὅπλων καὶ τὴν εὐταξίαν τῶν ἀνδρῶν· δοκοῦσί τε ἄν μοι πρὸς ἐκείνην οἱ στασιασταὶ μεταβαλέσθαι τὴν ὄψιν, εἰ μὴ δι’ ὑπερβολὴν ὧν τὸν δῆμον ἔδρασαν κακῶν συγγνώμην παρὰ Ῥωμαίοις ἀπήλπιζον. ἀποκειμένου δὲ τοῦ μετὰ κολάσεως, εἰ παύσαιντο, πολὺ κρείττονα τὸν ἐν πολέμῳ θάνατον ἡγοῦντο. καὶ τὸ χρεὼν δ’ ἐκράτει τούς τε ἀναιτίους τοῖς αἰτίοις συναπολέσθαι καὶ τῇ στάσει τὴν πόλιν.", "st": "5.9.1"}, {"sp": "N", "t": "Τέσσαρσιν μὲν οὖν ἡμέραις οἱ Ῥωμαῖοι καθ’ ἕκαστον τάγμα διετέλεσαν τὰς τροφὰς κομιζόμενοι, τῇ πέμπτῃ δ’ ὡς οὐδὲν ἀπήντα παρὰ τῶν Ἰουδαίων εἰρηνικόν, διχῆ διελὼν τὰ τάγματα Τίτος ἤρχετο τῶν χωμάτων κατά τε τὴν Ἀντωνίαν καὶ τὸ τοῦ Ἰωάννου μνημεῖον, ταύτῃ μὲν τὴν ἄνω πόλιν αἱρήσειν ἐπινοῶν, τὸ δ’ ἱερὸν κατὰ τὴν Ἀντωνίαν· τούτου γὰρ μὴ ληφθέντος οὐδὲ τὸ ἄστυ κατέχειν ἀκίνδυνον ἦν· πρὸς ἑκατέρῳ δὲ μέρει δύο χώματα ἠγείρετο καθ’ ἓν ἑκάστου τάγματος. καὶ τοὺς μὲν παρὰ τὸ μνημεῖον ἐργαζομένους οἵ τε Ἰδουμαῖοι καὶ τὸ μετὰ τοῦ Σίμωνος ὁπλιτικὸν εἶργον ἐπεκθέοντες, τοὺς δὲ πρὸ τῆς Ἀντωνίας οἱ περὶ τὸν Ἰωάννην καὶ τὸ τῶν ζηλωτῶν πλῆθος. ἐπλεονέκτουν δὲ οὐ κατὰ χεῖρα μόνον ἀφ’ ὑψηλοτέρων μαχόμενοι, καὶ τοῖς ὀργάνοις δὲ ἤδη χρῆσθαι μεμαθηκότες· ἡ γὰρ καθ’ ἡμέραν τριβὴ κατὰ μικρὸν ἔθρεψε τὴν ἐμπειρίαν. εἶχον δ’ ὀξυβελεῖς μὲν τριακοσίους, τεσσαράκοντα δὲ τῶν λιθοβόλων, δι’ ὧν τὰ χώματα τοῖς Ῥωμαίοις ἐποίουν δυσέργαστα. Τίτος δὲ σώζεσθαί τε τὴν πόλιν καὶ ἀπόλλυσθαι εἰδὼς ἑαυτῷ, ἅμα καὶ τῇ πολιορκίᾳ προσέκειτο καὶ τοῦ παραινεῖν Ἰουδαίοις μετάνοιαν οὐκ ἠμέλει, τοῖς δ’ ἔργοις ἀνέμισγε συμβουλίαν, καὶ πολλάκις γινώσκων ἀνυτικώτερον ὅπλων τὸν λόγον αὐτός τε σώζεσθαι παρεκάλει παραδόντας τὴν πόλιν ἤδη παρειλημμένην καὶ τὸν Ἰώσηπον καθίει τῇ πατρίῳ γλώσσῃ διαλέγεσθαι, τάχ’ ἂν ἐνδοῦναι πρὸς ὁμόφυλον δοκῶν αὐτούς.", "st": "5.9.2"}, {"sp": "N", "t": "Οὗτος περιιὼν τὸ τεῖχος καὶ πειρώμενος ἔξω τε βέλους εἶναι καὶ ἐν ἐπηκόῳ, πολλὰ κατηντιβόλει φείσασθαι μὲν αὑτῶν καὶ τοῦ δήμου, φείσασθαι δὲ τῆς πατρίδος καὶ τοῦ ἱεροῦ μηδὲ γενέσθαι πρὸς ταῦτα τῶν ἀλλοφύλων ἀπαθεστέρους. Ῥωμαίους μέν γε τοὺς μὴ μετέχοντας ἐντρέπεσθαι τὰ τῶν πολεμίων ἅγια καὶ μέχρι νῦν τὰς χεῖρας ἐπέχειν, τοὺς δ’ ἐντραφέντας αὐτοῖς κἂν περισωθῇ μόνους ἕξοντας ὡρμῆσθαι πρὸς ἀπώλειαν αὐτῶν. ἦ μὴν τὰ καρτερώτερα μὲν αὐτῶν ὁρᾶν τείχη πεπτωκότα, λειπόμενον δὲ τὸ τῶν ἑαλωκότων ἀσθενέστερον· γινώσκειν δὲ τὴν Ῥωμαίων ἰσχὺν ἀνυπόστατον καὶ τὸ δουλεύειν τούτοις οὐκ ἀπείρατον αὐτοῖς. εἰ γὰρ δὴ καὶ πολεμεῖν ὑπὲρ ἐλευθερίας καλόν, χρῆναι τὸ πρῶτον· τὸ δ’ ἅπαξ ὑποπεσόντας καὶ μακροῖς εἴξαντας χρόνοις ἔπειτα ἀποσείεσθαι τὸν ζυγὸν δυσθανατούντων, οὐ φιλελευθέρων εἶναι. δεῖν μέντοι καὶ δεσπότας ἀδοξεῖν ταπεινοτέρους, οὐχ οἷς ὑποχείρια τὰ πάντα. τί γὰρ Ῥωμαίους διαπεφευγέναι, πλὴν εἰ μή τι διὰ θάλπος ἢ κρύος ἄχρηστον; μεταβῆναι γὰρ πρὸς αὐτοὺς πάντοθεν τὴν τύχην, καὶ κατὰ ἔθνος τὸν θεὸν ἐμπεριάγοντα τὴν ἀρχὴν νῦν ἐπὶ τῆς Ἰταλίας εἶναι. νόμον γε μὴν ὡρίσθαι καὶ παρὰ θηρσὶν ἰσχυρότατον καὶ παρὰ ἀνθρώποις, εἴκειν τοῖς δυνατωτέροις καὶ τὸ κρατεῖν παρ’ οἷς ἀκμὴ τῶν ὅπλων εἶναι. διὰ τοῦτο καὶ τοὺς προγόνους αὐτῶν καὶ ταῖς ψυχαῖς καὶ τοῖς σώμασιν ἔτι δὲ καὶ ταῖς ἄλλαις ἀφορμαῖς ἀμείνους ὄντας εἶξαι Ῥωμαίοις, οὐκ ἂν εἰ μὴ τὸν θεὸν ᾔδεσαν σὺν αὐτοῖς τοῦθ’ ὑπομείναντας. αὐτοὺς δὲ τίνι καὶ πεποιθότας ἀντέχειν, ἑαλωκυίας μὲν ἐκ πλείστου τῆς πόλεως μέρους, τῶν δ’ ἔνδον, εἰ καὶ τὰ τείχη παρέμενεν, ἁλώσεως χεῖρον διακειμένων; οὐ γὰρ λανθάνειν Ῥωμαίους τὸν ἐν τῇ πόλει λιμόν, ᾧ νῦν μὲν τὸν δῆμον, μετ’ οὐ πολὺ δὲ διαφθαρήσεσθαι καὶ τοὺς μαχίμους. εἰ γὰρ δὴ καὶ παύσαιντο Ῥωμαῖοι τῆς πολιορκίας μηδ’ ἐπιπίπτοιεν τῇ πόλει ξιφήρεις, αὐτοῖς γε τὸν ἄμαχον πόλεμον ἔνδον παρακαθῆσθαι καθ’ ἑκάστην ὥραν τρεφόμενον, εἰ μὴ καὶ πρὸς τὸν λιμὸν ἆραι τὰ ὅπλα καὶ μάχεσθαι δύνανται μόνοι τε καὶ παθῶν ἐπικρατεῖν. προσετίθει δὲ ὡς καλὸν πρὸ ἀνηκέστου συμφορᾶς μεταβαλέσθαι καὶ πρὸς τὸ σωτήριον ἕως ἔξεστι ῥέψαι· καὶ γὰρ οὐδὲ μνησικακήσειν αὐτοῖς Ῥωμαίους τῶν γεγενημένων, εἰ μὴ μέχρι τέλους ἀπαυθαδίσαιντο· φύσει τε γὰρ ἐν τῷ κρατεῖν ἡμέρους εἶναι καὶ πρὸ τῶν θυμῶν θήσεσθαι τὸ συμφέρον. τοῦτο δ’ εἶναι μήτε τὴν πόλιν ἀνδρῶν κενὴν μήτε τὴν χώραν ἔρημον ἔχειν. διὸ καὶ νῦν Καίσαρα βούλεσθαι δεξιὰν αὐτοῖς παρασχεῖν· οὐ γὰρ ἂν σῶσαί τινα βίᾳ λαβόντα τὴν πόλιν, καὶ μάλιστα μηδ’ ἐν ἐσχάταις συμφοραῖς ὑπακουσάντων παρακαλοῦντι. τοῦ γε μὴν ταχέως τὸ τρίτον τεῖχος ἁλώσεσθαι τὰ προεαλωκότα πίστιν εἶναι· κἂν ἄρρηκτον δὲ ᾖ τὸ ἔρυμα, τὸν λιμὸν ὑπὲρ Ῥωμαίων αὐτοῖς μαχεῖσθαι.", "st": "5.9.3"}, {"sp": "N", "t": "Ταῦτα τὸν Ἰώσηπον παραινοῦντα πολλοὶ μὲν ἔσκωπτον ἀπὸ τοῦ τείχους, πολλοὶ δ’ ἐβλασφήμουν, ἔνιοι δ’ ἔβαλλον. ὁ δ’ ὡς ταῖς φανεραῖς οὐκ ἔπειθε συμβουλίαις, ἐπὶ τὰς ὁμοφύλους μετέβαινεν ἱστορίας ἆ δειλοί, βοῶν, καὶ τῶν ἰδίων ἀμνήμονες συμμάχων, ὅπλοις καὶ χερσὶ πολεμεῖτε Ῥωμαίοις; τίνα γὰρ ἄλλον οὕτως ἐνικήσαμεν; πότε δ’ οὐ θεὸς ὁ κτίσας ἂν ἀδικῶνται Ἰουδαίων ἔκδικος; οὐκ ἐπιστραφέντες ὄψεσθε πόθεν ὁρμώμενοι μάχεσθε καὶ πηλίκον ἐμιάνατε σύμμαχον; οὐκ ἀναμνήσεσθε πατέρων ἔργα δαιμόνια, καὶ τὸν ἅγιον τόνδε χῶρον ἡλίκους ἡμῖν πάλαι πολέμους καθεῖλεν; ἐγὼ μὲν φρίττω τὰ ἔργα τοῦ θεοῦ λέγων εἰς ἀναξίους ἀκοάς· ἀκούετε δ’ ὅμως, ἵνα γνῶτε μὴ μόνον Ῥωμαίοις πολεμοῦντες ἀλλὰ καὶ τῷ θεῷ. βασιλεὺς ὁ τότε Νεχαὼς Αἰγυπτίων, ὁ δ’ αὐτὸς ἐκαλεῖτο καὶ Φαραώ, μυρίᾳ χειρὶ καταβὰς ἥρπασε Σάρραν βασιλίδα, τὴν μητέρα τοῦ γένους ἡμῶν. τί οὖν ὁ ταύτης ἀνὴρ Ἁβραάμ, προπάτωρ δὲ ἡμέτερος; ἆρα τὸν ὑβριστὴν ἠμύνατο τοῖς ὅπλοις, καίτοι ὀκτωκαίδεκα μὲν καὶ τριακοσίους ὑπάρχους ἔχων, δύναμιν δὲ ἐφ’ ἑκάστῳ τούτων ἄπειρον; ἢ αὐτοὺς μὲν ἐρημίαν ἡγήσατο μὴ συμπαρόντος θεοῦ, καθαρὰς δ’ ἀνατείνας τὰς χεῖρας εἰς ὃν νῦν ἐμιάνατε χῶρον ὑμεῖς τὸν ἀνίκητον αὐτῷ βοηθὸν ἐστρατολόγησεν; οὐ μετὰ μίαν ἑσπέραν ἄχραντος μὲν ἡ βασίλισσα ἀνεπέμφθη πρὸς τὸν ἄνδρα, προσκυνῶν δὲ τὸν ὑφ’ ὑμῶν αἱμαχθέντα χῶρον ὁμοφύλῳ φόνῳ καὶ τρέμων ἀπὸ τῶν ἐν νυκτὶ φαντασμάτων ἔφευγεν ὁ Αἰγύπτιος, ἀργύρῳ δὲ καὶ χρυσῷ τοὺς θεοφιλεῖς Ἑβραίους ἐδωρεῖτο; εἴπω τὴν εἰς Αἴγυπτον μετοικίαν τῶν πατέρων; οὐ τυραννούμενοι καὶ βασιλεῦσιν ἀλλοφύλοις ὑποπεπτωκότες τετρακοσίοις ἔτεσι παρὸν ὅπλοις ἀμύνεσθαι καὶ χερσὶ σφᾶς αὐτοὺς ἐπέτρεψαν τῷ θεῷ; τίς οὐκ οἶδεν τὴν παντὸς θηρίου καταπλησθεῖσαν Αἴγυπτον καὶ πάσῃ φθαρεῖσαν νόσῳ, τὴν ἄκαρπον [γῆν], τὸν ἐπιλείποντα Νεῖλον, τὰς ἐπαλλήλους δέκα πληγάς, τοὺς διὰ ταῦτα μετὰ φρουρᾶς προπεμπομένους πατέρας ἡμῶν ἀναιμάκτους ἀκινδύνους, οὓς ὁ θεὸς αὑτῷ νεωκόρους ἦγεν; ἀλλὰ τὴν ὑπὸ Σύρων ἁρπαγεῖσαν ἁγίαν ἡμῖν λάρνακα οὐκ ἐστέναξε μὲν ἡ Παλαιστίνη καὶ Δαγὼν τὸ ξόανον, ἐστέναξε δὲ πᾶν τὸ τῶν ἁρπασαμένων ἔθνος, σηπόμενοι δὲ τὰ κρυπτὰ τοῦ σώματος καὶ δι’ αὐτῶν τὰ σπλάγχνα μετὰ τῶν σιτίων καταφέροντες, χερσὶ ταῖς λῃσαμέναις ἀνεκόμισαν κυμβάλων καὶ τυμπάνων ἤχῳ καὶ πᾶσι μειλικτηρίοις ἱλασκόμενοι τὸ ἅγιον; θεὸς ἦν ὁ ταῦτα πατράσιν ἡμετέροις στρατηγῶν, ὅτι τὰς χεῖρας καὶ τὰ ὅπλα παρέντες αὐτῷ κρῖναι τὸ ἔργον ἐπέτρεψαν. βασιλεὺς Ἀσσυρίων Σενναχηρεὶμ ὅτε πᾶσαν τὴν Ἀσίαν ἐπισυρόμενος τήνδε περιεστρατοπεδεύσατο τὴν πόλιν, ἆρα χερσὶν ἀνθρωπίναις ἔπεσεν; οὐχ αἱ μὲν ἀπὸ τῶν ὅπλων ἠρεμοῦσαι ἐν προσευχαῖς ἦσαν, ἄγγελος δὲ τοῦ θεοῦ μιᾷ νυκτὶ τὴν ἄπειρον στρατιὰν ἐλυμήνατο, καὶ μεθ’ ἡμέραν ἀναστὰς ὁ Ἀσσύριος ὀκτωκαίδεκα μυριάδας ἐπὶ πεντακισχιλίοις νεκρῶν εὗρε, μετὰ δὲ τῶν καταλειπομένων ἀνόπλους καὶ μὴ διώκοντας Ἑβραίους ἔφυγεν; ἴστε καὶ τὴν ἐν Βαβυλῶνι δουλείαν, ἔνθα μετανάστης ὁ λαὸς ὢν ἔτεσιν ἑβδομήκοντα οὐ πρότερον εἰς ἐλευθερίαν ἀνεχαίτισεν ἢ Κῦρον τοῦτο χαρίσασθαι τῷ θεῷ· προυπέμφθησαν γοῦν ὑπ’ αὐτοῦ, καὶ πάλιν τὸν αὑτῶν σύμμαχον ἐνεωκόρουν. καθόλου δ’ εἰπεῖν, οὐκ ἔστιν ὅ τι κατώρθωσαν οἱ πατέρες ἡμῶν τοῖς ὅπλοις ἢ δίχα τούτων διήμαρτον ἐπιτρέψαντες τῷ θεῷ· μένοντες μέν γε κατὰ χώραν ἐνίκων ὡς ἐδόκει τῷ κριτῇ, μαχόμενοι δὲ ἔπταισαν ἀεί. τοῦτο μέν, ἡνίκα βασιλεὺς Βαβυλωνίων ἐπολιόρκει ταύτην τὴν πόλιν, συμβαλὼν Σεδεκίας ὁ ἡμέτερος βασιλεὺς παρὰ τὰς Ἱερεμίου προφητείας αὐτός τε ἑάλω καὶ τὸ ἄστυ μετὰ τοῦ ναοῦ κατασκαπτόμενον εἶδε· καίτοι πόσῳ μετριώτερος ὁ μὲν βασιλεὺς ἐκεῖνος τῶν ὑμετέρων ἡγεμόνων ἦν, ὁ δ’ ὑπ’ αὐτῷ λαὸς ὑμῶν. βοῶντα γοῦν τὸν Ἱερεμίαν, ὡς ἀπέχθοιντο μὲν τῷ θεῷ διὰ τὰς εἰς αὐτὸν πλημμελείας, ἁλώσοιντο δ’ εἰ μὴ παραδοῖεν τὴν πόλιν, οὔθ’ ὁ βασιλεὺς οὔθ’ ὁ δῆμος ἀνεῖλεν. ἀλλ’ ὑμεῖς, ἵν’ ἐάσω τἄνδον, οὐ γὰρ ἂν ἑρμηνεῦσαι δυναίμην τὰς παρανομίας ὑμῶν ἀξίως, ἐμὲ τὸν παρακαλοῦντα πρὸς σωτηρίαν ὑμᾶς βλασφημεῖτε καὶ βάλλετε, παροξυνόμενοι πρὸς τὰς ὑπομνήσεις τῶν ἁμαρτημάτων καὶ μηδὲ τοὺς λόγους φέροντες ὧν τἆργα δρᾶτε καθ’ ἡμέραν. τοῦτο δ’, ἡνίκα Ἀντιόχου τοῦ κληθέντος Ἐπιφανοῦς προσκαθεζομένου τῇ πόλει πολλὰ πρὸς τὸ θεῖον ἐξυβρικότος, οἱ πρόγονοι μετὰ τῶν ὅπλων προῆλθον, αὐτοὶ μὲν ἀπεσφάγησαν ἐν τῇ μάχῃ, διηρπάγη δὲ τὸ ἄστυ τοῖς πολεμίοις, ἠρημώθη δ’ ἔτη τρία καὶ μῆνας ἓξ τὸ ἅγιον. καὶ τί δεῖ τἆλλα λέγειν; ἀλλὰ Ῥωμαίους τίς ἐστρατολόγησε κατὰ τοῦ ἔθνους; οὐχ ἡ τῶν ἐπιχωρίων ἀσέβεια; πόθεν δ’ ἠρξάμεθα δουλείας; ἆρ’ οὐχὶ ἐκ στάσεως τῶν προγόνων, ὅτε ἡ Ἀριστοβούλου καὶ Ὑρκανοῦ μανία καὶ πρὸς ἀλλήλους ἔρις Πομπήιον ἐπήγαγεν τῇ πόλει καὶ Ῥωμαίοις ὑπέταξεν ὁ θεὸς τοὺς οὐκ ἀξίους ἐλευθερίας; τρισὶ γοῦν μησὶ πολιορκηθέντες ἑαυτοὺς παρέδοσαν, οὔθ’ ἁμαρτόντες εἰς τὰ ἅγια καὶ τοὺς νόμους ἡλίκα ὑμεῖς καὶ πολὺ μείζοσιν ἀφορμαῖς πρὸς τὸν πόλεμον χρώμενοι. τὸ δ’ Ἀντιγόνου τέλος τοῦ Ἀριστοβούλου παιδὸς οὐκ ἴσμεν, οὗ βασιλεύοντος ὁ θεὸς ἁλώσει πάλιν τὸν λαὸν ἤλαυνε πλημμελοῦντα, καὶ Ἡρώδης μὲν ὁ Ἀντιπάτρου Σόσσιον, Σόσσιος δὲ Ῥωμαίων στρατιὰν ἤγαγεν, περισχεθέντες δ’ ἐπὶ μῆνας ἓξ ἐπολιορκοῦντο, μέχρι δίκας τῶν ἁμαρτιῶν δόντες ἑάλωσαν καὶ διηρπάγη τοῖς πολεμίοις ἡ πόλις; οὕτως οὐδέποτε τῷ ἔθνει τὰ ὅπλα δέδοται, τῷ δὲ πολεμεῖσθαι καὶ τὸ ἁλώσεσθαι πάντως πρόσεστι. δεῖ γάρ, οἶμαι, τοὺς χωρίον ἅγιον νεμομένους ἐπιτρέπειν πάντα τῷ θεῷ δικάζειν καὶ καταφρονεῖν τότε χειρὸς ἀνθρωπίνης, ὅταν αὐτοὶ πείθωσι τὸν ἄνω δικαστήν. ὑμῖν δὲ τί τῶν εὐλογηθέντων ὑπὸ τοῦ νομοθέτου πέπρακται; τί δὲ τῶν ὑπ’ ἐκείνου κατηραμένων παραλέλειπται; πόσῳ δ’ ἐστὲ τῶν τάχιον ἁλόντων ἀσεβέστεροι; οὐ τὰ κρυπτὰ μὲν τῶν ἁμαρτημάτων ἠδοξήκατε, κλοπὰς λέγω καὶ ἐνέδρας καὶ μοιχείας, ἁρπαγαῖς δ’ ἐρίζετε καὶ φόνοις καὶ ξένας καινοτομεῖτε κακίας ὁδούς, ἐκδοχεῖον δὲ πάντων τὸ ἱερὸν γέγονεν καὶ χερσὶν ἐμφυλίοις ὁ θεῖος μεμίανται χῶρος, ὃν καὶ Ῥωμαῖοι πόρρωθεν προσεκύνουν, πολλὰ τῶν ἰδίων ἐθῶν εἰς τὸν ὑμέτερον παραλύοντες νόμον. εἶτ’ ἐπὶ τούτοις τὸν ἀσεβηθέντα σύμμαχον προσδοκᾶτε; πάνυ γοῦν ἐστὲ δίκαιοι ἱκέται καὶ χερσὶ καθαραῖς τὸν βοηθὸν ὑμῶν παρακαλεῖτε. τοιαύταις ὁ βασιλεὺς ἡμῶν ἱκέτευσεν ἐπὶ τὸν Ἀσσύριον, ὅτε τὸν μέγαν ἐκεῖνον στρατὸν μιᾷ νυκτὶ κατέστρωσεν ὁ θεός; ὅμοια δὲ τῷ Ἀσσυρίῳ Ῥωμαῖοι δρῶσιν, ἵνα καὶ ἄμυναν ὑμεῖς ὁμοίαν ἐλπίσητε; οὐχ ὁ μὲν χρήματα παρὰ τοῦ βασιλέως ἡμῶν λαβὼν ἐφ’ ᾧ μὴ πορθήσει τὴν πόλιν κατέβη παρὰ τοὺς ὅρκους ἐμπρῆσαι τὸν ναόν, Ῥωμαῖοι δὲ τὸν συνήθη δασμὸν αἰτοῦσιν, ὃν οἱ πατέρες ἡμῶν τοῖς ἐκείνων πατράσι παρέσχον; καὶ τούτου τυχόντες οὔτε πορθοῦσι τὴν πόλιν οὔτε ψαύουσι τῶν ἁγίων, διδόασι δὲ ὑμῖν τὰ ἄλλα, γενεάς τ’ ἐλευθέρας καὶ κτήσεις τὰς ἑαυτῶν νέμεσθαι καὶ τοὺς ἱεροὺς νόμους σώζουσι. μανία δὴ τὸν θεὸν προσδοκᾶν ἐπὶ δικαίοις οἷος ἐπ’ ἀδίκοις ἐφάνη. καὶ παραχρῆμα δὲ ἀμύνειν οἶδεν ὅταν δέῃ· τοὺς γοῦν Ἀσσυρίους κατὰ νύκτα τὴν πρώτην παραστρατοπεδευσαμένους ἔκλασεν· ὥστ’ εἰ καὶ τὴν ἡμετέραν γενεὰν ἐλευθερίας ἢ Ῥωμαίους κολάσεως ἀξίους ἔκρινε, κἂν παραχρῆμα καθάπερ τοῖς Ἀσσυρίοις ἐνέσκηψεν, ὅτε τοῦ ἔθνους ἥπτετο Πομπήιος, ὅτε μετ’ αὐτὸν ἀνῄει Σόσσιος, ὅτε Οὐεσπασιανὸς ἐπόρθει τὴν Γαλιλαίαν, τὰ τελευταῖα νῦν, ὅτε ἤγγιζε Τίτος τῇ πόλει. καίτοι Μάγνος μὲν καὶ Σόσσιος πρὸς τῷ μηδὲν παθεῖν καὶ ἀνὰ κράτος ἔλαβον τὴν πόλιν, Οὐεσπασιανὸς δ’ ἐκ τοῦ πρὸς ἡμᾶς πολέμου καὶ βασιλείας ἤρξατο· Τίτῳ μὲν γὰρ καὶ πηγαὶ πλουσιώτεραι ῥέουσιν αἱ ξηρανθεῖσαι πρότερον ὑμῖν· πρὸ γοῦν τῆς αὐτοῦ παρουσίας τήν τε Σιλωὰν ἐπιλείπουσαν ἴστε καὶ τὰς πρὸ τοῦ ἄστεος ἁπάσας, ὥστε πρὸς ἀμφορέας ὠνεῖσθαι τὸ ὕδωρ· τὸ δὲ νῦν οὕτως πληθύουσι τοῖς πολεμίοις ὑμῶν, ὡς μὴ μόνον αὐτοῖς καὶ κτήνεσιν, ἀλλὰ καὶ κήποις διαρκεῖν. τό γε μὴν τέρας τοῦτο πεπείραται καὶ πρότερον ἐφ’ ἁλώσει τῆς πόλεως γεγενημένον, ὅτε ὁ προειρημένος Βαβυλώνιος ἐπεστράτευσεν, ὃς τήν τε πόλιν ἑλὼν ἐνέπρησε καὶ τὸν ναόν, οὐδὲν οἶμαι τῶν τότε ἠσεβηκότων τηλικοῦτον ἡλίκα ὑμεῖς· ὥστε ἐγὼ πεφευγέναι μὲν ἐκ τῶν ἁγίων οἶμαι τὸ θεῖον, ἑστάναι δὲ παρ’ οἷς πολεμεῖτε νῦν. ἀλλ’ ἀνὴρ μὲν ἀγαθὸς οἰκίαν ἀσελγῆ φεύξεται καὶ τοὺς ἐν αὐτῇ στυγήσει, τὸν δὲ θεὸν ἔτι πείθεσθε τοῖς οἰκείοις κακοῖς παραμένειν, ὃς τά τε κρυπτὰ πάντα ἐφορᾷ καὶ τῶν σιγωμένων ἀκούει; τί δὲ σιγᾶται παρ’ ὑμῖν ἢ τί κρύπτεται; τί δ’ οὐχὶ καὶ τοῖς ἐχθροῖς φανερὸν γέγονε; πομπεύετε γὰρ παρανομοῦντες καὶ καθ’ ἡμέραν ἐρίζετε, τίς χείρων γένηται, τῆς ἀδικίας ὥσπερ ἀρετῆς ἐπίδειξιν ποιούμενοι.", "st": "5.9.4"}, {"sp": "N", "t": "καταλείπεται δὲ ὅμως ἔτι σωτηρίας ὁδός, ἐὰν θέλητε, καὶ τὸ θεῖον εὐδιάλλακτον ἐξομολογουμένοις καὶ μετανοοῦσιν. ὦ σιδήρειοι, ῥίψατε τὰς πανοπλίας, λάβετε ἤδη κατερειπομένης αἰδῶ πατρίδος, ἐπιστράφητε καὶ θεάσασθε τὸ κάλλος ἧς προδίδοτε, οἷον ἄστυ, οἷον ἱερόν, ὅσων ἐθνῶν δῶρα. ἐπὶ ταῦτά τις ὁδηγεῖ φλόγα; ταῦτά τις μηκέτ’ εἶναι θέλει; καὶ τί σώζεσθαι τούτων ἀξιώτερον, ἄτεγκτοι καὶ λίθων ἀπαθέστεροι. καὶ εἰ μὴ ταῦτα γνησίοις ὄμμασιν βλέπετε, γενεὰς γοῦν ὑμετέρας οἰκτείρατε, καὶ πρὸ ὀφθαλμῶν ἑκάστῳ γενέσθω τέκνα καὶ γυνὴ καὶ γονεῖς, οὓς ἀναλώσει μετὰ μικρὸν ἢ λιμὸς ἢ πόλεμος. οἶδ’ ὅτι μοι συγκινδυνεύει μήτηρ καὶ γυνὴ καὶ γένος οὐκ ἄσημον καὶ πάλαι λαμπρὸς οἶκος, καὶ τάχα δοκῶ διὰ ταῦτα συμβουλεύειν. ἀποκτείνατε αὐτούς, λάβετε μισθὸν τῆς ἑαυτῶν σωτηρίας τὸ ἐμὸν αἷμα· κἀγὼ θνήσκειν ἕτοιμος, εἰ μετ’ ἐμὲ σωφρονεῖν μέλλετε.", "st": "5.9.4"}, {"sp": "N", "t": "Τοιαῦτα τοῦ Ἰωσήπου μετὰ δακρύων ἐμβοῶντος οἱ στασιασταὶ μὲν οὔτε ἐνέδοσαν οὔτ’ ἀσφαλῆ τὴν μεταβολὴν ἔκριναν, ὁ δὲ δῆμος ἐκινήθη πρὸς αὐτομολίαν. καὶ οἱ μὲν τὰς κτήσεις ἐλαχίστου πωλοῦντες, οἱ δὲ τὰ πολυτελέστερα τῶν κειμηλίων, τοὺς μὲν χρυσοῦς, ὡς μὴ φωραθεῖεν ὑπὸ τῶν λῃστῶν, κατέπινον, ἔπειτα πρὸς τοὺς Ῥωμαίους διαδιδράσκοντες, ὁπότε κατενέγκαιεν εὐπόρουν πρὸς ἃ δέοιντο. διηφίει γὰρ τοὺς πολλοὺς ὁ Τίτος εἰς τὴν χώραν ὅποι βούλοιτο ἕκαστος, καὶ τοῦτ’ αὐτὸ μᾶλλον πρὸς αὐτομολίαν παρεκάλει τῶν μὲν εἴσω κακῶν στερησομένους, μὴ δουλεύσοντας δὲ Ῥωμαίοις. οἱ δὲ περὶ τὸν Ἰωάννην καὶ τὸν Σίμωνα περιεφύλαττον τὰς τούτων ἐξόδους πλέον ἢ τὰς Ῥωμαίων εἰσόδους, καὶ σκιάν τις ὑπονοίας παρασχὼν μόνον εὐθέως ἀπεσφάττετο.", "st": "5.10.1"}, {"sp": "N", "t": "Τοῖς γε μὴν εὐπόροις καὶ τὸ μένειν πρὸς ἀπώλειαν ἴσον ἦν· προφάσει γὰρ αὐτομολίας ἀνῃρεῖτό τις διὰ τὴν οὐσίαν. τῷ λιμῷ δ’ ἡ ἀπόνοια τῶν στασιαστῶν συνήκμαζε, καὶ καθ’ ἡμέραν ἀμφότερα προσεξεκαίετο τὰ δεινά. φανερὸς μὲν γὰρ οὐδαμοῦ σῖτος ἦν, ἐπεισπηδῶντες δὲ διηρεύνων τὰς οἰκίας, ἔπειθ’ εὑρόντες μὲν ὡς ἀρνησαμένους ᾐκίζοντο, μὴ εὑρόντες δ’ ὡς ἐπιμελέστερον κρύψαντας ἐβασάνιζον. τεκμήριον δὲ τοῦ τ’ ἔχειν καὶ μὴ τὰ σώματα τῶν ἀθλίων, ὧν οἱ μὲν ἔτι συνεστῶτες εὐπορεῖν τροφῆς ἐδόκουν, οἱ τηκόμενοι δὲ ἤδη παρωδεύοντο, καὶ κτείνειν ἄλογον ἐδόκει τοὺς ὑπ’ ἐνδείας τεθνηξομένους αὐτίκα. πολλοὶ δὲ λάθρα τὰς κτήσεις ἑνὸς ἀντηλλάξαντο μέτρου πυρῶν μὲν εἰ πλουσιώτεροι τυγχάνοιεν ὄντες, οἱ δὲ πενέστεροι κριθῆς, ἔπειτα κατακλείοντες αὑτοὺς εἰς τὰ μυχαίτατα τῶν οἰκιῶν τινὲς μὲν ὑπ’ ἄκρας ἐνδείας ἀνέργαστον τὸν σῖτον ἤσθιον, οἱ δ’ ἔπεσσον ὡς ἥ τε ἀνάγκη καὶ τὸ δέος παρῄνει. καὶ τράπεζα μὲν οὐδαμοῦ παρετίθετο, τοῦ δὲ πυρὸς ὑφέλκοντες ἔτ’ ὠμὰ τὰ σιτία διήρπαζον.", "st": "5.10.2"}, {"sp": "N", "t": "Ἐλεεινὴ δὲ ἦν ἡ τροφὴ καὶ δακρύων ἄξιος ἡ θέα, τῶν μὲν δυνατωτέρων πλεονεκτούντων, τῶν δ’ ἀσθενῶν ὀδυρομένων. πάντων μὲν δὴ παθῶν ὑπερίσταται λιμός, οὐδὲν δ’ οὕτως ἀπόλλυσιν ὡς αἰδῶ· τὸ γὰρ ἄλλως ἐντροπῆς ἄξιον ἐν τούτῳ καταφρονεῖται. γυναῖκες γοῦν ἀνδρῶν καὶ παῖδες πατέρων, καὶ τὸ οἰκτρότατον, μητέρες νηπίων ἐξήρπαζον ἐξ αὐτῶν τῶν στομάτων τὰς τροφάς, καὶ τῶν φιλτάτων ἐν χερσὶ μαραινομένων οὐκ ἦν φειδὼ τοὺς τοῦ ζῆν ἀφελέσθαι σταλαγμούς. τοιαῦτα δ’ ἐσθίοντες ὅμως οὐ διελάνθανον, πανταχοῦ δ’ ἐφίσταντο οἱ στασιασταὶ καὶ τούτων ταῖς ἁρπαγαῖς. ὁπότε γὰρ κατίδοιεν ἀποκεκλεισμένην οἰκίαν, σημεῖον ἦν τοῦτο τοὺς ἔνδον προσφέρεσθαι τροφῆς· εὐθέως δ’ ἐξαράξαντες τὰς θύρας εἰσεπήδων, καὶ μόνον οὐκ ἐκ τῶν φαρύγγων ἀναθλίβοντες τὰς ἀκόλους ἀνέφερον. ἐτύπτοντο δὲ γέροντες ἀντεχόμενοι τῶν σιτίων, καὶ κόμης ἐσπαράττοντο γυναῖκες συγκαλύπτουσαι τὰ ἐν χερσίν. οὐδέ τις ἦν οἶκτος πολιᾶς ἢ νηπίων, ἀλλὰ συνεπαίροντες τὰ παιδία τῶν ψωμῶν ἐκκρεμάμενα κατέσειον εἰς ἔδαφος. τοῖς δὲ φθάσασι τὴν εἰσδρομὴν αὐτῶν καὶ προκαταπιοῦσι τὸ ἁρπαγησόμενον ὡς ἀδικηθέντες ἦσαν ὠμότεροι. δεινὰς δὲ βασάνων ὁδοὺς ἐπενόουν πρὸς ἔρευναν τροφῆς, ὀρόβοις μὲν ἐμφράττοντες τοῖς ἀθλίοις τοὺς τῶν αἰδοίων πόρους, ῥάβδοις δ’ ὀξείαις ἀναπείροντες τὰς ἕδρας, τὰ φρικτὰ δὲ καὶ ἀκοαῖς ἔπασχέ τις εἰς ἐξομολόγησιν ἑνὸς ἄρτου καὶ ἵνα μηνύσῃ δράκα μίαν κεκρυμμένην ἀλφίτων. οἱ βασανισταὶ δ’ οὐκ ἐπείνων, καὶ γὰρ ἧττον ἂν ὠμὸν ἦν τὸ μετ’ ἀνάγκης, γυμνάζοντες δὲ τὴν ἀπόνοιαν καὶ προπαρασκευάζοντες αὑτοῖς εἰς τὰς ἑξῆς ἡμέρας ἐφόδια. τοῖς δ’ ἐπὶ τὴν Ῥωμαίων φρουρὰν νύκτωρ ἐξερπύσασιν ἐπὶ λαχάνων συλλογὴν ἀγρίων καὶ πόας ὑπαντῶντες, ὅτ’ ἤδη διαπεφευγέναι τοὺς πολεμίους ἐδόκουν, ἀφήρπαζον τὰ κομισθέντα, καὶ πολλάκις ἱκετευόντων καὶ τὸ φρικτὸν ἐπικαλουμένων ὄνομα τοῦ θεοῦ μεταδοῦναί τι μέρος αὐτοῖς ὧν κινδυνεύσαντες ἤνεγκαν, οὐδ’ ὁτιοῦν μετέδοσαν· ἀγαπητὸν δ’ ἦν τὸ μὴ καὶ προσαπολέσθαι σεσυλημένον.", "st": "5.10.3"}, {"sp": "N", "t": "Οἱ μὲν δὴ ταπεινότεροι τοιαῦτα πρὸς τῶν δορυφόρων ἔπασχον, οἱ δ’ ἐν ἀξιώματι καὶ πλούτῳ πρὸς τοὺς τυράννους ἀνήγοντο. τούτων οἱ μὲν ἐπιβουλὰς ψευδεῖς ἐπικαλούμενοι διεφθείροντο, οἱ δὲ ὡς προδιδοῖεν Ῥωμαίοις τὴν πόλιν, τὸ δ’ ἑτοιμότατον ἦν μηνυτὴς ὑπόβλητος ὡς αὐτομολεῖν διεγνωκότων. ὁ δ’ ὑπὸ Σίμωνος γυμνωθεὶς πρὸς Ἰωάννην ἀνεπέμπετο, καὶ τὸν ὑπὸ Ἰωάννου σεσυλημένον ὁ Σίμων μετελάμβανεν· ἀντιπροέπινον δὲ ἀλλήλοις τὸ αἷμα τῶν δημοτῶν καὶ τὰ πτώματα τῶν ἀθλίων διεμερίζοντο. καὶ τοῦ μὲν κρατεῖν στάσις ἦν ἐν ἀμφοτέροις, τῶν δ’ ἀσεβημάτων ὁμόνοια· καὶ γὰρ ὁ μὴ μεταδοὺς ἐκ τῶν ἀλλοτρίων κακῶν θατέρῳ μονοτρόπως ἐδόκει πονηρός, καὶ ὁ μὴ μεταλαβὼν ὡς ἀγαθοῦ τινος ἤλγει τὸν νοσφισμὸν τῆς ὠμότητος.", "st": "5.10.4"}, {"sp": "N", "t": "Καθ’ ἕκαστον μὲν οὖν ἐπεξιέναι τὴν παρανομίαν αὐτῶν ἀδύνατον, συνελόντα δὲ εἰπεῖν, μήτε πόλιν ἄλλην τοιαῦτα πεπονθέναι μήτε γενεὰν ἐξ αἰῶνος γεγονέναι κακίας γονιμωτέραν, οἵ γε τελευταῖον καὶ τὸ γένος ἐφαύλιζον τῶν Ἑβραίων, ὡς ἧττον ἀσεβεῖς δοκοῖεν πρὸς ἀλλοτρίους, ἐξωμολογήσαντο δ’ ὅπερ ἦσαν εἶναι δοῦλοι καὶ σύγκλυδες καὶ νόθα τοῦ ἔθνους φθάρματα. τὴν μέν γε πόλιν ἀνέτρεψαν αὐτοί, Ῥωμαίους δ’ ἄκοντας ἠνάγκασαν ἐπιγραφῆναι σκυθρωπῷ κατορθώματι καὶ μόνον οὐχ εἵλκυσαν ἐπὶ τὸν ναὸν βραδῦνον τὸ πῦρ. ἀμέλει καιόμενον ἐκ τῆς ἄνω πόλεως ἀφορῶντες οὔτ’ ἤλγησαν οὔτ’ ἐδάκρυσαν, ἀλλὰ ταῦτα τὰ πάθη παρὰ Ῥωμαίοις εὑρέθη. καὶ ταῦτα μὲν κατὰ χώραν ὕστερον μετ’ ἀποδείξεως τῶν πραγμάτων ἐροῦμεν.", "st": "5.10.5"}, {"sp": "N", "t": "Τίτῳ δὲ τὰ μὲν χώματα προύκοπτεν καίτοι πολλὰ κακουμένων ἀπὸ τοῦ τείχους τῶν στρατιωτῶν, πέμψας δ’ αὐτὸς μοῖραν τῶν ἱππέων ἐκέλευσεν τοὺς κατὰ τὰς φάραγγας ἐπὶ συγκομιδῇ τροφῆς ἐξιόντας ἐνεδρεύειν. ἦσαν δέ τινες καὶ τῶν μαχίμων οὐκέτι διαρκούμενοι ταῖς ἁρπαγαῖς, τὸ δὲ πλέον ἐκ τοῦ δήμου πένητες, οὓς αὐτομολεῖν ἀπέτρεπε τὸ περὶ τῶν οἰκείων δέος· οὔτε γὰρ λήσεσθαι τοὺς στασιαστὰς ἤλπιζον μετὰ γυναικῶν καὶ παιδίων διαδιδράσκοντες καὶ καταλιπεῖν τοῖς λῃσταῖς ταῦτα οὐχ ὑπέμενον ὑπὲρ αὐτῶν σφαγησόμενα· τολμηροὺς δὲ πρὸς τὰς ἐξόδους ὁ λιμὸς ἐποίει, καὶ κατελείπετο λανθάνοντας τοὺς πολεμίους ἁλίσκεσθαι. λαμβανόμενοι δὲ κατ’ ἀνάγκην ἠμύνοντο, καὶ μετὰ μάχην ἱκετεύειν ἄωρον ἐδόκει. μαστιγούμενοι δὴ καὶ προβασανιζόμενοι τοῦ θανάτου πᾶσαν αἰκίαν ἀνεσταυροῦντο τοῦ τείχους ἀντικρύ. Τίτῳ μὲν οὖν οἰκτρὸν τὸ πάθος κατεφαίνετο πεντακοσίων ἑκάστης ἡμέρας ἔστι δὲ ὅτε καὶ πλειόνων ἁλισκομένων, οὔτε δὲ τοὺς βίᾳ ληφθέντας ἀφεῖναι ἀσφαλὲς καὶ φυλάττειν τοσούτους φρουρὰν τῶν φυλαξόντων ἑώρα· τό γε μὴν πλέον οὐκ ἐκώλυεν τάχ’ ἂν ἐνδοῦναι πρὸς τὴν ὄψιν ἐλπίσας αὐτούς, εἰ μὴ παραδοῖεν, ὅμοια πεισομένους. προσήλουν δὲ οἱ στρατιῶται δι’ ὀργὴν καὶ μῖσος τοὺς ἁλόντας ἄλλον ἄλλῳ σχήματι πρὸς χλεύην, καὶ διὰ τὸ πλῆθος χώρα τε ἐνέλειπε τοῖς σταυροῖς καὶ σταυροὶ τοῖς σώμασιν.", "st": "5.11.1"}, {"sp": "N", "t": "Οἱ στασιασταὶ δὲ τοσοῦτον ἀπεδέησαν τοῦ μεταβαλέσθαι πρὸς τὸ πάθος, ὥστε καὶ τοὐναντίον αὐτοὶ σοφίσασθαι πρὸς τὸ λοιπὸν πλῆθος. σύροντες γὰρ τοὺς τῶν αὐτομόλων οἰκείους ἐπὶ τὸ τεῖχος καὶ τῶν δημοτῶν τοὺς ἐπὶ πίστιν ὡρμημένους, οἷα πάσχουσιν οἱ Ῥωμαίοις προσφεύγοντες ἐπεδείκνυσαν καὶ τοὺς κεκρατημένους ἱκέτας ἔλεγον, οὐκ αἰχμαλώτους. τοῦτο πολλοὺς τῶν αὐτομολεῖν ὡρμημένων μέχρι τἀληθὲς ἐγνώσθη κατέσχεν· εἰσὶ δ’ οἳ καὶ παραχρῆμα διέδρασαν ὡς ἐπὶ βέβαιον τιμωρίαν, ἀνάπαυσιν ἡγούμενοι τὸν ἐκ τῶν πολεμίων θάνατον ἐν λιμοῦ συγκρίσει. πολλοὺς δὲ καὶ χειροκοπῆσαι κελεύσας Τίτος τῶν ἑαλωκότων, ὡς μὴ δοκοῖεν αὐτόμολοι καὶ πιστεύοιντο διὰ τὴν συμφοράν, εἰσέπεμψε πρὸς τὸν Σίμωνα καὶ τὸν Ἰωάννην, νῦν γε ἤδη παύσασθαι παραινῶν καὶ μὴ πρὸς ἀναίρεσιν τῆς πόλεως αὐτὸν βιάζεσθαι, κερδῆσαι δ’ ἐκ τῆς ἐν ὑστάτοις μεταμελείας τάς τε αὐτῶν ψυχὰς καὶ τηλικαύτην πατρίδα καὶ ναὸν ἀκοινώνητον ἄλλοις. περιιὼν δὲ τὰ χώματα τοὺς ἐργαζομένους ἅμα κατήπειγεν ὡς οὐκ εἰς μακρὰν ἀκολουθήσων ἔργοις τῷ λόγῳ. πρὸς ταῦτα αὐτόν τε ἐβλασφήμουν ἀπὸ τοῦ τείχους Καίσαρα καὶ τὸν πατέρα αὐτοῦ, καὶ τοῦ μὲν θανάτου καταφρονεῖν ἐβόων, ᾑρῆσθαι γὰρ αὐτὸν πρὸ δουλείας καλῶς, ἐργάσεσθαι δὲ ὅσα ἂν δύνωνται κακὰ Ῥωμαίους ἕως ἐμπνέωσι, πατρίδος δὲ οὐ μέλειν τῆς ὡς αὐτός φησιν ἀπολουμένης, καὶ ναοῦ [ἀπολομένου] ἀμείνω τούτου τῷ θεῷ τὸν κόσμον εἶναι. σωθήσεσθαί γε μὴν καὶ τοῦτον ὑπὸ τοῦ κατοικοῦντος, ὃν καὶ αὐτοὶ σύμμαχον ἔχοντες πᾶσαν χλευάσειν ἀπειλὴν ὑστεροῦσαν ἔργων· τὸ γὰρ τέλος εἶναι τοῦ θεοῦ. τοιαῦτα ταῖς λοιδορίαις ἀναμίσγοντες ἐκεκράγεσαν.", "st": "5.11.2"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ καὶ ὁ Ἐπιφανὴς Ἀντίοχος παρῆν ἄλλους τε ὁπλίτας συχνοὺς ἔχων καὶ περὶ αὑτὸν στῖφος Μακεδόνων καλούμενον, ἥλικας πάντας, ὑψηλούς, ὀλίγον ὑπὲρ ἀντίπαιδας, τὸν Μακεδονικὸν τρόπον ὡπλισμένους τε καὶ πεπαιδευμένους, ὅθεν καὶ τὴν ἐπίκλησιν εἶχον ὑστεροῦντες οἱ πολλοὶ τοῦ γένους. εὐδαιμονῆσαι γὰρ δὴ μάλιστα τῶν ὑπὸ Ῥωμαίοις βασιλέων τὸν Κομμαγηνὸν συνέβη πρὶν γεύσασθαι μεταβολῆς· ἀπέφηνε δὲ κἀκεῖνος ἐπὶ γήρως, ὡς οὐδένα χρὴ λέγειν πρὸ θανάτου μακάριον. ἀλλ’ ὅ γε παῖς ἀκμάζοντος αὐτοῦ τηνικαῦτα παρὼν θαυμάζειν ἔφασκε, τί δήποτε Ῥωμαῖοι κατοκνοῖεν προσιέναι τῷ τείχει· πολεμιστὴς δέ τις αὐτὸς ἦν καὶ φύσει παράβολος κατά τε ἀλκὴν τοσοῦτος, ὡς ὀλίγῳ τὰ τῆς τόλμης διαμαρτάνειν. μειδιάσαντος δὲ τοῦ Τίτου καὶ κοινὸς ὁ πόνος εἰπόντος, ὡς εἶχεν ὥρμησεν ὁ Ἀντίοχος μετὰ τῶν Μακεδόνων πρὸς τὸ τεῖχος. αὐτὸς μὲν οὖν διά τε ἰσχὺν καὶ κατ’ ἐμπειρίαν ἐφυλάττετο τὰ τῶν Ἰουδαίων βέλη τοξεύων εἰς αὐτούς, τὰ μειράκια δὲ αὐτῷ συνετρίβη πάντα πλὴν ὀλίγων· διὰ γὰρ αἰδῶ τῆς ὑποσχέσεως προσεφιλονείκει μαχόμενα· καὶ τέλος ἀνεχώρουν τραυματίαι πολλοί, συννοοῦντες ὅτι καὶ τοῖς ἀληθῶς Μακεδόσιν, εἰ μέλλοιεν κρατεῖν, δεῖ τῆς Ἀλεξάνδρου τύχης.", "st": "5.11.3"}, {"sp": "N", "t": "Τοῖς δὲ Ῥωμαίοις ἀρξαμένοις δωδεκάτῃ μηνὸς Ἀρτεμισίου συνετελέσθη τὰ χώματα μόλις ἐνάτῃ καὶ εἰκάδι ταῖς δεχεπτὰ συνεχῶς πονουμένων ἡμέραις· μέγιστα γὰρ ἐχώσθη τὰ τέσσαρα, καὶ θάτερον μὲν τὸ ἐπὶ τὴν Ἀντωνίαν ὑπὸ τοῦ πέμπτου τάγματος ἐβλήθη κατὰ μέσον τῆς Στρουθίου καλουμένης κολυμβήθρας, τὸ δ’ ἕτερον ὑπὸ τοῦ δωδεκάτου διεστῶτος ὅσον εἰς πήχεις εἴκοσι. τῷ δεκάτῳ δὲ τάγματι διέχοντι πολὺ τούτων κατὰ τὸ βόρειον κλίμα τὸ ἔργον ἦν καὶ κολυμβήθραν Ἀμύγδαλον προσαγορευομένην· τούτου δὲ τὸ πεντεκαιδέκατον ἀπὸ τριάκοντα πηχῶν ἔχου κατὰ τὸ τοῦ ἀρχιερέως μνημεῖον. προσαγομένων δὲ ἤδη αὐτῶν ὁ μὲν Ἰωάννης ἔνδοθεν ὑπορύξας τὸ κατὰ τὴν Ἀντωνίαν μέχρι τῶν χωμάτων καὶ διαλαβὼν σταυροῖς τοὺς ὑπονόμους ἀνακρήμνησιν τὰ ἔργα, πίσσῃ δὲ καὶ ἀσφάλτῳ διακεχρισμένην τὴν ὕλην εἰσκομίσας ἐνίησι πῦρ. καὶ τῶν σταυρῶν ὑποκαέντων ἥ τε διώρυξ ἐνέδωκεν ἀθρόα, καὶ μετὰ μεγίστου ψόφου κατεσείσθη τὰ χώματα εἰς αὐτήν. τὸ μὲν οὖν πρῶτον μετὰ τοῦ κονιορτοῦ καπνὸς ἠγείρετο βαθὺς πνιγομένου τῷ πταίσματι τοῦ πυρός, τῆς δὲ θλιβούσης ὕλης διαβιβρωσκομένης ἤδη φανερὰ φλὸξ ἐρρήγνυτο. καὶ τοῖς Ῥωμαίοις ἔκπληξις μὲν πρὸς τὸ αἰφνίδιον, ἀθυμία δὲ πρὸς τὴν ἐπίνοιαν ἐμπίπτει, καὶ κρατήσειν οἰομένοις ἤδη τὸ συμβὰν καὶ πρὸς τὸ μέλλον ἔψυξε τὴν ἐλπίδα· τὸ δὲ ἀμύνειν ἀχρεῖον ἐδόκει πρὸς τὸ πῦρ, καὶ εἰ σβεσθείη τῶν χωμάτων καταποθέντων.", "st": "5.11.4"}, {"sp": "N", "t": "Μετὰ δ’ ἡμέρας δύο καὶ τοῖς ἄλλοις ἐπιτίθενται χώμασιν οἱ περὶ τὸν Σίμωνα· καὶ γὰρ δὴ προσαγαγόντες ταύτῃ τὰς ἑλεπόλεις οἱ Ῥωμαῖοι διέσειον τὸ τεῖχος. Τεφθέος δέ τις ἀπὸ Γάρις πόλεως τῆς Γαλιλαίας, καὶ Μαγάσσαρος τῶν βασιλικῶν Μαριάμμης θεράπων, μεθ’ ὧν Ἀδιαβηνός τις υἱὸς Ναβαταίου, τοὔνομα κληθεὶς ἀπὸ τῆς τύχης καὶ ἀγίρας, ὅπερ σημαίνει χωλός, ἁρπάσαντες λαμπάδας προεπήδησαν ἐπὶ τὰς μηχανάς. τούτων τῶν ἀνδρῶν οὔτε τολμηρότεροι κατὰ τόνδε τὸν πόλεμον ἐκ τῆς πόλεως ἐφάνησαν οὔτε φοβερώτεροι· καθάπερ γὰρ εἰς φίλους ἐκτρέχοντες οὐ πολεμίων στῖφος οὔτ’ ἐμέλλησαν οὔτ’ ἀπέστησαν, ἀλλὰ διὰ μέσων ἐνθορόντες τῶν ἐχθρῶν ὑφῆψαν τὰς μηχανάς. βαλλόμενοι δὲ καὶ τοῖς ξίφεσιν ἀνωθούμενοι πάντοθεν οὐ πρότερον ἐκ τοῦ κινδύνου μετεκινήθησαν ἢ δράξασθαι τῶν ὀργάνων τὸ πῦρ. αἰρομένης δὲ ἤδη τῆς φλογὸς Ῥωμαῖοι μὲν ἀπὸ τῶν στρατοπέδων συνθέοντες ἐβοήθουν, Ἰουδαῖοι δ’ ἐκ τοῦ τείχους ἐκώλυον καὶ τοῖς σβεννύειν πειρωμένοις συνεπλέκοντο κατὰ μηδὲν τῶν ἰδίων φειδόμενοι σωμάτων. καὶ οἱ μὲν εἷλκον ἐκ τοῦ πυρὸς τὰς ἑλεπόλεις τῶν ὑπὲρ αὐτὰς γέρρων φλεγομένων, οἱ δ’ Ἰουδαῖοι καὶ διὰ τῆς φλογὸς ἀντελαμβάνοντο καὶ τοῦ σιδήρου ζέοντος δρασσόμενοι τοὺς κριοὺς οὐ μεθίεσαν· διέβαινε δ’ ἀπὸ τούτων ἐπὶ τὰ χώματα τὸ πῦρ καὶ τοὺς ἀμύνοντας προελάμβανεν. ἐν τούτῳ δ’ οἱ μὲν Ῥωμαῖοι κυκλούμενοι τῇ φλογὶ καὶ τὴν σωτηρίαν τῶν ἔργων ἀπογνόντες ἀνεχώρουν ἐπὶ τὰ στρατόπεδα, Ἰουδαῖοι δὲ προσέκειντο πλείους ἀεὶ γινόμενοι τῶν ἔνδοθεν προσβοηθούντων καὶ τῷ κρατεῖν τεθαρρηκότες ἀταμιεύτοις ἐχρῶντο ταῖς ὀργαῖς, προελθόντες δὲ μέχρι τῶν ἐρυμάτων ἤδη συνεπλέκοντο τοῖς φρουροῖς. τάξις ἐστὶν ἐκ διαδοχῆς ἱσταμένη πρὸ τοῦ στρατοπέδου, καὶ δεινὸς ἐπ’ αὐτῇ Ῥωμαίων νόμος τὸν ὑποχωρήσαντα καθ’ ἣν δήποτ’ οὖν αἰτίαν θνήσκειν. οὗτοι τοῦ μετὰ κολάσεως τὸν μετ’ ἀρετῆς θάνατον προκρίναντες ἵστανται, καὶ πρὸς τὴν τούτων ἀνάγκην πολλοὶ τῶν τραπέντων ἐπεστράφησαν αἰδούμενοι. διαθέντες δὲ καὶ τοὺς ὀξυβελεῖς ἐπὶ τοῦ τείχους εἶργον τὸ προσγινόμενον πλῆθος ἐκ τῆς πόλεως οὐδὲν εἰς ἀσφάλειαν ἢ φυλακὴν τῶν σωμάτων προνοουμένους· συνεπλέκοντο γὰρ Ἰουδαῖοι τοῖς προστυχοῦσι καὶ ταῖς αἰχμαῖς ἀφυλάκτως ἐμπίπτοντες αὐτοῖς τοῖς σώμασι τοὺς ἐχθροὺς ἔπαιον. οὔτε δὲ ἔργοις αὐτοὶ πλέον ἢ τῷ θαρρεῖν περιῆσαν καὶ Ῥωμαῖοι τῇ τόλμῃ πλέον εἶκον ἢ τῷ κακοῦσθαι.", "st": "5.11.5"}, {"sp": "N", "t": "Παρῆν δ’ ἤδη Τίτος ἀπὸ τῆς Ἀντωνίας, ὅπου κεχώριστο κατασκεπτόμενος τόπον ἄλλοις χώμασι, καὶ πολλὰ τοὺς στρατιώτας φαυλίσας, εἰ κρατοῦντες τῶν πολεμίων τειχῶν κινδυνεύουσι τοῖς ἰδίοις καὶ πολιορκουμένων ὑπομένουσιν αὐτοὶ τύχην ὥσπερ ἐκ δεσμωτηρίου καθ’ αὑτῶν Ἰουδαίους ἀνέντες, περιῄει μετὰ τῶν ἐπιλέκτων κατὰ πλευρὰ τοὺς πολεμίους αὐτός. οἱ δὲ κατὰ στόμα παιόμενοι καὶ πρὸς τοῦτον ἐπιστραφέντες ἐκαρτέρουν. μιγείσης δὲ τῆς παρατάξεως ὁ μὲν κονιορτὸς τῶν ὀμμάτων, ἡ κραυγὴ δὲ τῶν ἀκοῶν ἐπεκράτει, καὶ οὐδετέρῳ παρῆν ἔτι τεκμήρασθαι τὸ ἐχθρὸν ἢ τὸ φίλιον. Ἰουδαίων δὲ οὐ τοσοῦτον ἔτι κατ’ ἀλκὴν ὅσον ἀπογνώσει σωτηρίας παραμενόντων καὶ Ῥωμαίους ἐτόνωσεν αἰδὼς δόξης τε καὶ τῶν ὅπλων καὶ προκινδυνεύοντος Καίσαρος· ὥστε μοι δοκοῦσι τὰ τελευταῖα δι’ ὑπερβολὴν θυμῶν κἂν ἁρπάσαι τὸ τῶν Ἰουδαίων πλῆθος, εἰ μὴ τὴν ῥοπὴν τῆς παρατάξεως φθάσαντες ἀνεχώρησαν εἰς τὴν πόλιν. διεφθαρμένων δὲ τῶν χωμάτων Ῥωμαῖοι μὲν ἦσαν ἐν ἀθυμίαις τὸν μακρὸν κάματον ἐπὶ μιᾶς ὥρας ἀπολέσαντες· καὶ πολλοὶ μὲν ταῖς συνήθεσι μηχαναῖς ἀπήλπιζον ἁλώσεσθαι τὴν πόλιν.", "st": "5.11.6"}, {"sp": "N", "t": "Τίτος δὲ μετὰ τῶν ἡγεμόνων ἐβουλεύετο, καὶ τοῖς μὲν θερμοτέροις πᾶσαν ἐδόκει προσφέρειν τὴν δύναμιν ἀποπειρᾶσθαί τε τοῦ τείχους βίᾳ· μέχρι μὲν γὰρ νῦν κατὰ σπάσμα Ἰουδαίοις συμπεπλέχθαι, προσιόντων δ’ ἀθρόων οὐδὲ τὴν ἔφοδον οἴσειν· καταχωσθήσεσθαι γὰρ ὑπὸ τῶν βελῶν. τῶν δ’ ἀσφαλεστέρων οἱ μὲν καὶ τὰ χώματα ποιεῖν πάλιν, οἱ δὲ καὶ δίχα τούτων προσκαθέζεσθαι μόνον παραφυλάττοντας τάς τε ἐξόδους αὐτῶν καὶ τὰς εἰσκομιδὰς τῶν ἐπιτηδείων παρῄνουν καὶ τῷ λιμῷ καταλείπειν τὴν πόλιν, μηδὲ συμπλέκεσθαι κατὰ χεῖρα τοῖς πολεμίοις· ἄμαχον γὰρ εἶναι τὴν ἀπόγνωσιν οἷς εὐχὴ μὲν τὸ σιδήρῳ πεσεῖν, ἀπόκειται δὲ καὶ δίχα τούτου πάθος χαλεπώτερον. αὐτῷ δὲ τὸ μὲν ἀργεῖν καθόλου μετὰ τοσαύτης δυνάμεως οὐκ ἐδόκει πρέπειν καὶ τὸ μάχεσθαι περιττὸν πρὸς ἀλλήλων φθαρησομένοις, βάλλεσθαι δὲ χώματα δύσεργον ἀπέφαινεν ὕλης ἀπορίᾳ καὶ τὸ παραφυλάττειν τὰς ἐξόδους δυσεργότερον· κυκλώσασθαί τε γὰρ τῇ στρατιᾷ τὴν πόλιν διὰ μέγεθος καὶ δυσχωρίαν οὐκ εὐμαρὲς εἶναι καὶ σφαλερὸν ἄλλως πρὸς τὰς ἐπιθέσεις. τῶν δὲ φανερῶν φυλαττομένων ἀφανεῖς ἐπινοεῖσθαι Ἰουδαίοις ὁδοὺς κατά τε ἀνάγκην καὶ δι’ ἐμπειρίαν· εἰ δέ τι λάθρα παρεισκομισθήσοιτο, τριβὴν ἔσεσθαι πλείονα τῇ πολιορκίᾳ. δεδιέναι τε μὴ τὴν δόξαν τοῦ κατορθώματος αὐτῷ τὸ μῆκος ἐλαττώσῃ τοῦ χρόνου· τούτῳ μὲν γὰρ εἶναι πᾶν ἀνύσιμον, πρὸς δὲ τῆς εὐκλείας τὸ τάχος. δεῖν γε μήν, εἰ καὶ τῷ τάχει μετ’ ἀσφαλείας βούλοιτο χρήσασθαι, περιτειχίζειν ὅλην τὴν πόλιν· μόνως γὰρ οὕτως ἂν πάσας ἀποφράξαι τὰς ἐξόδους, καὶ Ἰουδαίους ἢ πρὸς ἅπαντα ἀπογνόντας τὴν σωτηρίαν παραδώσειν τὴν πόλιν ἢ λιμώττοντας χειρωθήσεσθαι ῥᾳδίως· οὐδὲ γὰρ ἠρεμήσειν αὐτὸς ἄλλως, ἀλλὰ καὶ τῶν χωμάτων ἐπιμελήσεσθαι πάλιν χρώμενος τοῖς κωλύουσιν ἀτονωτέροις. εἰ δέ τῳ μέγα δοκεῖ καὶ δυσήνυτον τὸ ἔργον, χρῆναι σκοπεῖν, ὡς οὔτε Ῥωμαίοις τι μικρὸν ἐνεργεῖν πρέπει, καὶ δίχα πόνου κατορθοῦν τι τῶν μεγάλων οὐδενὶ ῥᾴδιον.", "st": "5.12.1"}, {"sp": "N", "t": "Τούτοις πείσας τοὺς ἡγεμόνας διανέμειν ἐκέλευσε τὰς δυνάμεις ἐπὶ τὸ ἔργον. ὁρμὴ δέ τις ἐμπίπτει δαιμόνιος τοῖς στρατιώταις, καὶ μερισαμένων τὸν περίβολον οὐ μόνον τῶν ταγμάτων ἦν ἔρις, ἀλλὰ καὶ τῶν ἐν αὐτοῖς τάξεων πρὸς ἀλλήλας, καὶ στρατιώτης μὲν δεκαδάρχην, δεκαδάρχης δ’ ἑκατοντάρχην, οὗτος δ’ ἐσπούδαζεν ἀρέσασθαι χιλίαρχον, τῶν δὲ χιλιάρχων ἐπὶ τοὺς ἡγεμόνας ἔτεινεν ἡ φιλοτιμία καὶ τῶν ἡγεμόνων τὴν ἅμιλλαν ἐβράβευε Καῖσαρ· περιιὼν γὰρ αὐτὸς ἑκάστης ἡμέρας πολλάκις ἐπεσκόπει τὸ ἔργον. ἀρξάμενος δὲ ἀπὸ τῆς Ἀσσυρίων παρεμβολῆς, καθ’ ἣν αὐτὸς ἐστρατοπεδεύσατο, ἐπὶ τὴν κατωτέρω Καινόπολιν ἦγε τὸ τεῖχος, ἔνθεν διὰ τοῦ Κεδρῶνος ἐπὶ τὸ Ἐλαιῶν ὄρος· εἶτ’ ἀνακάμπτων κατὰ μεσημβρίαν περιλαμβάνει τὸ ὄρος ἄχρι τῆς Περιστερεῶνος καλουμένης πέτρας τόν τε ἑξῆς λόφον, ὃς ἐπίκειται τῇ κατὰ τὴν Σιλωὰμ φάραγγι, κἀκεῖθεν ἐκκλίνας πρὸς δύσιν εἰς τὴν τῆς πηγῆς κατῄει φάραγγα. μεθ’ ἣν ἀναβαίνων κατὰ τὸ Ἀνάνου τοῦ ἀρχιερέως μνημεῖον καὶ διαλαβὼν τὸ ὄρος, ἔνθα Πομπήιος ἐστρατοπεδεύσατο, πρὸς κλίμα βόρειον ἐπέστρεφε, καὶ προελθὼν μέχρι κώμης τινός, Ἐρεβίνθων οἶκος καλεῖται, καὶ μετ’ ἐκείνην τὸ Ἡρώδου μνημεῖον περισχὼν κατὰ ἀνατολὴν τῷ ἰδίῳ στρατοπέδῳ συνῆπτεν, ὅθεν ἤρξατο. τὸ μὲν οὖν τεῖχος ἑνὸς δέοντος τεσσαράκοντα σταδίων ἦν, ἔξωθεν δ’ αὐτῷ προσῳκοδομήθη τρισκαίδεκα φρούρια, καὶ τούτων οἱ κύκλοι δέκα συνηριθμοῦντο σταδίων. τρισὶ δ’ ᾠκοδομήθη τὸ πᾶν ἡμέραις, ὡς τὸ μὲν ἔργον μηνῶν [εἶναι] ἄξιον, τὸ τάχος δ’ ἡττᾶσθαι πίστεως. περικλείσας δὲ τῷ τείχει τὴν πόλιν καὶ δύναμιν τοῖς φρουρίοις ἐγκαταστήσας τὴν μὲν πρώτην φυλακὴν τῆς νυκτὸς περιιὼν αὐτὸς ἐπεσκέπτετο, τὴν δευτέραν δ’ ἐπέτρεψεν Ἀλεξάνδρῳ, τὴν τρίτην δ’ ἔλαχον οἱ τῶν ταγμάτων ἡγεμόνες. διεκληροῦντο δ’ οἱ φύλακες τοὺς ὕπνους, καὶ δι’ ὅλης νυκτὸς περιῄεσαν κατὰ διαστήματα τῶν φρουρίων.", "st": "5.12.2"}, {"sp": "N", "t": "Ἰουδαίοις δὲ μετὰ τῶν ἐξόδων ἀπεκόπη πᾶσα σωτηρίας ἐλπίς, καὶ βαθύνας αὑτὸν ὁ λιμὸς κατ’ οἴκους καὶ γενεὰς τὸν δῆμον ἐπεβόσκετο. καὶ τὰ μὲν τέγη πεπλήρωτο γυναικῶν καὶ βρεφῶν λελυμένων, οἱ στενωποὶ δὲ γερόντων νεκρῶν, παῖδες δὲ καὶ νεανίαι διοιδοῦντες ὥσπερ εἴδωλα κατὰ τὰς ἀγορὰς ἀνειλοῦντο καὶ κατέπιπτον ὅπῃ τινὰ τὸ πάθος καταλαμβάνοι. θάπτειν δὲ τοὺς προσήκοντας οὔτε ἴσχυον οἱ κάμνοντες καὶ τὸ διευτονοῦν ὤκνει διά τε πλῆθος τῶν νεκρῶν καὶ διὰ τὸ κατὰ σφᾶς ἄδηλον· πολλοὶ γοῦν τοῖς ὑπ’ αὐτῶν θαπτομένοις ἐπαπέθνησκον, πολλοὶ δὲ ἐπὶ τὰς θήκας πρὶν ἐπιστῆναι τὸ χρεὼν προῆλθον. οὔτε δὲ θρῆνος ἐν ταῖς συμφοραῖς οὔτ’ ὀλοφυρμὸς ἦν, ἀλλ’ ὁ λιμὸς ἤλεγχε τὰ πάθη, ξηροῖς δὲ τοῖς ὄμμασι καὶ σεσηρόσι τοῖς στόμασιν οἱ δυσθανατοῦντες ἐφεώρων τοὺς φθάσαντας ἀναπαύσασθαι, βαθεῖα δὲ περιεῖχεν τὴν πόλιν σιγὴ καὶ νὺξ θανάτου γέμουσα καὶ τούτων οἱ λῃσταὶ χαλεπώτεροι. τυμβωρυχοῦντες γοῦν τὰς οἰκίας ἐσύλων τοὺς νεκροὺς καὶ τὰ καλύμματα τῶν σωμάτων περισπῶντες μετὰ γέλωτος ἐξῄεσαν, τάς τε ἀκμὰς τῶν ξιφῶν ἐδοκίμαζον ἐν τοῖς πτώμασιν, καί τινας τῶν ἐρριμμένων ἔτι ζῶντας διήλαυνον ἐπὶ πείρᾳ τοῦ σιδήρου· τοὺς δ’ ἱκετεύοντας χρῆσαι σφίσι δεξιὰν καὶ ξίφος τῷ λιμῷ κατέλειπον ὑπερηφανοῦντες, καὶ τῶν ἐκπνεόντων ἕκαστος ἀτενίσας εἰς τὸν ναὸν ἀφεώρα τοὺς στασιαστὰς ζῶντας ἀπολιπών. οἱ δὲ τὸ μὲν πρῶτον ἐκ τοῦ δημοσίου θησαυροῦ τοὺς νεκροὺς θάπτειν ἐκέλευον τὴν ὀσμὴν οὐ φέροντες, ἔπειθ’ ὡς οὐ διήρκουν ἀπὸ τῶν τειχῶν ἔρριπτον εἰς τὰς φάραγγας.", "st": "5.12.3"}, {"sp": "N", "t": "Περιιὼν δὲ ταύτας ὁ Τίτος ὡς ἐθεάσατο πεπλησμένας τῶν νεκρῶν καὶ βαθὺν ἰχῶρα μυδώντων ὑπορρέοντα τῶν σωμάτων, ἐστέναξέ τε καὶ τὰς χεῖρας ἀνατείνας κατεμαρτύρατο τὸν θεόν, ὡς οὐκ εἴη τὸ ἔργον αὐτοῦ. τὰ μὲν δὴ κατὰ τὴν πόλιν εἶχεν οὕτως, Ῥωμαῖοι δὲ μηδενὸς ἔτι τῶν στασιαστῶν ἐκτρέχοντος, ἤδη γὰρ καὶ τούτων ἀθυμία καὶ λιμὸς ἐφήπτετο, ἐπ’ εὐθυμίαις ἦσαν σίτου τε ἀφθονίαν καὶ τῶν ἄλλων ἐπιτηδείων ἐκ τῆς Συρίας καὶ τῶν πλησίον ἐπαρχιῶν ἔχοντες· ἱστάμενοι δὲ πολλοὶ τοῦ τείχους πλησίον καὶ πολὺ πλῆθος τῶν· ἐδωδίμων ἐπιδεικνύμενοι τῷ κατὰ σφᾶς κόρῳ τὸν λιμὸν τῶν πολεμίων ἐξέκαιον. πρὸς δὲ τὸ πάθος τῶν στασιαστῶν μηδὲν ἐνδιδόντων Τίτος οἰκτείρων τὰ λείψανα τοῦ δήμου καὶ σπουδάζων τὸ γοῦν περιὸν ἐξαρπάσαι, πάλιν ἤρχετο χωμάτων χαλεπῶς αὐτῷ τῆς ὕλης ποριζομένης· ἡ μὲν γὰρ περὶ τὴν πόλιν πᾶσα τοῖς προτέροις ἔργοις ἐκέκοπτο, συνεφόρουν δὲ ἄλλην ἀπ’ ἐνενήκοντα σταδίων οἱ στρατιῶται. καὶ πρὸς μόνης ὕψουν τῆς Ἀντωνίας κατὰ μέρη τέσσαρα πολὺ μείζονα τῶν προτέρων χώματα. περιιὼν δὲ ὁ Καῖσαρ τὰ τάγματα καὶ κατεπείγων τὸ ἔργον ἐπεδείκνυ τοῖς λῃσταῖς, ὡς ἐν χερσὶν εἴησαν αὐτοῦ. μόνοις δὲ ἐκείνοις ἄρα κακῶν ἀπολώλει μεταμέλεια, καὶ τὰς ψυχὰς χωρίσαντες ἀπὸ τῶν σωμάτων ἀμφοτέροις ὡς ἀλλοτρίοις ἐχρῶντο. οὔτε γὰρ πάθος αὐτῶν ἡμέρου τὴν ψυχὴν οὔτ’ ἀλγηδὼν ἥπτετο τοῦ σώματος, οἵ γε καὶ νεκρὸν τὸν δῆμον ὥσπερ κύνες ἐσπάραττον καὶ τὰ δεσμωτήρια τῶν ἀρρώστων ἐνεπίμπλασαν.", "st": "5.12.4"}, {"sp": "N", "t": "Σίμων γοῦν οὐδὲ Ματθίαν, δι’ ὃν κατέσχε τὴν πόλιν, ἀβασάνιστον ἀνεῖλε· Βοηθοῦ παῖς ἦν οὗτος ἐκ τῶν ἀρχιερέων ἐν τοῖς μάλιστα τῷ δήμῳ πιστὸς καὶ τίμιος· ὃς ὑπὸ τοῖς ζηλωταῖς κακουμένου τοῦ πλήθους, οἷς ἤδη καὶ Ἰωάννης προσῆν, πείθει τὸν δῆμον εἰσαφεῖναι τὸν Σίμωνα βοηθόν, οὐδὲν οὔτε προσυνθέμενος οὔτε προσδοκήσας φαῦλον ἐξ αὐτοῦ. παρελθὼν δ’ ἐκεῖνος ὡς ἐκράτησε τῆς πόλεως, ἐχθρὸν ἐν ἴσῳ τοῖς ἄλλοις ἡγεῖτο καὶ τὸν ὑπὲρ αὐτοῦ σύμβουλον ὡς ἂν ἐξ ἁπλότητος γεγενημένον. ἀχθέντα δὲ τηνικαῦτα καὶ κατηγορούμενον τὰ τῶν Ῥωμαίων φρονεῖν κατακρίνει μὲν θανάτῳ μηδ’ ἀπολογίας ἀξιώσας σὺν τρισὶν υἱοῖς· ὁ γὰρ τέταρτος ἔφθη διαδρὰς πρὸς Τίτον· ἱκετεύοντα δὲ ἀναιρεθῆναι πρὸ τῶν τέκνων καὶ ταύτην αἰτούμενον τὴν χάριν ἀνθ’ ὧν ἀνοίξειεν αὐτῷ τὴν πόλιν, τελευταῖον ἀνελεῖν ἐκέλευσεν. ὁ μὲν οὖν ἐν ὄψει φονευθεῖσιν ἐπεσφάγη τοῖς παισὶν ἄντικρυς Ῥωμαίων προαχθείς· οὕτω γὰρ ὁ Σίμων Ἀνάνῳ τῷ Βαγαδάτου προσέταξεν, ὃς ἦν ὠμότατος αὐτῷ τῶν δορυφόρων, ἐπειρωνευόμενος, εἴ τι βοηθήσουσιν αὐτῷ πρὸς οὓς ἐξελθεῖν εἵλετο· θάπτειν τ’ ἀπεῖπε τὰ σώματα. μετὰ τούτους ἱερεύς τις Ἀνανίας υἱὸς Μασβάλου τῶν ἐπισήμων καὶ ὁ γραμματεὺς τῆς βουλῆς Ἀριστεύς, γένος ἐξ Ἀμμαοῦς, καὶ σὺν τούτοις πεντεκαίδεκα τῶν ἀπὸ τοῦ δήμου λαμπρῶν ἀναιροῦνται. τὸν δὲ τοῦ Ἰωσήπου πατέρα συγκλείσαντες ἐφύλαττον, κηρύττουσι δὲ μηδένα τῶν κατὰ τὴν πόλιν μήτε συνομιλεῖν μήτε ἐπὶ ταὐτὸ συναθροίζεσθαι δέει προδοσίας, καὶ τοὺς συνολοφυρομένους πρὸ ἐξετάσεως ἀνῄρουν.", "st": "5.13.1"}, {"sp": "N", "t": "Ταῦτα ὁρῶν Ἰούδης τις υἱὸς Ἰούδου, τῶν ὑπάρχων τοῦ Σίμωνος εἷς ὢν καὶ πεπιστευμένος ὑπ’ αὐτοῦ πύργον φυλάττειν, τάχα μέν τι καὶ οἴκτῳ τῶν ὠμῶς ἀπολλυμένων, τὸ δὲ πλέον αὑτοῦ προνοίᾳ, συγκαλέσας τοὺς πιστοτάτους τῶν ὑπ’ αὐτὸν δέκα, μέχρι τίνος ἀνθέξομεν, ἔφη, τοῖς κακοῖς; ἢ τίνα σωτηρίας ἔχομεν ἐλπίδα πιστοὶ πονηρῷ μένοντες; οὐχ ὁ μὲν λιμὸς ἤδη καθ’ ἡμῶν, Ῥωμαῖοι δὲ παρὰ μικρὸν ἔνδον, Σίμων δὲ καὶ πρὸς εὐεργέτας ἄπιστος, καὶ δέος μὲν ἤδη παρ’ αὐτοῦ κολάσεως, ἡ δὲ παρὰ Ῥωμαίοις δεξιὰ βέβαιος; φέρε, παραδόντες τὸ τεῖχος σώσωμεν ἑαυτοὺς καὶ τὴν πόλιν. πείσεται δὲ οὐδὲν δεινὸν Σίμων, ἐὰν ἀπεγνωκὼς ἑαυτὸν τάχιον δῷ δίκην. τούτοις τῶν δέκα πεισθέντων ὑπὸ τὴν ἕω τοὺς λοιποὺς τῶν ὑποτεταγμένων ἄλλον ἀλλαχόσε διέπεμπεν, ὡς μὴ φωραθείη τι τῶν βεβουλευμένων, αὐτὸς δὲ περὶ τρίτην ὥραν ἀπὸ τοῦ πύργου τοὺς Ῥωμαίους ἐκάλει. τῶν δὲ οἱ μὲν ὑπερηφάνουν, οἱ δὲ ἠπίστουν, οἱ πολλοὶ δὲ ὤκνουν ὡς μετὰ μικρὸν ἀκινδύνως ληψόμενοι τὴν πόλιν. ἐν ὅσῳ δὲ Τίτος μεθ’ ὁπλιτῶν παρῄει πρὸς τὸ τεῖχος, ἔφθη γνοὺς ὁ Σίμων, καὶ μετὰ τάχους τόν τε πύργον προκαταλαμβάνει καὶ τοὺς ἄνδρας συλλαβὼν ἐν ὄψει τῶν Ῥωμαίων ἀναιρεῖ καὶ πρὸ τοῦ τείχους λωβησάμενος ἔρριψε τὰ σώματα.", "st": "5.13.2"}, {"sp": "N", "t": "Κἀν τούτῳ περιιὼν Ἰώσηπος, οὐ γὰρ ἀνίει παρακαλῶν, βάλλεται τὴν κεφαλὴν λίθῳ καὶ παραχρῆμα πίπτει καρωθείς. ἐκδρομὴ δὲ ἐπὶ τὸ πτῶμα τῶν Ἰουδαίων γίνεται, κἂν ἔφθη συρεὶς εἰς τὴν πόλιν, εἰ μὴ ταχέως Καῖσαρ ἔπεμψε τοὺς ὑπερασπίζοντας. μαχομένων δὲ τούτων ὁ Ἰώσηπος μὲν αἴρεται βραχύ τι τῶν πραττομένων ἐπαΐων, οἱ στασιασταὶ δ’ ὡς ἀνελόντες ὃν ἐπεθύμουν μάλιστα μετὰ χαρᾶς ἀνεβόων. διαγγέλλεταί τε εἰς τὴν πόλιν, καὶ τὸ καταλειπόμενον πλῆθος ἐπέσχεν ἀθυμία πεπεισμένους οἴχεσθαι τῷ ὄντι δι’ ὃν αὐτομολεῖν ἐθάρρουν. ἀκούσασα δὲ ἡ τοῦ Ἰωσήπου μήτηρ ἐν τῷ δεσμωτηρίῳ τεθνάναι τὸν υἱόν, πρὸς μὲν τοὺς φύλακας ἀπὸ Ἰωταπάτων τοῦτο ἔφη πεπεῖσθαι· καὶ γὰρ οὐδὲ ζῶντος ἀπολαύειν· ἰδίᾳ δὲ ὀλοφυρομένη πρὸς τὰς θεραπαινίδας τοῦτον εἰληφέναι τῆς εὐτεκνίας ἔλεγε καρπὸν τὸ μηδὲ θάψαι τὸν υἱόν, ὑφ’ οὗ ταφήσεσθαι προσεδόκησεν. ἀλλὰ γὰρ οὔτε ταύτην ἐπὶ πλέον ὠδύνα τὸ ψεῦδος οὔτε τοὺς λῃστὰς ἔθαλπε· ταχέως γὰρ ἐκ τῆς πληγῆς ἀνήνεγκεν ὁ Ἰώσηπος, καὶ προελθὼν τοὺς μὲν οὐκ εἰς μακρὰν ἐβόα δίκας αὐτῷ δώσειν τοῦ τραύματος, τὸν δὲ δῆμον ἐπὶ πίστιν πάλιν προυκαλεῖτο. θάρσος δὲ τῷ λαῷ καὶ τοῖς στασιασταῖς ἔκπληξις ἐμπίπτει πρὸς τὴν ὄψιν αὐτοῦ.", "st": "5.13.3"}, {"sp": "N", "t": "Τῶν δ’ αὐτομόλων οἱ μὲν ὑπ’ ἀνάγκης ἀπὸ τοῦ τείχους ἐπήδων ταχέως, οἱ δὲ προϊόντες ὡς ἐπὶ μάχῃ μετὰ χερμάδων ἔπειτα πρὸς τοὺς Ῥωμαίους ἔφευγον. συνείπετο δὲ τούτοις τύχη τῶν εἴσω χαλεπωτέρα, καὶ τοῦ παρὰ σφίσι λιμοῦ συντονώτερον εὕρισκον πρὸς ὄλεθρον τὸν παρὰ Ῥωμαίοις κόρον. παρεγίνοντο μὲν γὰρ ἀπὸ τῆς ἐνδείας πεφυσημένοι καὶ ὥσπερ ὑδρωπιῶντες, ἔπειτα ἀθρόως κενοῖς ὑπερεμπιπλάμενοι τοῖς σώμασιν ἐρρήγνυντο πλὴν τῶν δι’ ἐμπειρίαν ταμιευσαμένων τὰς ὀρέξεις καὶ κατ’ ὀλίγον προσθέντων τροφὴν ἀπειθισμένῳ τῷ σώματι φέρειν. καὶ τοὺς οὕτω δὲ σωζομένους ἑτέρα πληγὴ μετελάμβανε· τῶν γὰρ παρὰ τοῖς Σύροις τις αὐτομόλων φωρᾶται τῶν τῆς γαστρὸς λυμάτων χρυσοῦς ἐκλέγων· καταπίνοντες δέ, ὡς ἔφαμεν, αὐτοὺς προῄεσαν, ἐπειδὴ διηρεύνων πάντας οἱ στασιασταί, καὶ πολὺ πλῆθος ἦν ἐν τῇ πόλει χρυσοῦ· δώδεκα γοῦν Ἀττικῶν ὠνοῦντο πρότερον ἰσχύοντας πέντε καὶ εἴκοσιν. ἀλλά τοι τῆς ἐπινοίας ἐλεγχθείσης δι’ ἑνὸς ἀναπίμπλαται μὲν φήμης τὰ στρατόπεδα, ὡς μεστοὶ χρυσίου παρεῖεν οἱ αὐτόμολοι, τὸ δὲ τῶν Ἀράβων πλῆθος καὶ οἱ Σύροι τοὺς ἱκέτας ἀνατέμνοντες ἠρεύνων τὰς γαστέρας. καὶ τούτου τοῦ πάθους οὐδὲν ἔμοιγε δοκεῖ συμβῆναι Ἰουδαίοις χαλεπώτερον· μιᾷ γοῦν ἀνεσχίσθησαν νυκτὶ πρὸς δισχιλίους.", "st": "5.13.4"}, {"sp": "N", "t": "Καὶ γνοὺς τὴν παρανομίαν Τίτος ὀλίγου μὲν ἐδέησε τὸ ἱππικὸν περιστήσας κατακοντίσαι τοὺς αἰτίους, εἰ μὴ πολὺ πλῆθος ἐνείχετο καὶ τῶν ἀνῃρημένων πολλαπλασίους ἦσαν οἱ κολασθησόμενοι. συγκαλέσας δὲ τοὺς τῶν συμμάχων ἡγεμόνας καὶ τοὺς τῶν ταγμάτων, συνδιεβάλλοντο γὰρ καὶ τῶν στρατιωτῶν τινές, πρὸς ἑκατέρους ἀγανακτεῖν ἔλεγεν, εἰ τῶν μὲν σὺν αὐτῷ στρατευομένων τινὲς τοιαῦτα δρῶσιν κέρδους ἕνεκεν ἀδήλου, μηδὲ τὰ ὅπλα σφῶν αὐτῶν αἰδούμενοι πεποιημένα ἀργύρου τε καὶ χρυσοῦ, τοῖς δὲ Ἄραψι καὶ [τοῖς] Σύροις, εἰ πρῶτον μὲν ἐν ἀλλοτρίῳ πολέμῳ τοῖς πάθεσιν αὐτεξουσίως χρῶνται, ἔπειτα τῇ περὶ φόνους ὠμότητι καὶ τῷ πρὸς Ἰουδαίους μίσει Ῥωμαίους ἐπιγράφουσι· καὶ γὰρ νῦν ἐνίους αὐτῷ τῶν στρατιωτῶν συναπολαύειν τῆς κακοδοξίας. τούτοις μὲν οὖν διηπείλησε θάνατον, εἴ τις εὑρεθείη πάλιν τὸ αὐτὸ τολμῶν, τοῖς δὲ ἀπὸ τῶν ταγμάτων ἐπέστελλεν ἐρευνήσαντας τοὺς ὑπόπτους ἀνάγειν ἐπ’ αὐτόν. κατεφρόνει δ’, ὡς ἔοικε, φιλοχρηματία πάσης κολάσεως, καὶ δεινὸς ἐμπέφυκεν ἀνθρώποις τοῦ κερδαίνειν ἔρως, οὐδέν τε οὕτως πάθος πλεονεξία παραβάλλεται. ἢ ταῦτα μὲν ἄλλως καὶ μέτρον ἔχει καὶ φόβοις ὑποτάσσεται, θεὸς δὲ ἦν ὁ τοῦ λαοῦ παντὸς κατακρίνας καὶ πᾶσαν αὐτοῖς σωτηρίας ὁδὸν εἰς ἀπώλειαν ἀποστρέφων. ὃ γοῦν μετ’ ἀπειλῆς ἀπεῖπεν ὁ Καῖσαρ λάθρα κατὰ τῶν αὐτομόλων ἐτολμᾶτο, καὶ τοὺς διαδιδράσκοντας πρὶν πᾶσιν ὀφθῆναι προαπαντῶντες ἔσφαττον οἱ βάρβαροι, περισκοπούμενοι δὲ μή τις ἐπίδοι Ῥωμαίων, ἀνέσχιζον κἀκ τῶν σπλάγχνων τὸ μιαρὸν κέρδος εἷλκον. ὀλίγοις δ’ ἐνευρίσκετο, καὶ τοὺς πολλοὺς παρανήλισκεν ἐλπὶς μόνη. τοῦτο μὲν δὴ τὸ πάθος πολλοὺς τῶν αὐτομόλων ἐπανήγαγεν.", "st": "5.13.5"}, {"sp": "N", "t": "Ἰωάννης δ’ ὡς ἐπέλειπον αἱ ἁρπαγαὶ παρὰ τοῦ δήμου, πρὸς ἱεροσυλίαν ἐτρέπετο, καὶ πολλὰ μὲν ἐκ τῶν ἀναθημάτων κατεχώνευε τοῦ ναοῦ, πολλὰ δὲ τῶν πρὸς τὰς λειτουργίας ἀναγκαίων σκεύη, κρατῆρας καὶ πίνακας καὶ τραπέζας· ἀπέσχετο δ’ οὐδὲ τῶν ὑπὸ τοῦ Σεβαστοῦ καὶ τῆς γυναικὸς αὐτοῦ πεμφθέντων ἀκρατοφόρων. οἱ μέν γε Ῥωμαίων βασιλεῖς ἐτίμησάν τε καὶ προσεκόσμησαν τὸ ἱερὸν ἀεί, τότε δὲ ὁ Ἰουδαῖος καὶ τὰ τῶν ἀλλοφύλων κατέσπα. πρὸς δὲ τοὺς συνόντας ἔλεγεν, ὡς δεῖ μετ’ ἀδείας καταχρήσασθαι τοῖς θείοις ὑπὲρ τοῦ θείου καὶ τοὺς τῷ ναῷ στρατευομένους ἐξ αὐτοῦ τρέφεσθαι. διὰ τοῦτο καὶ τὸν ἱερὸν οἶνον καὶ τὸ ἔλαιον, ὃ τοῖς ὁλοκαυτώμασιν οἱ ἱερεῖς ἐφύλαττον [ἐπιχεῖν], ἐκκενώσας, ἦν δ’ ἐν τῷ ἔνδον ἱερῷ, διένεμε τῷ πλήθει, κἀκεῖνοι δίχα φρίκης ἠλείφοντο καὶ ἔπινον [ἐξ αὐτῶν]. οὐκ ἂν ὑποστειλαίμην εἰπεῖν ἅ μοι κελεύει τὸ πάθος· οἶμαι Ῥωμαίων βραδυνόντων ἐπὶ τοὺς ἀλιτηρίους ἢ καταποθῆναι ἂν ὑπὸ χάσματος ἢ κατακλυσθῆναι τὴν πόλιν ἢ τοὺς τῆς Σοδομηνῆς μεταλαβεῖν κεραυνούς· πολὺ γὰρ τῶν ταῦτα παθόντων ἤνεγκε γενεὰν ἀθεωτέραν· τῇ γοῦν τούτων ἀπονοίᾳ πᾶς ὁ λαὸς συναπώλετο.", "st": "5.13.6"}, {"sp": "N", "t": "Καὶ τί δεῖ κατὰ μέρος ἐκδιηγεῖσθαι τὰς συμφοράς; ἀλλὰ πρὸς Τίτον ἐν ταύταις ταῖς ἡμέραις Μαννέος ὁ Λαζάρου φυγὼν διὰ μιᾶς ἔλεγεν ἐκκεκομίσθαι πύλης, ἣν αὐτὸς ἐπεπίστευτο, μυριάδας ἕνδεκα νεκρῶν ἐπὶ πεντακισχιλίοις ὀκτακοσίοις ὀγδοήκοντα, ἀφ’ ἧς αὐτοῖς ἡμέρας παρεστρατοπεδεύσατο τεσσαρεσκαιδεκάτῃ Ξανθικοῦ μηνὸς ἄχρι Πανέμου νουμηνίας. τοῦτο δ’ ἦν πλῆθος ἀπόρων· καὶ οὐδὲ αὐτὸς ἐφεστώς, ἀλλὰ δημοσίᾳ μισθὸν διδοὺς ἐξ ἀνάγκης ἠρίθμει. τοὺς δὲ λοιποὺς οἱ προσήκοντες ἔθαπτον· ταφὴ δ’ ἦν τὸ προκομίσαντας ἐκ τοῦ ἄστεος ῥῖψαι. μετὰ δὲ τοῦτον διαδράντες πολλοὶ τῶν ἐπισήμων τὰς πάσας τῶν ἀπόρων νεκρῶν ἀπήγγελλον μυριάδας ἑξήκοντα διὰ τῶν πυλῶν ἐκριφῆναι, τῶν δ’ ἄλλων ἀνεξερεύνητον εἶναι τὸν ἀριθμόν. μηκέτι δ’ εὐτονούντων τοὺς πτωχοὺς ἐκφέρειν [ἔλεγον] συσσωρεύοντας εἰς τοὺς μεγίστους οἴκους τὰ πτώματα ἀποκλείειν. καὶ τοῦ μὲν σίτου τὸ μέτρον πραθῆναι ταλάντου, μετὰ ταῦτα δ’ ὡς οὐδὲ ποηλογεῖν ἔθ’ οἷόν τ’ ἦν περιτειχισθείσης τῆς πόλεως, προελθεῖν τινας εἰς τοσοῦτον ἀνάγκης, ὥστε τὰς ἀμάρας ἐρευνῶντας καὶ παλαιὸν ὄνθον βοῶν προσφέρεσθαι τὰ ἐκ τούτων σκύβαλα, καὶ τὸ μηδ’ ὄψει φορητὸν πάλαι τότε γενέσθαι τροφήν. ταῦτα Ῥωμαῖοι μὲν ἀκούοντες ἠλέησαν, οἱ στασιασταὶ δὲ καὶ βλέποντες οὐ μετενόουν, ἀλλ’ ἠνείχοντο μέχρις αὐτῶν προελθεῖν· πεπήρωντο γὰρ ὑπὸ τοῦ χρεών, ὃ τῇ τε πόλει καὶ αὐτοῖς ἤδη παρῆν.", "st": "5.13.7"}, {"sp": "HDR", "t": "Βιβλίον Ϛʹ", "st": "6"}, {"sp": "N", "t": "Τὰ μὲν οὖν τῶν Ἱεροσολύμων πάθη προύκοπτεν καθ’ ἡμέραν ἐπὶ τὸ χεῖρον τῶν τε στασιαστῶν μᾶλλον παροξυνομένων ἐν ταῖς συμφοραῖς καὶ τοῦ λιμοῦ μετὰ τὸν δῆμον ἤδη κἀκείνους νεμομένου. τό γε μὴν πλῆθος τῶν σεσωρευμένων ἀνὰ τὴν πόλιν πτωμάτων ὄψει τε φρικῶδες ἦν καὶ λοιμώδη προσέβαλλεν ὀσμὴν πρός τε τὰς ἐκδρομὰς ἐμπόδιον τοῖς μαχομένοις· ὥσπερ γὰρ διὰ παρατάξεως φόνῳ μυρίῳ γεγυμνασμένης χωροῦντας ἔδει τὰ σώματα πατεῖν. οἱ δ’ ἐπιβαίνοντες οὔτ’ ἔφριττον οὔτ’ ἠλέουν οὔτε κλῃδόνα κακὴν σφῶν αὐτῶν ὑπελάμβανον τὴν εἰς τοὺς κατοιχομένους ὕβριν, πεφυρμένοι δ’ ὁμοφύλῳ φόνῳ τὰς δεξιὰς ἐπὶ τὸν πρὸς τοὺς ἀλλοφύλους πόλεμον ἐξέθεον, ὀνειδίζοντες, ἔμοιγε δοκεῖν, τὸ θεῖον εἰς βραδυτῆτα τῆς ἐπ’ αὐτῶν κολάσεως· οὐ γὰρ ἐλπίδι νίκης ὁ πόλεμος, ἤδη δὲ ἀπογνώσει σωτηρίας ἐθρασύνετο. Ῥωμαῖοι δὲ καίτοι πολλὰ περὶ τὴν τῆς ὕλης συγκομιδὴν ταλαιπωρούμενοι τὰ χώματα διήγειραν μιᾷ καὶ εἴκοσιν ἡμέραις, κείραντες, ὡς προείρηται, τὴν περὶ τὸ ἄστυ χώραν ἐπ’ ἐνενήκοντα σταδίους ἐν κύκλῳ πᾶσαν. ἦν δ’ ἐλεεινὴ καὶ τῆς γῆς ἡ θέα· τὰ γὰρ πάλαι δένδρεσι καὶ παραδείσοις κεκοσμημένα τότε πανταχόθεν ἠρήμωτο καὶ περικέκοπτο τὴν ὕλην, οὐδείς τε τὴν πάλαι Ἰουδαίαν καὶ τὰ περικαλλῆ προάστεια τῆς πόλεως ἑωρακὼς ἀλλόφυλος, ἔπειτα τὴν τότε βλέπων ἐρημίαν οὐκ ὠλοφύρατο καὶ κατεστέναξεν τὴν μεταβολὴν παρ’ ὅσον γένοιτο· πάντα γὰρ ἐλυμήνατο τὰ σημεῖα τοῦ κάλλους ὁ πόλεμος, καὶ οὐκ ἄν τις ἐξαπίνης ἐπιστὰς τῶν προεγνωκότων ἐγνώρισε τὸν τόπον, ἀλλὰ παρὼν ἐζήτει τὴν πόλιν.", "st": "6.1.1"}, {"sp": "N", "t": "Ῥωμαίοις δὲ καὶ Ἰουδαίοις τὸ τέλος τῶν χωμάτων ἴσην ἐνεποίει δέους ἀρχήν· οἱ μὲν γάρ, εἰ μὴ καὶ ταῦτα καύσειαν, ἁλώσεσθαι τὴν πόλιν προσεδόκων, Ῥωμαῖοι δ’ οὐκ [ἂν] ἔθ’ αἱρήσειν κἀκείνων διαφθαρέντων. ὕλης τε γὰρ ἦν ἀπορία, καὶ τῶν μὲν πόνων ἤδη τὸ σῶμα, τῶν δὲ ἐπαλλήλων πταισμάτων αἱ ψυχαὶ τοῖς στρατιώταις ἐλείποντο. τάς γε μὴν κατὰ τὴν πόλιν συμφορὰς Ῥωμαίοις πλέον εἶναι συνέβαινε πρὸς ἀθυμίας ἢ τοῖς ἐν αὐτῇ· παρὰ γὰρ τὰ τηλικαῦτα πάθη τοῖς μαχομένοις οὐδὲν ἐχρῶντο μαλακωτέροις, ἀλλ’ ἐθραύοντο πάντοτε τὰς ἐλπίδας, τῶν μὲν χωμάτων ταῖς ἐπιβουλαῖς, τῶν δ’ ὀργάνων στερρότητι τοῦ τείχους, τῆς δὲ κατὰ χεῖρα μάχης ταῖς τῶν συμπλεκομένων τόλμαις πλεονεκτούμενοι, τὸ δὲ μέγιστον, στάσεώς τε καὶ λιμοῦ καὶ πολέμου καὶ τοσούτων κακῶν εὑρίσκοντες ἐπάνω τὸ παράστημα τῆς ψυχῆς Ἰουδαίους ἔχοντας. ὑπελάμβανόν τε τῶν ἀνδρῶν ἀμάχους μὲν τὰς ὁρμάς, ἀνάλωτον δὲ τὴν ἐπὶ συμφοραῖς εὐθυμίαν εἶναι· τί γὰρ ἂν μὴ ὑποστῆναι δεξιᾷ τύχῃ χρωμένους τοὺς ὑπὸ κακῶν πρὸς ἀλκὴν τρεπομένους; οἱ μὲν οὖν ἐρρωμενεστέρας διὰ ταῦτα τῶν χωμάτων ἐποιοῦντο τὰς φυλακάς.", "st": "6.1.2"}, {"sp": "N", "t": "Οἱ δὲ περὶ τὸν Ἰωάννην κατὰ τὴν Ἀντωνίαν ἅμα καὶ πρὸς τὸ μέλλον, εἰ καταρριφθείη τὸ τεῖχος, ἠσφαλίζοντο καὶ πρὶν ἐπιστῆναι τοὺς κριοὺς ἐπέθεντο τοῖς ἔργοις. οὐ μὴν ἐκράτησάν γε τῆς ἐπιχειρήσεως, ἀλλὰ προελθόντες μετὰ λαμπάδων πρὶν ἐγγίσαι τοῖς χώμασι ψυχρότεροι τῆς ἐλπίδος ὑπέστρεψαν. πρῶτον μὲν γὰρ οὐδ’ ὁμονοεῖν ἡ σκέψις αὐτῶν ἐῴκει κατὰ μέρος ἐκπηδώντων κἀκ διαλειμμάτων καὶ μεμελλημένως μετὰ δέους καθόλου τε εἰπεῖν οὐκ Ἰουδαϊκῶς· τὰ γὰρ ἴδια τοῦ ἔθνους ὑστέρητο ἅμα ἡ τόλμα καὶ ὁρμὴ καὶ δρόμος ὁμοῦ πάντων καὶ τὸ μηδὲ πταίοντας ἀναστρέφειν. ἀτονώτεροι δ’ ἑαυτῶν προελθόντες καὶ τοὺς Ῥωμαίους εὗρον ἐρρωμενέστερον τοῦ συνήθους παρατεταγμένους· τοῖς μέν γε σώμασι καὶ ταῖς πανοπλίαις οὕτως ἐφράξαντο τὰ χώματα πάντοθεν ὡς τῷ πυρὶ μηδαμόθεν καταλιπεῖν παράδυσιν, τὴν δὲ ψυχὴν ἐτόνωσαν ἕκαστος μὴ μετακινηθῆναι τῆς τάξεως πρὸ θανάτου. πρὸς γὰρ τῷ πάσας αὐτῶν ὑποκόπτεσθαι τὰς ἐλπίδας, εἰ κἀκεῖνα καταφλεγείη τὰ ἔργα, δεινὴ τοὺς στρατιώτας εἶχεν αἰδώς, εἰ πάντα κρατήσειαν πανουργία μὲν ἀρετῆς, ἀπόνοια δ’ ὅπλων, πλῆθος δ’ ἐμπειρίας, Ἰουδαῖοι δὲ Ῥωμαίων. ἅμα δὲ τἀφετήρια συνήργει τῶν προπηδώντων ἐφικνούμενα, καὶ πεσών τις τῷ μεθ’ αὑτὸν ἐμπόδιον ἦν, ὅ τε κίνδυνος τοῦ πρόσω χωρεῖν ἐποίει μαλακωτέρους. τῶν δ’ ἐνδοτέρω βέλους ὑποδραμόντων οἱ μὲν πρὶν εἰς χεῖρας ἐλθεῖν τὴν εὐταξίαν καὶ τὸ πύκνωμα τῶν πολεμίων καταπλαγέντες, οἱ δὲ νυττόμενοι τοῖς ξυστοῖς ἐπαλινδρόμουν· καὶ τέλος ἀλλήλους κακίζοντες εἰς δειλίαν ἀνεχώρουν ἄπρακτοι. νουμηνίᾳ Πανέμου μηνὸς ἡ ἐπιχείρησις ἦν. ἀναχωρησάντων δὲ τῶν Ἰουδαίων προσῆγον οἱ Ῥωμαῖοι τὰς ἑλεπόλεις, βαλλόμενοι πέτραις τε ἀπὸ τῆς Ἀντωνίας καὶ πυρὶ καὶ σιδήρῳ καὶ παντὶ τῷ χορηγουμένῳ Ἰουδαίοις ὑπὸ τῆς ἀνάγκης βέλει· καίπερ γὰρ πολὺ τῷ τείχει πεποιθότες καὶ τῶν ὀργάνων καταφρονοῦντες ὅμως ἐκώλυον τοὺς Ῥωμαίους προσάγειν. οἱ δὲ τὴν σπουδὴν τῶν Ἰουδαίων τοῦ μὴ πληγῆναι τὴν Ἀντωνίαν ὑπολαμβάνοντες γίνεσθαι δι’ ἀσθένειαν τοῦ τείχους καὶ σαθροὺς ἐλπίσαντες εἶναι τοὺς θεμελίους ἀντεφιλονείκουν. οὐ μὴν ὑπήκουε τὸ τυπτόμενον, ἀλλ’ οἱ μὲν συνεχῶς βαλλόμενοι καὶ πρὸς μηδένα τῶν καθύπερθεν κινδύνων ἐνδιδόντες ἐνεργοὺς παρεῖχον τὰς ἑλεπόλεις· ὡς δ’ ἦσαν ἐλάττους καὶ περιεθραύοντο ταῖς πέτραις, ἕτεροι τοὺς θυρεοὺς ὀροφώσαντες ὑπὲρ τῶν σωμάτων χερσὶ καὶ μοχλοῖς ὑπώρυττον τοὺς θεμελίους, καὶ τέσσαράς γε λίθους προσκαρτερήσαντες ἐξέσεισαν. ἀνέπαυσε δὲ νὺξ ἑκατέρους, κἀν ταύτῃ τὸ τεῖχος ὑπὸ τῶν κριῶν σεσαλευμένον, καὶ καθ’ ὃ τοῖς προτέροις ἐπιβουλεύων χώμασιν ὁ Ἰωάννης ὑπώρυξεν ἐνδούσης τῆς διώρυχος, ἐξαπίνης κατερείπεται.", "st": "6.1.3"}, {"sp": "N", "t": "Τούτου συμβάντος παραδόξως ἑκατέροις διετέθη τὰ φρονήματα· Ἰουδαίους μὲν γάρ, οὓς ἀθυμεῖν εἰκὸς ἦν, τῷ μὴ παρ’ ἐλπίδα γενέσθαι τὸ πτῶμα καὶ προησφαλίσθαι πρὸς αὐτὸ θαρρεῖν ὡς μενούσης συνέβαινε τῆς Ἀντωνίας· Ῥωμαίων δέ γε τὴν παρ’ ἐλπίδα χαρὰν ἐπὶ τῷ καταρριφθέντι ταχέως ἔσβεσεν ὄψις ἑτέρου τείχους, ὅπερ ἔνδοθεν οἱ περὶ τὸν Ἰωάννην ἀντῳκοδομήκεσαν. εὐμαρεστέρα γε μὴν τῆς πρότερον ἡ προσβολὴ κατεφαίνετο· τό τε γὰρ ἀναβῆναι διὰ τῶν καταρριφθέντων ῥᾷον ἐδόκει, καὶ τὸ τεῖχος ἀσθενέστερόν τε πολλῷ τῆς Ἀντωνίας καὶ ταχέως τῷ πρόσκαιρον εἶναι λύειν ὑπελάμβανον. οὐ μὴν ἐτόλμα τις ἀναβῆναι· προῦπτος γὰρ τοῖς ἀρξαμένοις ἦν ἀπώλεια.", "st": "6.1.4"}, {"sp": "N", "t": "Νομίζων δὲ ὁ Τίτος ἐγείρεσθαι μάλιστα τὰς τῶν πολεμούντων προθυμίας ἐλπίδι καὶ λόγῳ, τάς τε προτροπὰς καὶ τὰς ὑποσχέσεις πολλάκις μὲν λήθην ἐνεργάζεσθαι τῶν κινδύνων, ἔστι δ’ ὅτε καὶ θανάτου καταφρόνησιν, συναγαγὼν ἐπὶ ταὐτὸ τοὺς ἀλκίμους ἐπειρᾶτο τῶν ἀνδρῶν, ὦ συστρατιῶται, λέγων, τὸ μὲν παρακελεύειν ἐπὶ τὰ μὴ φέροντα κίνδυνον αὐτόθεν τοῖς παρακελευομένοις ἀκλεές, ἀμέλει δὲ καὶ τῷ παρακελεύοντι φέρει κατάγνωσιν ἀνανδρίας. δεῖ δέ, οἶμαι, προτροπῆς εἰς μόνα τὰ σφαλερὰ τῶν πραγμάτων, ὡς ἐκεῖνά γε καθ’ αὑτοὺς πράττειν ἄξιον. ὥστ’ ἔγωγε τὸ μὲν ὑπάρχειν χαλεπὴν τὴν ἐπὶ τὸ τεῖχος ἄνοδον αὐτὸς ὑμῖν προτίθημι· τὸ δ’ ὅτι μάλιστα προσήκει μάχεσθαι τοῖς δυσκόλοις τοὺς ἀρετῆς ἐφιεμένους καὶ ὅτι καλὸν ἐν εὐκλείᾳ τελευτὴ καὶ ὡς οὐκ ἄκαρπον ἔσται τοῖς καταρξαμένοις τὸ γενναῖον, διέξειμι. πρῶτον μὲν οὖν ὑμῶν γενέσθω προτροπὴ τό τινας ἴσως ἀποτρέπον, ἡ Ἰουδαίων μακροθυμία καὶ τὸ καρτερικὸν ἐν οἷς κακοπαθοῦσιν· αἰσχρὸν γὰρ Ῥωμαίους τε ὄντας καὶ στρατιώτας ἐμούς, καὶ διδακτὸν μὲν ἐν εἰρήνῃ τὸ πολεμεῖν, ἔθιμον δὲ ἐν πολέμῳ τὸ κρατεῖν ἔχοντας, ἡττᾶσθαι κατὰ χεῖρα Ἰουδαίων ἢ κατὰ ψυχήν, καὶ ταῦτα πρὸς τῷ τέλει τῆς νίκης καὶ συνεργουμένους ὑπὸ τοῦ θεοῦ. τὰ γὰρ ἡμέτερα πταίσματα τῆς Ἰουδαίων ἐστὶν ἀπονοίας, τὰ δ’ ἐκείνων πάθη ταῖς τε ὑμετέραις ἀρεταῖς καὶ ταῖς τοῦ θεοῦ συνεργίαις αὔξεται· στάσις γὰρ καὶ λιμὸς καὶ πολιορκία καὶ δίχα μηχανημάτων πίπτοντα τείχη τί ἂν ἀλλ’ ἢ θεοῦ μὲν εἴη μῆνις ἐκείνοις, βοήθεια δὲ ἡμετέρα; τὸ τοίνυν μὴ μόνον ἐλαττοῦσθαι χειρόνων, ἀλλὰ καὶ τὴν θείαν συμμαχίαν προδιδόναι πρὸς ἡμῶν οὐκ ἂν εἴη. πῶς δ’ οὐκ αἰσχρὸν Ἰουδαίους μέν, οἷς οὐ πολλὴν αἰσχύνην φέρει τὸ λείπεσθαι μαθοῦσι δουλεύειν, ὑπὲρ τοῦ μηκέτι τοῦτο πάσχειν θανάτου καταφρονεῖν καὶ πολλάκις εἰς μέσους ἡμᾶς ἐκτρέχειν, οὐκ ἐλπίδι τοῦ κρατήσειν ἀλλὰ διὰ ψιλὴν ἐπίδειξιν ἀνδρείας· ὑμᾶς δὲ τοὺς γῆς ὀλίγου δεῖν ἁπάσης καὶ θαλάσσης κρατοῦντας, οἷς καὶ τὸ μὴ νικᾶν ὄνειδος, μηδ’ ἅπαξ εἰς τοὺς πολεμίους παραβάλλεσθαι, περιμένειν δὲ τὸν λιμὸν κατ’ αὐτῶν καὶ τὴν τύχην ἀργοὺς καθεζομένους μετὰ τοιούτων ὅπλων, καὶ ταῦτα δι’ ὀλίγου τοῦ παραβόλου τὸ πᾶν κατορθῶσαι δυναμένους; ἀναβάντες γοῦν ἐπὶ τὴν Ἀντωνίαν ἔχομεν τὴν πόλιν· καὶ γὰρ ἂν γίνηταί τις ἔτι πρὸς τοὺς ἔνδον, ὅπερ οὐκ οἶμαι, μάχη, τό γε κατὰ κορυφὴν εἶναι καὶ ταῖς ἀναπνοαῖς ἐπικαθῆσθαι τῶν πολεμίων ταχέως τὴν ὁλοσχερῆ νίκην ἐγγυᾶται. καὶ ἔγωγε τὸ μὲν ὑμνεῖν ἄρτι τὴν ἐν πολέμῳ τελευτὴν καὶ τὴν ἐπὶ τοῖς ἀρειμανίοις πεσοῦσιν ἀθανασίαν παραλιπὼν ἐπαρασαίμην ἂν τοῖς ἄλλως ἔχουσι τὸν κατ’ εἰρήνην ἐκ νόσου θάνατον, οἷς μετὰ τοῦ σώματος καὶ ἡ ψυχὴ τάφῳ κατακρίνεται. τίς γὰρ οὐκ οἶδε τῶν ἀγαθῶν ἀνδρῶν ὅτι τὰς μὲν ἐν παρατάξει ψυχὰς σιδήρῳ τῶν σαρκῶν ἀπολυθείσας τὸ καθαρώτατον στοιχεῖον αἰθὴρ ξενοδοχῶν ἄστροις ἐγκαθιδρύει, δαίμονες δ’ ἀγαθοὶ καὶ ἥρωες εὐμενεῖς ἰδίοις ἐγγόνοις ἐμφανίζονται, τὰς δὲ ἐν νοσοῦσι τοῖς σώμασι συντακείσας, κἂν τὰ μάλιστα κηλίδων ἢ μιασμάτων ὦσι καθαραί, νὺξ ὑπόγειος ἀφανίζει καὶ λήθη βαθεῖα δέχεται, λαμβανούσας ἅμα τοῦ τε βίου καὶ τῶν σωμάτων ἔτι δὲ τῆς μνήμης περιγραφήν; εἰ δὲ κέκλωσται μὲν ἀνθρώποις ἀναγκαία τελευτή, κουφότερον δὲ εἰς αὐτὴν νόσου πάσης σίδηρος ὑπηρέτης, πῶς οὐκ ἀγεννὲς μὴ διδόναι ταῖς χρείαις ὃ τῷ χρεὼν ἀποδώσομεν; καὶ ταῦτα μὲν ὡς οὐ δυναμένων σωθῆναι τῶν ἐπιχειρησόντων διεξῆλθον· ἔνεστι δὲ σώζεσθαι τοῖς ἀνδριζομένοις κἀκ τῶν σφαλερωτάτων. πρῶτον μὲν γὰρ τὸ καταρριφθὲν εὐεπίβατον, ἔπειτα πᾶν τὸ οἰκοδομηθὲν εὐδιάλυτον, ὑμεῖς τε πλείους θαρσήσαντες ἐπὶ τὴν πρᾶξιν ἀλλήλοις προτροπὴ καὶ βοήθεια γίνεσθε, καὶ τοῖς πολεμίοις τὸ ὑμέτερον παράστημα ταχέως κλάσει τὰ φρονήματα. καὶ τάχα ἂν ὑμῖν ἀναίμακτον τὸ κατόρθωμα γένοιτο μόνον καταρξαμένοις· ἀναβαίνοντας μὲν γὰρ κωλύειν πειράσονται κατὰ τὸ εἰκός, λαθόντας δὲ καὶ βιασαμένους ἅπαξ οὐκ ἂν ὑποσταῖεν ἔτι, κἂν ὀλίγοι φθάσητε. τὸν δὲ καταρξάμενον αἰσχυνοίμην ἂν εἰ μὴ ποιήσαιμι ζηλωτὸν ἐν ταῖς ἐπικαρπίαις, καὶ ὁ μὲν ζῶν ἄρξει τῶν νῦν ὁμοίων, μακαριστὰ δ’ ἀκολουθήσει καὶ τοῖς πεσοῦσι τὰ ἀριστεῖα.", "st": "6.1.5"}, {"sp": "N", "t": "Τοιαῦτα τοῦ Τίτου διεξιόντος τὸ μὲν ἄλλο πλῆθος ἔδεισε τοῦ κινδύνου τὸ μέγεθος, τῶν δ’ ἐν ταῖς σπείραις στρατευομένων Σαβῖνος τοὔνομα, γένος ἀπὸ Συρίας, ἀνὴρ καὶ κατὰ χεῖρα καὶ κατὰ ψυχὴν ἄριστος ἐφάνη. καίτοι προϊδὼν ἄν τις αὐτὸν ἀπό γε τῆς σωματικῆς ἕξεως οὐδ’ εἰκαῖον εἶναι στρατιώτην ἔδοξε· μέλας μὲν γὰρ ἦν τὴν χροίαν, ἰσχνός, τὴν σάρκα πεπιλημένος, ἀλλ’ ἐνῴκει τις ἡρωικὴ ψυχὴ λεπτῷ σώματι καὶ πολὺ τῆς ἰδίας ἀλκῆς στενοτέρῳ. πρῶτος γοῦν ἀναστάς ἐπιδίδωμί σοι, Καῖσαρ, ἔφη, προθύμως ἐμαυτόν. πρῶτος ἀναβαίνω τὸ τεῖχος. καὶ εὔχομαι μέν μου τῇ τε ἰσχύι καὶ τῇ γνώμῃ τὴν σὴν ἀκολουθῆσαι τύχην, εἰ δὲ νεμεσηθείην τῆς ἐπιβολῆς, ἴσθι μή με πταίσαντα παρ’ ἐλπίδας, ἀλλ’ ὑπὲρ σοῦ κρίσει τὸν θάνατον ᾑρημένον. ταῦτα εἰπὼν καὶ τῇ μὲν ἀριστερᾷ χειρὶ τὸν θυρεὸν ὑπὲρ τῆς κεφαλῆς ἀνατείνας, τῇ δεξιᾷ δὲ τὸ ξίφος σπασάμενος ἐχώρει πρὸς τὸ τεῖχος περὶ ὥραν μάλιστα τῆς ἡμέρας ἕκτην. εἵποντο δ’ αὐτῷ καὶ τῶν ἄλλων ἕνδεκα μόνοι ζηλωταὶ τῆς ἀνδρείας γενόμενοι· προῆγε δὲ πολὺ πάντων ὁ ἀνὴρ ὁρμῇ τινι δαιμονίῳ χρώμενος. οἱ φρουροὶ δὲ ἀπὸ τοῦ τείχους κατηκόντιζόν τε αὐτοὺς καὶ βέλεσι πάντοθεν ἀπείροις ἔβαλλον καὶ πέτρας ἐξαισίους κατεκύλιον, αἳ ἐκ τῶν μὲν ἕνδεκα παρέσυραν ἐνίους, ὁ δὲ Σαβῖνος ἀπαντῶν τοῖς ἀφιεμένοις καὶ καταχωννύμενος ὑπὸ τῶν βελῶν οὐ πρότερον ἐπέσχε τὴν ὁρμὴν ἢ γενέσθαι τε ἐπ’ ἄκρῳ καὶ τρέψασθαι τοὺς πολεμίους· καταπλαγέντες γὰρ αὐτοῦ τήν τε δύναμιν οἱ Ἰουδαῖοι καὶ τὸ παράστημα τῆς ψυχῆς, ἅμα δὲ καὶ πλείους ἀναβεβηκέναι δόξαντες ἐτράπησαν. ἔνθα δὴ καταμέμψαιτ’ ἄν τις ὡς φθονερὰν ἐπὶ ταῖς ἀρεταῖς τὴν τύχην καὶ κωλύουσαν ἀεὶ τὰ παράδοξα τῶν κατορθωμάτων. ὁ γοῦν ἀνὴρ οὗτος ὅτ’ ἐκράτησε τῆς ἐπιβολῆς, ἐσφάλη καὶ πταίσας πρός τινι πέτρᾳ πρηνὴς ἐπ’ αὐτὴν μετὰ μεγίστου ψόφου κατέπεσεν· ἐπιστραφέντες δὲ οἱ Ἰουδαῖοι καὶ κατιδόντες μόνον τε αὐτὸν καὶ πεπτωκότα, πάντοθεν ἔβαλλον. ὁ δ’ ἐς γόνυ διαναστὰς καὶ προκαλυψάμενος τὸν θυρεὸν τὸ μὲν πρῶτον ἠμύνετο καὶ πολλοὺς τῶν πλησιασάντων ἔτρωσεν· αὖθις δ’ ὑπὸ πλήθους τραυμάτων παρῆκε τὴν δεξιὰν καὶ τέλος πρὶν ἀποδοῦναι τὴν ψυχὴν κατεχώσθη τοῖς βέλεσιν, ἀνὴρ ἄξιος μὲν ἀμείνονι χρῆσθαι δι’ ἀνδρείαν καὶ τύχῃ, πεσὼν δὲ τῆς ἐπιβολῆς ἀναλόγως. τῶν δὲ ἄλλων τρεῖς μὲν τοὺς ἤδη πρὸς τοῖς ἄκροις ὄντας συντρίψαντες ἀπέκτειναν τοῖς λίθοις, οἱ δὲ ὀκτὼ τραυματίαι κατασυρέντες ἀνεκομίσθησαν εἰς τὸ στρατόπεδον. ταῦτα μὲν οὖν τρίτῃ μηνὸς Πανέμου ἐπράχθη.", "st": "6.1.6"}, {"sp": "N", "t": "Μετὰ δ’ ἡμέρας δύο τῶν προκοιτούντων τινὲς ἐπὶ τοῖς χώμασι φυλάκων εἴκοσι συνελθόντες προσποιοῦνται μὲν τὸν τοῦ πέμπτου τάγματος σημαιαφόρον καὶ δύο τινὰς τῶν ἐν ταῖς ἴλαις ἱππέων καὶ σαλπικτὴν ἕνα, κατὰ δὲ ὥραν τῆς νυκτὸς ἐνάτην προσβαίνουσι μὲν ἡσυχῆ διὰ τῶν ἐρειπίων ἐπὶ τὴν Ἀντωνίαν, ἀποσφάξαντες δὲ τοὺς πρώτους τῶν φρουρῶν κοιμωμένους κρατοῦσι τοῦ τείχους καὶ τῷ σαλπικτῇ σημαίνειν ἐκέλευσαν. πρὸς ὃ τῶν μὲν ἄλλων φυλάκων ἐξανάστασις αἰφνίδιος ἦν καὶ φυγὴ πρίν τινα τὸ πλῆθος ἐπιδεῖν τῶν ἐπιβεβηκότων· ὅ τε γὰρ φόβος καὶ ἡ σάλπιγξ φαντασίαν αὐτοῖς τοῦ πλῆθος ἀναβεβηκέναι πολεμίων παρεῖχε. Καῖσαρ δὲ τοῦ σημείου κατακούσας ἐξοπλίζει τήν τε δύναμιν διὰ τάχους καὶ μετὰ τῶν ἡγεμόνων πρῶτος ἀναβαίνει τοὺς ἐπιλέκτους ἔχων. καταπεφευγότων δὲ Ἰουδαίων εἰς τὸ ἱερὸν καὶ αὐτοὶ διὰ τῆς διώρυγος εἰσέπιπτον, ἣν ὁ Ἰωάννης ἐπὶ τὰ χώματα τῶν Ῥωμαίων ὑπώρυξε. καὶ διαστάντες ἀπ’ ἀμφοτέρων οἱ στασιασταὶ τῶν ταγμάτων, τοῦ τε Ἰωάννου καὶ τοῦ Σίμωνος, εἶργον αὐτοὺς οὐδεμίαν οὔτε ἰσχύος οὔτε προθυμίας ἐλλείποντες ὑπερβολήν· πέρας γὰρ ἁλώσεως ὑπελάμβανον τὸ Ῥωμαίους παρελθεῖν εἰς τὸ ἅγιον, ὃ δὴ κἀκεῖνοι τοῦ κρατεῖν ἀρχήν. συρρήγνυται δὲ περὶ τὰς εἰσόδους μάχη καρτερά, τῶν μὲν καταλαβέσθαι καὶ τὸ ἱερὸν εἰσβιαζομένων, τῶν δὲ Ἰουδαίων ἐξωθούντων αὐτοὺς ἐπὶ τὴν Ἀντωνίαν. καὶ τὰ βέλη μὲν ἦν ἀμφοτέροις ἄχρηστα καὶ τὰ δόρατα, σπασάμενοι δὲ τὰ ξίφη συνεπλέκοντο, καὶ περὶ τὴν συμβολὴν ἄκριτον ἦν ὁποτέρωθεν ἕκαστοι μάχοιντο, πεφυρμένων μὲν τῶν ἀνδρῶν καὶ περὶ τὴν στενοχωρίαν διηλλαγμένων, τῆς δὲ βοῆς ἀσημάντου προσπιπτούσης διὰ τὸ μέγεθος. φόνος τε ἦν ἑκατέρωθεν πολύς, καὶ τῶν πεσόντων τά τε σώματα καὶ τὰς πανοπλίας πατοῦντες ἔθραυον οἱ μαχόμενοι. ἀεὶ δ’ ἐφ’ ὁπότερον βρίσειεν ῥέων ὁ πόλεμος, παρακέλευσις μὲν ἦν τῶν πλεονεκτούντων, οἰμωγαὶ δὲ τῶν τρεπομένων. οὔτε δὲ αἱ φυγαὶ τόπον εἶχον οὔτε αἱ διώξεις, ἀλλ’ ἀγχώμαλοι ῥοπαὶ καὶ μετακλίσεις μεμιγμένης ἐγίνοντο τῆς παρατάξεως. τοῖς δ’ ἔμπροσθεν γινομένοις ἢ τοῦ θνήσκειν ἢ τοῦ κτείνειν ἀνάγκη παρῆν οὐκ οὔσης ἀναφυγῆς· οἱ γὰρ κατὰ νώτου πρόσω βιαζόμενοι τοὺς σφετέρους παρ’ ἀμφοῖν οὐδὲ τῇ μάχῃ μεταίχμιον κατέλειπον. πλεονεκτούντων δὲ τῶν Ἰουδαίων τοῖς θυμοῖς τὴν Ῥωμαίων ἐμπειρίαν καὶ κλινομένης καθάπαν ἤδη τῆς παρατάξεως, ἀπὸ γὰρ ἐνάτης ὥρας τῆς νυκτὸς εἰς ἑβδόμην τῆς ἡμέρας ἐπολέμουν, οἱ μὲν ἀθρόοι καὶ τὸν τῆς ἁλώσεως κίνδυνον ἔχοντες ἀνδρείας ἐφόδιον Ῥωμαῖοι δὲ μέρει τῆς δυνάμεως, οὔπω γὰρ ἐπαναβεβήκει τὰ τάγματα, κἀκείνοις ἐπανεῖχον οἱ μαχόμενοι τότε, κρατεῖν τῆς Ἀντωνίας ἀποχρῆν ἐπὶ τοῦ παρόντος ἐδόκει.", "st": "6.1.7"}, {"sp": "N", "t": "Ἰουλιανὸς δέ τις ἑκατοντάρχης τῶν ἀπὸ τῆς Βιθυνίας, οὐκ ἄσημος ὢν ἀνήρ, ὧν ἐγὼ κατ’ ἐκεῖνον ἱστόρησα τὸν πόλεμον ὅπλων τε ἐμπειρίᾳ καὶ ἀλκῇ σώματος καὶ ψυχῆς παραστήματι πάντων ἄριστος, ὁρῶν τοὺς Ῥωμαίους ἐνδιδόντας ἤδη καὶ κακῶς ἀμυνομένους, παρειστήκει δὲ Τίτῳ κατὰ τὴν Ἀντωνίαν, προπηδᾷ καὶ νικῶντας ἤδη τοὺς Ἰουδαίους τρέπεται μόνος μέχρι τῆς τοῦ ἐνδοτέρω ἱεροῦ γωνίας. ἔφευγε δὲ τὸ πλῆθος ἄθρουν, οὔτε τὴν ἰσχὺν οὔτε τὴν τόλμαν ἀνθρωπίνην ὑπολαμβάνοντες. ὁ δὲ διὰ μέσων τῶν σκεδαννυμένων ἄλλοτε ἄλλῃ διᾴττων ἐφόνευε τοὺς καταλαμβανομένους, καὶ τῆς ὄψεως ἐκείνης οὐδὲν οὔτε τῷ Καίσαρι θαυμασιώτερον οὔτε τοῖς ἄλλοις παρέστη φρικωδέστερον. ἐδιώκετο δὲ ἄρα καὶ αὐτὸς ὑπὸ τῆς εἱμαρμένης, ἣν ἀμήχανον διαφυγεῖν θνητὸν ὄντα. τὰ γὰρ ὑποδήματα πεπαρμένα πυκνοῖς καὶ ὀξέσιν ἥλοις ἔχων, ὥσπερ τῶν ἄλλων στρατιωτῶν ἕκαστος, καὶ κατὰ λιθοστρώτου τρέχων ὑπολισθάνει, πεσὼν δὲ ὕπτιος μετὰ μεγίστου τῆς πανοπλίας ἤχου τοὺς φεύγοντας ἐπιστρέφει. καὶ τῶν μὲν ἀπὸ τῆς Ἀντωνίας Ῥωμαίων ἤρθη βοὴ περὶ τἀνδρὶ δεισάντων, οἱ δὲ Ἰουδαῖοι περιστάντες αὐτὸν ἀθρόοι τοῖς τε ξυστοῖς καὶ ταῖς ῥομφαίαις πάντοθεν ἔπαιον. ὁ δὲ πολὺν μὲν τῷ θυρεῷ σίδηρον ἐξεδέχετο, πολλάκις δὲ ἀναστῆναι πειράσας ὑπὸ τοῦ πλήθους τῶν τυπτόντων ἀνετράπη, καὶ κείμενος δ’ ὅμως ἔνυττε τῷ ξίφει πολλούς· οὐδὲ γὰρ ἀνῃρέθη ταχέως τῷ τε κράνει καὶ τῷ θώρακι πεφραγμένος πάντα τὰ καίρια πρὸς σφαγὴν καὶ τὸν αὐχένα συνέλκων· μέχρι κοπτομένων αὐτῷ τῶν ἄλλων μελῶν καὶ μηδενὸς προσαμῦναι τολμῶντος ἐνέδωκε. δεινὸν δὲ πάθος εἰσῄει Καίσαρα ἀνδρὸς οὕτως ἐναρέτου καὶ ἐν ὄψει τοσούτων φονευομένου· καὶ αὐτὸν μὲν ὁ τόπος διέκλειε βοηθεῖν θέλοντα, τοὺς δυναμένους δὲ κατάπληξις. Ἰουλιανὸς μὲν οὖν πολλὰ δυσθανατήσας καὶ τῶν κτεινόντων ὀλίγους ἀπλῆγας καταλιπὼν μόλις ἀποσφάττεται, μέγιστον οὐ παρὰ Ῥωμαίοις καὶ Καίσαρι μόνον ἀλλὰ καὶ παρὰ τοῖς πολεμίοις κλέος καταλιπών· Ἰουδαῖοι δὲ καὶ τὸν νεκρὸν ἁρπασάμενοι πάλιν τοὺς Ῥωμαίους τρέπονται καὶ κατακλείουσιν εἰς τὴν Ἀντωνίαν. ἠγωνίσαντο δὲ ἐξ αὐτῶν ἐπισήμως κατὰ ταύτην τὴν μάχην Ἀλεξᾶς μέν τις καὶ Γυφθέος τοῦ Ἰωάννου τάγματος, ἐκ δὲ τῶν περὶ Σίμωνα Μαλαχίας τε καὶ ὁ τοῦ Μέρτωνος Ἰούδας, καὶ Σωσᾶ υἱὸς Ἰάκωβος τῶν Ἰδουμαίων ἡγεμών, τῶν δὲ ζηλωτῶν ἀδελφοὶ δύο, παῖδες Ἀρί, Σίμων τε καὶ Ἰούδης.", "st": "6.1.8"}, {"sp": "N", "t": "Τίτος δὲ τοῖς μὲν σὺν αὐτῷ στρατιώταις κατασκάπτειν προσέταξε τοὺς θεμελίους τῆς Ἀντωνίας καὶ τῇ δυνάμει πάσῃ ῥᾳδίαν τὴν ἄνοδον εὐτρεπίζειν, αὐτὸς δὲ τὸν Ἰώσηπον παραστησάμενος· ἐπέπυστο γὰρ ἐπ’ ἐκείνης τῆς ἡμέρας, Πανέμου δ’ ἦν ἑπτακαιδεκάτη, τὸν ἐνδελεχισμὸν καλούμενον ἀνδρῶν ἀπορίᾳ διαλελοιπέναι τῷ θεῷ καὶ τὸν δῆμον ἐπὶ τούτῳ δεινῶς ἀθυμεῖν· λέγειν τῷ Ἰωάννῃ πάλιν ἐκέλευσεν ἃ καὶ πρότερον, ὡς εἰ καί τις αὐτὸν ἔρως κακὸς ἔχοι τοῦ μάχεσθαι, προελθόντι μεθ’ ὅσων βούλεται πολεμεῖν ἐξείη δίχα τοῦ συναπολέσθαι τήν τε πόλιν καὶ τὸν ναὸν αὐτῷ, μηκέτι μέντοι μιαίνειν τὸ ἅγιον μηδὲ εἰς τὸν θεὸν πλημμελεῖν, παρεῖναι δ’ αὐτῷ τὰς ἐπιλελοιπυίας θυσίας ἐκτελεῖν δι’ ὧν ἂν ἐπιλέξηται Ἰουδαίων. καὶ ὁ Ἰώσηπος, ὡς ἂν εἴη μὴ τῷ Ἰωάννῃ μόνον ἀλλὰ καὶ τοῖς πολλοῖς ἐν ἐπηκόῳ, τά τε τοῦ Καίσαρος διήγγελλεν ἑβραΐζων, καὶ πολλὰ προσηντιβόλει φείσασθαι τῆς πατρίδος καὶ διασκεδάσαι τοῦ ναοῦ γευόμενον ἤδη τὸ πῦρ, τούς τ’ ἐναγισμοὺς ἀποδοῦναι τῷ θεῷ. πρὸς ταῦτα τοῦ δήμου μὲν ἦν κατήφεια καὶ σιγή, πολλὰ δ’ ὁ τύραννος λοιδορηθείς τε τῷ Ἰωσήπῳ καὶ καταρασάμενος τὸ τελευταῖον προσέθηκεν, ὡς οὐκ ἄν ποτε δείσειεν ἅλωσιν· θεοῦ γὰρ ὑπάρχειν τὴν πόλιν. καὶ ὁ Ἰώσηπος πρὸς ταῦτα ἀνέκραγεν πάνυ γοῦν καθαρὰν τῷ θεῷ τετήρηκας αὐτήν, ἀμίαντον δὲ μένει τὸ ἅγιον, εἰς ὅν τ’ ἐλπίζεις σύμμαχον οὐδὲν ἠσέβησας, τὰς δ’ ἐθίμους θυσίας ἀπολαμβάνει. κἂν μὲν σοῦ τις ἀφέλῃ τὴν καθ’ ἡμέραν τροφήν, ἀσεβέστατε, τοῦτον ἥγησαι πολέμιον, αὐτὸν δ’ ὃν τῆς αἰωνίου θρησκείας ἐστέρησας θεὸν ἐλπίζεις σύμμαχον ἔχειν ἐν τῷ πολέμῳ; καὶ Ῥωμαίοις τὰς ἁμαρτίας ἀνατίθης, οἳ μέχρι νῦν κήδονται τῶν ἡμετέρων νόμων καὶ τὰς ὑπὸ σοῦ διακοπείσας θυσίας ἀποδίδοσθαι τῷ θεῷ βιάζονται; τίς οὐκ ἂν στενάξειε καὶ κατολοφύραιτο τῆς παραδόξου μεταβολῆς τὴν πόλιν, εἴ γε ἀλλόφυλοι μὲν καὶ πολέμιοι τὴν σὴν ἀσέβειαν ἐπανορθοῦνται, σὺ δ’ ὁ Ἰουδαῖος, ὁ τοῖς νόμοις ἐντραφείς, κἀκείνων πρὸς αὐτοὺς γίνῃ χαλεπώτερος; ἀλλά τοι, Ἰωάννη, καὶ μετανοῆσαι μὲν ἐκ κακῶν οὐκ αἰσχρὸν ἐν ἐσχάτοις καὶ καλὸν ὑπόδειγμα βουλομένῳ σώζειν τὴν πατρίδα σοι πρόκειται βασιλεὺς Ἰουδαίων Ἰεχονίας, ὅς ποτε στρατεύσαντι τῷ Βαβυλωνίῳ δι’ αὐτὸν ἑκὼν ἐξέστη πρὶν ἁλῶναι τῆς πόλεως καὶ μετὰ γενεᾶς αἰχμαλωσίαν ὑπέμεινεν ἐθελούσιον ὑπὲρ τοῦ μὴ παραδοῦναι ταῦτα πολεμίοις τὰ ἅγια καὶ τὸν οἶκον τοῦ θεοῦ περιιδεῖν φλεγόμενον. διὰ τοῦτο λόγος τε αὐτὸν πρὸς ἁπάντων Ἰουδαίων ἱερὸς ὑμνεῖ καὶ μνήμη ῥέουσα δι’ αἰῶνος ἀεὶ νέα τοῖς ἐπιγινομένοις παραδίδωσιν ἀθάνατον. καλόν, ὦ Ἰωάννη, ὑπόδειγμα, κἂν προσῇ κίνδυνος· ἐγὼ δέ σοι καὶ τὴν ἀπὸ Ῥωμαίων συγγνώμην ἐγγυῶμαι. μέμνησο δ’ ὡς ὁμόφυλος ὢν παραινῶ καὶ Ἰουδαῖος ὢν ἐπαγγέλλομαι, καὶ χρὴ σκοπεῖν τίς ὁ συμβουλεύων καὶ πόθεν. μὴ γὰρ ἔγωγέ ποτε γενοίμην ζῶν οὕτως αἰχμάλωτος, ἵνα παύσωμαι τοῦ γένους ἢ τῶν πατρίων ἐπιλάθωμαι. πάλιν ἀγανακτεῖς καὶ κέκραγάς μοι λοιδορούμενος, ἀξίῳ γε καὶ χαλεπωτέρων, ὃς ἀντικρὺς εἱμαρμένης τι παραινῶ καὶ τοὺς ὑπὸ τοῦ θεοῦ βιάζομαι κατακρίτους σώζειν. τίς οὐκ οἶδεν τὰς τῶν παλαιῶν προφητῶν ἀναγραφὰς καὶ τὸν ἐπιρρέποντα τῇ τλήμονι πόλει χρησμὸν ἤδη ἐνεστῶτα; τότε γὰρ ἅλωσιν αὐτῆς προεῖπον, ὅταν ὁμοφύλου τις ἄρξῃ φόνου. τῶν ὑμετέρων δὲ πτωμάτων οὐχ ἡ πόλις καὶ τὸ ἱερὸν δὲ πᾶν πεπλήρωται; θεὸς ἄρα, θεὸς αὐτὸς ἐπάγει μετὰ Ῥωμαίων κάθαρσιν αὐτῷ πῦρ καὶ τὴν τοσούτων μιασμάτων γέμουσαν πόλιν ἀναρπάζει.", "st": "6.2.1"}, {"sp": "N", "t": "Ταῦτα λέγων ὁ Ἰώσηπος μετ’ ὀδυρμοῦ καὶ δακρύων λυγμῷ τὴν φωνὴν ἐνεκόπη. καὶ Ῥωμαῖοι μὲν ᾤκτειράν τε τοῦ πάθους καὶ τῆς προαιρέσεως αὐτὸν ἐθαύμασαν, οἱ δὲ περὶ τὸν Ἰωάννην παρωξύνοντο μᾶλλον ἐπὶ τοὺς Ῥωμαίους ἐπιθυμοῦντες ἐγκρατεῖς γενέσθαι κἀκείνου. τῶν γε μὴν εὐγενῶν πολλοὺς ἐκίνησεν ὁ λόγος, καὶ τινὲς μὲν ὀρρωδοῦντες τὰς φυλακὰς τῶν στασιαστῶν κατὰ χώραν ἔμενον, ἀπώλειαν μέντοι σφῶν τε αὐτῶν καὶ τῆς πόλεως κατεγνώκεσαν, εἰσὶ δὲ οἳ καιροφυλακήσαντες ἄδειαν ἀναχωρήσεως πρὸς τοὺς Ῥωμαίους κατέφυγον. ὧν ἦσαν ἀρχιερεῖς μὲν Ἰώσηπός τε καὶ Ἰησοῦς, υἱοὶ δὲ ἀρχιερέων τρεῖς μὲν Ἰσμαήλου τοῦ καρατομηθέντος ἐν Κυρήνῃ, καὶ τέσσαρες Ματθίου καὶ εἷς ἑτέρου Ματθίου, διαδρὰς μετὰ τὴν τοῦ πατρὸς ἀπώλειαν, ὃν ὁ τοῦ Γιώρα Σίμων ἀπέκτεινεν σὺν τρισὶν υἱοῖς, ὡς προείρηται. πολλοὶ δὲ καὶ τῶν ἄλλων εὐγενῶν τοῖς ἀρχιερεῦσι συμμετεβάλοντο. Καῖσαρ δὲ αὐτοὺς τά τε ἄλλα φιλοφρόνως ἐδέξατο καὶ γινώσκων ἀλλοφύλοις ἤθεσιν ἀηδῆ τὴν διατριβὴν ἕξειν ἀπέπεμψεν αὐτοὺς εἰς Γόφναν, τέως ἐκεῖ παραινῶν μένειν· ἀποδώσειν γὰρ ἑκάστῳ τὰς κτήσεις κατὰ σχολὴν ἀπὸ τοῦ πολέμου γενόμενος. οἱ μὲν οὖν εἰς τὸ δοθὲν πολίχνιον μετὰ πάσης ἀσφαλείας ἀνεχώρουν ἄσμενοι· μὴ φαινομένων δὲ αὐτῶν διεφήμισαν οἱ στασιασταὶ πάλιν ὡς ἀποσφαγεῖεν ὑπὸ Ῥωμαίων οἱ αὐτόμολοι, δηλονότι τοὺς λοιποὺς ἀποτρέποντες τῷ φόβῳ διαδιδράσκειν. ἤνυστο δ’ ὡς καὶ πρότερον αὐτοῖς τὸ πανοῦργον πρὸς καιρόν· ἐπεσχέθησαν γὰρ ὑπὸ τοῦ δέους αὐτομολεῖν.", "st": "6.2.2"}, {"sp": "N", "t": "Αὖθις δέ, ὡς ἀνακαλέσας τοὺς ἄνδρας ἀπὸ τῆς Γοφνὰ Τίτος ἐκέλευσε μετὰ τοῦ Ἰωσήπου περιελθόντας τὸ τεῖχος ὀφθῆναι τῷ δήμῳ, πλεῖστοι πρὸς τοὺς Ῥωμαίους ἔφευγον. γενόμενοι δὲ ἀθρόοι καὶ πρὸ τῶν Ῥωμαίων ἱστάμενοι μετ’ οἰμωγῆς καὶ δακρύων ἱκέτευον τοὺς στασιαστὰς τὸ μὲν πρῶτον ὅλῃ τοὺς Ῥωμαίους δέξασθαι τῇ πόλει καὶ τὴν πατρίδα σῶσαι πάλιν, εἰ δὲ μή, τοῦ γε ἱεροῦ πάντως ὑπεξελθεῖν καὶ ῥύσασθαι τὸν ναὸν αὐτοῖς· οὐ γὰρ ἂν τολμῆσαι Ῥωμαίους μὴ μετὰ μεγίστης ἀνάγκης καταφλέξαι τὰ ἅγια. τούτοις μᾶλλον ἀντεφιλονείκουν, καὶ πολλὰ βλάσφημα τοῖς αὐτομόλοις ἀντικεκραγότες ἐπὶ τῶν ἱερῶν πυλῶν τούς τε ὀξυβελεῖς καὶ καταπέλτας καὶ λιθοβόλους μηχανὰς διέστησαν, ὡς τὸ κύκλῳ μὲν ἱερὸν ὑπὸ πλήθους νεκρῶν προσεοικέναι πολυανδρίῳ, τὸν δὲ ναὸν αὐτὸν φρουρίῳ. τοῖς δὲ ἁγίοις καὶ ἀβάτοις μετὰ τῶν ὅπλων εἰσεπήδων θερμὰς ἔτι τὰς χεῖρας ἐξ ὁμοφύλων ἔχοντες φόνων, καὶ προύκοψαν εἰς τοσοῦτον παρανομίας, ὥσθ’ ἣν ἂν εἰκὸς ἀγανάκτησιν γενέσθαι Ἰουδαίων, εἰ Ῥωμαῖοι ταῦτ’ ἐξύβριζον εἰς αὐτούς, ταύτην εἶναι παρὰ Ῥωμαίων τότε πρὸς Ἰουδαίους ἀσεβοῦντας εἰς τὰ ἴδια. τῶν μέν γε στρατιωτῶν οὐκ ἔστιν ὅστις οὐ μετὰ φρίκης εἰς τὸν ναὸν ἀφεώρα καὶ προσεκύνει τούς τε λῃστὰς ηὔχετο πρὶν ἀνηκέστου πάθους μετανοῆσαι.", "st": "6.2.3"}, {"sp": "N", "t": "Τίτος δὲ ὑπερπαθήσας πάλιν ἐξωνείδιζε τοὺς περὶ τὸν Ἰωάννην, λέγων ἆρ’ οὐχ ὑμεῖς, ὦ μιαρώτατοι, τὸν δρύφακτον τοῦτον προεβάλεσθε τῶν ἁγίων; οὐχ ὑμεῖς δὲ τὰς ἐν αὐτῷ στήλας διεστήσατε, γράμμασιν Ἑλληνικοῖς καὶ ἡμετέροις κεχαραγμένας, μηδένα τὸ γείσιον ὑπερβαίνειν παραγγέλλειν; οὐχ ἡμεῖς δὲ τοὺς ὑπερβάντας ὑμῖν ἀναιρεῖν ἐπετρέψαμεν, κἂν Ῥωμαῖός τις ᾖ; τί οὖν νῦν, ἀλιτήριοι, καὶ νεκροὺς ἐν αὐτῷ καταπατεῖτε; τί δὲ τὸν ναὸν αἵματι ξένῳ καὶ ἐγχωρίῳ φύρετε; μαρτύρομαι θεοὺς ἐγὼ πατρίους καὶ εἴ τις ἐφεώρα ποτὲ τόνδε τὸν χῶρον, νῦν μὲν γὰρ οὐκ οἴομαι, μαρτύρομαι δὲ καὶ στρατιὰν τὴν ἐμὴν καὶ τοὺς παρ’ ἐμοὶ Ἰουδαίους καὶ ὑμᾶς αὐτούς, ὡς οὐκ ἐγὼ ταῦθ’ ὑμᾶς ἀναγκάζω μιαίνειν. κἂν ἀλλάξητε τῆς παρατάξεως τὸν τόπον, οὔτε προσελεύσεταί τις Ῥωμαίων τοῖς ἁγίοις οὔτε ἐνυβρίσει, τηρήσω δὲ τὸν ναὸν ὑμῖν καὶ μὴ θέλουσι.", "st": "6.2.4"}, {"sp": "N", "t": "Ταῦτα τοῦ Ἰωσήπου διαγγέλλοντος ἐκ τοῦ Καίσαρος, οἱ λῃσταὶ καὶ ὁ τύραννος οὐκ ἀπ’ εὐνοίας ἀλλὰ κατὰ δειλίαν γίνεσθαι τὰς παρακλήσεις δοκοῦντες ὑπερηφάνουν. Τίτος δὲ ὡς οὔτε οἶκτον ἑαυτῶν τοὺς ἄνδρας οὔτε φειδὼ τοῦ ναοῦ ποιουμένους ἑώρα, πάλιν πρὸς πόλεμον ἄκων ἐχώρει. πᾶσαν μὲν οὖν τὴν δύναμιν ἐπάγειν αὐτοῖς οὐχ οἷόν τε ἦν μὴ χωρουμένην τῷ τόπῳ, τριάκοντα δ’ ἐπιλέξας ἀφ’ ἑκάστης ἑκατονταρχίας τοὺς ἀρίστους καὶ τοῖς χιλιάρχοις ἀνὰ χιλίους παραδούς, τούτων δ’ ἐπιτάξας ἡγεμόνα Κερεάλιον, ἐπιθέσθαι προσέταξε ταῖς φυλακαῖς περὶ ὥραν τῆς νυκτὸς ἐνάτην. ὄντα δὲ καὶ αὐτὸν ἐν τοῖς ὅπλοις καὶ συγκαταβαίνειν παρεσκευασμένον οἵ τε φίλοι διὰ τὸ μέγεθος τοῦ κινδύνου κατέσχον καὶ τὰ παρὰ τῶν ἡγεμόνων λεγόμενα· πλεῖον γὰρ αὐτὸν ἀνύσειν ἔφασαν ἐπὶ τῆς Ἀντωνίας καθεζόμενον καὶ τὴν μάχην ἀγωνοθετοῦντα τοῖς στρατιώταις ἢ εἰ καταβὰς προκινδυνεύοι· πάντας γὰρ ὁρῶντος Καίσαρος ἀγαθοὺς πολεμιστὰς ἔσεσθαι. τούτοις πεισθεὶς Καῖσαρ καὶ δι’ ἓν τοῦτο τοῖς στρατιώταις ὑπομένειν εἰπών, ἵνα κρίνῃ τὰς ἀρετὰς αὐτῶν καὶ μήτε τῶν ἀγαθῶν τις ἀγέραστος μήτε τῶν ἐναντίων ἀτιμώρητος διαλάθῃ, γένηται δὲ αὐτόπτης καὶ μάρτυς ἁπάντων ὁ καὶ τοῦ κολάζειν καὶ τοῦ τιμᾶν κύριος, τοὺς μὲν ἐπὶ τὴν πρᾶξιν ἔπεμπε καθ’ ἣν ὥραν προείρηται, προελθὼν δὲ αὐτὸς εἰς τὸ εὐκάτοπτον ἀπὸ τῆς Ἀντωνίας ἐκαραδόκει τὸ μέλλον.", "st": "6.2.5"}, {"sp": "N", "t": "Οὐ μὴν οἵ γε πεμφθέντες τοὺς φύλακας εὗρον κοιμωμένους, ὡς ἤλπισαν, ἀλλ’ ἀναπηδήσασι μετὰ κραυγῆς εὐθέως συνεπλέκοντο· πρὸς δὲ τὴν βοὴν τῶν ἐκκοιτούντων ἔνδοθεν οἱ λοιποὶ κατὰ στῖφος ἐξέθεον. τῶν μὲν δὴ πρώτων τὰς ὁρμὰς ἐξεδέχοντο Ῥωμαῖοι· περιέπιπτον δ’ οἱ μετ’ ἐκείνους τῷ σφετέρῳ τάγματι, καὶ πολλοὶ τοῖς οἰκείοις ὡς πολεμίοις ἐχρῶντο. τὴν μὲν γὰρ διὰ βοῆς ἐπίγνωσιν ἡ κραυγὴ συγχυθεῖσα παρ’ ἀμφοῖν, τὴν δὲ δι’ ὀμμάτων ἡ νὺξ ἕκαστον ἀφείλετο, καὶ τυφλώττειν ἄλλως οὓς μὲν οἱ θυμοὶ παρεσκεύαζον οὓς δ’ οἱ φόβοι· διὰ τοῦτο τὸν προστυχόντα πλήττειν ἦν ἄκριτον. Ῥωμαίους μὲν οὖν συνησπικότας καὶ κατὰ συντάξεις προπηδῶντας ἧττον ἔβλαπτεν ἡ ἄγνοια· καὶ γὰρ ἦν παρ’ ἑκάστῳ μνήμη τοῦ συνθήματος· Ἰουδαῖοι δ’ ἀεὶ σκεδαννύμενοι καὶ τάς τε προσβολὰς καὶ τὰς ὑποχωρήσεις ἀνέδην ποιούμενοι πολλάκις φαντασίαν παρεῖχον ἀλλήλοις πολεμίων· τὸν ὑποστρέφοντα γὰρ ἕκαστος οἰκεῖον διὰ σκότους ὡς ἐπιόντα Ῥωμαῖον ἐξεδέχετο. πλείους γοῦν ὑπὸ τῶν ἰδίων ἢ τῶν πολεμίων ἐτρώθησαν, ἕως ἡμέρας γενομένης ὄψει τὸ λοιπὸν ἡ μάχη διεκρίνετο, καὶ κατὰ φάλαγγα διαστάντες τοῖς τε βέλεσιν εὐτάκτοις ἐχρῶντο καὶ ταῖς ἀμύναις. οὐδέτεροι δὲ οὔτ’ εἶκον οὔτ’ ἐκοπίων, ἀλλ’ οἱ μὲν ὡς ἐφορῶντος Καίσαρος κατ’ ἄνδρα καὶ κατὰ συντάξεις ἤριζον ἀλλήλοις, καὶ προκοπῆς ἕκαστος ἐκείνην αὐτῷ τὴν ἡμέραν ἄρξειν ὑπελάμβανεν, εἰ γενναίως ἀγωνίσαιτο· Ἰουδαίοις δ’ ἐβράβευε τὰς τόλμας ὅ τε περὶ σφῶν αὐτῶν καὶ τοῦ ἱεροῦ φόβος καὶ ὁ τύραννος ἐφεστὼς καὶ τοὺς μὲν παρακαλῶν, τοὺς δὲ μαστιγῶν καὶ διεγείρων ἀπειλαῖς. συνέβαινε δὲ τὸ μὲν πλεῖστον σταδιαίαν εἶναι τὴν μάχην, ἐν ὀλίγῳ δὲ καὶ ταχέως ἀντιστρέφεσθαι τὰς ῥοπάς· οὐδέτεροι γὰρ οὔτε φυγῆς οὔτε διώξεως μῆκος εἶχον. ἀεὶ δὲ πρὸς τὸ συμβαῖνον οἰκεῖος ἀπὸ τῆς Ἀντωνίας ὁ θόρυβος ἦν, θαρρεῖν δὲ καὶ κρατοῦσι τοῖς σφετέροις ἐπεβόων καὶ μένειν τρεπομένοις. ἦν δὲ ὥσπερ τι πολέμου θέατρον· οὐδὲν γὰρ οὔτε Τίτον οὔτε τοὺς περὶ αὐτὸν ἐλάνθανε τῶν κατὰ τὴν μάχην. τὸ δὲ πέρας ἀρξάμενοι τῆς νυκτὸς ἐνάτης ὥρας ὑπὲρ πέμπτην τῆς ἡμέρας διελύθησαν ἀφ’ οὗπερ ἤρξαντο τόπου τῆς συμβολῆς, μηδέτεροι βεβαίως κλίναντες τοὺς ἑτέρους, ἀλλὰ τὴν νίκην μέσην ἐν ἀγχωμάλῳ καταλιπόντες. καὶ Ῥωμαίων μὲν ἐπισήμως ἠγωνίσαντο πολλοί, Ἰουδαίων δ’ ἐκ μὲν τῶν περὶ Σίμωνα Ἰούδης ὁ τοῦ Μαρεώτου καὶ Σίμων ὁ τοῦ Ὁσαΐα, τῶν δὲ Ἰδουμαίων Ἰάκωβος καὶ Σίμων, Ἀκατελᾶ μὲν οὗτος παῖς, Σωσᾶ δὲ ὁ Ἰάκωβος, τῶν δὲ μετὰ Ἰωάννου Γεφθέος καὶ Ἀλεξᾶς, τῶν δὲ ζηλωτῶν Σίμων υἱὸς Ἀρί.", "st": "6.2.6"}, {"sp": "N", "t": "Ἐν τούτῳ δ’ ἡ λοιπὴ τῶν Ῥωμαίων δύναμις ἡμέραις ἑπτὰ καταστρεψαμένη τοὺς τῆς Ἀντωνίας θεμελίους μέχρι τοῦ ἱεροῦ πλατεῖαν ὁδὸν εὐτρεπίσαντο. πλησιάσαντα δὲ τῷ πρώτῳ περιβόλῳ τὰ τάγματα κατήρχετο χωμάτων, τὸ μὲν ἀντικρὺς τῆς τοῦ εἴσω ἱεροῦ γωνίας, ἥτις ἦν κατ’ ἄρκτον καὶ δύσιν, τὸ δὲ κατὰ τὴν βόρειον ἐξέδραν, ἣ μεταξὺ τῶν δύο πυλῶν ἦν· τῶν δὲ λοιπῶν δύο θάτερον μὲν κατὰ τὴν ἑσπέριον στοὰν τοῦ ἔξωθεν ἱεροῦ, τὸ δ’ ἕτερον ἔξω κατὰ τὴν βόρειον. προύκοπτεν μέντοι μετὰ πολλοῦ καμάτου καὶ ταλαιπωρίας αὐτοῖς τὰ ἔργα [καὶ] τὴν ὕλην ἀφ’ ἑκατὸν σταδίων συγκομίζουσιν, ἐκακοῦντο δ’ ἔσθ’ ὅπη καὶ κατ’ ἐπιβουλάς, αὐτοὶ διὰ περιουσίαν τοῦ κρατεῖν ὄντες ἀδεέστεροι καὶ δι’ ἀπόγνωσιν ἤδη σωτηρίας χρώμενοι τολμηροτέροις τοῖς Ἰουδαίοις. τῶν γὰρ ἱππέων τινὲς ὁπότε προέλθοιεν ἐπὶ ξυλείαν ἢ χόρτου συλλογήν, τὸν τῆς συγκομιδῆς χρόνον ἀνίεσαν βόσκεσθαι τοὺς ἵππους ἀποχαλινοῦντες, οὓς οἱ Ἰουδαῖοι κατὰ στῖφος ἐκπηδῶντες ἥρπαζον. καὶ τούτου συνεχῶς γινομένου νομίσας Καῖσαρ, ὅπερ ἦν, ἀμελείᾳ τῶν σφετέρων πλέον ἢ τῇ Ἰουδαίων ἀνδρείᾳ γίνεσθαι τὰς ἁρπαγάς, ἔγνω σκυθρωπότερον τοὺς λοιποὺς πρὸς φυλακὴν τῶν ἵππων ἐπιστρέψαι. καὶ κελεύσας ἀπαχθῆναι τὴν ἐπὶ θανάτῳ τῶν ἀπολεσάντων στρατιωτῶν ἕνα, φόβῳ τοῖς ἄλλοις ἐτήρησε τοὺς ἵππους· οὐκέτι γὰρ εἴων νέμεσθαι, καθάπερ δὲ συμπεφυκότες αὐτοῖς ἐπὶ τὰς χρείας ἐξῄεσαν. οἱ μὲν οὖν προσεπολέμουν τῷ ἱερῷ καὶ τὰ χώματα διήγειρον.", "st": "6.2.7"}, {"sp": "N", "t": "Μετὰ δὲ μίαν ἡμέραν αὐτῶν τῆς ἀνόδου πολλοὶ τῶν στασιαστῶν, οἷς ἁρπαγαί τε ἐπέλειπον ἤδη καὶ ὁ λιμὸς ἤπειγε, συνελθόντες ταῖς κατὰ τὸ Ἐλαιῶν ὄρος Ῥωμαίων φυλακαῖς ἐπιτίθενται περὶ ὥραν ἑνδεκάτην τῆς ἡμέρας, οἰόμενοι πρῶτον μὲν ἀδοκήτων, ἔπειτα πρὸς θεραπείαις ἤδη τοῦ σώματος ὄντων ῥᾳδίως διεκπαίσειν. προαισθόμενοι δὲ τὴν ἔφοδον αὐτῶν οἱ Ῥωμαῖοι καὶ ταχέως ἐκ τῶν πλησίον φρουρίων συνδραμόντες εἶργον ὑπερπηδᾶν καὶ διακόπτειν τὸ περιτείχισμα βιαζομένους. γενομένης δὲ καρτερᾶς τῆς συμβολῆς ἄλλα τε πολλὰ παρ’ ἑκατέρων γενναίως ἐπράχθη, Ῥωμαίων μὲν μετὰ τῆς ἰσχύος ἐμπειρίᾳ τοῦ πολεμεῖν χρωμένων, Ἰουδαίων δὲ ἀφειδέσι ταῖς ὁρμαῖς καὶ τοῖς θυμοῖς ἀκατασχέτοις· ἐστρατήγει δὲ τῶν μὲν αἰδώς, τῶν δὲ ἀνάγκη· τό τε γὰρ ἐξαφεῖναι Ἰουδαίους ὥσπερ ἄρκυσιν ἐνειλημμένους Ῥωμαίοις αἴσχιστον ἐδόκει, κἀκεῖνοι μίαν ἐλπίδα σωτηρίας εἶχον, εἰ βιασάμενοι ῥήξειαν τὸ τεῖχος· καὶ τῶν ἀπὸ σπείρας τις ἱππέων, Πεδάνιος τοὔνομα, τρεπομένων ἤδη τῶν Ἰουδαίων καὶ κατὰ τῆς φάραγγος συνωθουμένων ῥόθιον ἐκ πλαγίου παρελαύνων τὸν ἵππον ἁρπάζει τινὰ φεύγοντα τῶν πολεμίων, νεανίαν στιβαρόν τε ἄλλως τὸ σῶμα καὶ καθωπλισμένον, δραξάμενος ἐκ τοῦ σφυροῦ· τοσοῦτον μὲν ἑαυτὸν ἐκ τρέχοντος ἐπέκλινε τοῦ ἵππου, τοσοῦτον δὲ ἐπεδείξατο τῆς δεξιᾶς τὸν τόνον καὶ τοῦ λοιποῦ σώματος ἔτι δ’ ἐμπειρίας ἱππικῆς. ὁ μὲν οὖν ὥσπερ τι κειμήλιον ἁρπασάμενος ἧκε φέρων Καίσαρι τὸν αἰχμάλωτον· Τίτος δὲ τὸν μὲν λαβόντα τῆς δυνάμεως θαυμάσας, τὸν δὲ ληφθέντα τῆς περὶ τὸ τεῖχος ἐπιχειρήσεως κολάσαι κελεύσας, αὐτὸς ἐν ταῖς περὶ τὸ ἱερὸν διαμάχαις ἦν καὶ τὰ χώματα κατήπειγεν.", "st": "6.2.8"}, {"sp": "N", "t": "Ἐν ᾧ Ἰουδαῖοι κακούμενοι ταῖς συμβολαῖς ἀεὶ κατ’ ὀλίγον κορυφουμένου τοῦ πολέμου καὶ τῷ ναῷ προσέρποντος, καθάπερ σηπομένου σώματος ἀπέκοπτον τὰ προειλημμένα μέλη φθάνοντες τὴν εἰς τὸ πρόσω νομήν. τῆς γὰρ βορείου καὶ κατὰ δύσιν στοᾶς τὸ συνεχὲς πρὸς τὴν Ἀντωνίαν ἐμπρήσαντες ἔπειτα ἀπέρρηξαν ὅσον πήχεις εἴκοσι, ταῖς ἰδίαις χερσὶν ἀρξάμενοι καίειν τὰ ἅγια. μετὰ δ’ ἡμέρας δύο, τετράδι καὶ εἰκάδι τοῦ προειρημένου μηνός, τὴν πλησίον στοὰν ὑποπιμπρᾶσι Ῥωμαῖοι, καὶ μέχρι πεντεκαίδεκα πηχῶν προκόψαντος τοῦ πυρὸς ἀποκόπτουσιν ὁμοίως Ἰουδαῖοι τὴν ὀροφήν, μήτε καθάπαξ ἐξιστάμενοι τῶν ἔργων καὶ τὸ πρὸς τὴν Ἀντωνίαν συναφὲς αὐτῶν διαιροῦντες· διὸ καὶ παρὸν κωλύειν ὑποπιμπράντας, οἱ δὲ πρὸς τὴν ἐμβολὴν τοῦ πυρὸς ἠρεμήσαντες τὴν νομὴν ἐμέτρησαν αὐτῷ σφίσι χρησίμως. περὶ μὲν δὴ τὸ ἱερὸν οὐ διέλειπον αἱ συμβολαί, συνεχὴς δ’ ἦν κατὰ μέρος ἐκθεόντων ἐπ’ ἀλλήλους ὁ πόλεμος.", "st": "6.2.9"}, {"sp": "N", "t": "Τῶν Ἰουδαίων δέ τις κατὰ ταύτας τὰς ἡμέρας ἀνὴρ τό τε σῶμα βραχὺς καὶ τὴν ὄψιν εὐκαταφρόνητος γένους θ’ ἕνεκα καὶ τῶν ἄλλων ἄσημος, Ἰωνάθης ἐκαλεῖτο, προελθὼν κατὰ τὸ τοῦ ἀρχιερέως Ἰωάννου μνημεῖον ἄλλα τε πολλὰ πρὸς τοὺς Ῥωμαίους ὑπερηφάνως ἐφθέγγετο καὶ τὸν ἄριστον αὐτῶν εἰς μονομαχίαν προυκαλεῖτο. τῶν δὲ ταύτῃ παρατεταγμένων οἱ πολλοὶ μὲν ὑπερηφάνουν, ἦσαν δ’ οἳ κατὰ τὸ εἰκὸς ἐδεδοίκεσαν, ἥπτετό γε μὴν τινῶν καὶ λογισμὸς οὐκ ἀσύνετος θανατῶντι μὴ συμπλέκεσθαι· τοὺς γὰρ ἀπεγνωκότας τὴν σωτηρίαν ἅμα καὶ τὰς ὁρμὰς ἀταμιεύτους ἔχειν καὶ τὸ θεῖον εὐδυσώπητον, τό τε παραβάλλεσθαι πρὸς οὓς καὶ τὸ νικᾶν οὐ μέγα καὶ μετ’ αἰσχύνης τὸ λειφθῆναι σφαλερόν, οὐκ ἀνδρείας ἀλλὰ θρασύτητος εἶναι. μηδενὸς δ’ ἐπὶ πολὺ προϊόντος καὶ τοῦ Ἰουδαίου πολλὰ κατακερτομοῦντος αὐτοὺς εἰς δειλίαν, ἀλαζὼν γάρ τις ἦν αὑτῷ σφόδρα καὶ τῶν Ῥωμαίων ὑπερήφανος, Πούδης τις ὄνομα τῶν ἐξ ἴλης ἱππέων βδελυξάμενος αὐτοῦ τά τε ῥήματα καὶ τὸ αὔθαδες, εἰκὸς δὲ καὶ πρὸς τὴν βραχύτητα τοῦ σώματος αὐτὸν ἀσκέπτως ἐπαρθῆναι, προπηδᾷ, καὶ τὰ μὲν ἄλλα περιῆν συμβαλών, προεδόθη δὲ ὑπὸ τῆς τύχης· πεσόντα γὰρ αὐτὸν ὁ Ἰωνάθης ἀποσφάττει προσδραμών. ἔπειτα ἐπιβὰς τῷ νεκρῷ τό τε ξίφος ᾑμαγμένον ἀνέσειε καὶ τῇ λαιᾷ τὸν θυρεὸν ἐπηλάλαξέ τε τῇ στρατιᾷ πολλὰ καὶ πρὸς τὸν πεσόντα κομπάζων καὶ τοὺς ὁρῶντας Ῥωμαίους ἐπισκώπτων, ἕως αὐτὸν ἀνασκιρτῶντα καὶ ματαΐζοντα Πρῖσκός τις ἑκατοντάρχης τοξεύσας διήλασε βέλει· πρὸς ὃ τῶν τε Ἰουδαίων καὶ τῶν Ῥωμαίων κραυγὴ συνεξήρθη διάφορος. ὁ δὲ δινηθεὶς ἐκ τῶν ἀλγηδόνων ἐπὶ τὸ σῶμα τοῦ πολεμίου κατέπεσεν, ὠκυτάτην ἀποφήνας ἐν πολέμῳ τὴν ἐπὶ τῷ ἀλόγως εὐτυχοῦντι νέμεσιν.", "st": "6.2.10"}, {"sp": "N", "t": "Οἱ δὲ ἀνὰ τὸ ἱερὸν στασιασταὶ φανερῶς τε οὐκ ἀνίεσαν τοὺς ἐπὶ τῶν χωμάτων στρατιώτας ἀμυνόμενοι καθ’ ἑκάστην ἡμέραν, καὶ τοῦ προειρημένου μηνὸς ἑβδόμῃ καὶ εἰκάδι δόλον ἐνσκευάζονται τοιόνδε. τῆς ἑσπερίου στοᾶς τὸ μεταξὺ τῶν δοκῶν καὶ τῆς ὑπ’ αὐτῆς ὀροφῆς ὕλης ἀναπιμπλᾶσιν αὔης, πρὸς δὲ ἀσφάλτου τε καὶ πίσσης· ἔπειθ’ ὡς καταπονούμενοι δῆθεν ὑπεχώρουν. πρὸς ὃ τῶν μὲν ἀσκέπτων πολλοὶ ταῖς ὁρμαῖς φερόμενοι προσέκειντο τοῖς ὑποχωροῦσιν ἐπί τε τὴν στοὰν ἀνεπήδων προσθέμενοι κλίμακας, οἱ δὲ συνετώτεροι τὴν ἄλογον τροπὴν τῶν Ἰουδαίων ὑπονοήσαντες ἔμενον. κατεπλήσθη μέντοι τῶν ἀναπηδησάντων ἡ στοά, κἀν τούτῳ Ἰουδαῖοι πᾶσαν ὑποπιμπρᾶσιν αὐτήν. αἰρομένης δ’ αἰφνιδίως πάντοθεν τῆς φλογὸς τούς τε ἔξω τοῦ κινδύνου Ῥωμαίους ἔκπληξις ἐπέσχε δεινὴ καὶ τοὺς περισχεθέντας ἀμηχανία. κυκλούμενοι δὲ ὑπὸ τῆς φλογὸς οἱ μὲν εἰς τὴν πόλιν ὀπίσω κατεκρήμνιζον ἑαυτούς, οἱ δ’ εἰς τοὺς πολεμίους, πολλοὶ δ’ ἐλπίδι σωτηρίας εἰς τοὺς σφετέρους καταπηδῶντες ἐκλῶντο τὰ μέλη, πλείστων δ’ ἔφθανε τὰς ὁρμὰς τὸ πῦρ καί τινες τὴν φλόγα σιδήρῳ. περιεῖχε δ’ εὐθέως καὶ τοὺς ἄλλως φθειρομένους τὸ πῦρ ἐπὶ πλεῖστον ἐκφερόμενον. Καίσαρα δὲ καίπερ χαλεπαίνοντα τοῖς ἀπολλυμένοις, ἐπειδὴ δίχα παραγγέλματος ἀναβεβήκεσαν, ὅμως οἶκτος εἰσῄει τῶν ἀνδρῶν· καὶ μηδενὸς προσαμύνειν δυναμένου, τοῦτο γοῦν παραμύθιον ἦν τοῖς φθειρομένοις τὸ βλέπειν ὑπὲρ οὗ τις ἠφίει τὴν ψυχὴν ὀδυνώμενον· βοῶν τε γὰρ αὐτοῖς καὶ προπηδῶν καὶ τοῖς περὶ αὐτὸν ἐκ τῶν ἐνόντων ἐπαμύνειν παρακαλῶν δῆλος ἦν. τὰς δὲ φωνὰς ἕκαστος καὶ τὴν διάθεσιν ὥσπερ τι λαμπρὸν ἀποφέρων ἐντάφιον εὔθυμος ἀπέθνησκεν. ἔνιοί γε μὴν ἐπὶ τὸν τοῖχον τῆς στοᾶς ὄντα πλατὺν ἀναχωρήσαντες ἐκ μὲν τοῦ πυρὸς διεσώθησαν, ὑπὸ δὲ τῶν Ἰουδαίων περισχεθέντες ἐπὶ πολὺ μὲν ἀντέσχον διατιτρωσκόμενοι, τέλος δὲ πάντες ἔπεσον,", "st": "6.3.1"}, {"sp": "N", "t": "καὶ τελευταῖός τις αὐτῶν νεανίας, ὀνόματι Λόγγος, ὅλον ἐπικοσμήσας τὸ πάθος καὶ κατ’ ἄνδρα μνήμης ἀξίων ὄντων πάντων τῶν ἀπολωλότων ἄριστος φανείς. ὃν οἱ μὲν Ἰουδαῖοι τῆς τε ἀλκῆς ἀγάμενοι καὶ ἄλλως ἀνελεῖν ἀσθενοῦντες καταβῆναι πρὸς αὐτοὺς ἐπὶ δεξιᾷ παρεκάλουν, ὁ δὲ ἀδελφὸς Κορνήλιος ἐκ θατέρου μὴ καταισχῦναι τὸ σφέτερον κλέος καὶ τὴν Ῥωμαίων στρατιάν. τούτῳ πεισθεὶς καὶ διαράμενος φανερὸν ἑκατέροις τοῖς τάγμασι τὸ ξίφος αὑτὸν ἀναιρεῖ. τῶν δὲ τῷ πυρὶ περισχεθέντων Ἀρτώριός τις πανουργίᾳ διασώζεται· προσκαλεσάμενος γάρ τινα τῶν στρατιωτῶν Λούκιον, ᾧ συνεσκήνει, μεγάλῃ τῇ φωνῇ κληρονόμον, ἔφη, καταλείπω σε τῶν ἐμαυτοῦ κτημάτων, εἰ προσελθών με δέξαιο. τοῦ δὲ ἑτοίμως προσδραμόντος ὁ μὲν ἐπ’ αὐτὸν κατενεχθεὶς ἔζησεν, ὁ δὲ δεξάμενος ὑπὸ τοῦ βάρους τῷ λιθοστρώτῳ προσαραχθεὶς παραχρῆμα θνήσκει. τοῦτο τὸ πάθος πρὸς καιρὸν μὲν Ῥωμαίοις ἐνεποίησεν ἀθυμίαν, πρὸς δὲ τὸ μέλλον ὅμως ἀπαρακλήτους κατεσκεύασεν φυλακτικωτέρους τε πρὸς τὰς Ἰουδαίων ἀπάτας ὠφέλησεν, ἐν αἷς τὰ πολλὰ δι’ ἄγνοιαν τῶν τόπων καὶ τὸ ἦθος τῶν ἀνδρῶν ἐβλάπτοντο. κατεκάη δ’ ἡ στοὰ μέχρι τοῦ Ἰωάννου πύργου, ὃν ἐκεῖνος ἐν τῷ πρὸς Σίμωνα πολέμῳ κατεσκεύασεν ὑπὲρ τὰς ἐξαγούσας ὑπὲρ τὸν ξυστὸν πύλας· τὸ δὲ λοιπὸν ἐπὶ διεφθαρμένοις ἤδη Ἰουδαῖοι τοῖς ἀναβᾶσιν ἀπέκοψαν. τῇ δ’ ὑστεραίᾳ καὶ Ῥωμαῖοι τὴν βόρειον στοὰν ἐνέπρησαν μέχρι τῆς ἀνατολικῆς ὅλην, ὧν ἡ συνάπτουσα γωνία τῆς Κεδρῶνος καλουμένης φάραγγος ὑπερδεδόμητο, παρ’ ὃ καὶ φοβερὸν ἦν τὸ βάθος. καὶ τὰ μὲν περὶ τὸ ἱερὸν ἐν τούτοις ἦν.", "st": "6.3.2"}, {"sp": "N", "t": "Τῶν δὲ ὑπὸ τοῦ λιμοῦ φθειρομένων κατὰ τὴν πόλιν ἄπειρον μὲν ἔπιπτε τὸ πλῆθος, ἀδιήγητα δὲ συνέβαινε τὰ πάθη. καθ’ ἑκάστην γὰρ οἰκίαν, εἴ που τροφῆς παραφανείη σκιά, πόλεμος ἦν, καὶ διὰ χειρῶν ἐχώρουν οἱ φίλτατοι πρὸς ἀλλήλους ἐξαρπάζοντες τὰ ταλαίπωρα τῆς ψυχῆς ἐφόδια. πίστις δ’ ἀπορίας οὐδὲ τοῖς θνήσκουσιν ἦν, ἀλλὰ καὶ τοὺς ἐκπνέοντας οἱ λῃσταὶ διηρεύνων, μή τις ὑπὸ κόλπον ἔχων τροφὴν σκήπτοιτο τὸν θάνατον αὑτῷ. οἱ δ’ ὑπ’ ἐνδείας κεχηνότες ὥσπερ λυσσῶντες κύνες ἐσφάλλοντο, καὶ παρεφέροντο ταῖς τε θύραις ἐνσειόμενοι μεθυόντων τρόπον καὶ ὑπ’ ἀμηχανίας εἰς τοὺς αὐτοὺς οἴκους εἰσπηδῶντες δὶς ἢ τρὶς ὥρᾳ μιᾷ. πάντα δὲ ὑπ’ ὀδόντας ἦγεν ἡ ἀνάγκη, καὶ τὰ μηδὲ τοῖς ῥυπαρωτάτοις τῶν ἀλόγων ζῴων πρόσφορα συλλέγοντες ἐσθίειν ὑπέφερον· ζωστήρων γοῦν καὶ ὑποδημάτων τὸ τελευταῖον οὐκ ἀπέσχοντο καὶ τὰ δέρματα τῶν θυρεῶν ἀποδέροντες ἐμασῶντο. τροφὴ δ’ ἦν καὶ χόρτου τισὶ παλαιοῦ σπάραγμα· τὰς γὰρ ἶνας ἔνιοι συλλέγοντες ἐλάχιστον σταθμὸν ἐπώλουν Ἀττικῶν τεσσάρων. καὶ τί δεῖ τὴν ἐπ’ ἀψύχοις ἀναίδειαν τοῦ λιμοῦ λέγειν; εἶμι γὰρ αὐτοῦ δηλώσων ἔργον οἷον μήτε παρ’ Ἕλλησιν μήτε παρὰ βαρβάροις ἱστόρηται, φρικτὸν μὲν εἰπεῖν, ἄπιστον δὲ ἀκοῦσαι. καὶ ἔγωγε μὴ δόξαιμι τερατεύεσθαι τοῖς αὖθις ἀνθρώποις, κἂν παρέλειπον τὴν συμφορὰν ἡδέως, εἰ μὴ τῶν κατ’ ἐμαυτὸν εἶχον ἀπείρους μάρτυρας. ἄλλως τε καὶ ψυχρὰν ἂν καταθείμην τῇ πατρίδι χάριν καθυφέμενος τὸν λόγον ὧν πέπονθεν τὰ ἔργα.", "st": "6.3.3"}, {"sp": "N", "t": "Γυνή τις τῶν ὑπὲρ τὸν Ἰορδάνην κατοικούντων, Μαρία τοὔνομα, πατρὸς Ἐλεαζάρου, κώμης Βηθεζουβᾶ, σημαίνει δὲ τοῦτο οἶκος ὑσσώπου, διὰ γένος καὶ πλοῦτον ἐπίσημος, μετὰ τοῦ λοιποῦ πλήθους εἰς τὰ Ἱεροσόλυμα καταφυγοῦσα συνεπολιορκεῖτο. ταύτης τὴν μὲν ἄλλην κτῆσιν οἱ τύραννοι διήρπασαν, ὅσην ἐκ τῆς Περαίας ἀνασκευασαμένη μετήνεγκεν εἰς τὴν πόλιν, τὰ δὲ λείψανα τῶν κειμηλίων καὶ εἴ τι τροφῆς ἐπινοηθείη καθ’ ἡμέραν εἰσπηδῶντες ἥρπαζον οἱ δορυφόροι. δεινὴ δὲ τὸ γύναιον ἀγανάκτησις εἰσῄει, καὶ πολλάκις λοιδοροῦσα καὶ καταρωμένη τοὺς ἅρπαγας ἐφ’ αὑτὴν ἠρέθιζεν. ὡς δ’ οὔτε παροξυνόμενός τις οὔτ’ ἐλεῶν αὐτὴν ἀνῄρει, καὶ τὸ μὲν εὑρεῖν τι σιτίον ἄλλοις ἐκοπία, πανταχόθεν δὲ ἄπορον ἦν ἤδη καὶ τὸ εὑρεῖν, ὁ λιμὸς δὲ διὰ σπλάγχνων καὶ μυελῶν ἐχώρει καὶ τοῦ λιμοῦ μᾶλλον ἐξέκαιον οἱ θυμοί, σύμβουλον λαβοῦσα τὴν ὀργὴν μετὰ τῆς ἀνάγκης ἐπὶ τὴν φύσιν ἐχώρει, καὶ τὸ τέκνον, ἦν δὲ αὐτῇ παῖς ὑπομάστιος, ἁρπασαμένη βρέφος, εἶπεν, ἄθλιον, ἐν πολέμῳ καὶ λιμῷ καὶ στάσει τίνι σε τηρήσω; τὰ μὲν παρὰ Ῥωμαίοις δουλεία, κἂν ζήσωμεν ἐπ’ αὐτούς, φθάνει δὲ καὶ δουλείαν ὁ λιμός, οἱ στασιασταὶ δὲ ἀμφοτέρων χαλεπώτεροι. ἴθι, γενοῦ μοι τροφὴ καὶ τοῖς στασιασταῖς ἐρινὺς καὶ τῷ βίῳ μῦθος ὁ μόνος ἐλλείπων ταῖς Ἰουδαίων συμφοραῖς. καὶ ταῦθ’ ἅμα λέγουσα κτείνει τὸν υἱόν, ἔπειτ’ ὀπτήσασα τὸ μὲν ἥμισυ κατεσθίει, τὸ δὲ λοιπὸν κατακαλύψασα ἐφύλαττεν. εὐθέως δ’ οἱ στασιασταὶ παρῆσαν, καὶ τῆς ἀθεμίτου κνίσης σπάσαντες ἠπείλουν, εἰ μὴ δείξειεν τὸ παρασκευασθέν, ἀποσφάξειν αὐτὴν εὐθέως. ἡ δὲ καὶ μοῖραν αὐτοῖς εἰποῦσα καλὴν τετηρηκέναι τὰ λείψανα τοῦ τέκνου διεκάλυψεν. τοὺς δ’ εὐθέως φρίκη καὶ παρέκστασις ᾕρει καὶ παρὰ τὴν ὄψιν ἐπεπήγεσαν. ἡ δ’ ἐμόν, ἔφη, τοῦτο τέκνον γνήσιον καὶ τὸ ἔργον ἐμόν. φάγετε, καὶ γὰρ ἐγὼ βέβρωκα. μὴ γένησθε μήτε μαλακώτεροι γυναικὸς μήτε συμπαθέστεροι μητρός. εἰ δ’ ὑμεῖς εὐσεβεῖς καὶ τὴν ἐμὴν ἀποστρέφεσθε θυσίαν, ἐγὼ μὲν ὑμῖν βέβρωκα, καὶ τὸ λοιπὸν δὲ ἐμοὶ μεινάτω. μετὰ ταῦθ’ οἱ μὲν τρέμοντες ἐξῄεσαν, πρὸς ἓν τοῦτο δειλοὶ καὶ μόλις ταύτης τῆς τροφῆς τῇ μητρὶ παραχωρήσαντες, ἀνεπλήσθη δ’ εὐθέως ὅλη τοῦ μύσους ἡ πόλις, καὶ πρὸ ὀμμάτων ἕκαστος τὸ πάθος λαμβάνων ὥσπερ αὐτῷ τολμηθὲν ἔφριττε. σπουδὴ δὲ τῶν λιμωττόντων ἐπὶ τὸν θάνατον ἦν, καὶ μακαρισμὸς τῶν φθασάντων πρὶν ἀκοῦσαι καὶ θεάσασθαι κακὰ τηλικαῦτα.", "st": "6.3.4"}, {"sp": "N", "t": "Ταχέως δὲ καὶ Ῥωμαίοις διηγγέλθη τὸ πάθος. τῶν δ’ οἱ μὲν ἠπίστουν, οἱ δὲ ᾤκτειρον, τοὺς δὲ πολλοὺς εἰς μῖσος τοῦ ἔθνους σφοδρότερον συνέβη προελθεῖν. Καῖσαρ δὲ ἀπελογεῖτο καὶ περὶ τούτου τῷ θεῷ, φάσκων παρὰ μὲν αὐτοῦ Ἰουδαίοις εἰρήνην καὶ αὐτονομίαν προτείνεσθαι καὶ πάντων ἀμνηστίαν τῶν τετολμημένων, τοὺς δὲ ἀντὶ μὲν ὁμονοίας στάσιν, ἀντὶ δὲ εἰρήνης πόλεμον, πρὸ κόρου δὲ καὶ εὐθηνίας λιμὸν αἱρουμένους, ἰδίαις δὲ χερσὶν ἀρξαμένους καίειν τὸ συντηρούμενον ὑφ’ ἡμῶν ἱερὸν αὐτοῖς, εἶναι καὶ τοιαύτης τροφῆς ἀξίους. καλύψειν μέντοι τὸ τῆς τεκνοφαγίας μύσος αὐτῷ τῷ τῆς πατρίδος πτώματι καὶ οὐ καταλείψειν ἐπὶ τῆς οἰκουμένης ἡλίῳ καθορᾶν πόλιν, ἐν ᾗ μητέρες οὕτω τρέφονται. προσήκειν μέντοι πρὸ μητέρων πατράσιν τὴν τοιαύτην τροφήν, οἳ καὶ μετὰ τηλικαῦτα πάθη μένουσιν ἐν τοῖς ὅπλοις. ταῦθ’ ἅμα διεξιὼν ἐνενόει καὶ τὴν ἀπόγνωσιν τῶν ἀνδρῶν· οὐ γὰρ ἂν ἔτι σωφρονῆσαι τοὺς πάντα προπεπονθότας ἐφ’ οἷς εἰκὸς ἦν μεταβαλέσθαι μὴ παθοῦσιν.", "st": "6.3.5"}, {"sp": "N", "t": "Ἤδη δὲ τῶν δύο ταγμάτων συντετελεκότων τὰ χώματα Λώου μηνὸς ὀγδόῃ προσάγειν ἐκέλευσε τοὺς κριοὺς κατὰ τὴν ἑσπέριον ἐξέδραν τοῦ ἔξωθεν ἱεροῦ. πρὸ δὲ τούτων ἓξ ἡμέρας ἀδιαλείπτως ἡ στερροτάτη πασῶν ἑλέπολις τύπτουσα τὸν τοῖχον οὐδὲν ἤνυσεν, ἀλλὰ καὶ ταύτης καὶ τῶν ἄλλων τὸ μέγεθος καὶ ἡ ἁρμονία τῶν λίθων ἦν ἀμείνων. τῆς δὲ βορείου πύλης ὑπώρυττον ἕτεροι τοὺς θεμελίους καὶ πολλὰ ταλαιπωρήσαντες τοὺς ἔμπροσθεν λίθους ἐξεκύλισαν. ἀνείχοντο δ’ ὑπὸ τῶν ἐνδοτέρω καὶ διέμεινεν ἡ πύλη, μέχρι τὰς δι’ ὀργάνων καὶ τῶν μοχλῶν ἐπιχειρήσεις ἀπογνόντες κλίμακας ταῖς στοαῖς προσέφερον. οἱ δὲ Ἰουδαῖοι κωλῦσαι μὲν οὐκ ἔφθασαν, ἀναβᾶσι δὲ συμπεσόντες ἐμάχοντο, καὶ τοὺς μὲν ἀνωθοῦντες εἰς τοὐπίσω κατεκρήμνιζον, τοὺς δ’ ὑπαντιάζοντας ἀνῄρουν· πολλοὺς δὲ τῶν κλιμάκων ἀποβαίνοντας πρὶν φράξασθαι τοῖς θυρεοῖς παίοντες ταῖς ῥομφαίαις ἔφθανον, ἐνίας δὲ γεμούσας ὁπλιτῶν κλίμακας παρακλίνοντες ἄνωθεν κατέσειον· ἦν δ’ οὐκ ὀλίγος καὶ αὐτῶν φόνος. οἱ δὲ ἀνενεγκόντες τὰς σημαίας περὶ αὐτῶν ἐπολέμουν, δεινὴν ἡγούμενοι καὶ πρὸς αἰσχύνης τούτων τὴν ἁρπαγήν. τέλος δὲ καὶ τῶν σημαιῶν οἱ Ἰουδαῖοι κρατοῦσιν καὶ τοὺς ἀναβάντας διαφθείρουσιν· οἱ δὲ λοιποὶ πρὸς τὸ τῶν ἀπολωλότων πάθος ὀρρωδοῦντες ἀνεχώρουν. τῶν μὲν οὖν Ῥωμαίων ἄπρακτος οὐδεὶς ἀπέθανεν, τῶν δὲ στασιαστῶν οἳ κατὰ τὰς προτέρας μάχας ἠγωνίσαντο γενναίως καὶ τότε καὶ Ἐλεάζαρος ἀδελφιδοῦς τοῦ τυράννου Σίμωνος. ὁ δὲ Τίτος ὡς ἑώρα τὴν ἐπὶ τοῖς ἀλλοτρίοις ἱεροῖς φειδὼ πρὸς βλάβης τοῖς στρατιώταις γινομένην καὶ φόνου, τὰς πύλας προσέταξεν ὑφάπτειν.", "st": "6.4.1"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ πρὸς αὐτὸν αὐτομολοῦσιν Ἄνανός τε ὁ ἀφαμμαούς, τῶν Σίμωνος δορυφόρων ὁ φονικώτατος, καὶ Ἀρχέλαος υἱὸς Μαγαδδάτου, συγγνώμην ἐλπίσαντες ἐπειδὴ κρατούντων Ἰουδαίων ἀπεχώρουν. Τίτος δὲ καὶ τοῦτο τὸ πανούργημα προβάλλεται τῶν ἀνδρῶν, καὶ τὴν ἄλλην περὶ τοὺς ἰδίους ὠμότητα πεπυσμένος ὥρμητο κτείνειν ἑκατέρους, ὑπ’ ἀνάγκης ἦχθαι λέγων αὐτούς, οὐκ ἐκ προαιρέσεως παρεῖναι, καὶ σωτηρίας οὐκ ἀξίους εἶναι τοὺς φλεγομένης ἤδη δι’ αὐτοὺς τῆς πατρίδος ἐξαλλομένους. ἐκράτει δ’ ὅμως τοῦ θυμοῦ ἡ πίστις, καὶ ἀφίησι τοὺς ἄνδρας, οὐ μὴν ἐν ἴσῃ μοίρᾳ κατέτασσε τοῖς ἄλλοις. ἤδη δὲ ταῖς πύλαις οἱ στρατιῶται προσῆγον τὸ πῦρ, καὶ περιτηκόμενος ὁ ἄργυρος διεδίδου ταχέως εἰς τὴν ξυλείαν τὴν φλόγα, ἔνθεν ἀθρόως ἐκφερομένη τῶν στοῶν ἐπελαμβάνετο. τοῖς δὲ Ἰουδαίοις ὁρῶσι τὸ πῦρ ἐν κύκλῳ μετὰ τῶν σωμάτων παρείθησαν αἱ ψυχαί, καὶ διὰ τὴν κατάπληξιν ἀμύνειν μὲν ἢ σβεννύειν ὥρμησεν οὐδείς, αὖοι δ’ ἑστῶτες ἀφεώρων. οὐ μὴν πρὸς τὸ δαπανώμενον ἀθυμοῦντες εἰς γοῦν τὸ λοιπὸν ἐσωφρόνουν, ἀλλ’ ὡς ἤδη καὶ τοῦ ναοῦ καιομένου τοὺς θυμοὺς ἐπὶ Ῥωμαίους ἔθηγον. ἐκείνην μὲν οὖν τὴν ἡμέραν καὶ τὴν ἐπιοῦσαν νύκτα τὸ πῦρ ἐπεκράτει· κατὰ μέρος γάρ, οὐχ ὁμοῦ πάντοθεν ἴσχυσαν ὑφάψαι τὰς στοάς.", "st": "6.4.2"}, {"sp": "N", "t": "Τῇ δ’ ἐπιούσῃ Τίτος μέρει τῆς δυνάμεως σβεννύειν τε καὶ τὰ παρὰ τὰς πύλας ὁδοποιεῖν εἰς εὐμαρεστέραν τῶν ταγμάτων ἄνοδον κελεύσας αὐτὸς συνῆγε τοὺς ἡγεμόνας. καὶ συνελθόντων ἓξ τῶν κορυφαιοτάτων, Τιβερίου τε Ἀλεξάνδρου τοῦ πάντων τῶν στρατευμάτων ἐπάρχοντος, καὶ Σέξτου Κερεαλίου τοῦ τὸ πέμπτον ἄγοντος τάγμα, καὶ Λαρκίου Λεπίδου τὸ δέκατον, καὶ Τίτου Φρυγίου τὸ πεντεκαιδέκατον, πρὸς οἷς Φρόντων ἦν Ἑτέριος στρατοπεδάρχης τῶν ἀπὸ Ἀλεξανδρείας δύο ταγμάτων, καὶ Μᾶρκος Ἀντώνιος Ἰουλιανὸς ὁ τῆς Ἰουδαίας ἐπίτροπος, καὶ μετὰ τούτους ἐπιτρόπων καὶ χιλιάρχων ἀθροισθέντων, βουλὴν περὶ τοῦ ναοῦ προυτίθει. τοῖς μὲν οὖν ἐδόκει χρῆσθαι τῷ τοῦ πολέμου νόμῳ· μὴ γὰρ ἄν ποτε Ἰουδαίους παύσασθαι νεωτερίζοντας τοῦ ναοῦ μένοντος, ἐφ’ ὃν οἱ πανταχόθεν συλλέγονται. τινὲς δὲ παρῄνουν, εἰ μὲν καταλίποιεν αὐτὸν Ἰουδαῖοι καὶ μηδεὶς ἐπ’ αὐτοῦ τὰ ὅπλα θείη, σώζειν, εἰ δὲ πολεμοῖεν ἐπιβάντες, καταφλέγειν· φρούριον γάρ, οὐκέτι ναὸν εἶναι, καὶ τὸ λοιπὸν ἔσεσθαι τῶν ἀναγκασάντων τὴν ἀσέβειαν, οὐκ αὐτῶν. ὁ δὲ Τίτος οὐδ’ ἂν ἐπιβάντες ἐπ’ αὐτοῦ πολεμῶσιν Ἰουδαῖοι φήσας ἀντὶ τῶν ἀνδρῶν ἀμυνεῖσθαι τὰ ἄψυχα οὐδὲ καταφλέξειν ποτὲ τηλικοῦτον ἔργον· Ῥωμαίων γὰρ ἔσεσθαι τὴν βλάβην, ὥσπερ καὶ κόσμον τῆς ἡγεμονίας αὐτοῦ μένοντος· θαρροῦντες δὲ ἤδη προσετίθεντο τῇ γνώμῃ Φρόντων τε καὶ Ἀλέξανδρος καὶ Κερεάλιος. τότε μὲν οὖν διαλύει τὸ συνέδριον καὶ τὰς ἄλλας δυνάμεις διαναπαῦσαι κελεύσας τοῖς ἡγεμόσιν, ὅπως ἐρρωμενεστέροις ἐν τῇ παρατάξει χρήσαιτο, τοῖς ἀπὸ τῶν σπειρῶν ἐπιλέκτοις ὁδοποιεῖν διὰ τῶν ἐρειπίων προσέταξε καὶ τὸ πῦρ σβεννύειν.", "st": "6.4.3"}, {"sp": "N", "t": "Κατ’ ἐκείνην μὲν δὴ τὴν ἡμέραν τῶν Ἰουδαίων κάματός τε καὶ κατάπληξις ἐκράτησε τὰς ὁρμάς· τῇ δ’ ἐπιούσῃ συλλεξάμενοί τε τὴν ἰσχὺν καὶ ἀναθαρσήσαντες ἐπεκθέουσι διὰ τῆς ἀνατολικῆς πύλης τοῖς φύλαξι τοῦ ἔξωθεν ἱεροῦ περὶ δευτέραν ὥραν. οἱ δὲ καρτερῶς μὲν ἐδέξαντο αὐτῶν τὴν ἐμβολὴν καὶ φραξάμενοι τοῖς θυρεοῖς κατὰ μέτωπον ὥσπερ τεῖχος ἐπύκνωσαν τὴν φάλαγγα, δῆλοι δ’ ἦσαν οὐκ ἐπὶ πολὺ συμμενοῦντες πλήθει τε τῶν ἐκτρεχόντων καὶ θυμοῖς ἡττώμενοι. φθάσας δὲ τῆς παρατάξεως τὴν ῥοπὴν Καῖσαρ, καθεώρα γὰρ ἀπὸ τῆς Ἀντωνίας, ἐπήμυνε μετὰ τῶν ἐπιλέκτων ἱππέων. Ἰουδαῖοι δὲ τὴν ἔφοδον οὐχ ὑπέμειναν, ἀλλὰ τῶν πρώτων πεσόντων ἐτράπησαν οἱ πολλοί· καὶ ὑποχωροῦσι μὲν τοῖς Ῥωμαίοις ἐπιστρεφόμενοι προσέκειντο, μεταβαλλομένων δὲ ἀνέφευγον πάλιν, ἕως περὶ πέμπτην τῆς ἡμέρας ὥραν οἱ μὲν βιασθέντες εἰς τὸ ἔνδον συνεκλείσθησαν ἱερόν.", "st": "6.4.4"}, {"sp": "N", "t": "Τίτος δὲ ἀνεχώρησεν εἰς τὴν Ἀντωνίαν διεγνωκὼς τῆς ἐπιούσης ἡμέρας ὑπὸ τὴν ἕω μετὰ πάσης ἐμβαλεῖν τῆς δυνάμεως καὶ τὸν ναὸν περικατασχεῖν. τοῦ δ’ ἄρα κατεψήφιστο μὲν τὸ πῦρ ὁ θεὸς πάλαι, παρῆν δ’ ἡ εἱμαρμένη χρόνων περιόδοις ἡμέρα δεκάτη Λώου μηνός, καθ’ ἣν καὶ πρότερον ὑπὸ τοῦ τῶν Βαβυλωνίων βασιλέως ἐνεπρήσθη. λαμβάνουσι δ’ αἱ φλόγες ἐκ τῶν οἰκείων τὴν ἀρχὴν καὶ τὴν αἰτίαν· ὑποχωρήσαντος γὰρ τοῦ Τίτου πρὸς ὀλίγον λωφήσαντες οἱ στασιασταὶ πάλιν τοῖς Ῥωμαίοις ἐπιτίθενται, καὶ τῶν τοῦ ναοῦ φρουρῶν γίνεται συμβολὴ πρὸς τοὺς σβεννύντας τὸ πῦρ τοῦ ἔνδοθεν ἱεροῦ, οἳ τρεψάμενοι τοὺς Ἰουδαίους μέχρι τοῦ ναοῦ παρηκολούθουν. ἔνθα δὴ τῶν στρατιωτῶν τις οὔτε παράγγελμα περιμείνας οὔτ’ ἐπὶ τηλικούτῳ δείσας ἐγχειρήματι, δαιμονίῳ ὁρμῇ τινι χρώμενος ἁρπάζει μὲν ἐκ τῆς φλεγομένης † φλογός, ἀνακουφισθεὶς δὲ ὑπὸ συστρατιώτου τὸ πῦρ ἐνίησι θυρίδι χρυσῇ, καθ’ ἣν εἰς τοὺς περὶ τὸν ναὸν οἴκους εἰσιτὸν ἦν ἐκ τοῦ βορείου κλίματος. αἰρομένης δὲ τῆς φλογὸς Ἰουδαίων μὲν ἐγείρεται κραυγὴ τοῦ πάθους ἀξία, καὶ πρὸς τὴν ἄμυναν συνέθεον, οὔτε τοῦ ζῆν ἔτι φειδὼ λαμβάνοντες οὔτε ταμιευόμενοι τὴν ἰσχύν, δι’ ὃ φυλακτικοὶ πρότερον ἦσαν οἰχομένου.", "st": "6.4.5"}, {"sp": "N", "t": "Δραμὼν δέ τις ἀγγέλλει Τίτῳ· κἀκεῖνος, ἔτυχεν δὲ κατὰ σκηνὴν ἀναπαυόμενος ἐκ τῆς μάχης, ὡς εἶχεν ἀναπηδήσας ἔθει πρὸς τὸν ναὸν εἴρξων τὸ πῦρ. κατόπιν δὲ οἵ τε ἡγεμόνες εἵποντο πάντες, καὶ πτοηθέντα τούτοις ἠκολούθει τὰ τάγματα· βοὴ δὲ ἦν καὶ θόρυβος ἅτε τηλικαύτης δυνάμεως ἀτάκτως κεκινημένης. ὁ μὲν οὖν Καῖσαρ τῇ τε φωνῇ καὶ τῇ δεξιᾷ διεσήμαινε τοῖς μαχομένοις τὸ πῦρ σβεννύειν, οὔτε δὲ βοῶντος ἤκουον μείζονι κραυγῇ τὰς ἀκοὰς προκατειλημμένοι καὶ τοῖς νεύμασι τῆς χειρὸς οὐ προσεῖχον, οἱ μὲν τῷ πολεμεῖν, οἱ δὲ ὀργῇ περισπώμενοι. τῶν δὲ ταγμάτων εἰσθεόντων οὔτε παραίνεσις οὔτ’ ἀπειλὴ κατεῖχεν τὰς ὁρμάς, ἀλλ’ ὁ θυμὸς ἁπάντων ἐστρατήγει· καὶ περὶ τὰς εἰσόδους συνωθούμενοι πολλοὶ μὲν ὑπ’ ἀλλήλων κατεπατοῦντο, πολλοὶ δὲ θερμοῖς ἔτι καὶ τυφομένοις τοῖς ἐρειπίοις τῶν στοῶν ἐμπίπτοντες ἡττωμένων συμφοραῖς ἐχρῶντο. πλησίον δὲ τοῦ ναοῦ γινόμενοι τῶν μὲν τοῦ Καίσαρος παραγγελμάτων προσεποιοῦντο μηδὲ κατακούειν, τοῖς πρὸ αὐτῶν δὲ τὸ πῦρ ἐνιέναι παρεκελεύοντο. τῶν δὲ στασιαστῶν ἀμηχανία μὲν ἦν ἤδη τοῦ βοηθεῖν, φόνος δὲ πανταχοῦ καὶ τροπή. τὸ δὲ πλέον ἀπὸ τοῦ δήμου λαὸς ἀσθενὴς καὶ ἄνοπλος ὅπου καταληφθείη τις ἀπεσφάττετο, καὶ περὶ μὲν τὸν βωμὸν πλῆθος ἐσωρεύετο νεκρῶν, κατὰ δὲ τῶν τοῦ ναοῦ βάθρων αἷμά τ’ ἔρρει πολὺ καὶ τὰ τῶν ἄνω φονευομένων σώματα κατωλίσθανε.", "st": "6.4.6"}, {"sp": "N", "t": "Καῖσαρ δ’ ὡς οὔτε τὰς ὁρμὰς ἐνθουσιώντων τῶν στρατιωτῶν κατασχεῖν οἷός τε ἦν καὶ τὸ πῦρ ἐπεκράτει, παρελθὼν μετὰ τῶν ἡγεμόνων ἔνδον ἐθεάσατο τοῦ ναοῦ τὸ ἅγιον καὶ τὰ ἐν αὐτῷ, πολὺ μὲν τῆς παρὰ τοῖς ἀλλοφύλοις φήμης ἀμείνω, τοῦ δὲ κόμπου καὶ τῆς παρὰ τοῖς οἰκείοις δόξης οὐκ ἐλάττω. τῆς φλογὸς δὲ οὐδέπω διικνουμένης οὐδαμόθεν εἴσω, τοὺς δὲ περὶ τὸν ναὸν οἴκους νεμομένης, νομίσας, ὅπερ ἦν, ἔτι σώζεσθαι τὸ ἔργον δύνασθαι προπηδᾷ, καὶ αὐτός τε παρακαλεῖν τοὺς στρατιώτας ἐπειρᾶτο τὸ πῦρ σβεννύειν καὶ Λιβεράλιον ἑκατοντάρχην τῶν περὶ αὐτὸν λογχοφόρων ξύλοις παίοντα τοὺς ἀπειθοῦντας ἐκέλευσεν εἴργειν. τῶν δὲ καὶ τὴν πρὸς τὸν Καίσαρα αἰδῶ καὶ τὸν ἀπὸ τοῦ κωλύοντος φόβον ἐνίκων οἱ θυμοὶ καὶ τὸ πρὸς Ἰουδαίους μῖσος, καὶ πολεμική τις ὁρμὴ λαβροτέρα· τοὺς δὲ πολλοὺς ἐνῆγεν ἁρπαγῆς ἐλπίς, δόξαν τε ἔχοντας ὡς τὰ ἔνδον ἅπαντα χρημάτων μεστὰ εἴη, καὶ τὰ πέριξ ὁρῶντας χρυσοῦ πεποιημένα. φθάνει δέ τις καὶ τῶν εἴσω παρεληλυθότων ἐκπηδήσαντος τοῦ Καίσαρος πρὸς ἐποχὴν τῶν στρατιωτῶν πῦρ εἰς τοὺς στροφέας ἐμβαλὼν τῆς πύλης † ἐν σκότῳ· τότε γὰρ ἐξαπίνης ἔνδοθεν ἐκφανείσης φλογὸς οἵ τε ἡγεμόνες μετὰ τοῦ Καίσαρος ἀνεχώρουν, καὶ τοὺς ἔξωθεν οὐδεὶς ὑφάπτειν ἐκώλυεν. ὁ μὲν οὖν ναὸς οὕτως ἄκοντος Καίσαρος ἐμπίπραται.", "st": "6.4.7"}, {"sp": "N", "t": "Πολλὰ δ’ ἄν τις ἐπολοφυράμενος ἔργῳ πάντων ὧν ὄψει καὶ ἀκοῇ παρειλήφαμεν θαυμασιωτάτῳ κατασκευῆς τε ἕνεκα καὶ μεγέθους ἔτι τε τῆς καθ’ ἕκαστον πολυτελείας καὶ τῆς περὶ τὰ ἅγια δόξης, μεγίστην λάβοι παραμυθίαν τὴν εἱμαρμένην ἄφυκτον οὖσαν ὥσπερ ἐμψύχοις οὕτω καὶ ἔργοις καὶ τόποις. θαυμάσαι δ’ ἄν τις ἐν αὐτῇ τῆς περιόδου τὴν ἀκρίβειαν· καὶ μῆνα γοῦν, ὡς ἔφην, καὶ ἡμέραν ἐτήρησεν τὴν αὐτήν, ἐν ᾗ πρότερον ὑπὸ Βαβυλωνίων ὁ ναὸς ἐνεπρήσθη. καὶ ἀπὸ μὲν τῆς πρώτης αὐτοῦ κτίσεως, ἣν κατεβάλετο Σολομὼν ὁ βασιλεύς; μέχρι τῆς νῦν ἀναιρέσεως, ἣ γέγονεν ἔτει δευτέρῳ τῆς Οὐεσπασιανοῦ ἡγεμονίας, ἔτη συνάγεται χίλια ἑκατὸν τριάκοντα, πρὸς δὲ μῆνες ἑπτὰ καὶ πεντεκαίδεκα ἡμέραι· ἀπὸ δὲ τῆς ὕστερον, ἣν ἔτει δευτέρῳ Κύρου βασιλεύοντος ἐποιήσατο Ἀγγαῖος, ἔτη μέχρι τῆς ὑπὸ Οὐεσπασιανοῦ ἁλώσεως τριακονταεννέα πρὸς ἑξακοσίοις καὶ ἡμέραι τεσσαρακονταπέντε.", "st": "6.4.8"}, {"sp": "N", "t": "Καιομένου δὲ τοῦ ναοῦ τῶν μὲν προσπιπτόντων ἦν ἁρπαγή, φόνος δὲ τῶν καταλαμβανομένων μυρίος καὶ οὔτε ἡλικίας ἦν ἔλεος οὔτ’ ἐντροπὴ σεμνότητος, ἀλλὰ καὶ παιδία καὶ γέροντες καὶ βέβηλοι καὶ ἱερεῖς ὁμοίως ἀνῃροῦντο, καὶ πᾶν γένος ἐπεξῄει περισχὼν ὁ πόλεμος, ὁμοῦ τούς τε ἱκετεύοντας καὶ τοὺς ἀμυνομένους. συνήχει δὲ ἡ φλὸξ ἐπὶ πλεῖστον ἐκφερομένη τοῖς τῶν πιπτόντων στεναγμοῖς, καὶ διὰ μὲν τὸ ὕψος τοῦ λόφου καὶ τὸ τοῦ φλεγομένου μέγεθος ἔργου πᾶσαν ἄν τις ἔδοξε καίεσθαι τὴν πόλιν, τῆς δὲ βοῆς ἐκείνης οὐδὲν ἐπινοηθῆναι δύναιτ’ ἂν ἢ μεῖζον ἢ φοβερώτερον. τῶν τε γὰρ Ῥωμαϊκῶν ταγμάτων ἀλαλαγμὸς ἦν συμφερομένων, καὶ τῶν στασιαστῶν πυρὶ καὶ σιδήρῳ κεκυκλωμένων κραυγή, τοῦ τε ἀποληφθέντος ἄνω λαοῦ τροπή τε μετ’ ἐκπλήξεως εἰς τοὺς πολεμίους καὶ πρὸς τὸ πάθος οἰμωγαί. συνεβόα δὲ τοῖς ἐπὶ τοῦ λόφου τὸ κατὰ τὴν πόλιν πλῆθος· ἤδη δὲ πολλοὶ τῷ λιμῷ μαραινόμενοι καὶ μεμυκότες ὡς εἶδον τὸ τοῦ ναοῦ πῦρ, εἰς ὀδυρμοὺς πάλιν καὶ κραυγὴν εὐτόνησαν· συνήχει δὲ ἥ τε Περαία καὶ τὰ πέριξ ὄρη βαρυτέραν ποιοῦντα τὴν βοήν. ἦν δὲ τοῦ θορύβου τὰ πάθη φοβερώτερα· τὸν μέν γε τοῦ ἱεροῦ λόφον ἐκ ῥιζῶν ἄν τις ἔδοξε βράττεσθαι πάντοθεν τοῦ πυρὸς καταγέμοντα, δαψιλέστερον δὲ τὸ αἷμα τοῦ πυρὸς εἶναι καὶ τῶν φονευόντων πλείους τοὺς φονευομένους· οὐδαμοῦ γὰρ ἡ γῆ διεφαίνετο τῶν νεκρῶν, ἀλλὰ σωροῖς ἐπιβαίνοντες οἱ στρατιῶται σωμάτων ἐπὶ τοὺς διαφεύγοντας ἔθεον. τὸ μὲν οὖν λῃστρικὸν πλῆθος ὠσάμενοι τοὺς Ῥωμαίους μόλις εἰς τὸ ἔξω διεκπίπτουσιν ἱερὸν κἀκεῖθεν εἰς τὴν πόλιν, τοῦ δημοτικοῦ δὲ τὸ λειφθὲν ἐπὶ τὴν ἔξω στοὰν κατέφυγε. τῶν δὲ ἱερέων τινὲς τὸ μὲν πρῶτον ἀπὸ τοῦ ναοῦ τούς τε ὀβελοὺς καὶ τὰς ἕδρας αὐτῶν μολίβου πεποιημένας ἀνασπῶντες εἰς τοὺς Ῥωμαίους ἠφίεσαν, αὖθις δὲ ὡς οὔτε ἤνυόν τι καὶ τὸ πῦρ ἐπ’ αὐτοὺς ἀνερρήγνυτο, ἐπὶ τὸν τοῖχον ἀναχωρήσαντες ὄντα ὀκτάπηχυν τὸ εὖρος ἔμενον. δύο γε μὴν τῶν ἐπισήμων, παρὸν σωθῆναι πρὸς Ῥωμαίους μεταστᾶσιν ἢ διακαρτερεῖν πρὸς τὴν μετὰ τῶν ἄλλων τύχην, ἑαυτοὺς ἔρριψαν εἰς τὸ πῦρ καὶ τῷ ναῷ συγκατεφλέγησαν, Μηϊρός τε υἱὸς Βελγᾶ καὶ Ἰώσηπος Δαλαίου.", "st": "6.5.1"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ μάταιον τὴν ἐπὶ τοῖς πέριξ φειδὼ κρίναντες τοῦ ναοῦ φλεγομένου πάντα συνεπίμπρασαν, τά τε λείψανα τῶν στοῶν καὶ τὰς πύλας πλὴν δύο, τῆς μὲν ἐκ τῶν ἀνατολικῶν τῆς δὲ μεσημβρινῆς· καὶ ταύτας ὕστερον κατέσκαψαν. ἔκαιον δὲ καὶ τὰ γαζοφυλάκια, ἐν οἷς ἄπειρον μὲν χρημάτων πλῆθος ἄπειροι δ’ ἐσθῆτες καὶ ἄλλα κειμήλια, συνελόντι δ’ εἰπεῖν, πᾶς ὁ Ἰουδαίων σεσώρευτο πλοῦτος, ἀνεσκευασμένων ἐκεῖ τοὺς οἴκους τῶν εὐπόρων. ἧκον δὲ καὶ ἐπὶ τὴν λοιπὴν στοὰν τοῦ ἔξωθεν ἱεροῦ· καταφεύγει δ’ ἐπ’ αὐτὴν ἀπὸ τοῦ δήμου γύναια καὶ παιδία καὶ σύμμικτος ὄχλος εἰς ἑξακισχιλίους. πρὶν δὲ Καίσαρα κρῖναί τι περὶ αὐτῶν ἢ κελεῦσαι τοὺς ἡγεμόνας, φερόμενοι τοῖς θυμοῖς οἱ στρατιῶται τὴν στοὰν ὑφάπτουσι, καὶ συνέβη τοὺς μὲν ῥιπτοῦντας αὑτοὺς ἐκ τῆς φλογὸς διαφθαρῆναι, τοὺς δὲ ἐν αὐτῇ· περιεσώθη δὲ ἐκ τοσούτων οὐδείς. τούτοις αἴτιος τῆς ἀπωλείας ψευδοπροφήτης τις κατέστη κατ’ ἐκείνην κηρύξας τὴν ἡμέραν τοῖς ἐπὶ τῆς πόλεως, ὡς ὁ θεὸς ἐπὶ τὸ ἱερὸν ἀναβῆναι κελεύει δεξομένους τὰ σημεῖα τῆς σωτηρίας. πολλοὶ δ’ ἦσαν ἐγκάθετοι παρὰ τῶν τυράννων τότε πρὸς τὸν δῆμον προφῆται προσμένειν τὴν ἀπὸ τοῦ θεοῦ βοήθειαν καταγγέλλοντες, ὡς ἧττον αὐτομολοῖεν καὶ τοὺς ἐπάνω δέους καὶ φυλακῆς γενομένους ἐλπὶς παρακροτοίη. πείθεται δὲ ταχέως ἄνθρωπος ἐν συμφοραῖς, ὅταν δ’ ἤδη καὶ τῶν κατεχόντων δεινῶν ἀπαλλαγὴν ὁ ἐξαπατῶν ὑπογράφῃ, τόθ’ ὁ πάσχων ὅλος γίνεται τῆς ἐλπίδος.", "st": "6.5.2"}, {"sp": "N", "t": "Τὸν γοῦν ἄθλιον δῆμον οἱ μὲν ἀπατεῶνες καὶ καταψευδόμενοι τοῦ θεοῦ τηνικαῦτα παρέπειθον, τοῖς δ’ ἐναργέσι καὶ προσημαίνουσι τὴν μέλλουσαν ἐρημίαν τέρασιν οὔτε προσεῖχον οὔτ’ ἐπίστευον, ἀλλ’ ὡς ἐμβεβροντημένοι καὶ μήτε ὄμματα μήτε ψυχὴν ἔχοντες τῶν τοῦ θεοῦ κηρυγμάτων παρήκουσαν, τοῦτο μὲν ὅτε ὑπὲρ τὴν πόλιν ἄστρον ἔστη ῥομφαίᾳ παραπλήσιον καὶ παρατείνας ἐπ’ ἐνιαυτὸν κομήτης, τοῦτο δ’ ἡνίκα πρὸ τῆς ἀποστάσεως καὶ τοῦ πρὸς τὸν πόλεμον κινήματος ἀθροιζομένου τοῦ λαοῦ πρὸς τὴν τῶν ἀζύμων ἑορτήν, ὀγδόη δ’ ἦν Ξανθικοῦ μηνός, κατὰ νυκτὸς ἐνάτην ὥραν τοσοῦτο φῶς περιέλαμψε τὸν βωμὸν καὶ τὸν ναόν, ὡς δοκεῖν ἡμέραν εἶναι λαμπράν, καὶ τοῦτο παρέτεινεν ἐφ’ ἡμίσειαν ὥραν· ὃ τοῖς μὲν ἀπείροις ἀγαθὸν ἐδόκει, τοῖς δὲ ἱερογραμματεῦσι πρὸς τῶν ἀποβεβηκότων εὐθέως ἐκρίθη. καὶ κατὰ τὴν αὐτὴν ἑορτὴν βοῦς μὲν ἀχθεῖσα ὑπό του πρὸς τὴν θυσίαν ἔτεκεν ἄρνα ἐν τῷ ἱερῷ μέσῳ, ἡ δ’ ἀνατολικὴ πύλη τοῦ ἐνδοτέρω ναοῦ χαλκῆ μὲν οὖσα καὶ στιβαρωτάτη, κλειομένη δὲ περὶ δείλην μόλις ὑπ’ ἀνθρώπων εἴκοσι, καὶ μοχλοῖς μὲν ἐπερειδομένη σιδηροδέτοις, κατάπηγας δὲ ἔχουσα βαθυτάτους εἰς τὸν οὐδὸν ὄντα διηνεκοῦς λίθου καθιεμένους, ὤφθη κατὰ νυκτὸς ὥραν ἕκτην αὐτομάτως ἠνοιγμένη. δραμόντες δὲ οἱ τοῦ ἱεροῦ φύλακες ἤγγειλαν τῷ στρατηγῷ, κἀκεῖνος ἀναβὰς μόλις αὐτὴν ἴσχυσεν κλεῖσαι. πάλιν τοῦτο τοῖς μὲν ἰδιώταις κάλλιστον ἐδόκει τέρας· ἀνοῖξαι γὰρ τὸν θεὸν αὐτοῖς τὴν τῶν ἀγαθῶν πύλην· οἱ λόγιοι δὲ λυομένην αὐτομάτως τοῦ ναοῦ τὴν ἀσφάλειαν ἐνενόουν, καὶ πολεμίοις δῶρον ἀνοίγεσθαι τὴν πύλην, δηλωτικόν τε ἐρημίας ἀπέφαινον ἐν αὑτοῖς τὸ σημεῖον. μετὰ δὲ τὴν ἑορτὴν οὐ πολλαῖς ἡμέραις ὕστερον, μιᾷ καὶ εἰκάδι Ἀρτεμισίου μηνός, φάσμα τι δαιμόνιον ὤφθη μεῖζον πίστεως· τερατεία δὲ ἂν ἔδοξεν οἶμαι τὸ ῥηθησόμενον, εἰ μὴ καὶ παρὰ τοῖς θεασαμένοις ἱστόρητο καὶ τὰ ἐπακολουθήσαντα πάθη τῶν σημείων ἦν ἄξια· πρὸ γὰρ ἡλίου δύσεως ὤφθη μετέωρα περὶ πᾶσαν τὴν χώραν ἅρματα καὶ φάλαγγες ἔνοπλοι διᾴττουσαι τῶν νεφῶν καὶ κυκλούμεναι τὰς πόλεις. κατὰ δὲ τὴν ἑορτήν, ἣ πεντηκοστὴ καλεῖται, νύκτωρ οἱ ἱερεῖς παρελθόντες εἰς τὸ ἔνδον ἱερόν, ὥσπερ αὐτοῖς ἔθος πρὸς τὰς λειτουργίας, πρῶτον μὲν κινήσεως ἔφασαν ἀντιλαβέσθαι καὶ κτύπου, μετὰ δὲ ταῦτα φωνῆς ἀθρόας μεταβαίνομεν ἐντεῦθεν. τὸ δὲ τούτων φοβερώτερον, Ἰησοῦς γάρ τις υἱὸς Ἀνανίου τῶν ἰδιωτῶν ἄγροικος πρὸ τεσσάρων ἐτῶν τοῦ πολέμου τὰ μάλιστα τῆς πόλεως εἰρηνευομένης καὶ εὐθηνούσης, ἐλθὼν εἰς τὴν ἑορτήν, ἐν ᾗ σκηνοποιεῖσθαι πάντας ἔθος τῷ θεῷ, κατὰ τὸ ἱερὸν ἐξαπίνης ἀναβοᾶν ἤρξατο φωνὴ ἀπὸ ἀνατολῆς, φωνὴ ἀπὸ δύσεως, φωνὴ ἀπὸ τῶν τεσσάρων ἀνέμων, φωνὴ ἐπὶ Ἱεροσόλυμα καὶ τὸν ναόν, φωνὴ ἐπὶ νυμφίους καὶ νύμφας, φωνὴ ἐπὶ τὸν λαὸν πάντα. τοῦτο μεθ’ ἡμέραν καὶ νύκτωρ κατὰ πάντας τοὺς στενωποὺς περιῄει κεκραγώς. τῶν δὲ ἐπισήμων τινὲς δημοτῶν ἀγανακτήσαντες πρὸς τὸ κακόφημον συλλαμβάνουσι τὸν ἄνθρωπον καὶ πολλαῖς αἰκίζονται πληγαῖς. ὁ δὲ οὔθ’ ὑπὲρ αὑτοῦ φθεγξάμενος οὔτε ἰδίᾳ πρὸς τοὺς παίοντας, ἃς καὶ πρότερον φωνὰς βοῶν διετέλει. νομίσαντες δὲ οἱ ἄρχοντες, ὅπερ ἦν, δαιμονιώτερον τὸ κίνημα τἀνδρὸς ἀνάγουσιν αὐτὸν ἐπὶ τὸν παρὰ Ῥωμαίοις ἔπαρχον. ἔνθα μάστιξι μέχρι ὀστέων ξαινόμενος οὔθ’ ἱκέτευσεν οὔτ’ ἐδάκρυσεν, ἀλλ’ ὡς ἐνῆν μάλιστα τὴν φωνὴν ὀλοφυρτικῶς παρεγκλίνων πρὸς ἑκάστην ἀπεκρίνατο πληγήν αἰαὶ Ἱεροσολύμοις. τοῦ δ’ Ἀλβίνου διερωτῶντος, οὗτος γὰρ ἔπαρχος ἦν, τίς εἴη καὶ πόθεν, καὶ διὰ τί ταῦτα φθέγγοιτο, πρὸς ταῦτα μὲν οὐδ’ ὁτιοῦν ἀπεκρίνατο, τὸν δὲ ἐπὶ τῇ πόλει θρῆνον εἴρων οὐ διέλειπεν, μέχρι καταγνοὺς μανίαν ὁ Ἀλβῖνος ἀπέλυσεν αὐτόν. ὁ δὲ τὸν μέχρι τοῦ πολέμου χρόνον οὔτε προσῄει τινὶ τῶν πολιτῶν οὔτε ὤφθη λαλῶν, ἀλλὰ καθ’ ἡμέραν ὥσπερ εὐχὴν μεμελετηκώς αἰαὶ Ἱεροσολύμοις ἐθρήνει. οὔτε δέ τινι τῶν τυπτόντων αὐτὸν ὁσημέραι κατηρᾶτο οὔτε τοὺς τροφῆς μεταδιδόντας εὐλόγει, μία δὲ πρὸς πάντας ἦν ἡ σκυθρωπὴ κλῃδὼν ἀπόκρισις. μάλιστα δ’ ἐν ταῖς ἑορταῖς ἐκεκράγει· καὶ τοῦτ’ ἐφ’ ἑπτὰ ἔτη καὶ μῆνας πέντε εἴρων οὔτ’ ἤμβλυνεν τὴν φωνὴν οὔτ’ ἔκαμεν, μέχρις οὗ κατὰ τὴν πολιορκίαν ἔργα τῆς κλῃδόνος ἰδὼν ἀνεπαύσατο. περιιὼν γὰρ ἀπὸ τοῦ τείχους αἰαὶ πάλιν τῇ πόλει καὶ τῷ λαῷ καὶ τῷ ναῷ διαπρύσιον ἐβόα, ὡς δὲ τελευταῖον προσέθηκεν αἰαὶ δὲ κἀμοί, λίθος ἐκ τοῦ πετροβόλου σχασθεὶς καὶ πλήξας αὐτὸν παραχρῆμα κτείνει, φθεγγομένην δ’ ἔτι τὰς κλῃδόνας ἐκείνας τὴν ψυχὴν ἀφῆκε.", "st": "6.5.3"}, {"sp": "N", "t": "Ταῦτά τις ἐννοῶν εὑρήσει τὸν μὲν θεὸν ἀνθρώπων κηδόμενον καὶ παντοίως προσημαίνοντα τῷ σφετέρῳ γένει τὰ σωτήρια, τοὺς δ’ ὑπ’ ἀνοίας καὶ κακῶν αὐθαιρέτων ἀπολλυμένους, ὅπου γε Ἰουδαῖοι καὶ τὸ ἱερὸν μετὰ τὴν καθαίρεσιν τῆς Ἀντωνίας τετράγωνον ἐποίησαν, ἀναγεγραμμένον ἐν τοῖς λογίοις ἔχοντες ἁλώσεσθαι τὴν πόλιν καὶ τὸν ναόν, ἐπειδὰν τὸ ἱερὸν γένηται τετράγωνον. τὸ δ’ ἐπᾶραν αὐτοὺς μάλιστα πρὸς τὸν πόλεμον ἦν χρησμὸς ἀμφίβολος ὁμοίως ἐν τοῖς ἱεροῖς εὑρημένος γράμμασιν, ὡς κατὰ τὸν καιρὸν ἐκεῖνον ἀπὸ τῆς χώρας αὐτῶν τις ἄρξει τῆς οἰκουμένης. τοῦθ’ οἱ μὲν ὡς οἰκεῖον ἐξέλαβον καὶ πολλοὶ τῶν σοφῶν ἐπλανήθησαν περὶ τὴν κρίσιν, ἐδήλου δ’ ἄρα τὴν Οὐεσπασιανοῦ τὸ λόγιον ἡγεμονίαν ἀποδειχθέντος ἐπὶ Ἰουδαίας αὐτοκράτορος. ἀλλὰ γὰρ οὐ δυνατὸν ἀνθρώποις τὸ χρεὼν διαφυγεῖν οὐδὲ προορωμένοις. οἱ δὲ καὶ τῶν σημείων ἃ μὲν ἔκριναν πρὸς ἡδονὴν ἃ δὲ ἐξουθένησαν, μέχρις οὗ τῇ τε ἁλώσει τῆς πατρίδος καὶ τῷ σφῶν αὐτῶν ὀλέθρῳ διηλέγχθησαν τὴν ἄνοιαν.", "st": "6.5.4"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ τῶν μὲν στασιαστῶν καταπεφευγότων εἰς τὴν πόλιν, καιομένου δὲ αὐτοῦ τε τοῦ ναοῦ καὶ τῶν πέριξ ἁπάντων, κομίσαντες τὰς σημαίας εἰς τὸ ἱερὸν καὶ θέμενοι τῆς ἀνατολικῆς πύλης ἄντικρυς ἔθυσάν τε αὐταῖς αὐτόθι καὶ τὸν Τίτον μετὰ μεγίστων εὐφημιῶν ἀπέφηναν αὐτοκράτορα. ταῖς δὲ ἁρπαγαῖς οὕτως ἐνεπλήσθησαν οἱ στρατιῶται πάντες, ὥστε κατὰ τὴν Συρίαν πρὸς ἥμισυ τῆς πάλαι τιμῆς τὸν σταθμὸν τοῦ χρυσίου πιπράσκεσθαι. τῶν δ’ ἀνὰ τὸν τοῖχον τοῦ ναοῦ ἱερέων διακαρτερούντων παῖς διψήσας ἱκέτευε τοὺς φύλακας τῶν Ῥωμαίων δοῦναι δεξιὰν αὐτῷ καὶ τὸ δίψος ἐξωμολογεῖτο. τῶν δὲ τῆς ἡλικίας καὶ τῆς ἀνάγκης οἶκτον λαβόντων καὶ δόντων δεξιὰς καταβὰς αὐτός τε πίνει καὶ ὃ φέρων ἧκεν ἀγγεῖον πλήσας ὕδατος ᾤχετο φεύγων ἄνω πρὸς τοὺς σφετέρους. τῶν δὲ φυλάκων καταλαβεῖν μὲν οὐδεὶς ἴσχυσε, πρὸς δὲ τὴν ἀπιστίαν ἐβλασφήμουν. κἀκεῖνος οὐδὲν ἔφη παραβεβηκέναι τῶν συνθηκῶν· λαβεῖν γὰρ δεξιὰν οὐ τοῦ μένειν παρ’ αὐτοῖς ἀλλὰ τοῦ καταβῆναι μόνον καὶ λαβεῖν ὕδωρ, ἅπερ ἀμφότερα πεποιηκὼς πιστὸς ἔδοξεν εἶναι. τὸ μὲν δὴ πανούργημα διὰ τὴν ἡλικίαν μάλιστα τοῦ παιδὸς ἀπεθαύμαζον οἱ πλανηθέντες· πέμπτῃ δ’ ἡμέρᾳ λιμώττοντες οἱ ἱερεῖς καταβαίνουσι καὶ πρὸς Τίτον ἀναχθέντες ὑπὸ τῶν φυλάκων ἱκέτευον τυχεῖν σωτηρίας. ὁ δὲ τὸν μὲν τῆς συγγνώμης καιρὸν αὐτοῖς παρῳχηκέναι φήσας, οἴχεσθαι δὲ δι’ ὃν εὐλόγως ἂν αὐτοὺς ἔσωζε, πρέπειν δὲ τοῖς ἱερεῦσι τῷ ναῷ συναπολέσθαι, κελεύει κολάσαι τοὺς ἄνδρας.", "st": "6.6.1"}, {"sp": "N", "t": "Οἱ δὲ περὶ τοὺς τυράννους ὡς τῷ τε πολέμῳ πάντοθεν ἐκρατοῦντο καὶ περιτετειχισμένοις διαφυγεῖν οὐδαμόθεν ἦν, προκαλοῦνται τὸν Τίτον εἰς λόγους. ὁ δὲ καὶ διὰ τὸ φιλάνθρωπον φύσει τὸ γοῦν ἄστυ περισῶσαι προαιρούμενος καὶ τῶν φίλων ἐναγόντων, ἤδη γὰρ μετριάζειν τοὺς λῃστὰς ὑπελάμβανεν, ἵσταται κατὰ τὸ πρὸς δύσιν μέρος τοῦ ἔξωθεν ἱεροῦ· ταύτῃ γὰρ ὑπὲρ τὸν ξυστὸν ἦσαν πύλαι, καὶ γέφυρα συνάπτουσα τῷ ἱερῷ τὴν ἄνω πόλιν· αὕτη τότε μέση τῶν τυράννων ἦν καὶ τοῦ Καίσαρος. τὸ δὲ πλῆθος ἑκατέροις βύζην ἐφεστήκει, Ἰουδαῖοι μὲν περὶ Σίμωνα καὶ Ἰωάννην μετέωροι συγγνώμης ἐλπίδι, Ῥωμαῖοι δὲ Καίσαρι καραδοκοῦντες αὐτῶν τὴν ἀξίωσιν. παραγγείλας δὲ τοῖς στρατιώταις Τίτος θυμοῦ τε καὶ βελῶν μένειν ἐγκρατεῖς, καὶ τὸν ἑρμηνέα παραστησάμενος, ὅπερ ἦν τεκμήριον τοῦ κρατεῖν, πρῶτος ἤρξατο λέγειν· ἆρά γε ἤδη κεκόρεσθε τῶν τῆς πατρίδος κακῶν, ὦ ἄνδρες, οἱ μήτε τῆς ἡμετέρας δυνάμεως μήτε τῆς ἑαυτῶν ἀσθενείας ἔννοιαν λαβόντες, ὁρμῇ δὲ ἀσκέπτῳ καὶ μανίᾳ τόν τε δῆμον καὶ τὴν πόλιν καὶ τὸν ναὸν ἀπολωλεκότες, ἀπολούμενοι δὲ καὶ αὐτοὶ δικαίως, οἳ πρῶτον μὲν ἀφ’ οὗ Πομπήιος εἷλεν ὑμᾶς κατὰ κράτος οὐκ ἐπαύσασθε νεωτεροποιίας, ἔπειτα καὶ φανερὸν ἐξηνέγκατε πρὸς Ῥωμαίους πόλεμον; ἆρά γε πλήθει πεποιθότες; καὶ μὴν ἐλάχιστον ὑμῖν μέρος ἀντήρκεσεν τοῦ Ῥωμαίων στρατιωτικοῦ. πίστει τοιγαροῦν συμμάχων; καὶ τί τῶν ἔξω τῆς ἡμετέρας ἡγεμονίας ἐθνῶν ἔμελλεν αἱρήσεσθαι Ἰουδαίους πρὸ Ῥωμαίων; ἀλλ’ ἀλκῇ σωμάτων; καὶ μὴν ἴστε Γερμανοὺς δουλεύοντας ἡμῖν. ὀχυρότητι δὲ τειχῶν; καὶ τί μεῖζον ὠκεανοῦ τεῖχος κώλυμα, ὃν περιβεβλημένοι Βρεττανοὶ τὰ Ῥωμαίων ὅπλα προσκυνοῦσιν; καρτερίᾳ ψυχῆς καὶ πανουργίᾳ στρατηγῶν; ἀλλὰ μὴν ᾔδειτε καὶ Καρχηδονίους ἁλόντας. τοιγαροῦν ὑμᾶς ἐπήγειρε κατὰ Ῥωμαίων ἡ Ῥωμαίων φιλανθρωπία, οἳ πρῶτον μὲν ὑμῖν τήν τε χώραν ἔδομεν νέμεσθαι καὶ βασιλεῖς ὁμοφύλους ἐπεστήσαμεν, ἔπειτα τοὺς πατρίους νόμους ἐτηρήσαμεν, καὶ ζῆν οὐ μόνον καθ’ ἑαυτοὺς ἀλλὰ καὶ πρὸς τοὺς ἄλλους ἐπετρέψαμεν ὡς ἐβούλεσθε· τὸ δὲ μέγιστον, δασμολογεῖν τε ὑμῖν ἐπὶ τῷ θεῷ καὶ ἀναθήματα συλλέγειν ἐπετρέψαμεν, καὶ τοὺς ταῦτα φέροντας οὔτε ἐνουθετήσαμεν οὔτε ἐκωλύσαμεν, ἵν’ ἡμῖν γένησθε πλουσιώτεροι καὶ παρασκευάσησθε τοῖς ἡμετέροις χρήμασιν καθ’ ἡμῶν. ἔπειτα τηλικούτων ἀγαθῶν ἀπολαύοντες ἐπὶ τοὺς παρασχόντας ἠνέγκατε τὸν κόρον καὶ δίκην τῶν ἀτιθασεύτων ἑρπετῶν τοῖς σαίνουσι τὸν ἰὸν ἐναφήκατε. ἔστω γοῦν, κατεφρονήσατε τῆς Νέρωνος ῥᾳθυμίας, καὶ καθάπερ ῥήγματα ἢ σπάσματα τὸν ἄλλον χρόνον κακοήθως ἠρεμοῦντες ἐν τῇ μείζονι νόσῳ διεφάνητε καὶ πρὸς ἐλπίδας ἀναιδεῖς ἀμέτρους ἐξετείνατε τὰς ἐπιθυμίας. ἧκεν ὁ πατὴρ οὑμὸς εἰς τὴν χώραν, οὐ τιμωρησόμενος ὑμᾶς τῶν κατὰ Κέστιον, ἀλλὰ νουθετήσων· δέον γοῦν, εἴπερ ἐπ’ ἀναστάσει τοῦ ἔθνους παρῆν, ἐπὶ τὴν ῥίζαν ὑμῶν δραμεῖν καὶ ταύτην ἐκπορθεῖν τὴν πόλιν εὐθέως, ὁ δὲ Γαλιλαίαν ἐδῄου καὶ τὰ πέριξ ἐπιδιδοὺς ὑμῖν χρόνον εἰς μεταμέλειαν. ἀλλ’ ὑμῖν ἀσθένεια τὸ φιλάνθρωπον ἐδόκει κἀκ τῆς ἡμετέρας πρᾳότητος τὴν τόλμαν ἐπεθρέψατε. Νέρωνος οἰχομένου τοῦθ’ ὅπερ ἐχρῆν τοὺς πονηροτάτους ἐποιήσατε, ταῖς ἐμφυλίοις ἡμῶν ταραχαῖς ἐπεθαρρήσατε καὶ χωρισθέντων εἰς τὴν Αἴγυπτον ἐμοῦ τε καὶ τοῦ πατρὸς εἰς παρασκευὰς τοῦ πολέμου κατεχρήσασθε τοῖς καιροῖς, καὶ οὐκ ᾐδέσθητε ταράσσειν αὐτοκράτορας γεγενημένους οὓς καὶ στρατηγοὺς φιλανθρώπους ἐπειράσατε. προσφυγούσης γοῦν ἡμῖν τῆς ἡγεμονίας, καὶ τῶν μὲν κατὰ ταύτην ἠρεμούντων πάντων, πρεσβευομένων δὲ καὶ συνηδομένων τῶν ἔξωθεν ἐθνῶν, πάλιν οἱ Ἰουδαῖοι πολέμιοι, καὶ πρεσβεῖαι μὲν ὑμῶν πρὸς τοὺς ὑπὲρ Εὐφράτην ἐπὶ νεωτερισμῷ, περίβολοι δὲ τειχῶν ἀνοικοδομούμενοι καινοί, στάσεις δὲ καὶ τυράννων φιλονεικίαι καὶ πόλεμος ἐμφύλιος, μόνα τοῖς οὕτω πονηροῖς πρέποντα. ἧκον ἐπὶ τὴν πόλιν ἐγὼ παρὰ τοῦ πατρὸς ἄκοντος λαβὼν σκυθρωπὰ παραγγέλματα. τὸν δῆμον ἀκούσας εἰρηνικὰ φρονεῖν ἥσθην. ὑμᾶς παύσασθαι πρὸ πολέμου παρεκάλουν, μέχρι πολλοῦ πολεμούντων ἐφειδόμην, δεξιὰς αὐτομόλοις ἔδωκα, καταφυγοῦσι πίστεις ἐτήρησα, πολλοὺς αἰχμαλώτους ἠλέησα, τοὺς ἐπείγοντας βασανίσας ἐκόλασα; τείχεσιν ὑμετέροις μηχανὰς ἄκων προσήγαγον, ἀεὶ φονῶντας τοὺς στρατιώτας ἐφ’ ὑμῖν κατέσχον, καθ’ ἑκάστην νίκην ὡς ἡττώμενος ὑμᾶς εἰς εἰρήνην προυκαλεσάμην. τοῦ ἱεροῦ πλησίον γενόμενος πάλιν ἑκὼν ἐξελαθόμην τῶν τοῦ πολέμου νόμων, φείσασθαι δὲ παρεκάλουν τῶν ἰδίων ὑμᾶς ἁγίων καὶ σῶσαι τὸν ναὸν ἑαυτοῖς, διδοὺς ἄδειάν τε ἐξόδου καὶ πίστιν σωτηρίας, εἰ δ’ ἐβούλεσθε, καὶ μάχης καιρὸν ἐν ἄλλῳ τόπῳ· πάντων ὑπερείδετε καὶ τὸν ναὸν ἰδίαις χερσὶν ἐνεπρήσατε. ἔπειτα, μιαρώτατοι, προκαλεῖσθέ με πρὸς λόγους νῦν; ἵνα τί σώσητε τοιοῦτον οἷον ἀπόλωλεν; ποίας ὑμᾶς αὐτοὺς ἀξιοῦτε μετὰ τὸν ναὸν σωτηρίας; ἀλλὰ καὶ νῦν μετὰ τῶν ὅπλων ἑστήκατε καὶ οὐδ’ ἐν ἐσχάτοις ὑποκρίνεσθε γοῦν ἱκέτας, ὦ ταλαίπωροι, τίνι πεποιθότες; οὐ νεκρὸς μὲν ὑμῶν ὁ δῆμος, οἴχεται δ’ ὁ ναός, ὑπ’ ἐμοὶ δὲ ἡ πόλις, ἐν χερσὶ δὲ ταῖς ἐμαῖς ἔχετε τὰς ψυχάς; εἶτα ὑπολαμβάνετε δόξαν ἀνδρείας τὸ δυσθανατᾶν; οὐ μὴν ἐγὼ φιλονεικήσω πρὸς τὴν ἀπόνοιαν ὑμῶν, ῥίψασι δὲ τὰ ὅπλα καὶ παραδοῦσι τὰ σώματα χαρίζομαι τὸ ζῆν, ὥσπερ ἐν οἰκίᾳ πρᾷος δεσπότης τὰ μὲν ἀνήκεστα κολάσας, τὰ δὲ λοιπὰ σώζων ἐμαυτῷ.", "st": "6.6.2"}, {"sp": "N", "t": "Πρὸς ταῦτα ἀποκρίνονται δεξιὰν μὲν μὴ δύνασθαι παρ’ αὐτοῦ λαβεῖν, ὀμωμοκέναι γὰρ μήποτε τοῦτο ποιήσειν, ἔξοδον δ’ ᾐτοῦντο διὰ τοῦ περιτειχίσματος μετὰ γυναικῶν καὶ τέκνων· ἀπελεύσεσθαι γὰρ εἰς τὴν ἔρημον καὶ καταλείψειν αὐτῷ τὴν πόλιν. πρὸς ταῦτα ἀγανακτήσας Τίτος, εἰ τύχην ἑαλωκότων ἔχοντες αἱρέσεις αὐτῷ προτείνουσι νενικηκότων, κηρῦξαι μὲν ἐκέλευσεν εἰς αὐτοὺς μήτε αὐτομολεῖν ἔτι μήτε δεξιὰν ἐλπίζειν, φείσεσθαι γὰρ οὐδενός, ἀλλὰ πάσῃ δυνάμει μάχεσθαι καὶ σώζειν ἑαυτοὺς ὅπως ἂν δύνωνται· πάντα γὰρ αὐτὸς ἤδη πράξειν πολέμου νόμῳ· τοῖς δὲ στρατιώταις ἐμπιπράναι καὶ διαρπάζειν ἐπέτρεψεν τὴν πόλιν. οἱ δὲ ἐκείνην μὲν ἐπέσχον τὴν ἡμέραν, τῇ δὲ ὑστεραίᾳ τό τε ἀρχεῖον καὶ τὴν ἄκραν καὶ τὸ βουλευτήριον καὶ τὸν Ὀφλᾶν καλούμενον ὑφῆψαν· καὶ προύκοψε τὸ πῦρ μέχρι τῶν Ἑλένης βασιλείων, ἃ δὴ κατὰ μέσην τὴν ἄκραν ἦν, ἐκαίοντο δὲ οἱ στενωποὶ καὶ αἱ οἰκίαι νεκρῶν ὑπὸ τοῦ λιμοῦ διεφθαρμένων πλήρεις.", "st": "6.6.3"}, {"sp": "N", "t": "Κατὰ ταύτην τὴν ἡμέραν οἵ τε Ἰζάτου βασιλέως υἱοὶ καὶ ἀδελφοί, πρὸς οἷς πολλοὶ τῶν ἐπισήμων δημοτῶν ἐκεῖ συνελθόντες, ἱκέτευσαν Καίσαρα δοῦναι δεξιὰν αὐτοῖς. ὁ δὲ καίτοι πρὸς πάντας τοὺς ὑπολοίπους διωργισμένος οὐκ ἤλλαξε τὸ ἦθος, δέχεται δὲ τοὺς ἄνδρας. καὶ τότε μὲν ἐν φρουρᾷ πάντας εἶχε, τοὺς δὲ τοῦ βασιλέως παῖδας καὶ συγγενεῖς δήσας ὕστερον εἰς Ῥώμην ἀνήγαγεν πίστιν ὁμήρων παρέξοντας.", "st": "6.6.4"}, {"sp": "N", "t": "Οἱ στασιασταὶ δὲ ἐπὶ τὴν βασιλικὴν ὁρμήσαντες αὐλήν, εἰς ἣν δι’ ὀχυρότητα πολλοὶ τὰς κτήσεις ἀπέθεντο, τούς τε Ῥωμαίους ἀπ’ αὐτῆς τρέπονται καὶ τὸ συνηθροισμένον αὐτόθι τοῦ δήμου πᾶν φονεύσαντες, ὄντας εἰς ὀκτακισχιλίους καὶ τετρακοσίους, τὰ χρήματα διήρπασαν. ἐζώγρησαν δὲ καὶ Ῥωμαίων δύο, τὸν μὲν ἱππέα τὸν δὲ πεζόν, καὶ τὸν μὲν πεζὸν ἀποσφάξαντες εὐθέως ἔσυραν περὶ τὴν πόλιν, ὥσπερ ἑνὶ σώματι πάντας Ῥωμαίους ἀμυνόμενοι, ὁ δὲ ἱππεὺς ὠφέλιμόν τι αὐτοῖς πρὸς σωτηρίαν ὑποθήσεσθαι λέγων ἀνάγεται πρὸς Σίμωνα· παρ’ ᾧ μηδὲν εἰπεῖν ἔχων Ἀρδάλᾳ τινὶ τῶν ἡγεμόνων παραδίδοται κολασθησόμενος. ὁ δὲ αὐτοῦ ὀπίσω τὼ χεῖρε δήσας καὶ ταινίᾳ τοὺς ὀφθαλμοὺς ἀντικρὺ τῶν Ῥωμαίων προήγαγεν ὡς καρατομήσων· φθάνει δ’ ἐκεῖνος εἰς τοὺς Ῥωμαίους διαφυγὼν ἐν ὅσῳ τὸ ξίφος ἐσπάσατο ὁ Ἰουδαῖος. τοῦτον διαφυγόντα ἐκ τῶν πολεμίων ἀνελεῖν μὲν οὐχ ὑπέμεινεν Τίτος, ἀνάξιον δὲ Ῥωμαίων εἶναι στρατιώτην κρίνας, ὅτι ζῶν ἐλήφθη, τά τε ὅπλα ἀφείλετο καὶ τοῦ τάγματος ἐξέβαλεν, ἅπερ ἦν αἰσχυνομένῳ θανάτου χαλεπώτερα.", "st": "6.7.1"}, {"sp": "N", "t": "Τῇ δ’ ἑξῆς Ῥωμαῖοι τρεψάμενοι τοὺς λῃστὰς ἐκ τῆς κάτω πόλεως τὰ μέχρι τοῦ Σιλωᾶ [πάντα] ἐνέπρησαν, καὶ τοῦ μὲν ἄστεος ἥδοντο δαπανωμένου, τῶν δ’ ἁρπαγῶν διημάρτανον, ἐπειδὴ πάνθ’ οἱ στασιασταὶ προκενοῦντες ἀνεχώρουν εἰς τὴν ἄνω πόλιν. ἦν γὰρ αὐτοῖς μετάνοια μὲν οὐδεμία τῶν κακῶν, ἀλαζονεία δὲ ὡς ἐπ’ ἀγαθοῖς· καιομένην γοῦν ἀφορῶντες τὴν πόλιν ἱλαροῖς τοῖς προσώποις εὔθυμοι προσδέχεσθαι τὴν τελευτὴν ἔλεγον, πεφονευμένου μὲν τοῦ δήμου, κεκαυμένου δὲ τοῦ ναοῦ, φλεγομένου δὲ τοῦ ἄστεος μηδὲν καταλιπόντες τοῖς πολεμίοις. οὐ μὴν ὅ γε Ἰώσηπος ἐν ἐσχάτοις ἱκετεύων αὐτοὺς ὑπὲρ τῶν λειψάνων τῆς πόλεως ἔκαμνεν, ἀλλὰ πολλὰ μὲν πρὸς τὴν ὠμότητα καὶ τὴν ἀσέβειαν εἰπών, πολλὰ δὲ συμβουλεύσας πρὸς σωτηρίαν οὐδὲν τοῦ χλευασθῆναι πλέον ἀπηνέγκατο. ἐπεὶ δὲ οὔτε παραδοῦναι διὰ τὸν ὅρκον ἑαυτοὺς ὑπέμενον οὔτε πολεμεῖν ἐξ ἴσου Ῥωμαίοις ἔθ’ οἷοί τε ἦσαν ὥσπερ εἱρκτῇ περιειλημμένοι, τό τε τοῦ φονεύειν ἔθος ἐκίνει τὰς δεξιάς, σκιδνάμενοι κατὰ τὰ ἔμπροσθεν τῆς πόλεως τοῖς ἐρειπίοις ὑπελόχων τοὺς αὐτομολεῖν ὡρμημένους. ἡλίσκοντο δὲ πολλοί, καὶ πάντας ἀποσφάττοντες, ὑπὸ γὰρ ἐνδείας οὐδὲ φεύγειν ἴσχυον, ἐρρίπτουν αὐτῶν κυσὶ τοὺς νεκρούς. ἐδόκει δὲ πᾶς τρόπος ἀπωλείας τοῦ λιμοῦ κουφότερος, ὥστε καὶ Ῥωμαίοις ἀπηλπικότες ἤδη τὸν ἔλεον ὅμως προσέφευγον καὶ φονεύουσι τοῖς στασιασταῖς ἑκόντες ἐνέπιπτον. τόπος τ’ ἐπὶ τῆς πόλεως οὐδεὶς γυμνὸς ἦν, ἀλλὰ πᾶς λιμοῦ νεκρὸν εἶχεν ἢ στάσεως [καὶ πεπλήρωτο νεκρῶν ἢ διὰ στάσιν ἢ διὰ λιμὸν ἀπολωλότων].", "st": "6.7.2"}, {"sp": "N", "t": "Ἔθαλπε δὲ τούς τε τυράννους καὶ τὸ σὺν αὐτοῖς λῃστρικὸν ἐλπὶς ἐσχάτη περὶ τῶν ὑπονόμων, εἰς οὓς καταφεύγοντες οὐ προσεδόκων ἐρευνηθήσεσθαι, μετὰ δὲ τὴν παντελῆ τῆς πόλεως ἅλωσιν ἀναζευξάντων Ῥωμαίων προελθόντες ἀποδράσεσθαι ἐπεχείρουν. τὸ δὲ ἦν ἄρα ὄνειρος αὐτοῖς· οὔτε γὰρ τὸν θεὸν οὔτε Ῥωμαίους λήσειν ἔμελλον. τηνικαῦτά γε μὴν τοῖς ὑπογείοις πεποιθότες αὐτοὶ πλείονα τῶν Ῥωμαίων ἐνεπίμπρασαν, καὶ τοὺς ἐκ τῶν καιομένων καταφεύγοντας εἰς τὰς διώρυχας ἔκτεινόν τε ἀνέδην καὶ ἐσύλων καὶ εἴ τινος εὕροιεν τροφὴν ἁρπάζοντες αἵματι πεφυρμένην κατέπινον. ἦν δὲ καὶ πρὸς ἀλλήλους ἐν ταῖς ἁρπαγαῖς ἤδη πόλεμος αὐτοῖς, δοκοῦσί τε ἄν μοι μὴ φθασθέντες ὑπὸ τῆς ἁλώσεως δι’ ὑπερβολὴν ὠμότητος γεύσασθαι καὶ τῶν νεκρῶν.", "st": "6.7.3"}, {"sp": "N", "t": "Καῖσαρ δέ, ὡς ἀμήχανον ἦν ἐξελεῖν δίχα χωμάτων τὴν ἄνω πόλιν περίκρημνον οὖσαν, διανέμει τοῖς ἔργοις τὴν δύναμιν Λώου μηνὸς εἰκάδι. χαλεπὴ δὲ ἦν τῆς ὕλης ἡ κομιδὴ πάντων, ὡς ἔφην, τῶν περὶ τὴν πόλιν ἐφ’ ἑκατὸν σταδίους ἐψιλωμένων εἰς τὰ πρότερον χώματα. τῶν μὲν οὖν τεσσάρων ταγμάτων ἠγείρετο τὰ ἔργα κατὰ τὸ πρὸς δύσιν κλίμα τῆς πόλεως ἀντικρὺ τῆς βασιλικῆς αὐλῆς, τὸ δὲ συμμαχικὸν πλῆθος καὶ ὁ λοιπὸς ὄχλος κατὰ τὸν ξυστὸν ἔχου καὶ τὴν γέφυραν καὶ τὸν Σίμωνος πύργον, ὃν ᾠκοδόμησε πρὸς Ἰωάννην πολεμῶν ἑαυτῷ φρούριον.", "st": "6.8.1"}, {"sp": "N", "t": "Κατὰ ταύτας τὰς ἡμέρας οἱ τῶν Ἰδουμαίων ἡγεμόνες κρύφα συνελθόντες ἐβουλεύσαντο περὶ παραδόσεως σφῶν αὐτῶν, καὶ πέμψαντες ἄνδρας πέντε πρὸς Τίτον ἱκέτευον δοῦναι δεξιὰν αὐτοῖς. ὁ δὲ καὶ τοὺς τυράννους ἐνδώσειν ἐλπίσας ἀποσπασθέντων τῶν Ἰδουμαίων, οἳ πολὺ τοῦ πολέμου μέρος ἦσαν, βραδέως μέν, ἀλλ’ οὖν κατανεύει τε τὴν σωτηρίαν αὐτοῖς καὶ τοὺς ἄνδρας ἀνέπεμψε. παρασκευαζομένων δὲ ἀποχωρεῖν αἰσθάνεται Σίμων, καὶ πέντε μὲν τοὺς ἀπελθόντας πρὸς Τίτον εὐθέως ἀναιρεῖ, τοὺς δὲ ἡγεμόνας, ὧν ἐπισημότατος ἦν ὁ τοῦ Σωσᾶ Ἰάκωβος, συλλαβὼν εἵργνυσι· τὸ δὲ πλῆθος τῶν Ἰδουμαίων ἀμηχανοῦν διὰ τὴν ἀφαίρεσιν τῶν ἡγεμόνων οὐκ ἀφύλακτον εἶχε καὶ τὸ τεῖχος φρουραῖς ἐπιμελεστέραις διελάμβανεν. οὐ μὴν ἀντέχειν οἱ φρουροὶ πρὸς τὰς αὐτομολίας ἴσχυον, ἀλλὰ καίτοι πλείστων φονευομένων πολὺ πλείους οἱ διαφεύγοντες ἦσαν. ἐδέχοντο δὲ Ῥωμαῖοι πάντας, τοῦ τε Τίτου διὰ πρᾳότητα τῶν προτέρων ἀμελήσαντος παραγγελμάτων, καὶ αὐτοὶ κόρῳ τοῦ κτείνειν ἀπεχόμενοι καὶ κέρδους ἐλπίδι· τοὺς γὰρ δημοτικοὺς καταλιπόντες μόνους τὸν ἄλλον ὄχλον ἐπώλουν σὺν γυναιξὶ καὶ τέκνοις, ἐλαχίστης τιμῆς ἕκαστον πλήθει τε τῶν πιπρασκομένων καὶ ὀλιγότητι τῶν ὠνουμένων. καίπερ δὲ προκηρύξας μηδένα μόνον αὐτομολεῖν, ὅπως καὶ τὰς γενεὰς ἐξαγάγοιεν, ὅμως καὶ τούτους ἐδέχετο· ἐπέστησε μέντοι τοὺς διακρινοῦντας ἀπ’ αὐτῶν, εἴ τις εἴη κολάσεως ἄξιος. καὶ τῶν μὲν ἀπεμποληθέντων ἄπειρον ἦν τὸ πλῆθος, οἱ δημοτικοὶ δὲ διεσώθησαν ὑπὲρ τετρακισμυρίους, οὓς διαφῆκεν Καῖσαρ ᾗ φίλον ἦν ἑκάστῳ.", "st": "6.8.2"}, {"sp": "N", "t": "Ἐν δὲ ταῖς αὐταῖς ἡμέραις καὶ τῶν ἱερέων τις Θεβουθεῖ παῖς, Ἰησοῦς ὄνομα, λαβὼν περὶ σωτηρίας ὅρκους παρὰ Καίσαρος ἐφ’ ᾧ παραδώσει τινὰ τῶν ἱερῶν κειμηλίων, ἔξεισι καὶ παραδίδωσιν ἀπὸ τοῦ τοίχου τοῦ ναοῦ λυχνίας δύο τῶν κατὰ τὸν ναὸν κειμένων παραπλησίας τραπέζας τε καὶ κρατῆρας καὶ φιάλας, πάντα ὁλόχρυσα καὶ στιβαρώτατα, παραδίδωσι δὲ καὶ τὰ καταπετάσματα καὶ τὰ ἐνδύματα τῶν ἀρχιερέων σὺν τοῖς λίθοις καὶ πολλὰ τῶν πρὸς τὰς ἱερουργίας σκευῶν ἄλλα. συλληφθεὶς δὲ καὶ ὁ γαζοφύλαξ τοῦ ἱεροῦ Φινέας ὄνομα τούς τε χιτῶνας καὶ τὰς ζώνας ὑπέδειξε τῶν ἱερέων πορφύραν τε πολλὴν καὶ κόκκον, ἃ πρὸς τὰς χρείας ἀπέκειτο τοῦ καταπετάσματος, σὺν οἷς κιννάμωμόν τε πολὺ καὶ κασσίαν καὶ πλῆθος ἑτέρων ἀρωμάτων, ἃ συμμίσγοντες ἐθυμίων ὁσημέραι τῷ θεῷ. παρεδόθη δὲ ὑπ’ αὐτοῦ πολλὰ καὶ τῶν ἄλλων κειμηλίων κόσμος τε ἱερὸς οὐκ ὀλίγος, ἅπερ αὐτῷ βίᾳ ληφθέντι τὴν τῶν αὐτομόλων συγγνώμην ἔδωκε.", "st": "6.8.3"}, {"sp": "N", "t": "Συντετελεσμένων δ’ ἤδη καὶ τῶν χωμάτων ἐν ὀκτωκαίδεκα ἡμέραις ἑβδόμῃ Γορπιαίου μηνὸς Ῥωμαῖοι μὲν προσῆγον τὰς μηχανάς, τῶν δὲ στασιαστῶν οἱ μὲν ἀπεγνωκότες ἤδη τὴν πόλιν ἀνεχώρουν τοῦ τείχους εἰς τὴν ἄκραν, οἱ δὲ ἐγκατεδύοντο τοῖς ὑπονόμοις· πολλοὶ δὲ διαστάντες ἠμύνοντο τοὺς προσάγοντας τὰς ἑλεπόλεις. ἐκράτουν δὲ καὶ τούτων Ῥωμαῖοι πλήθει τε καὶ βίᾳ καὶ τὸ μέγιστον, εὐθυμοῦντες ἀθύμων ἤδη καὶ παρειμένων. ὡς δὲ παρερράγη μέρος τι τοῦ τείχους, καί τινες τῶν πύργων τυπτόμενοι τοῖς κριοῖς ἐνέδοσαν, φυγὴ μὲν ἦν εὐθέως τῶν ἀμυνομένων, δέος δὲ καὶ τοῖς τυράννοις ἐμπίπτει σφοδρότερον τῆς ἀνάγκης· πρὶν γὰρ ὑπερβῆναι τοὺς πολεμίους ἐνάρκων τε καὶ μετέωροι πρὸς φυγὴν ἦσαν, ἦν δὲ ἰδεῖν τοὺς πάλαι σοβαροὺς καὶ τοῖς ἀσεβήμασιν ἀλαζόνας τότε ταπεινοὺς καὶ τρέμοντας, ὡς ἐλεεινὴν εἶναι καίπερ ἐν πονηροτάτοις τὴν μεταβολήν. ὥρμησαν μὲν οὖν ἐπὶ τὸ περιτείχισμα δραμόντες ὤσασθαί τε τοὺς φρουροὺς καὶ διακόψαντες ἐξελθεῖν· ὡς δὲ τοὺς μὲν πάλαι πιστοὺς ἑώρων οὐδαμοῦ, διέφυγον γὰρ ὅπῃ τινὶ συνεβούλευεν ἡ ἀνάγκη, προσθέοντες δὲ οἱ μὲν ὅλον ἀνατετράφθαι τὸ πρὸς δύσιν τεῖχος ἤγγελλον, οἱ δ’ ἐμβεβληκέναι τοὺς Ῥωμαίους ἤδη τε πλησίον εἶναι ζητοῦντας αὐτούς, ἕτεροι δὲ καὶ ἀφορᾶν ἀπὸ τῶν πύργων πολεμίους ἔλεγον πλάζοντος τὰς ὄψεις τοῦ δέους, ἐπὶ στόμα πεσόντες ἀνῴμωζον τὴν ἑαυτῶν φρενοβλάβειαν καὶ καθάπερ ὑποκεκομμένοι τὰ νεῦρα τῆς φυγῆς ἠπόρουν. ἔνθα δὴ μάλιστ’ ἄν τις καταμάθοι τήν τε τοῦ θεοῦ δύναμιν ἐπὶ τοῖς ἀνοσίοις καὶ τὴν Ῥωμαίων τύχην· οἱ μέν γε τύραννοι τῆς ἀσφαλείας ἐγύμνωσαν αὑτοὺς κἀκ τῶν πύργων κατέβησαν ἑκόντες, ἐφ’ ὧν βίᾳ μὲν οὐδέποθ’ ἁλῶναι, μόνῳ δ’ ἐδύναντο λιμῷ. Ῥωμαῖοι δὲ τοσαῦτα περὶ τοῖς ἀσθενεστέροις τείχεσι καμόντες παρέλαβον τύχῃ τὰ μὴ δυνατὰ τοῖς ὀργάνοις· παντὸς γὰρ ἰσχυρότεροι μηχανήματος ἦσαν οἱ τρεῖς πύργοι, περὶ ὧν ἀνωτέρω δεδηλώκαμεν.", "st": "6.8.4"}, {"sp": "N", "t": "Καταλιπόντες δὴ τούτους, μᾶλλον δὲ ὑπὸ τοῦ θεοῦ καταβληθέντες ἀπ’ αὐτῶν, παραχρῆμα μὲν εἰς τὴν ὑπὸ τῇ Σιλωᾶ φάραγγα καταφεύγουσιν, αὖθις δὲ ὀλίγον ἀνακύψαντες ἐκ τοῦ δέους ὥρμησαν ἐπὶ τὸ τῇδε περιτείχισμα. χρησάμενοι δὲ ταῖς τόλμαις ἀγενεστέραις τῆς ἀνάγκης, κατεάγησαν γὰρ ἤδη τὴν ἰσχὺν ἅμα τῷ δέει καὶ ταῖς συμφοραῖς, ὑπὸ τῶν φρουρῶν ἀνωθοῦνται καὶ σκεδασθέντες ὑπ’ ἀλλήλων κατέδυσαν εἰς τοὺς ὑπονόμους. Ῥωμαῖοι δὲ τῶν τειχῶν κρατήσαντες τάς τε σημαίας ἔστησαν ἐπὶ τῶν πύργων καὶ μετὰ κρότου καὶ χαρᾶς ἐπαιάνιζον ἐπὶ τῇ νίκῃ, πολὺ τῆς ἀρχῆς κουφότερον τοῦ πολέμου τὸ τέλος εὑρηκότες· ἀναιμωτὶ γοῦν τοῦ τελευταίου τείχους ἐπιβάντες ἠπίστουν, καὶ μηδένα βλέποντες ἀντίπαλον ἀληθῶς ἠπόρηντο. εἰσχυθέντες δὲ τοῖς στενωποῖς ξιφήρεις τούς τε καταλαμβανομένους ἐφόνευον ἀνέδην καὶ τῶν συμφευγόντων τὰς οἰκίας αὐτάνδρους ὑπεπίμπρασαν. πολλὰς δὲ κεραΐζοντες ὁπότ’ ἔνδον παρέλθοιεν ἐφ’ ἁρπαγήν, γενεὰς ὅλας νεκρῶν κατελάμβανον καὶ τὰ δωμάτια πλήρη τῶν τοῦ λιμοῦ πτωμάτων, ἔπειτα πρὸς τὴν ὄψιν πεφρικότες κεναῖς χερσὶν ἐξῄεσαν. οὐ μὴν οἰκτείροντες τοὺς οὕτως ἀπολωλότας ταὐτὸ καὶ πρὸς τοὺς ζῶντας ἔπασχον, ἀλλὰ τὸν ἐντυγχάνοντα διελαύνοντες ἀπέφραξαν μὲν τοὺς στενωποὺς νεκροῖς, αἵματι δὲ ὅλην τὴν πόλιν κατέκλυσαν, ὡς πολλὰ καὶ τῶν φλεγομένων σβεσθῆναι τῷ φόνῳ. καὶ οἱ μὲν κτείνοντες ἐπαύσαντο πρὸς ἑσπέραν, ἐν δὲ τῇ νυκτὶ τὸ πῦρ ἐπεκράτει, φλεγομένοις δ’ ἐπανέτειλεν Ἱεροσολύμοις ἡμέρα Γορπιαίου μηνὸς ὀγδόη, πόλει τοσαύταις χρησαμένῃ συμφοραῖς κατὰ τὴν πολιορκίαν, ὅσοις ἀπὸ κτίσεως ἀγαθοῖς κεχρημένη πάντως ἂν ἐπίφθονος ἔδοξεν, οὐ μὴν ἀξίᾳ κατ’ ἄλλο τι τῶν τηλικούτων ἀτυχημάτων ἢ τὸ γενεὰν τοιαύτην ἐνεγκεῖν, ὑφ’ ἧς ἀνετράπη.", "st": "6.8.5"}, {"sp": "N", "t": "Παρελθὼν δὲ Τίτος εἴσω τά τε ἄλλα τῆς ὀχυρότητος τὴν πόλιν καὶ τῶν πύργων ἀπεθαύμασεν, οὓς οἱ τύραννοι κατὰ φρενοβλάβειαν ἀπέλιπον. κατιδὼν γοῦν τό τε ναστὸν αὐτῶν ὕψος καὶ τὸ μέγεθος ἑκάστης πέτρας τήν τε ἀκρίβειαν τῆς ἁρμονίας, καὶ ὅσοι μὲν εὖρος ἡλίκοι δὲ ἦσαν τὴν ἀνάστασιν, σὺν θεῷ γε ἐπολεμήσαμεν, ἔφη, καὶ θεὸς ἦν ὁ τῶνδε τῶν ἐρυμάτων Ἰουδαίους καθελών, ἐπεὶ χεῖρες ἀνθρώπων ἢ μηχαναὶ τί πρὸς τούτους τοὺς πύργους δύνανται; τότε μὲν οὖν πολλὰ τοιαῦτα διελέχθη πρὸς τοὺς φίλους, τοὺς δὲ τῶν τυράννων δεσμώτας, ὅσοι κατελήφθησαν ἐν τοῖς φρουρίοις, ἀνῆκεν. αὖθις δὲ τὴν ἄλλην ἀφανίζων πόλιν καὶ τὰ τείχη κατασκάπτων τούτους τοὺς πύργους κατέλιπε μνημεῖον εἶναι τῆς αὐτοῦ τύχης, ᾗ συστρατιώτιδι χρησάμενος ἐκράτησε τῶν ἁλῶναι μὴ δυναμένων.", "st": "6.9.1"}, {"sp": "N", "t": "Ἐπεὶ δ’ οἱ στρατιῶται μὲν ἔκαμνον ἤδη φονεύοντες, πολὺ δέ τι πλῆθος τῶν περιόντων ἀνεφαίνετο, κελεύει Καῖσαρ μόνους μὲν τοὺς ἐνόπλους καὶ χεῖρας ἀντίσχοντας κτείνειν, τὸ δὲ λοιπὸν πλῆθος ζωγρεῖν. οἱ δὲ μετὰ τῶν παρηγγελμένων τό τε γηραιὸν καὶ τοὺς ἀσθενεῖς ἀνῄρουν, τὸ δ’ ἀκμάζον καὶ χρήσιμον εἰς τὸ ἱερὸν συνελάσαντες ἐγκατέκλεισαν τῷ τῶν γυναικῶν περιτειχίσματι. καὶ φρουρὸν μὲν ἐπέστησε Καῖσαρ ἕνα τῶν ἀπελευθέρων, Φρόντωνα δὲ τῶν φίλων ἐπικρινοῦντα τὴν ἀξίαν ἑκάστῳ τύχην. ὁ δὲ τοὺς μὲν στασιώδεις καὶ λῃστρικοὺς πάντας ὑπ’ ἀλλήλων ἐνδεικνυμένους ἀπέκτεινε, τῶν δὲ νέων τοὺς ὑψηλοτάτους καὶ καλοὺς ἐπιλέξας ἐτήρει τῷ θριάμβῳ. τοῦ δὲ λοιποῦ πλήθους τοὺς ὑπὲρ ἑπτακαίδεκα ἔτη δήσας ἔπεμψεν εἰς τὰ κατ’ Αἴγυπτον ἔργα, πλείστους δ’ εἰς τὰς ἐπαρχίας διεδωρήσατο Τίτος φθαρησομένους ἐν τοῖς θεάτροις σιδήρῳ καὶ θηρίοις· οἱ δ’ ἐντὸς ἑπτακαίδεκα ἐτῶν ἐπράθησαν. ἐφθάρησαν δὲ αὐτῶν ἐν αἷς διέκρινεν ὁ Φρόντων ἡμέραις ὑπ’ ἐνδείας χίλιοι πρὸς τοῖς μυρίοις, οἱ μὲν ὑπὸ μίσους τῶν φυλάκων μὴ μεταλαμβάνοντες τροφῆς, οἱ δ’ οὐ προσιέμενοι διδομένην· πρὸς δὲ τὸ πλῆθος ἦν ἔνδεια καὶ σίτου.", "st": "6.9.2"}, {"sp": "N", "t": "Τῶν μὲν οὖν αἰχμαλώτων πάντων, ὅσα καθ’ ὅλον ἐλήφθη τὸν πόλεμον, ἀριθμὸς ἐννέα μυριάδες καὶ ἑπτακισχίλιοι συνήχθη, τῶν δὲ ἀπολομένων κατὰ πᾶσαν τὴν πολιορκίαν μυριάδες ἑκατὸν καὶ δέκα. τούτων τὸ πλέον ὁμόφυλον μὲν ἀλλ’ οὐκ ἐπιχώριον· ἀπὸ γὰρ τῆς χώρας ὅλης ἐπὶ τὴν τῶν ἀζύμων ἑορτὴν συνεληλυθότες ἐξαπίνης τῷ πολέμῳ περιεσχέθησαν, ὥστε τὸ μὲν πρῶτον αὐτοῖς τὴν στενοχωρίαν γενέσθαι λοιμώδη φθοράν, αὖθις δὲ καὶ λιμὸν ὠκύτερον. ὅτι δ’ ἐχώρει τοσούτους ἡ πόλις, δῆλον ἐκ τῶν ἐπὶ Κεστίου συναριθμηθέντων, ὃς τὴν ἀκμὴν τῆς πόλεως διαδηλῶσαι Νέρωνι βουλόμενος καταφρονοῦντι τοῦ ἔθνους παρεκάλεσεν τοὺς ἀρχιερεῖς, εἴ πως δυνατὸν εἴη τὴν πληθὺν ἐξαριθμήσασθαι· οἱ δ’ ἐνστάσης ἑορτῆς, πάσχα καλεῖται, καθ’ ἣν θύουσιν μὲν ἀπὸ ἐνάτης ὥρας μέχρις ἑνδεκάτης, ὥσπερ δὲ φατρία περὶ ἑκάστην γίνεται θυσίαν οὐκ ἐλάσσων ἀνδρῶν δέκα, μόνον γὰρ οὐκ ἔξεστιν δαίνυσθαι, πολλοὶ δὲ καὶ συνείκοσιν ἀθροίζονται, τῶν μὲν θυμάτων εἰκοσιπέντε μυριάδας ἠρίθμησαν, πρὸς δὲ πεντακισχίλια ἑξακόσια. γίνονται ἀνδρῶν, ἵν’ ἑκάστου δέκα δαιτυμόνας θῶμεν, μυριάδες ἑβδομήκοντα καὶ διακόσιαι καθαρῶν ἁπάντων καὶ ἁγίων· οὔτε γὰρ λεπροῖς οὔτε γονορροιϊκοῖς οὔτε γυναιξὶν ἐπεμμήνοις οὔτε τοῖς ἄλλως μεμιασμένοις ἐξὸν ἦν τῆσδε τῆς θυσίας μεταλαμβάνειν,", "st": "6.9.3"}, {"sp": "N", "t": "ἀλλ’ οὐδὲ τοῖς ἀλλοφύλοις, ὅσοι κατὰ θρησκείαν παρῆσαν, πολὺ δὲ τούτων πλῆθος ἔξωθεν συλλέγεται. τότε γε μὴν ὥσπερ εἰς εἱρκτὴν ὑπὸ τῆς εἱμαρμένης πᾶν συνεκλείσθη τὸ ἔθνος, καὶ ναστὴν ὁ πόλεμος τὴν πόλιν ἀνδρῶν ἐκυκλώσατο. πᾶσαν γοῦν ἀνθρωπίνην καὶ δαιμονίαν φθορὰν ὑπερβάλλει τὸ πλῆθος τῶν ἀπολωλότων· ἐπεὶ γοῦν τῶν φανερῶν οὓς μὲν ἀνεῖλον οὓς δ’ ᾐχμαλωτίσαντο Ῥωμαῖοι, τοὺς ἐν τοῖς ὑπονόμοις ἀνηρεύνων καὶ τοὔδαφος ἀναῤῥηγνύντες ὅσοις μὲν ἐνετύγχανον ἔκτεινον, εὑρέθησαν δὲ κἀκεῖ νεκροὶ πλείους δισχιλίων, οἱ μὲν ὑπὸ σφῶν αὐτῶν οἱ δὲ ὑπ’ ἀλλήλων, τὸ πλέον δ’ ὑπὸ τοῦ λιμοῦ διεφθαρμένοι. δεινὴ δ’ ὑπήντα τοῖς ἐπεισπίπτουσιν ὀδμὴ τῶν σωμάτων, ὡς πολλοὺς μὲν ἀναχωρεῖν εὐθέως, τοὺς δὲ ὑπὸ πλεονεξίας εἰσδύεσθαι νεκροὺς σεσωρευμένους ἐμπατοῦντας· πολλὰ γὰρ τῶν κειμηλίων ἐν ταῖς διώρυξιν εὑρίσκετο, καὶ πᾶσαν θεμιτὴν ὁδὸν ἐποίει τὸ κέρδος· ἀνήγοντο δὲ καὶ δεσμῶται πολλοὶ τῶν τυράννων· οὐδὲ γὰρ ἐν ἐσχάτοις ἐπαύσαντο τῆς ὠμότητος. ἀπετίσατό γε μὴν ὁ θεὸς ἀμφοτέρους ἀξίως, καὶ Ἰωάννης μὲν λιμώττων μετὰ τῶν ἀδελφῶν ἐν τοῖς ὑπονόμοις ἣν πολλάκις ὑπερηφάνησε παρὰ Ῥωμαίων δεξιὰν λαβεῖν ἱκέτευσε, Σίμων δὲ πολλὰ διαμαχήσας πρὸς τὴν ἀνάγκην, ὡς διὰ τῶν ἑξῆς δηλώσομεν, αὑτὸν παραδίδωσιν. ἐφυλάχθη δὲ ὁ μὲν τῷ θριάμβῳ σφάγιον, ὁ δ’ Ἰωάννης δεσμοῖς αἰωνίοις. Ῥωμαῖοι δὲ τάς τ’ ἐσχατιὰς τοῦ ἄστεος ἐνέπρησαν καὶ τὰ τείχη κατέσκαψαν.", "st": "6.9.4"}, {"sp": "N", "t": "Ἑάλω μὲν οὕτως Ἱεροσόλυμα ἔτει δευτέρῳ τῆς Οὐεσπασιανοῦ ἡγεμονίας Γορπιαίου μηνὸς ὀγδόῃ, ἁλοῦσα δὲ καὶ πρότερον πεντάκις τοῦτο δεύτερον ἠρημώθη. Ἀσωχαῖος μὲν γὰρ ὁ τῶν Αἰγυπτίων βασιλεὺς καὶ μετ’ αὐτὸν Ἀντίοχος, ἔπειτα Πομπήιος καὶ ἐπὶ τούτοις σὺν Ἡρώδῃ Σόσσιος ἑλόντες ἐτήρησαν τὴν πόλιν. πρὸ δὲ τούτων ὁ τῶν Βαβυλωνίων βασιλεὺς κρατήσας ἠρήμωσεν αὐτὴν μετὰ ἔτη τῆς κτίσεως χίλια τετρακόσια ἑξηκονταοκτὼ μῆνας ἕξ. ὁ δὲ πρῶτος κτίσας ἦν Χαναναίων δυνάστης ὁ τῇ πατρίῳ γλώσσῃ κληθεὶς βασιλεὺς δίκαιος· ἦν γὰρ δὴ τοιοῦτος. διὰ τοῦτο ἱεράσατό τε τῷ θεῷ πρῶτος καὶ τὸ ἱερὸν πρῶτος δειμάμενος Ἱεροσόλυμα τὴν πόλιν προσηγόρευσεν Σόλυμα καλουμένην πρότερον. τὸν μὲν δὴ τῶν Χαναναίων λαὸν ἐκβαλὼν ὁ τῶν Ἰουδαίων βασιλεὺς Δαυίδης κατοικίζει τὸν ἴδιον, καὶ μετὰ τοῦτον ἔτεσι τετρακοσίοις ἑβδομήκοντα καὶ ἑπτὰ μησὶν ἓξ ὑπὸ Βαβυλωνίων κατασκάπτεται. ἀπὸ δὲ Δαυίδου τοῦ βασιλέως, ὃς πρῶτος αὐτῆς ἐβασίλευσεν Ἰουδαῖος, μέχρι τῆς ὑπὸ Τίτου γενομένης κατασκαφῆς ἔτη χίλια καὶ ἑκατὸν ἑβδομήκοντα καὶ ἐννέα. ἀπὸ δὲ τῆς πρώτης κτίσεως ἔτη μέχρι τῆς ἐσχάτης ἁλώσεως δισχίλια ἑκατὸν ἑβδομήκοντα καὶ ἑπτά. ἀλλὰ γὰρ οὔθ’ ἡ ἀρχαιότης οὔθ’ ὁ πλοῦτος ὁ βαθὺς οὔτε τὸ διαπεφοιτηκὸς ὅλης τῆς οἰκουμένης ἔθνος οὔθ’ ἡ μεγάλη δόξα τῆς θρησκείας ἤρκεσέ τι πρὸς ἀπώλειαν αὐτῇ. τοιοῦτο μὲν δὴ τὸ τέλος τῆς Ἱεροσολύμων πολιορκίας.", "st": "6.10.1"}, {"sp": "HDR", "t": "Βιβλίον Ζʹ", "st": "7"}, {"sp": "N", "t": "Ἐπεὶ δ’ οὔτε φονεύειν οὔτε διαρπάζειν εἶχεν ἡ στρατιὰ πάντων τοῖς θυμοῖς ἐπιλειπόντων, οὐ γὰρ δή γε φειδοῖ τινος ἔμελλον ἀφέξεσθαι δρᾶν ἔχοντες, κελεύει Καῖσαρ ἤδη τήν τε πόλιν ἅπασαν καὶ τὸν νεὼν κατασκάπτειν, πύργους μὲν ὅσοι τῶν ἄλλων ὑπερανειστήκεσαν καταλιπόντας, Φασάηλον Ἱππικὸν Μαριάμμην, τεῖχος δ’ ὅσον ἦν ἐξ ἑσπέρας τὴν πόλιν περιέχον, τοῦτο μέν, ὅπως εἴη τοῖς ὑπολειφθησομένοις φρουροῖς στρατόπεδον, τοὺς πύργους δέ, ἵνα τοῖς ἔπειτα σημαίνωσιν οἵας πόλεως καὶ τίνα τρόπον ὀχυρᾶς οὕτως ἐκράτησεν ἡ Ῥωμαίων ἀνδραγαθία. τὸν δ’ ἄλλον ἅπαντα τῆς πόλεως περίβολον οὕτως ἐξωμάλισαν οἱ κατασκάπτοντες, ὡς μηδεπώποτ’ οἰκηθῆναι πίστιν ἂν ἔτι παρασχεῖν τοῖς προσελθοῦσι. τοῦτο μὲν οὖν τὸ τέλος ἐκ τῆς τῶν νεωτερισάντων ἀνοίας Ἱεροσολύμοις ἐγένετο, λαμπρᾷ τε πόλει καὶ παρὰ πᾶσιν ἀνθρώποις διαβοηθείσῃ.", "st": "7.1.1"}, {"sp": "N", "t": "Καῖσαρ δὲ φυλακὴν μὲν αὐτόθι καταλιπεῖν ἔγνω τῶν ταγμάτων τὸ δέκατον καί τινας ἴλας ἱππέων καὶ λόχους πεζῶν, πάντα δ’ ἤδη τὰ τοῦ πολέμου διῳκηκὼς ἐπαινέσαι τε σύμπασαν ἐπόθει τὴν στρατιὰν ἐπὶ τοῖς κατορθώμασιν καὶ τὰ προσήκοντα γέρα τοῖς ἀριστεύσασιν ἀποδοῦναι. ποιηθέντος οὖν αὐτῷ μεγάλου κατὰ μέσην τὴν πρότερον παρεμβολὴν βήματος, καταστὰς ἐπὶ τοῦτο μετὰ τῶν ἡγεμόνων εἰς ἐπήκοον ἁπάσῃ τῇ στρατιᾷ ἔλεγε χάριν μὲν πολλὴν ἔχειν αὐτοῖς τῆς πρὸς αὐτὸν εὐνοίας, ᾗ χρώμενοι διατελοῦσιν· ἐπῄνει δὲ τῆς ἐν παντὶ πολέμῳ πειθαρχίας, ἣν ἐν πολλοῖς καὶ μεγάλοις κινδύνοις ἅμα τῇ κατὰ σφᾶς ἀνδρείᾳ παρέσχον, τῇ μὲν πατρίδι καὶ δι’ αὐτῶν τὸ κράτος αὔξοντες, φανερὸν δὲ πᾶσιν ἀνθρώποις καθιστάντες, ὅτι μήτε πλῆθος πολεμίων μήτε χωρίων ὀχυρότητες ἢ μεγέθη πόλεων ἢ τῶν ἀντιτεταγμένων ἀλόγιστοι τόλμαι καὶ θηριώδεις ἀγριότητες δύναιντ’ ἄν ποτε τὴν Ῥωμαίων ἀρετὴν διαφυγεῖν, κἂν εἰς πολλά τινες τὴν τύχην εὕρωνται συναγωνιζομένην. καλὸν μὲν οὖν ἔφη καὶ τῷ πολέμῳ τέλος αὐτοὺς ἐπιθεῖναι πολλῷ χρόνῳ γενομένῳ· μηδὲ γὰρ εὔξασθαί τι τούτων ἄμεινον, ὅτ’ εἰς αὐτὸν καθίσταντο· τούτου δὲ κάλλιον αὐτοῖς καὶ λαμπρότερον ὑπάρχειν, ὅτι τοὺς ἡγησομένους καὶ τῆς Ῥωμαίων ἀρχῆς ἐπιτροπεύσοντας αὐτῶν χειροτονησάντων εἴς τε τὴν πατρίδα προπεμψάντων ἄσμενοι πάντες προσίενται καὶ τοῖς ὑπ’ αὐτῶν ἐγνωσμένοις ἐμμένουσι, χάριν ἔχοντες τοῖς ἑλομένοις. θαυμάζειν μὲν οὖν ἔφη πάντας καὶ ἀγαπᾶν, εἰδὼς ὅτι τοῦ δυνατοῦ τὴν προθυμίαν οὐδεὶς ἔσχε βραδυτέραν· τοῖς μέντοι διαπρεπέστερον ἀγωνισαμένοις ὑπὸ ῥώμης πλείονος καὶ τὸν μὲν αὑτῶν βίον ἀριστείαις κεκοσμηκόσι, τὴν δ’ αὐτοῦ στρατείαν ἐπιφανεστέραν διὰ τῶν κατορθωμάτων πεποιηκόσιν ἔφη τὰ γέρα καὶ τὰς τιμὰς εὐθὺς ἀποδώσειν, καὶ μηδένα τῶν πλέον πονεῖν ἑτέρου θελησάντων τῆς δικαίας ἀμοιβῆς ἁμαρτήσεσθαι. πλείστην γὰρ αὐτῷ τούτου γενήσεσθαι τὴν ἐπιμέλειαν, ἐπεὶ καὶ μᾶλλον ἐθέλειν τὰς ἀρετὰς τιμᾶν τῶν συστρατευομένων ἢ κολάζειν τοὺς ἁμαρτάνοντας.", "st": "7.1.2"}, {"sp": "N", "t": "Εὐθέως οὖν ἐκέλευσεν ἀναγινώσκειν τοῖς ἐπὶ τοῦτο τεταγμένοις ὅσοι τι λαμπρὸν ἦσαν ἐν τῷ πολέμῳ κατωρθωκότες. καὶ κατ’ ὄνομα καλῶν ἐπῄνει τε παριόντας ὡς ἂν ὑπερευφραινόμενός τις ἐπ’ οἰκείοις κατορθώμασι καὶ στεφάνους ἐπετίθει χρυσοῦς, περιαυχένιά τε χρυσᾶ καὶ δόρατα μικρὰ χρυσᾶ καὶ σημαίας ἐδίδου πεποιημένας ἐξ ἀργύρου, καὶ τὴν ἑκάστου τάξιν ἤλλαττεν εἰς τὸ κρεῖττον, οὐ μὴν ἀλλὰ κἀκ τῶν λαφύρων ἄργυρον καὶ χρυσὸν ἐσθῆτάς τε καὶ τῆς ἄλλης αὐτοῖς λείας δαψιλῶς ἀπένειμε. πάντων δὲ τετιμημένων ὅπως αὐτὸς ἕκαστον ἠξίωσε, τῇ συμπάσῃ στρατιᾷ ποιησάμενος εὐχὰς ἐπὶ πολλῇ κατέβαινεν εὐφημίᾳ τρέπεταί τε πρὸς θυσίας ἐπινικίους, καὶ πολλοῦ βοῶν πλήθους τοῖς βωμοῖς παρεστηκότος καταθύσας πάντας τῇ στρατιᾷ διαδίδωσιν εἰς εὐωχίαν. αὐτὸς δὲ τοῖς ἐν τέλει τρεῖς ἡμέρας συνεορτάσας τὴν μὲν ἄλλην στρατιὰν διαφίησιν ᾗ καλῶς εἶχεν ἑκάστους ἀπιέναι, τῷ δεκάτῳ δὲ τάγματι τὴν τῶν Ἱεροσολύμων ἐπέτρεψε φυλακὴν οὐκέτι αὐτοὺς ἐπὶ τὸν Εὐφράτην ἀποστείλας, ἔνθα πρότερον ἦσαν. μεμνημένος δὲ τοῦ δωδεκάτου τάγματος, ὅτι Κεστίου στρατηγοῦντος ἐνέδωκαν τοῖς Ἰουδαίοις, τῆς μὲν Συρίας αὐτὸ παντάπασιν ἐξήλασεν, ἦν γὰρ τὸ παλαιὸν ἐν Ῥαφανέαις, εἰς δὲ τὴν Μελιτηνὴν καλουμένην ἀπέστειλε· παρὰ τὸν Εὐφράτην ἐν μεθορίοις τῆς Ἀρμενίας ἐστὶ καὶ Καππαδοκίας. δύο δὲ ἠξίωσεν αὐτῷ μέχρι τῆς εἰς Αἴγυπτον ἀφίξεως, τὸ πέμπτον καὶ τὸ πεντεκαιδέκατον, παραμένειν. καὶ καταβὰς ἅμα τῷ στρατῷ πρὸς τὴν ἐπὶ τῇ θαλάττῃ Καισάρειαν εἰς ταύτην τό τε πλῆθος τῶν λαφύρων ἀπέθετο καὶ τοὺς αἰχμαλώτους προσέταξεν ἐν αὐτῇ φυλάττεσθαι· τὸν γὰρ εἰς τὴν Ἰταλίαν πλοῦν ὁ χειμὼν ἐκώλυε.", "st": "7.1.3"}, {"sp": "N", "t": "Καθ’ ὃ δὲ καιροῦ Τίτος Καῖσαρ τοῖς Ἱεροσολύμοις πολιορκῶν προσήδρευεν, ἐν τούτῳ νεὼς φορτίδος Οὐεσπασιανὸς ἐπιβὰς ἀπὸ τῆς Ἀλεξανδρείας εἰς Ῥόδον διέβαινεν. ἐντεῦθεν δὲ πλέων ἐπὶ τριήρων καὶ πάσας τὰς ἐν τῷ παράπλῳ πόλεις ἐπελθὼν εὐκταίως αὐτὸν δεχομένας, ἀπὸ τῆς Ἰωνίας εἰς τὴν Ἑλλάδα περαιοῦται κἀκεῖθεν ἀπὸ Κερκύρας ἐπ’ ἄκραν Ἰαπυγίαν, ὅθεν ἤδη κατὰ γῆν ἐποιεῖτο τὴν πορείαν. Τίτος δὲ ἀπὸ τῆς ἐπὶ θαλάττῃ Καισαρείας ἀναζεύξας εἰς τὴν Φιλίππου καλουμένην Καισάρειαν ἧκε συχνόν τ’ ἐν αὐτῇ χρόνον ἐπέμεινεν παντοίας θεωρίας ἐπιτελῶν καὶ πολλοὶ τῶν αἰχμαλώτων ἐνταῦθα διεφθάρησαν, οἱ μὲν θηρίοις παραβληθέντες, οἱ δὲ κατὰ πληθὺν ἀλλήλοις ἀναγκαζόμενοι χρήσασθαι πολεμίοις. ἐνταῦθα καὶ τὴν Σίμωνος τοῦ Γιώρα σύλληψιν ἐπύθετο τοῦτον γενομένην τὸν τρόπον.", "st": "7.2.1"}, {"sp": "N", "t": "Σίμων οὗτος Ἱεροσολύμων πολιορκουμένων ἐπὶ τῆς ἄνω πόλεως ὤν, ἐπεὶ τῶν τειχῶν ἐντὸς ἡ Ῥωμαίων στρατιὰ γενομένη πᾶσαν ἐπόρθει τὴν πόλιν, τότε τῶν φίλων τοὺς πιστοτάτους παραλαβὼν καὶ σὺν αὐτοῖς λιθοτόμους τε καὶ τὸν πρὸς τὴν ἐργασίαν ἐπιτήδειον τούτοις σίδηρον τροφήν τε διαρκεῖν εἰς πολλὰς ἡμέρας δυναμένην, σὺν ἐκείνοις ἅπασι καθίησιν αὑτὸν εἴς τινα τῶν ἀφανῶν ὑπονόμων. καὶ μέχρι μὲν ἦν τὸ παλαιὸν ὄρυγμα, προυχώρουν δι’ αὐτοῦ, τῆς στερεᾶς δὲ γῆς ὑπαντώσης ταύτην ὑπενόμευον, ἐλπίδι τοῦ πορρωτέρω δυνήσεσθαι προελθόντες ἐν ἀσφαλεῖ ποιησάμενοι τὴν ἀνάδυσιν ἀποσώζεσθαι. ψευδῆ δὲ τὴν ἐλπίδα διήλεγχεν ἡ πεῖρα τῶν ἔργων· ὀλίγον τε γὰρ μόλις προύβαινον οἱ μεταλλεύοντες, ἥ τε τροφὴ καίτοι ταμιευομένοις ἔμελλεν ἐπιλείψειν. τότε δὴ τοίνυν ὡς δι’ ἐκπλήξεως ἀπατῆσαι τοὺς Ῥωμαίους δυνησόμενος λευκοὺς ἐνδιδύσκει χιτωνίσκους καὶ πορφυρᾶν ἐμπερονησάμενος χλανίδα κατ’ αὐτὸν ἐκεῖνον τὸν τόπον, ἐν ᾧ τὸ ἱερὸν ἦν πρόσθεν, ἐκ τῆς γῆς ἀνεφάνη. τὸ μὲν οὖν πρῶτον τοῖς ἰδοῦσι θάμβος προσέπεσε καὶ κατὰ χώραν ἔμενον, ἔπειτα δ’ ἐγγυτέρω προσελθόντες ὅστις ἐστὶν ἤροντο. καὶ τοῦτο μὲν οὐκ ἐδήλου Σίμων αὐτοῖς, καλεῖν δὲ τὸν ἡγεμόνα προσέταττεν. καὶ ταχέως πρὸς αὐτὸν δραμόντων ἧκεν Τερέντιος Ῥοῦφος· οὗτος γὰρ ἄρχων τῆς στρατιᾶς κατελέλειπτο· πυθόμενός τε παρ’ αὐτοῦ πᾶσαν τὴν ἀλήθειαν τὸν μὲν ἐφύλαττε δεδεμένον, Καίσαρι δ’ ὅπως εἴη συνειλημμένος ἐδήλου. Σίμωνα μὲν οὖν εἰς δίκην τῆς κατὰ τῶν πολιτῶν ὠμότητος, ὧν πικρῶς αὐτὸς ἐτυράννησεν, ὑπὸ τοῖς μάλιστα μισοῦσι πολεμίοις ἐποίησεν ὁ θεός, οὐ βίᾳ γενόμενον αὐτοῖς ὑποχείριον, ἀλλ’ αὑτὸν ἑκουσίως εἰς τὴν τιμωρίαν παραβαλόντα, δι’ ὃ πολλοὺς αὐτὸς ὠμῶς ἀπέκτεινε ψευδεῖς αἰτίας ἐπιφέρων τῆς πρὸς Ῥωμαίους μεταβολῆς. οὐδὲ γὰρ διαφεύγει πονηρία θεοῦ χόλον, οὐδὲ ἀσθενὴς ἡ δίκη, χρόνῳ δὲ μέτεισι τοὺς εἰς αὐτὴν παρανομήσαντας καὶ χείρω τὴν τιμωρίαν ἐπιφέρει τοῖς πονηροῖς, ὅτι καὶ προσεδόκησαν αὐτῆς ἀπηλλάχθαι μὴ παραυτίκα κολασθέντες. ἔγνω τοῦτο καὶ Σίμων εἰς τὰς Ῥωμαίων ὀργὰς ἐμπεσών. ἡ δ’ ἐκείνου γῆθεν ἄνοδος πολὺ καὶ τῶν ἄλλων στασιαστῶν πλῆθος ὑπ’ ἐκείνας τὰς ἡμέρας ἐν τοῖς ὑπονόμοις φωραθῆναι παρεσκεύασε. Καίσαρι δὲ εἰς τὴν παράλιον ἐπανελθόντι Καισάρειαν Σίμων προσήχθη δεδεμένος· κἀκεῖνον μὲν εἰς ὃν ἐπιτελεῖν ἐν Ῥώμῃ παρεσκευάζετο θρίαμβον προσέταξε φυλάττειν.", "st": "7.2.2"}, {"sp": "N", "t": "Διατρίβων δ’ αὐτόθι τὴν τἀδελφοῦ γενέθλιον ἡμέραν ἐπιφανῶς ἑώρταζε, πολὺ καὶ τῆς τῶν Ἰουδαίων κολάσεως εἰς τὴν ἐκείνου τιμὴν ἀνατιθείς. ὁ γὰρ ἀριθμὸς τῶν ἔν τε ταῖς πρὸς τὰ θηρία μάχαις καὶ τῶν καταπιμπραμένων ἔν τε ταῖς ἀλληλοκτονίαις ἀναιρουμένων πεντακοσίους ἐπὶ τοῖς δισχιλίοις ὑπερέβαλε. πάντα μέντοι Ῥωμαίοις ἐδόκει ταῦτα μυρίοις αὐτῶν ἀπολλυμένων τρόποις ἐλάττων κόλασις εἶναι. μετὰ τοῦτο Καῖσαρ εἰς Βηρυτὸν ἧκεν· ἡ δ’ ἐστὶν ἐν τῇ Φοινίκῃ πόλις Ῥωμαίων ἄποικος· κἀνταῦθα χρονιωτέραν ἐποιήσατο τὴν ἐπιδημίαν πλείονι χρώμενος τῇ λαμπρότητι περὶ τὴν τοῦ πατρὸς ἡμέραν γενέθλιον ἔν τε ταῖς τῶν θεωριῶν πολυτελείαις καὶ κατὰ τὴν ἄλλην ἐπίνοιαν τῶν ἄλλων ἀναλωμάτων. τὸ δὲ τῶν αἰχμαλώτων πλῆθος τὸν αὐτὸν τρόπον ὡς πρόσθεν ἀπώλλυτο.", "st": "7.3.1"}, {"sp": "N", "t": "Γενέσθαι δὲ συνέβη περὶ τὸν καιρὸν τοῦτον καὶ τοῖς ἐν Ἀντιοχείᾳ τῶν Ἰουδαίων ὑπολειπομένοις ἐγκλήματα καὶ κίνδυνον ὀλέθρου τῆς πόλεως ἐπ’ αὐτοὺς τῶν Ἀντιοχέων ἐκταραχθείσης διά τε τὰς ἐν τῷ παρόντι διαβολὰς αὐτοῖς ἐπενεχθείσας καὶ διὰ τὰ ὑπηργμένα χρόνῳ πρόσθεν οὐ πολλῷ, περὶ ὧν ἀναγκαῖόν ἐστι διὰ συντόμων προειπεῖν, ἵνα καὶ τῶν μετὰ ταῦτα πραχθέντων εὐπαρακολούθητον ποιήσωμαι τὴν διήγησιν.", "st": "7.3.2"}, {"sp": "N", "t": "Τὸ γὰρ Ἰουδαίων γένος πολὺ μὲν κατὰ πᾶσαν τὴν οἰκουμένην παρέσπαρται τοῖς ἐπιχωρίοις, πλεῖστον δὲ τῇ Συρίᾳ κατὰ τὴν γειτνίασιν ἀναμεμιγμένον ἐξαιρέτως ἐπὶ τῆς Ἀντιοχείας ἦν πολὺ διὰ τὸ τῆς πόλεως μέγεθος· μάλιστα δ’ αὐτοῖς ἀδεᾶ τὴν ἐκεῖ κατοίκησιν οἱ μετ’ Ἀντίοχον βασιλεῖς παρέσχον· Ἀντίοχος μὲν γὰρ ὁ κληθεὶς Ἐπιφανὴς Ἱεροσόλυμα πορθήσας τὸν νεὼν ἐσύλησεν, οἱ δὲ μετ’ αὐτὸν τὴν βασιλείαν παραλαβόντες τῶν ἀναθημάτων ὅσα χαλκᾶ πεποίητο πάντα τοῖς ἐπ’ Ἀντιοχείας Ἰουδαίοις ἀπέδοσαν εἰς τὴν συναγωγὴν αὐτῶν ἀναθέντες, καὶ συνεχώρησαν αὐτοῖς ἐξ ἴσου τῆς πόλεως τοῖς Ἕλλησι μετέχειν. τὸν αὐτὸν δὲ τρόπον καὶ τῶν μετὰ ταῦτα βασιλέων αὐτοῖς προσφερομένων εἴς τε πλῆθος ἐπέδωκαν καὶ τῇ κατασκευῇ καὶ τῇ πολυτελείᾳ τῶν ἀναθημάτων τὸ ἱερὸν ἐξελάμπρυναν, ἀεί τε προσαγόμενοι ταῖς θρησκείαις πολὺ πλῆθος Ἑλλήνων, κἀκείνους τρόπῳ τινὶ μοῖραν αὐτῶν πεποίηντο. καθ’ ὃν δὲ καιρὸν ὁ πόλεμος ἀνακεκήρυκτο, νεωστὶ δ’ εἰς τὴν Συρίαν Οὐεσπασιανὸς καταπεπλεύκει, τὸ δὲ κατὰ τῶν Ἰουδαίων παρὰ πᾶσιν ἤκμαζε μῖσος, τότε δή τις Ἀντίοχος εἷς ἐξ αὐτῶν τὰ μάλιστα διὰ τὸν πατέρα τιμώμενος, ἦν γὰρ ἄρχων τῶν ἐπ’ Ἀντιοχείας Ἰουδαίων, τοῦ δήμου τῶν Ἀντιοχέων ἐκκλησιάζοντος εἰς τὸ θέατρον παρελθὼν τόν τε πατέρα τὸν αὐτοῦ καὶ τοὺς ἄλλους ἐνεδείκνυτο κατηγορῶν, ὅτι νυκτὶ μιᾷ καταπρῆσαι τὴν πόλιν ἅπασαν διεγνώκεισαν, καὶ παρεδίδου ξένους Ἰουδαίους τινὰς ὡς κεκοινωνηκότας τῶν βεβουλευμένων. ταῦτα ἀκούων ὁ δῆμος τὴν ὀργὴν οὐ κατεῖχεν, ἀλλ’ ἐπὶ μὲν τοὺς παραδοθέντας πῦρ εὐθὺς ἐκέλευον κομίζειν, καὶ παραχρῆμα πάντες ἐπὶ τοῦ θεάτρου κατεφλέγησαν, ἐπὶ δὲ τὸ πλῆθος ὥρμητο τῶν Ἰουδαίων ἐν τῷ τάχιον ἐκείνους τιμωρίᾳ περιβαλεῖν τὴν αὐτῶν πατρίδα σώζειν νομίζοντες. Ἀντίοχος δὲ προσεπέτεινε τὴν ὀργήν, περὶ μὲν τῆς αὐτοῦ μεταβολῆς καὶ τοῦ μεμισηκέναι τὰ τῶν Ἰουδαίων ἔθη τεκμήριον ἐμπαρέχειν οἰόμενος τὸ ἐπιθύειν ὥσπερ νόμος ἐστὶ τοῖς Ἕλλησιν· ἐκέλευε δὲ καὶ τοὺς ἄλλους τὸ αὐτὸ ποιεῖν ἀναγκάζειν· φανεροὺς γὰρ γενήσεσθαι τῷ μὴ θέλειν τοὺς ἐπιβεβουλευκότας. χρωμένων δὲ τῇ πείρᾳ τῶν Ἀντιοχέων ὀλίγοι μὲν ὑπέμειναν, οἱ δὲ μὴ βουληθέντες ἀνῃρέθησαν. Ἀντίοχος δὲ στρατιώτας παρὰ τοῦ Ῥωμαίων ἡγεμόνος λαβὼν χαλεπὸς ἐφειστήκει τοῖς αὐτοῦ πολίταις, ἀργεῖν τὴν ἑβδόμην οὐκ ἐπιτρέπων, ἀλλὰ βιαζόμενος πάντα πράττειν ὅσα δὴ καὶ ταῖς ἄλλαις ἡμέραις. οὕτως τε τὴν ἀνάγκην ἰσχυρὰν ἐποίησεν, ὡς μὴ μόνον ἐπ’ Ἀντιοχείας καταλυθῆναι τὴν ἑβδομάδα ἀργὴν ἡμέραν, ἀλλ’ ἐκεῖθεν ἀρξαμένου τοῦ πράγματος κἀν ταῖς ἄλλαις πόλεσιν ὁμοίως βραχύν τινα χρόνον.", "st": "7.3.3"}, {"sp": "N", "t": "Τοιούτων δὴ τοῖς ἐπ’ Ἀντιοχείας Ἰουδαίοις τῶν κατ’ ἐκεῖνον τὸν καιρὸν κακῶν γεγενημένων δευτέρα πάλιν συμφορὰ προσέπεσε, περὶ ἧς ἐπιχειρήσαντες ἀφηγεῖσθαι καὶ ταῦτα διεξήλθομεν. ἐπεὶ γὰρ συνέβη καταπρησθῆναι τὴν τετράγωνον ἀγορὰν ἀρχεῖά τε καὶ γραμματοφυλάκιον καὶ τὰς βασιλικάς, μόλις τε τὸ πῦρ ἐκωλύθη μετὰ πολλῆς βίας ἐπὶ πᾶσαν τὴν πόλιν περιφερόμενον, ταύτην Ἀντίοχος τὴν πρᾶξιν Ἰουδαίων κατηγόρει. καὶ τοὺς Ἀντιοχεῖς, εἰ καὶ μὴ πρότερον εἶχον πρὸς αὐτοὺς ἀπεχθῶς, τάχιστα τῇ διαβολῇ παρὰ τὴν ἐκ τοῦ συμβεβηκότος ταραχὴν ὑπαχθέντας πολὺ μᾶλλον ἐκ τῶν προϋπηργμένων τοῖς ὑπ’ αὐτοῦ λεγομένοις πιστεύειν παρεσκεύασεν, ὡς μόνον οὐκ αὐτοὺς τὸ πῦρ ἐνιέμενον ὑπὸ τῶν Ἰουδαίων ἑωρακότας, καὶ καθάπερ ἐμμανεῖς γεγενημένοι μετὰ πολλοῦ τινος οἴστρου πάντες ἐπὶ τοὺς διαβεβλημένους ὥρμηντο. μόλις δ’ αὐτῶν ἐδυνήθη τὰς ὁρμὰς ἐπισχεῖν Ναῖος Κολλήγας τις πρεσβευτής, ἀξιῶν ἐπιτρέψαι Καίσαρι δηλωθῆναι περὶ τῶν γεγονότων· τὸν γὰρ ἡγεμονεύοντα τῆς Συρίας Καισέννιον Παῖτον ἤδη μὲν Οὐεσπασιανὸς ἐξαπεστάλκει, συνέβαινε δὲ παρεῖναι μηδέπω. ποιούμενος δὲ ἐπιμελῆ τὴν ἀναζήτησιν ὁ Κολλήγας ἐξεῦρε τὴν ἀλήθειαν, καὶ τῶν μὲν τὴν αἰτίαν ὑπ’ Ἀντιόχου λαβόντων Ἰουδαίων οὐδεὶς οὐδ’ ἐκοινώνησεν, ἅπαν δὲ τοὖργον ἔπραξαν ἄνθρωποί τινες ἀλιτήριοι διὰ χρεῶν ἀνάγκας νομίζοντες, εἰ τὴν ἀγορὰν καὶ τὰ δημόσια καταπρήσειαν γράμματα, τῆς ἀπαιτήσεως ἀπαλλαγὴν ἕξειν. Ἰουδαῖοι μὲν οὖν ἐπὶ μετεώροις ταῖς αἰτίαις τὸ μέλλον ἔτι καραδοκοῦντες ἐν φόβοις χαλεποῖς ἀπεσάλευον.", "st": "7.3.4"}, {"sp": "N", "t": "Τίτος δὲ Καῖσαρ τῆς περὶ τοῦ πατρὸς ἀγγελίας αὐτῷ κομισθείσης, ὅτι πάσαις μὲν ποθεινὸς ταῖς κατὰ τὴν Ἰταλίαν πόλεσιν ἐπῆλθεν, μάλιστα δ’ ἡ Ῥώμη μετὰ πολλῆς αὐτὸν ἐδέξατο προθυμίας καὶ λαμπρότητος, εἰς πολλὴν χαρὰν καὶ θυμηδίαν ἐτράπετο, τῶν περὶ αὐτοῦ φροντίδων ὡς ἥδιστον ἦν ἀπηλλαγμένος. Οὐεσπασιανὸν γὰρ ἔτι μὲν καὶ μακρὰν ἀπόντα πάντες οἱ κατὰ τὴν Ἰταλίαν ἄνθρωποι ταῖς γνώμαις περιεῖπον ὡς ἥκοντα, τὴν προσδοκίαν ἐκ τοῦ πάνυ θέλειν ἄφιξιν αὐτοῦ νομίζοντες καὶ πάσης ἀνάγκης ἐλευθέραν τὴν πρὸς αὐτὸν ἔχοντες εὔνοιαν. τῇ τε γὰρ βουλῇ κατὰ μνήμην τῶν γεγενημένων ἐν ταῖς τῶν ἡγεμόνων μεταβολαῖς συμφορῶν εὐκταῖον ἦν ἀπολαβεῖν ἡγεμόνα γήρως σεμνότητι καὶ πράξεων ἀκμῇ πολεμικῶν κεκοσμημένον, ᾧ τὴν ὑπεροχὴν πρὸς μόνην ἠπίσταντο τὴν τῶν ἀρχομένων σωτηρίαν ἐσομένην. καὶ μὴν ὁ δῆμος ὑπὸ τῶν ἐμφυλίων κακῶν τετρυχωμένος ἔτι μᾶλλον ἐλθεῖν αὐτὸν ἔσπευδε, τότε δὴ βεβαίως μὲν ἀπαλλαγήσεσθαι τῶν συμφορῶν ὑπολαμβάνων, ἀπολήψεσθαι δὲ τὴν ἄδειαν μετὰ τῆς εὐετηρίας πεπιστευκώς. ἐξαιρέτως δὲ τὸ στρατιωτικὸν εἰς αὐτὸν ἀφεώρα· μάλιστα γὰρ οὗτοι τῶν κατωρθωμένων αὐτῷ πολέμων ἐγίνωσκον τὸ μέγεθος, τῆς ἀπειρίας δὲ τῶν ἄλλων ἡγεμόνων καὶ τῆς ἀνανδρίας πεπειραμένοι πολλῆς μὲν αἰσχύνης αὐτοὺς ἐπεθύμουν ἀπηλλάχθαι, τὸν μόνον δὲ καὶ σώζειν αὐτοὺς καὶ κοσμεῖν δυνάμενον ἀπολαβεῖν ηὔχοντο. τοιαύτης δὲ εὐνοίας ἐξ ἁπάντων ὑπαρχούσης τοῖς μὲν κατὰ τὰς ἀξιώσεις προύχουσι τῶν ἀνδρῶν οὐκέτ’ ἀνεκτὸν ἦν ἀναμένειν, ἀλλὰ πορρωτάτω τῆς Ῥώμης αὐτῷ προεντυχεῖν ἔσπευδον. οὐ μὴν οὐδὲ τῶν ἄλλων τις ἠνείχετο τῆς ἐντεύξεως τὴν ἀναβολήν, ἀλλ’ οὕτως ἐξεχέοντο πάντες ἀθρόοι καὶ πᾶσιν εὐπορώτερον καὶ ῥᾷον ἐδόκει τοῦ μένειν τὸ ἀπιέναι, ὡς καὶ τὴν πόλιν αὐτὴν τότε πρῶτον ἐν ἑαυτῇ λαβεῖν ὀλιγανθρωπίας αἴσθησιν ἰδίαν· ἦσαν γὰρ ἐλάττους τῶν ἀπιόντων οἱ μένοντες. ἐπεὶ δὲ προσιὼν ἠγγέλλετο, καὶ τὴν ἡμερότητα τῆς ἐντεύξεως αὐτοῦ τὴν πρὸς ἑκάστους ἐδήλουν οἱ προσελθόντες, ἅπαν ἤδη τὸ λοιπὸν πλῆθος ἅμα γυναιξὶ καὶ παισὶν ἐπὶ ταῖς παρόδοις ἐξεδέχετο, καὶ καθ’ οὓς γένοιτο παριὼν οὗτοι πρὸς τὴν ἡδονὴν τῆς θέας καὶ τὸ μειλίχιον αὐτοῦ τῆς ὄψεως παντοίας ἠφίεσαν φωνάς, τὸν εὐεργέτην καὶ σωτῆρα καὶ μόνον ἄξιον ἡγεμόνα τῆς Ῥώμης ἀνακαλοῦντες· ἅπασα δ’ ἡ πόλις ὡς νεὼς ἦν στεφανωμάτων καὶ θυμιαμάτων ἀνάπλεως. μόλις δ’ ὑπὸ πλήθους τῶν περὶ αὐτὸν ἱσταμένων δυνηθεὶς εἰς τὸ βασίλειον ἐλθεῖν αὐτὸς μὲν τοῖς ἔνδον θεοῖς θυσίας τῆς ἀφίξεως χαριστηρίους ἐπετέλει, προτρέπεται δὲ τὰ πλήθη πρὸς εὐωχίαν καὶ κατὰ φυλὰς καὶ γένη καὶ γειτονίας ποιούμενοι τὰς ἑστιάσεις ηὔχοντο τῷ θεῷ σπένδοντες αὐτόν τ’ ἐπὶ πλεῖστον χρόνον Οὐεσπασιανὸν ἐπιμεῖναι τῇ Ῥωμαίων ἡγεμονίᾳ, καὶ παισὶν αὐτοῦ καὶ τοῖς ἐξ ἐκείνων ἀεὶ γινομένοις φυλαχθῆναι τὸ κράτος ἀνανταγώνιστον. ἡ μὲν οὖν Ῥωμαίων πόλις οὕτως Οὐεσπασιανὸν ἐκδεξαμένη προθύμως εὐθὺς εἰς πολλὴν εὐδαιμονίαν ἐπεδίδου.", "st": "7.4.1"}, {"sp": "N", "t": "Πρὸ δὲ τούτων τῶν χρόνων, ἐν οἷς Οὐεσπασιανὸς μὲν περὶ Ἀλεξάνδρειαν ἦν, Τίτος δὲ τῇ τῶν Ἱεροσολύμων προσήδρευε πολιορκίᾳ, πολὺ μέρος Γερμανῶν ἐκινήθη πρὸς ἀπόστασιν, οἷς καὶ Γαλατῶν οἱ πλεῖστοι συμφρονήσαντες κοινῇ μεγάλας ἐλπίδας αὐτοῖς συνέθεσαν ὡς καὶ τῆς Ῥωμαίων ἀπαλλαξόμενοι δεσποτείας. ἐπῆρε δὲ τοὺς Γερμανοὺς ἅψασθαι τῆς ἀποστάσεως καὶ τὸν πόλεμον ἐξενεγκεῖν πρώτη μὲν ἡ φύσις οὖσα λογισμῶν ἔρημος ἀγαθῶν καὶ μετὰ μικρᾶς ἐλπίδος ἑτοίμως ῥιψοκίνδυνος· ἔπειτα δὲ καὶ μῖσος τὸ πρὸς τοὺς κρατοῦντας, ἐπεὶ μόνοις ἴσασι Ῥωμαίοις τὸ γένος αὐτῶν δουλεύειν βεβιασμένον. οὐ μὴν ἀλλὰ μάλιστά γε πάντων ὁ καιρὸς αὐτοῖς θάρσος ἐνεποίησεν· ὁρῶντες γὰρ τὴν Ῥωμαίων ἀρχὴν ταῖς συνεχέσι τῶν αὐτοκρατόρων ἀλλαγαῖς ἐν ἑαυτῇ τεταραγμένην, πᾶν τε μέρος τῆς ὑπ’ αὐτοῖς οἰκουμένης πυνθανόμενοι μετέωρον εἶναι καὶ κραδαίνεσθαι, τοῦτον σφίσιν αὐτοῖς ἄριστον ὑπὸ τῆς ἐκείνων κακοπραγίας καὶ στάσεως καιρὸν ᾠήθησαν παραδεδόσθαι. ἐνῆγον δὲ τὸ βούλευμα καὶ ταύταις αὐτοὺς ταῖς ἐλπίσιν ἐτύφουν Κλασσικός τις καὶ Οὐίτιλλος τῶν παρ’ αὐτοῖς [ὄντες] ἡγεμόνων, οἳ δῆλον μὲν ὡς ἐκ μακροῦ ταύτης ἐφίεντο τῆς νεωτεροποιίας, ὑπὸ τοῦ καιροῦ δὲ θαρσῆσαι προαχθέντες τὴν αὐτῶν γνώμην ἐξέφηναν· ἔμελλον δὲ προθύμως διακειμένοις τὴν πεῖραν τοῖς πλήθεσι προσφέρειν. πολλοῦ δὲ μέρους ἤδη τῶν Γερμανῶν τὴν ἀποστασίαν ἀνωμολογηκότος καὶ τῶν ἄλλων οὐκ ἄνδιχα φρονησάντων, ὥσπερ ἐκ δαιμονίου προνοίας Οὐεσπασιανὸς πέμπει γράμματα Πετιλίῳ Κερεαλίῳ τὸ πρότερον ἡγεμόνι Γερμανίας γενομένῳ, τὴν ὕπατον διδοὺς τιμὴν καὶ κελεύων ἄρξοντα Βρεττανίας ἀπιέναι. πορευόμενος οὖν ἐκεῖνος ὅποι προσετέτακτο καὶ τὰ περὶ τὴν ἀπόστασιν τῶν Γερμανῶν πυθόμενος, ἤδη συνειλεγμένοις αὐτοῖς ἐπιπεσὼν καὶ παραταξάμενος πολύ τε πλῆθος αὐτῶν ἀναιρεῖ κατὰ τὴν μάχην καὶ τῆς ἀνοίας παυσαμένους ἠνάγκασε σωφρονεῖν. ἔμελλον δὲ κἀκείνου μὴ θᾶττον εἰς τοὺς τόπους παραβαλόντος δίκην οὐκ εἰς μακρὰν ὑφέξειν· ἡνίκα γὰρ πρῶτον ἡ τῆς ἀποστάσεως αὐτῶν ἀγγελία τῇ Ῥώμῃ προσέπεσε, Δομετιανὸς Καῖσαρ πυθόμενος οὐχ ὡς ἂν ἕτερος ἐν τούτῳ τῆς ἡλικίας, νέος γὰρ ἦν ἔτι παντάπασιν, τηλικοῦτον ἄρασθαι μέγεθος πραγμάτων ὤκνησεν, ἔχων δὲ πατρόθεν ἔμφυτον τὴν ἀνδραγαθίαν καὶ τελειοτέραν τὴν ἄσκησιν τῆς ἡλικίας πεποιημένος ἐπὶ τοὺς βαρβάρους εὐθὺς ἤλαυνεν. οἱ δὲ πρὸς τὴν φήμην τῆς ἐφόδου καταπεσόντες ἐπ’ αὐτῷ σφᾶς αὐτοὺς ἐποιήσαντο μέγα τοῦ φόβου κέρδος εὑράμενοι τὸ χωρὶς συμφορῶν ὑπὸ τὸν αὐτὸν πάλιν ζυγὸν ὑπαχθῆναι. πᾶσιν οὖν ἐπιθεὶς τοῖς περὶ τὴν Γαλατίαν τάξιν τὴν προσήκουσαν Δομετιανός, ὡς μηδ’ αὖθις ἄν ποτε ῥᾳδίως ἔτι τἀκεῖ ταραχθῆναι, λαμπρὸς καὶ περίβλεπτος ἐπὶ κρείττοσι μὲν τῆς ἡλικίας, πρέπουσι δὲ τῷ πατρὶ κατορθώμασιν εἰς τὴν Ῥώμην ἀνέζευξε.", "st": "7.4.2"}, {"sp": "N", "t": "Τῇ δὲ προειρημένῃ Γερμανῶν ἀποστάσει κατὰ τὰς αὐτὰς ἡμέρας καὶ Σκυθικὸν τόλμημα πρὸς Ῥωμαίους συνέδραμεν. οἱ γὰρ καλούμενοι Σκυθῶν Σαρμάται, πολὺ πλῆθος ὄντες, ἄδηλοι μὲν τὸν Ἴστρον ἐπεραιώθησαν εἰς τὴν ἐπιτάδε, πολλῇ δὲ βίᾳ καὶ χαλεποὶ διὰ τὸ παντάπασιν ἀνέλπιστον τῆς ἐφόδου προσπεσόντες πολλοὺς μὲν τῶν ἐπὶ τῆς φρουρᾶς Ῥωμαίων ἀναιροῦσι, καὶ τὸν πρεσβευτὴν τὸν ὑπατικὸν Φοντήιον Ἀγρίππαν ὑπαντιάσαντα καρτερῶς μαχόμενον κτείνουσι, τὴν δ’ ὑποκειμένην χώραν ἅπασαν κατέτρεχον ἄγοντες καὶ φέροντες ὅτῳ περιπέσοιεν. Οὐεσπασιανὸς δὲ τὰ γεγενημένα καὶ τὴν πόρθησιν τῆς Μυσίας πυθόμενος Ῥούβριον Γάλλον ἐκπέμπει δίκην ἐπιθήσοντα τοῖς Σαρμάταις. ὑφ’ οὗ πολλοὶ μὲν αὐτῶν ἐν ταῖς μάχαις ἀπέθανον, τὸ δὲ περισωθὲν μετὰ δέους εἰς τὴν οἰκείαν διέφυγεν. τοῦτο δὲ τῷ πολέμῳ τέλος ἐπιθεὶς ὁ στρατηγὸς καὶ τῆς εἰς τὸ μέλλον ἀσφαλείας προυνόησε· πλείοσι γὰρ καὶ μείζοσι φυλακαῖς τὸν τόπον διέλαβεν, ὡς εἶναι τοῖς βαρβάροις τὴν διάβασιν τελέως ἀδύνατον. ὁ μὲν οὖν περὶ τὴν Μυσίαν πόλεμος ταχεῖαν οὕτως ἔλαβε τὴν κρίσιν.", "st": "7.4.3"}, {"sp": "N", "t": "Τίτος δὲ Καῖσαρ χρόνον μέν τινα διέτριβεν ἐν Βηρυτῷ, καθὰ προειρήκαμεν, ἐκεῖθεν δὲ ἀναζεύξας καὶ δι’ ὧν ᾔει πόλεων τῆς Συρίας ἐν πάσαις θεωρίας τε συντελῶν πολυτελεῖς καὶ τῶν Ἰουδαίων τοὺς αἰχμαλώτους εἰς ἐπίδειξιν τῆς ἑαυτῶν ἀπωλείας ἀποχρώμενος, θεᾶται κατὰ τὴν πορείαν ποταμοῦ φύσιν ἀξίαν ἱστορηθῆναι. ῥεῖ μὲν γὰρ μέσος Ἀρκέας τῆς Ἀγρίππα βασιλείας καὶ Ῥαφανέας, ἔχει δὲ θαυμαστὴν ἰδιότητα· πολὺς γὰρ ὤν, ὅτε ῥεῖ, καὶ κατὰ τὴν φορὰν οὐ σχολαῖος, ἔπειτα δὲ πᾶς ἐκ τῶν πηγῶν ἐπιλείπων ἓξ ἡμερῶν ἀριθμὸν ξηρὸν παραδίδωσιν ὁρᾶν τὸν τόπον· εἶθ’ ὥσπερ οὐδεμιᾶς γενομένης μεταβολῆς ὅμοιος κατὰ τὴν ἑβδόμην ἐκδίδωσι, καὶ ταύτην ἀεὶ τὴν τάξιν ἀκριβῶς τετήρηται διαφυλάττων· ὅθεν δὴ καὶ Σαββατικὸν αὐτὸν κεκλήκασιν ἀπὸ τῆς ἱερᾶς τῶν Ἰουδαίων ἑβδόμης οὕτως ὀνομάσαντες.", "st": "7.5.1"}, {"sp": "N", "t": "Ὁ δὲ τῶν Ἀντιοχέων δῆμος ἐπεὶ πλησίον ὄντα Τίτον ἐπυνθάνοντο, μένειν μὲν ἐντὸς τειχῶν ὑπὸ χαρᾶς οὐχ ὑπέμενον, ἔσπευδον δὲ ἐπὶ τὴν ὑπάντησιν· καὶ τριάκοντα σταδίων ἐπὶ πλέον προῆλθον οὐκ ἄνδρες μόνον ἀλλὰ καὶ γυναικῶν πλῆθος ἅμα παισὶ τῆς πόλεως ἐκχεόμενοι. κἀπειδήπερ ἐθεάσαντο προσιόντα, παρὰ τὴν ὁδὸν ἑκατέρωθεν καταστάντες τάς τε δεξιὰς προύτεινον προσαγορεύοντες καὶ παντοίοις ἐπιφημίσμασι χρώμενοι συνυπέστρεφον· συνεχὴς δὲ ἦν αὐτῶν παρὰ πάσας ἅμα τὰς εὐφημίας δέησις ἐκβαλεῖν τῆς πόλεως τοὺς Ἰουδαίους. Τίτος μὲν οὖν οὐδὲν ἐνέδωκεν πρὸς ταύτην τὴν δέησιν, ἀλλ’ ἡσυχῆ τῶν λεγομένων ἐπήκουεν· ἐπ’ ἀδήλῳ δὲ τῷ τί φρονεῖ καὶ τί ποιήσει πολὺς καὶ χαλεπὸς τοῖς Ἰουδαίοις ὁ φόβος ἦν· οὐδὲ γὰρ ὑπέμεινεν ἐν Ἀντιοχείᾳ Τίτος, ἀλλ’ εὐθὺς ἐπὶ τὸ Ζεῦγμα τὸ κατὰ τὸν Εὐφράτην συνέτεινε τὴν πορείαν, ἔνθα δὴ καὶ παρὰ τοῦ Πάρθων βασιλέως Βολογέσου πρὸς αὐτὸν ἧκον στέφανον χρυσοῦν ἐπὶ τῇ κατὰ τῶν Ἰουδαίων νίκῃ κομίζοντες. ὃν δεξάμενος εἱστία τοὺς βασιλικούς, κἀκεῖθεν εἰς τὴν Ἀντιόχειαν ἐπανέρχεται. τῆς δὲ βουλῆς καὶ τοῦ δήμου τῶν Ἀντιοχέων πολλὰς ποιησαμένων δεήσεις ἐλθεῖν εἰς τὸ θέατρον αὐτόν, ἐν ᾧ πᾶν τὸ πλῆθος ἠθροισμένον ἐξεδέχετο, φιλανθρώπως ὑπήκουσε. πάλιν δ’ αὐτῶν σφόδρα λιπαρῶς ἐγκειμένων καὶ συνεχῶς δεομένων ἐξελάσαι τῆς πόλεως τοὺς Ἰουδαίους, εὔστοχον ἐποιήσατο τὴν ἀπόκρισιν, εἰπών ἀλλ’ ἥ γε πατρὶς αὐτῶν, εἰς ἣν ἐκβαλεῖν ἐχρῆν ὄντας Ἰουδαίους, ἀνῄρηται, καὶ δέξαιτ’ ἂν οὐδεὶς αὐτοὺς ἔτι τόπος. ἐπὶ δευτέραν οὖν Ἀντιοχεῖς τρέπονται δέησιν τῆς προτέρας ἀποστάντες· τὰς γὰρ χαλκᾶς ἠξίουν δέλτους ἀνελεῖν αὐτόν, ἐν αἷς γέγραπται τὰ δικαιώματα τῶν Ἰουδαίων. οὐ μὴν οὐδὲ τοῦτο Τίτος ἐπένευσεν αὐτοῖς, ἀλλ’ ἐάσας πάντα κατὰ χώραν τοῖς ἐπ’ Ἀντιοχείας Ἰουδαίοις ὡς πρότερον εἶχον εἰς Αἴγυπτον ἀπηλλάττετο. καὶ κατὰ τὴν πορείαν τοῖς Ἱεροσολύμοις προσελθὼν καὶ τὴν λυπρὰν ἐρημίαν βλεπομένην ἀντιτιθεὶς τῇ ποτε τῆς πόλεως λαμπρότητι, καὶ τὸ μέγεθος τῶν ἐρρηγμένων κατασκευασμάτων καὶ τὸ πάλαι κάλλος εἰς μνήμην βαλλόμενος, ᾤκτειρε τῆς πόλεως τὸν ὄλεθρον, οὐχ ὥσπερ ἄν τις αὐχῶν ὅτι τηλικαύτην οὖσαν καὶ τοσαύτην εἷλε κατὰ κράτος, ἀλλὰ πολλάκις ἐπαρώμενος τοῖς αἰτίοις τῆς ἀποστάσεως ὑπάρξασι καὶ ταύτην ἐπὶ τῇ πόλει τὴν τιμωρίαν γενέσθαι παρασκευάσασιν· οὕτως ἔκδηλος ἦν οὐκ ἂν θελήσας ἐκ τῆς συμφορᾶς τῶν κολασθέντων γενέσθαι τῆς ἀρετῆς τὴν ἐπιφάνειαν. τοῦ δὲ πολλοῦ πλούτου τῆς πόλεως ἔτι κἀν τοῖς ἐρειπίοις οὐκ ὀλίγον μέρος ἀνηυρίσκετο· τὰ μὲν γὰρ πολλὰ ἀνέσκαπτον οἱ Ῥωμαῖοι, τὰ πλείω δὲ ἐκ μηνύσεως τῶν αἰχμαλώτων ἀνῃροῦντο, χρυσόν τε καὶ ἄργυρον καὶ τῆς ἄλλης τὰ τιμιώτατα κατασκευῆς, ἅπερ οἱ κεκτημένοι πρὸς τὰς ἀδήλους τοῦ πολέμου τύχας κατὰ γῆς ἀποτεθησαυρίκεσαν.", "st": "7.5.2"}, {"sp": "N", "t": "Τίτος δὲ τὴν προκειμένην ποιούμενος πορείαν ἐπ’ Αἴγυπτον καὶ τὴν ἔρημον ᾗ τάχιστα διανύσας ἧκεν εἰς Ἀλεξάνδρειαν, καὶ πλεῖν ἐπὶ τῆς Ἰταλίας διεγνωκὼς δυοῖν αὐτῷ ταγμάτων συνηκολουθηκότων ἑκάτερον ὅθεν περ ἀφῖκτο πάλιν ἀπέστειλεν, εἰς μὲν τὴν Μυσίαν τὸ πέμπτον, εἰς Παννονίαν δὲ τὸ πεντεκαιδέκατον. τῶν αἰχμαλώτων δὲ τοὺς μὲν ἡγεμόνας Σίμωνα καὶ Ἰωάννην, τόν τ’ ἄλλον ἀριθμὸν ἑπτακοσίους ἄνδρας ἐπιλέξας μεγέθει τε καὶ κάλλει σωμάτων ὑπερβάλλοντας, προσέταξεν εἰς τὴν Ἰταλίαν αὐτίκα μάλα κομίζεσθαι βουλόμενος αὐτοὺς ἐν τῷ θριάμβῳ παραγαγεῖν. τοῦ πλοῦ δὲ αὐτῷ κατὰ νοῦν ἀνυσθέντος ὁμοίως μὲν ἡ Ῥώμη περὶ τὴν ὑποδοχὴν εἶχε καὶ τὰς ὑπαντήσεις ὥσπερ ἐπὶ τοῦ πατρός, λαμπρότερον δ’ ἦν Τίτῳ καὶ αὐτὸς ὁ πατὴρ ὑπαντῶν καὶ δεχόμενος. τῷ δὲ πλήθει τῶν πολιτῶν δαιμόνιόν τινα τὴν χαρὰν παρεῖχε τὸ βλέπειν αὐτοὺς ἤδη τοὺς τρεῖς ἐν ταὐτῷ γεγονότας. οὐ πολλῶν δὲ ἡμερῶν διελθουσῶν ἕνα καὶ κοινὸν ἔγνωσαν τὸν ἐπὶ τοῖς κατωρθωμένοις ποιήσασθαι θρίαμβον, καίπερ ἑκατέρῳ τῆς βουλῆς ἴδιον ψηφισαμένης. προδιασαφηθείσης δὲ τῆς ἡμέρας ἐφ’ ἧς ἔμελλεν ἡ πομπὴ γενήσεσθαι τῶν ἐπινικίων, οὐδεὶς οἴκοι καταλέλειπτο τῆς ἀμέτρου πληθύος ἐν τῇ πόλει, πάντες δὲ ὅπη καὶ στῆναι μόνον ἦν οἷον προεληλυθότες τοὺς τόπους κατειλήφεσαν, ὅσον τοῖς ὀφθησομένοις μόνον εἰς πάροδον ἀναγκαίαν καταλιπόντες.", "st": "7.5.3"}, {"sp": "N", "t": "Τοῦ δὲ στρατιωτικοῦ παντὸς ἔτι νύκτωρ κατὰ λόχους καὶ τάξεις ὑπὸ τοῖς ἡγεμόσι διεξωδευκότος καὶ περὶ θύρας ὄντος οὐ τῶν ἄνω βασιλείων ἀλλὰ πλησίον τοῦ τῆς Ἴσιδος ἱεροῦ, ἐκεῖ γὰρ ἀνεπαύοντο τῆς νυκτὸς ἐκείνης οἱ αὐτοκράτορες, περὶ αὐτὴν ἀρχομένην ἤδη τὴν ἕω προΐασιν Οὐεσπασιανὸς καὶ Τίτος δάφνῃ μὲν ἐστεφανωμένοι, πορφυρᾶς δ’ ἐσθῆτας πατρίους ἀμπεχόμενοι, καὶ παρίασιν εἰς τοὺς Ὀκταουίας περιπάτους· ἐνταῦθα γὰρ ἥ τε βουλὴ καὶ τὰ τέλη τῶν ἀρχόντων οἵ τε ἀπὸ τῶν τιμημάτων ἱππεῖς τὴν ἄφιξιν αὐτῶν ἀνέμενον. πεποίητο δὲ βῆμα πρὸ τῶν στοῶν δίφρων αὐτοῖς ἐλεφαντίνων ἐπ’ αὐτοῦ κειμένων, ἐφ’ οὓς παρελθόντες ἐκαθέσθησαν, καὶ τὸ στρατιωτικὸν εὐθέως ἐπευφήμει πολλὰς αὐτοῖς τῆς ἀρετῆς μαρτυρίας ἀποδιδόντες ἅπαντες· κἀκεῖνοι χωρὶς ὅπλων ἦσαν ἐν ἐσθήσεσιν σηρικαῖς ἐστεφανωμένοι δάφναις. δεξάμενος δ’ αὐτῶν τὴν εὐφημίαν Οὐεσπασιανὸς ἔτι βουλομένων λέγειν τὸ τῆς σιγῆς ἐποιήσατο σύμβολον, καὶ πολλῆς ἐκ πάντων ἡσυχίας γενομένης ἀναστὰς καὶ τῷ περιβλήματι τὸ πλέον τῆς κεφαλῆς μέρος ἐπικαλυψάμενος εὐχὰς ἐποιήσατο τὰς νενομισμένας· ὁμοίως δὲ καὶ Τίτος ηὔξατο. μετὰ δὲ τὰς εὐχὰς εἰς κοινὸν ἅπασιν Οὐεσπασιανὸς βραχέα διαλεχθεὶς τοὺς μὲν στρατιώτας ἀπέλυσεν ἐπὶ τὸ νενομισμένον ἄριστον αὐτοῖς ὑπὸ τῶν αὐτοκρατόρων εὐτρεπίζεσθαι, πρὸς δὲ τὴν πύλην αὐτὸς ἀνεχώρει τὴν ἀπὸ τοῦ πέμπεσθαι δι’ αὐτῆς αἰεὶ τοὺς θριάμβους τῆς προσηγορίας ἀπ’ αὐτῶν τετυχυῖαν. ἐνταῦθα τροφῆς τε προαπογεύονται καὶ τὰς θριαμβικὰς ἐσθῆτας ἀμφιασάμενοι τοῖς τε παριδρυμένοις τῇ πύλῃ θύσαντες θεοῖς ἔπεμπον τὸν θρίαμβον διὰ τῶν θεάτρων διεξελαύνοντες, ὅπως εἴη τοῖς πλήθεσιν ἡ θέα ῥᾴων.", "st": "7.5.4"}, {"sp": "N", "t": "Ἀμήχανον δὲ κατὰ τὴν ἀξίαν εἰπεῖν τῶν θεαμάτων ἐκείνων τὸ πλῆθος καὶ τὴν μεγαλοπρέπειαν ἐν ἅπασιν οἷς ἄν τις ἐπινοήσειεν ἢ τεχνῶν ἔργοις ἢ πλούτου μέρεσιν ἢ φύσεως σπανιότησιν· σχεδὸν γὰρ ὅσα τοῖς πώποτε ἀνθρώποις εὐδαιμονήσασιν ἐκτήθη κατὰ μέρος ἄλλα παρ’ ἄλλοις θαυμαστὰ καὶ πολυτελῆ, ταῦτα ἐπὶ τῆς ἡμέρας ἐκείνης ἀθρόα τῆς Ῥωμαίων ἡγεμονίας ἔδειξε τὸ μέγεθος. ἀργύρου γὰρ καὶ χρυσοῦ καὶ ἐλέφαντος ἐν παντοίαις ἰδέαις κατασκευασμάτων ἦν ὁρᾶν οὐχ ὥσπερ ἐν πομπῇ κομιζόμενον πλῆθος, ἀλλ’ ὡς ἂν εἴποι τις ῥέοντα ποταμόν, καὶ τὰ μὲν ἐκ πορφύρας ὑφάσματα τῆς σπανιωτάτης φερόμενα, τὰ δ’ εἰς ἀκριβῆ ζωγραφίαν πεποικιλμένα τῇ Βαβυλωνίων τέχνῃ· λίθοι τε διαφανεῖς, οἱ μὲν χρυσοῖς ἐμπεπλεγμένοι στεφάνοις, οἱ δὲ κατ’ ἄλλας ποιήσεις, τοσοῦτοι παρηνέχθησαν, ὥστε μαθεῖν ὅτι μάτην εἶναί τι τούτων σπάνιον ὑπειλήφαμεν. ἐφέρετο δὲ καὶ θεῶν ἀγάλματα τῶν παρ’ αὐτοῖς μεγέθεσι θαυμαστὰ καὶ κατὰ τὴν τέχνην οὐ παρέργως πεποιημένα, καὶ τούτων οὐδέν, ὅ τι μὴ τῆς ὕλης τῆς πολυτελοῦς, ζῴων τε πολλαὶ φύσεις παρήγοντο κόσμον οἰκεῖον ἁπάντων περικειμένων. ἦν δὲ καὶ τὸ κομίζον ἕκαστα τούτων πλῆθος ἀνθρώπων ἁλουργαῖς ἐσθῆσι καὶ διαχρύσοις κεκοσμημένον, οἵ τ’ εἰς αὐτὸ τὸ πομπεύειν διακριθέντες ἐξαίρετον εἶχον καὶ καταπληκτικὴν περὶ αὐτοὺς τοῦ κόσμου τὴν πολυτέλειαν. ἐπὶ τούτοις οὐδὲ τὸν αἰχμάλωτον ἦν ἰδεῖν ὄχλον ἀκόσμητον, ἀλλ’ ἡ τῶν ἐσθήτων ποικιλία καὶ τὸ κάλλος αὐτοῖς τὴν ἀπὸ τῆς κακώσεως τῶν σωμάτων ἀηδίαν ἔκλεπτε τῆς ὄψεως. θαῦμα δ’ ἐν τοῖς μάλιστα παρεῖχεν ἡ τῶν φερομένων πηγμάτων κατασκευή· καὶ γὰρ διὰ μέγεθος ἦν δεῖσαι τῷ βεβαίῳ τῆς φορᾶς ἀπιστήσαντα, τριώροφα γὰρ αὐτῶν πολλὰ καὶ τετρώροφα πεποίητο, καὶ τῇ πολυτελείᾳ τῇ περὶ τὴν κατασκευὴν ἦν ἡσθῆναι μετ’ ἐκπλήξεως. καὶ γὰρ ὑφάσματα πολλοῖς διάχρυσα περιβέβλητο, καὶ χρυσὸς καὶ ἐλέφας οὐκ ἀποίητος πᾶσι περιεπεπήγει. διὰ πολλῶν δὲ μιμημάτων ὁ πόλεμος ἄλλος εἰς ἄλλα μεμερισμένος ἐναργεστάτην ὄψιν αὑτοῦ παρεῖχεν· ἦν γὰρ ὁρᾶν χώραν μὲν εὐδαίμονα δῃουμένην, ὅλας δὲ φάλαγγας κτεινομένας πολεμίων, καὶ τοὺς μὲν φεύγοντας τοὺς δ’ εἰς αἰχμαλωσίαν ἀγομένους, τείχη δ’ ὑπερβάλλοντα μεγέθει μηχαναῖς ἐρειπόμενα καὶ φρουρίων ἁλισκομένας ὀχυρότητας καὶ πόλεων πολυανθρώπους περιβόλους κατ’ ἄκρας ἐχομένους, καὶ στρατιὰν ἔνδον τειχῶν εἰσχεομένην, καὶ πάντα φόνου πλήθοντα τόπον, καὶ τῶν ἀδυνάτων χεῖρας ἀνταίρειν ἱκεσίας, πῦρ τε ἐνιέμενον ἱεροῖς καὶ κατασκαφὰς οἴκων ἐπὶ τοῖς δεσπόταις, καὶ μετὰ πολλὴν ἐρημίαν καὶ κατήφειαν ποταμοὺς ῥέοντας οὐκ ἐπὶ γῆν γεωργουμένην, οὐδὲ ποτὸν ἀνθρώποις ἢ βοσκήμασιν, ἀλλὰ διὰ τῆς ἐπιπανταχόθεν φλεγομένης· ταῦτα γὰρ Ἰουδαῖοι πεισομένους αὑτοὺς τῷ πολέμῳ παρέδοσαν. ἡ τέχνη δὲ καὶ τῶν κατασκευασμάτων ἡ μεγαλουργία τοῖς οὐκ ἰδοῦσι γινόμενα τότ’ ἐδείκνυεν ὡς παροῦσι. τέτακτο δ’ ἐφ’ ἑκάστῳ τῶν πηγμάτων ὁ τῆς ἁλισκομένης πόλεως στρατηγὸς ὃν τρόπον ἐλήφθη. πολλαὶ δὲ καὶ νῆες εἵποντο. λάφυρα δὲ τὰ μὲν ἄλλα χύδην ἐφέρετο, διέπρεπε δὲ πάντων τὰ ἐγκαταληφθέντα τῷ ἐν Ἱεροσολύμοις ἱερῷ, χρυσῆ τε τράπεζα τὴν ὁλκὴν πολυτάλαντος καὶ λυχνία χρυσῆ μὲν ὁμοίως πεποιημένη, τὸ δ’ ἔργον ἐξήλλακτο τῆς κατὰ τὴν ἡμετέραν χρῆσιν συνηθείας. ὁ μὲν γὰρ μέσος ἦν κίων ἐκ τῆς βάσεως πεπηγώς, λεπτοὶ δ’ ἀπ’ αὐτοῦ μεμήκυντο καυλίσκοι τριαίνης σχήματι παραπλησίαν τὴν θέσιν ἔχοντες, λύχνον ἕκαστος αὐτῶν ἐπ’ ἄκρον κεχαλκευμένος· ἑπτὰ δ’ ἦσαν οὗτοι τῆς παρὰ τοῖς Ἰουδαίοις ἑβδομάδος τὴν τιμὴν ἐμφανίζοντες. ὅ τε νόμος ὁ τῶν Ἰουδαίων ἐπὶ τούτοις ἐφέρετο τῶν λαφύρων τελευταῖος. ἐπὶ τούτοις παρῄεσαν πολλοὶ Νίκης ἀγάλματα κομίζοντες· ἐξ ἐλέφαντος δ’ ἦν πάντων καὶ χρυσοῦ ἡ κατασκευή. μεθ’ ἃ Οὐεσπασιανὸς ἤλαυνε πρῶτος καὶ Τίτος εἵπετο, Δομετιανὸς δὲ παρίππευεν, αὐτός τε διαπρεπῶς κεκοσμημένος καὶ τὸν ἵππον παρέχων θέας ἄξιον.", "st": "7.5.5"}, {"sp": "N", "t": "Ἦν δὲ τῆς πομπῆς τὸ τέλος ἐπὶ τὸν νεὼ τοῦ Καπετωλίου Διός, ἐφ’ ὃν ἐλθόντες ἔστησαν· ἦν γὰρ παλαιὸν πάτριον περιμένειν, μέχρις ἂν τὸν τοῦ στρατηγοῦ τῶν πολεμίων θάνατον ἀπαγγείλῃ τις. Σίμων οὗτος ἦν ὁ Γιώρα, τότε πεπομπευκὼς ἐν τοῖς αἰχμαλώτοις, βρόχῳ δὲ περιβληθεὶς εἰς τὸν ἐπὶ τῆς ἀγορᾶς ἐσύρετο τόπον αἰκιζομένων αὐτὸν ἅμα τῶν ἀγόντων· νόμος δ’ ἐστὶ Ῥωμαίοις ἐκεῖ κτείνειν τοὺς ἐπὶ κακουργίᾳ θάνατον κατεγνωσμένους. ἐπεὶ δ’ ἀπηγγέλθη τέλος ἔχων καὶ πάντες εὐφήμησαν, ἤρχοντο τῶν θυσιῶν, ἃς ἐπὶ ταῖς νομιζομέναις καλλιερήσαντες εὐχαῖς ἀπῄεσαν εἰς τὸ βασίλειον. καὶ τοὺς μὲν αὐτοὶ πρὸς εὐωχίαν ὑπεδέχοντο, τοῖς δ’ ἄλλοις ἅπασιν εὐτρεπεῖς κατὰ τὸ οἰκεῖον αἱ τῆς ἑστιάσεως ἦσαν παρασκευαί. ταύτην γὰρ τὴν ἡμέραν ἡ Ῥωμαίων πόλις ἑώρταζεν ἐπινίκιον μὲν τῆς κατὰ τῶν πολεμίων στρατείας, πέρας δὲ τῶν ἐμφυλίων κακῶν, ἀρχὴν δὲ τῶν ὑπὲρ τῆς εὐδαιμονίας ἐλπίδων.", "st": "7.5.6"}, {"sp": "N", "t": "Μετὰ δὲ τοὺς θριάμβους καὶ τὴν βεβαιοτάτην τῆς Ῥωμαίων ἡγεμονίας κατάστασιν Οὐεσπασιανὸς ἔγνω τέμενος Εἰρήνης κατασκευάσαι· ταχὺ δὲ δὴ μάλα καὶ πάσης ἀνθρωπίνης κρεῖττον ἐπινοίας ἐτετελείωτο. τῇ γὰρ ἐκ τοῦ πλούτου χορηγίᾳ δαιμονίῳ χρησάμενος ἔτι καὶ τοῖς ἔκπαλαι κατωρθωμένοις γραφῆς τε καὶ πλαστικῆς ἔργοις αὐτὸ κατεκόσμησεν· πάντα γὰρ εἰς ἐκεῖνον τὸν νεὼ συνήχθη καὶ κατετέθη, δι’ ὧν τὴν θέαν ἄνθρωποι πρότερον περὶ πᾶσαν ἐπλανῶντο τὴν οἰκουμένην, ἕως ἄλλο παρ’ ἄλλοις ἦν κείμενον ἰδεῖν ποθοῦντες. ἀνέθηκε δὲ ἐνταῦθα καὶ τὰ ἐκ τοῦ ἱεροῦ τῶν Ἰουδαίων χρυσᾶ κατασκευάσματα σεμνυνόμενος ἐπ’ αὐτοῖς. τὸν δὲ νόμον αὐτῶν καὶ τὰ πορφυρᾶ τοῦ σηκοῦ καταπετάσματα προσέταξεν ἐν τοῖς βασιλείοις ἀποθεμένους φυλάττειν.", "st": "7.5.7"}, {"sp": "N", "t": "Εἰς δὲ τὴν Ἰουδαίαν πρεσβευτὴς Λουκίλιος Βάσσος ἐκπεμφθεὶς καὶ τὴν στρατιὰν παρὰ Κερεαλίου Οὐετιλιανοῦ παραλαβὼν τὸ μὲν ἐν τῷ Ἡρωδείῳ φρούριον προσηγάγετο μετὰ τῶν ἐχόντων, μετὰ ταῦτα δὲ πᾶν ὅσον ἦν στρατιωτικὸν συναγαγών, πολὺ δ’ ἦν κατὰ μέρη διῃρημένον, καὶ τῶν ταγμάτων τὸ δέκατον, ἔγνω στρατεύειν ἐπὶ Μαχαιροῦντα· πάνυ γὰρ ἦν ἀναγκαῖον ἐξαιρεθῆναι τὸ φρούριον, μὴ διὰ τὴν ὀχυρότητα πολλοὺς εἰς ἀποστασίαν ἐπαγάγηται. καὶ γὰρ τοῖς κατέχουσι βεβαίαν ἐλπίδα σωτηρίας καὶ τοῖς ἐπιοῦσιν ὄκνον καὶ δέος ἡ τοῦ χωρίου φύσις ἦν παρασχεῖν ἱκανωτάτη. αὐτὸ μὲν γὰρ τὸ τετειχισμένον πετρώδης ὄχθος ἐστὶν εἰς μήκιστον ὕψος ἐγηγερμένος, ὡς εἶναι καὶ διὰ τοῦτο δυσχείρωτος, μεμηχάνηται δ’ ὑπὸ τῆς φύσεως εἶναι μηδὲ προσιτός· φάραγξιν γὰρ πάντοθεν ἀσύνοπτον ἐχούσαις τὸ βάθος περιτετάφρευται, μήτε περαθῆναι ῥᾳδίως δυναμέναις καὶ χωσθῆναι παντάπασιν ἀμηχάνοις. ἡ μὲν γὰρ ἀπὸ τῆς ἑσπέρας περιτέμνουσα παρατείνει σταδίους ἑξήκοντα πέρας αὑτῆς τὴν Ἀσφαλτῖτιν ποιουμένη λίμνην· κατὰ τοῦτο δέ πῃ καὶ αὐτὸς ὁ Μαχαιροῦς τὴν ὑψηλοτάτην ἔχει κορυφὴν ὑπερανίσχουσαν· αἱ δ’ ἀπὸ τῆς ἄρκτου καὶ μεσημβρίας φάραγγες μεγέθει μὲν ἀπολείπονται τῆς προειρημένης, ὁμοίως δ’ εἰσὶν ἀμήχανοι πρὸς ἐπιχείρησιν. τῆς δὲ πρὸς ἀνατολὴν φάραγγος τὸ μὲν βάθος οὐκ ἔλαττον ἑκατὸν εὑρίσκεται πήχεων, τέρμα δὲ γίνεται πρὸς ὄρος ἀπαντικρὺ κείμενον Μαχαιροῦντος.", "st": "7.6.1"}, {"sp": "N", "t": "Ταύτην τοῦ τόπου κατιδὼν τὴν φύσιν βασιλεὺς Ἰουδαίων Ἀλέξανδρος πρῶτος ἐπ’ αὐτοῦ τειχίζει φρούριον, ὃ μετὰ ταῦτα Γαβίνιος Ἀριστοβούλῳ πολεμῶν καθεῖλεν. Ἡρώδῃ δὲ βασιλεύοντι παντὸς ἔδοξε μᾶλλον ἐπιμελείας ἄξιον εἶναι καὶ κατασκευῆς ὀχυρωτάτης μάλιστα καὶ διὰ τὴν τῶν Ἀράβων γειτνίασιν· κεῖται γὰρ ἐν ἐπικαίρῳ πρὸς τὴν ἐκείνων γῆν ἀποβλέπον. μέγαν μὲν οὖν τόπον τείχεσιν καὶ πύργοις περιβαλὼν πόλιν ἐνταῦθα κατῴκισεν, ἐξ ἧς ἄνοδος εἰς αὐτὴν ἔφερε τὴν ἀκρώρειαν. οὐ μὴν ἀλλὰ καὶ περὶ αὐτὴν ἄνω τὴν κορυφὴν τεῖχος ἐδείματο καὶ πύργους ἐπὶ ταῖς γωνίαις ἕκαστον ἑξήκοντα πηχῶν ἀνέστησεν. μέσον δὲ τοῦ περιβόλου βασίλειον ᾠκοδομήσατο μεγέθει τε καὶ κάλλει τῶν οἰκήσεων πολυτελές, πολλὰς δὲ καὶ δεξαμενὰς εἰς ὑποδοχὴν ὕδατος καὶ χορηγίαν ἄφθονον ἐν τοῖς ἐπιτηδειοτάτοις τῶν τόπων κατεσκεύασεν, ὥσπερ πρὸς τὴν φύσιν ἁμιλληθείς, ἵν’ αὐτὸς τὸ κατ’ ἐκείνην τοῦ τόπου δυσάλωτον ὑπερβάληται ταῖς χειροποιήτοις ὀχυρώσεσιν· ἔτι γὰρ καὶ βελῶν πλῆθος καὶ μηχανημάτων ἐγκατέθετο καὶ πᾶν ἐπενόησεν ἑτοιμάσασθαι τὸ παρασχεῖν δυνάμενον τοῖς ἐνοικοῦσιν μηκίστης πολιορκίας καταφρόνησιν.", "st": "7.6.2"}, {"sp": "N", "t": "Ἐπεφύκει δ’ ἐν τοῖς βασιλείοις πήγανον ἄξιον τοῦ μεγέθους θαυμάσαι· συκῆς γὰρ οὐδεμιᾶς ὕψους καὶ πάχους ἐλείπετο. λόγος δὲ ἦν ἀπὸ τῶν Ἡρώδου χρόνων αὐτὸ διαρκέσαι, κἂν ἐπὶ πλεῖστον ἴσως ἔμεινεν, ἐξεκόπη δὲ ὑπὸ τῶν παραλαβόντων τὸν τόπον Ἰουδαίων. τῆς φάραγγος δὲ τῆς κατὰ τὴν ἄρκτον περιεχούσης τὴν πόλιν Βαάρας ὀνομάζεταί τις τόπος, φύει ῥίζαν ὁμωνύμως λεγομένην αὐτῷ. αὕτη φλογὶ μὲν τὴν χροίαν ἔοικε, περὶ δὲ τὰς ἑσπέρας σέλας ἀπαστράπτουσα τοῖς ἐπιοῦσι καὶ βουλομένοις λαβεῖν αὐτὴν οὐκ ἔστιν εὐχείρωτος, ἀλλ’ ὑποφεύγει καὶ οὐ πρότερον ἵσταται, πρὶν ἄν τις οὖρον γυναικὸς ἢ τὸ ἔμμηνον αἷμα χέῃ κατ’ αὐτῆς. οὐ μὴν ἀλλὰ καὶ τότε τοῖς ἁψαμένοις πρόδηλός ἐστι θάνατος, εἰ μὴ τύχοι τις αὐτὴν ἐκείνην ἐπενεγκάμενος τὴν ῥίζαν ἐκ τῆς χειρὸς ἀπηρτημένην. ἁλίσκεται δὲ καὶ καθ’ ἕτερον τρόπον ἀκινδύνως, ὅς ἐστι τοιόσδε· κύκλῳ πᾶσαν αὐτὴν περιορύσσουσιν, ὡς εἶναι τὸ κρυπτόμενον τῆς ῥίζης βραχύτατον. εἶτ’ ἐξ αὐτῆς ἀποδοῦσι κύνα, κἀκείνου τῷ δήσαντι συνακολουθεῖν ὁρμήσαντος ἡ μὲν ἀνασπᾶται ῥᾳδίως, θνήσκει δ’ εὐθὺς ὁ κύων ὥσπερ ἀντιδοθεὶς τοῦ μέλλοντος τὴν βοτάνην ἀναιρήσεσθαι· φόβος γὰρ οὐδεὶς τοῖς μετὰ ταῦτα λαμβάνουσιν. ἔστι δὲ μετὰ τοσούτων κινδύνων διὰ μίαν ἰσχὺν περισπούδαστος· τὰ γὰρ καλούμενα δαιμόνια, ταῦτα δὲ πονηρῶν ἐστιν ἀνθρώπων πνεύματα τοῖς ζῶσιν εἰσδυόμενα καὶ κτείνοντα τοὺς βοηθείας μὴ τυγχάνοντας, αὕτη ταχέως ἐξελαύνει, κἂν προσενεχθῇ μόνον τοῖς νοσοῦσι. ῥέουσι δὲ καὶ θερμῶν ὑδάτων πηγαὶ κατὰ τὸν τόπον πολὺ τὴν γεῦσιν ἀλλήλων διαφέρουσαι· πικραὶ μὲν γὰρ αὐτῶν τινές εἰσιν, αἱ δὲ γλυκύτητος οὐδὲν ἀπολείπουσαι. πολλαὶ δὲ καὶ ψυχρῶν ὑδάτων ἀναδόσεις οὐ μόνον ἐν τῷ χθαμαλωτέρῳ τὰς πηγὰς παραλλήλους ἔχουσαι, ἀλλ’ ὡς ἂν καὶ μᾶλλόν τις θαυμάσειε, σπήλαιον γάρ τι πλησίον ὁρᾶται κοιλότητι μὲν οὐ βαθύ, τῇ πέτρᾳ δὲ προυχούσῃ σκεπόμενον· ταύτης ἄνωθεν ὡσανεὶ μαστοὶ δύο ἀνέχουσιν ἀλλήλων ὀλίγῳ διεστῶτες, καὶ ψυχροτάτην μὲν ἅτερος πηγήν, ἅτερος δὲ θερμοτάτην ἐκδίδωσιν, αἳ μισγόμεναι ποιοῦσι λουτρὸν ἥδιστον παιώνιόν τε νοσημάτων, πολλῷ δὲ μάλιστα νεύρων ἄκεσιν. ἔχει δὲ ὁ τόπος καὶ θείου καὶ στυπτηρίας μέταλλα.", "st": "7.6.3"}, {"sp": "N", "t": "Βάσσος δὲ περισκεψάμενος τὸ χωρίον ἔγνω ποιεῖσθαι τὴν πρόσοδον χωννὺς τὴν φάραγγα τὴν πρὸς ταῖς ἀνατολαῖς καὶ τῶν ἔργων εἴχετο, σπουδὴν ποιούμενος ᾗ τάχος ἐξᾶραι τὸ χῶμα καὶ δι’ αὐτοῦ ῥᾳδίαν ποιῆσαι τὴν πολιορκίαν. οἱ δ’ ἔνδον ἀπειλημμένοι τῶν Ἰουδαίων αὐτοὶ καθ’ ἑαυτοὺς ἀπὸ τῶν ξένων διακριθέντες ἐκείνους μὲν ἠνάγκασαν, ὄχλον ἄλλως εἶναι νομίζοντες, ἐν τῇ κάτω πόλει παραμένειν καὶ τοὺς κινδύνους προεκδέχεσθαι, τὸ δ’ ἄνω φρούριον αὐτοὶ καταλαβόντες εἶχον καὶ διὰ τὴν ἰσχὺν τῆς ὀχυρότητος καὶ προνοίᾳ τῆς σωτηρίας αὐτῶν· τεύξεσθαι γὰρ ἀφέσεως ὑπελάμβανον, εἰ τὸ χωρίον Ῥωμαίοις ἐγχειρίσειαν. πείρᾳ δὲ πρότερον ἐβούλοντο τὰς ὑπὲρ τοῦ διαφεύξεσθαι τὴν πολιορκίαν ἐλπίδας ἐλέγξαι. διὰ τοῦτο καὶ προθύμως ἐποιοῦντο τὰς ἐξόδους ἀνὰ πᾶσαν ἡμέραν, καὶ τοῖς χοῦσι συμπλεκόμενοι πολλοὶ μὲν ἔθνησκον, πολλοὺς δὲ τῶν Ῥωμαίων ἀνῄρουν. ἀεὶ δὲ τὸ κρατεῖν ὁ καιρὸς ἐβράβευεν ἑκατέροις τὸ πλέον, τοῖς μὲν Ἰουδαίοις, εἰ πρὸς ἀφυλακτοτέρους προσπέσοιεν, τοῖς δὲ ἐπὶ τῶν χωμάτων προϊδομένοις, εἰ τὴν ἐκδρομὴν αὐτῶν δέχοιντο πεφραγμένως. ἀλλ’ οὐκ ἐν τούτοις ἔμελλεν γενήσεσθαι τὸ πέρας τῆς πολιορκίας, ἔργον δέ τι πραχθὲν ἐκ συντυχίας παράλογον τῆς παραδόσεως τοῦ φρουρίου τὴν ἀνάγκην ἐπέστησε τοῖς Ἰουδαίοις. ἦν ἐν τοῖς πολιορκουμένοις νεανίας τολμῆσαί τε θρασὺς καὶ κατὰ χεῖρα δραστήριος, Ἐλεάζαρος ὄνομα· γεγόνει δὲ οὗτος ἐν ταῖς ἐκδρομαῖς ἐπιφανὴς τοὺς πολλοὺς ἐξιέναι καὶ κωλύειν τὴν χῶσιν παρακαλῶν καὶ κατὰ τὰς μάχας πολλὰ καὶ δεινὰ τοὺς Ῥωμαίους διατιθείς, τοῖς δὲ σὺν αὐτῷ τολμῶσιν ἐπεκτρέχειν ῥᾳδίαν μὲν τὴν προσβολὴν τιθέμενος, ἀκίνδυνον δὲ παρέχων τὴν ἀναχώρησιν τῷ τελευταῖος ἀπιέναι. καὶ δή ποτε τῆς μάχης διακριθείσης καὶ γεγονυίας ἀμφοτέρων ἀναχωρήσεως αὐτὸς ἅτε δὴ περιφρονῶν καὶ νομίζων οὐκ ἂν ἔτι τῶν πολεμίων οὐδένα τότε μάχης ἄρξειν, μείνας τῶν πυλῶν ἔξω τοῖς ἐπὶ τοῦ τείχους διελάλει καὶ πᾶς πρὸς ἐκείνοις τὴν διάνοιαν ἦν. ὁρᾷ δὲ τὸν καιρὸν τοῦ Ῥωμαϊκοῦ τις στρατοπέδου Ῥοῦφος, γένος Αἰγύπτιος, καὶ μηδενὸς ἂν προσδοκήσαντος ἐξαίφνης ἐπιδραμὼν σὺν αὐτοῖς ἀράμενος αὐτὸν τοῖς ὅπλοις, ἕως κατεῖχε τοὺς ἀπὸ τῶν τειχῶν ἰδόντας ἔκπληξις, φθάνει τὸν ἄνδρα μεταθεὶς πρὸς τὸ Ῥωμαίων στρατόπεδον. τοῦ δὲ στρατηγοῦ κελεύσαντος γυμνὸν διαλαβεῖν αὐτὸν καὶ καταστήσαντας εἰς τὸ φανερώτατον τοῖς ἐκ τῆς πόλεως ἀποβλέπουσι μάστιξιν αἰκίζεσθαι, σφόδρα τοὺς Ἰουδαίους τὸ περὶ τὸν νεανίαν πάθος συνέχεεν, ἀθρόα τε ἡ πόλις ἀνῴμωξε, καὶ θρῆνος ἦν μείζων ἢ καθ’ ἑνὸς ἀνδρὸς συμφοράν. τοῦτο συνιδὼν ὁ Βάσσος κατὰ τῶν πολεμίων ἀρχὴν ἐποιήσατο στρατηγήματος, καὶ βουληθεὶς αὐτῶν ἐπιτεῖναι τὸ περιαλγές, ἵνα βιασθῶσιν ἀντὶ τῆς σωτηρίας τἀνδρὸς ποιήσασθαι τοῦ φρουρίου παράδοσιν, τῆς ἐλπίδος οὐ διήμαρτεν. ὁ μὲν γὰρ προσέταξε καταπηγνύναι σταυρὸν ὡς αὐτίκα κρεμῶν τὸν Ἐλεάζαρον, τοῖς δὲ ἀπὸ τοῦ φρουρίου τοῦτο θεασαμένοις ὀδύνη τε πλείων προσέπεσε, καὶ διωλύγιον ἀνῴμωζον οὐκ ἀνασχετὸν εἶναι τὸ πάθος βοῶντες. ἐνταῦθα δὴ τοίνυν Ἐλεάζαρος ἱκέτευεν αὐτοὺς μήτε αὐτὸν περιιδεῖν ὑπομείναντα θανάτων τὸν οἴκτιστον καὶ σφίσιν αὐτοῖς τὴν σωτηρίαν παρασχεῖν τῇ Ῥωμαίων εἴξαντας ἰσχύι καὶ τύχῃ μετὰ πάντας ἤδη κεχειρωμένους. οἱ δὲ καὶ πρὸς τοὺς ἐκείνου λόγους κατακλώμενοι καὶ πολλῶν ἔνδον ὑπὲρ αὐτοῦ δεομένων, ἦν γὰρ ἐκ μεγάλης καὶ σφόδρα πολυανθρώπου συγγενείας, παρὰ τὴν αὐτῶν φύσιν εἰς οἶκτον ἐνέδωκαν· καί τινας ἐξαποστείλαντες κατὰ τάχος διελέγοντο ποιεῖσθαι τὴν παράδοσιν τοῦ φρουρίου ἀξιοῦντες, ἵν’ ἀδεεῖς ἀπαλλάττωνται κομισάμενοι τὸν Ἐλεάζαρον. δεξαμένων δὲ τῶν Ῥωμαίων καὶ τοῦ στρατηγοῦ ταῦτα, τὸ πλῆθος τῶν ἐν τῇ κάτω πόλει τὴν γεγενημένην ἰδίᾳ τοῖς Ἰουδαίοις πυθόμενοι σύμβασιν αὐτοὶ κατὰ νύκτα λαθόντες ἔγνωσαν ἀποδρᾶναι. τὰς πύλας δὲ αὐτῶν ἀνοιξάντων παρὰ τῶν τὴν ὁμολογίαν πεποιημένων πρὸς τὸν Βάσσον ἧκεν μήνυσις, εἴτ’ οὖν τῆς σωτηρίας αὐτοῖς φθονησάντων εἴτε [καὶ] διὰ δέος, μὴ τὴν αἰτίαν αὐτοὶ λάβωσι τῆς ἐκείνων ἀποδράσεως. οἱ μὲν οὖν ἀνδρειότατοι τῶν ἐξιόντων ἔφθασαν διεκπαίσασθαι καὶ διαφυγεῖν, τῶν δ’ ἔνδον καταλειφθέντων ἄνδρες μὲν ἀνῃρέθησαν ἐπὶ τοῖς χιλίοις ἑπτακόσιοι, γύναια δὲ καὶ παῖδες ἠνδραποδίσθησαν. τὰς δὲ πρὸς τοὺς παραδόντας τὸ φρούριον ὁμολογίας οἰόμενος δεῖν ὁ Βάσσος διαφυλάττειν αὐτούς τε ἀφίησιν καὶ τὸν Ἐλεάζαρον ἀπέδωκε.", "st": "7.6.4"}, {"sp": "N", "t": "Ταῦτα δὲ διοικησάμενος ἠπείγετο τὴν στρατιὰν ἄγων ἐπὶ τὸν προσαγορευόμενον Ἰάρδην δρυμόν· πολλοὶ γὰρ εἰς αὐτὸν ἠγγέλθησαν ἠθροῖσθαι τῶν κατὰ τὰς πολιορκίας πρότερον ἔκ τε Ἱεροσολύμων καὶ Μαχαιροῦντος ἀποδράντων. ἐλθὼν οὖν ἐπὶ τὸν τόπον καὶ γνοὺς τὴν ἀγγελίαν οὐκ ἐψευσμένην πρῶτον μὲν τοῖς ἱππεῦσιν ἅπαν κυκλοῦται τὸ χωρίον, ὅπως τοῖς διεκπαίεσθαι τολμῶσιν τῶν Ἰουδαίων ἄπορος ἡ φυγὴ γίνηται διὰ τοὺς ἱππέας· τοὺς δὲ πεζοὺς ἐκέλευσεν δενδροτομεῖν τὴν ὕλην, εἰς ἣν καταπεφεύγεσαν. καθίστανται δὲ διὰ τοῦτο πρὸς ἀνάγκην οἱ Ἰουδαῖοι τοῦ δρᾶν τι γενναῖον ὡς ἐκ παραβόλου ἀγωνίσασθαι τάχα ἂν καὶ διαφυγόντες, ἀθρόοι δὲ καὶ μετὰ βοῆς ᾄξαντες ἐνέπιπτον τοῖς κεκυκλωμένοις. οἱ δ’ αὐτοὺς ἐδέχοντο καρτερῶς, καὶ πολλῇ τῶν μὲν ἀπονοίᾳ τῶν δὲ φιλονεικίᾳ χρωμένων χρόνος μὲν οὐκ ὀλίγος διὰ τοῦτο τῇ μάχῃ προύβη, τέλος δ’ αὐτῆς οὐχ ὅμοιον ἀπέβη τοῖς ἀγωνισαμένοις. Ῥωμαίων μὲν γὰρ δώδεκα τοὺς πάντας συνέβη πεσεῖν ὀλίγους τε τρωθῆναι, Ἰουδαίων δὲ ἐκ τῆς μάχης ταύτης οὐδεὶς διέφυγεν, ἀλλ’ ὄντες οὐκ ἐλάττους τρισχιλίων πάντες ἀπέθανον, καὶ ὁ στρατηγὸς αὐτῶν Ἰούδας ὁ τοῦ Ἀρεῖ παῖς, περὶ οὗ πρότερον εἰρήκαμεν ὅτι τάξεως ἡγούμενός τινος ἐν τῇ πολιορκίᾳ τῶν Ἱεροσολύμων κατά τινας διαδὺς τῶν ὑπονόμων ἔλαθεν ἀποδράς.", "st": "7.6.5"}, {"sp": "N", "t": "Περὶ δὲ τὸν αὐτὸν καιρὸν ἐπέστειλε Καῖσαρ Βάσσῳ καὶ Λαβερίῳ Μαξίμῳ, οὗτος δὲ ἦν ἐπίτροπος, κελεύων πᾶσαν γῆν ἀποδόσθαι τῶν Ἰουδαίων. οὐ γὰρ κατῴκισεν ἐκεῖ πόλιν ἰδίαν αὑτῷ τὴν χώραν φυλάττων, ὀκτακοσίοις δὲ μόνοις ἀπὸ τῆς στρατιᾶς διαφειμένοις χωρίον ἔδωκεν εἰς κατοίκησιν, ὃ καλεῖται μὲν Ἀμμαοῦς, ἀπέχει δὲ τῶν Ἱεροσολύμων σταδίους τριάκοντα. φόρον δὲ τοῖς ὁπουδηποτοῦν οὖσιν Ἰουδαίοις ἐπέβαλεν δύο δραχμὰς ἕκαστον κελεύσας ἀνὰ πᾶν ἔτος εἰς τὸ Καπετώλιον φέρειν, ὥσπερ πρότερον εἰς τὸν ἐν Ἱεροσολύμοις νεὼν συνετέλουν. καὶ τὰ μὲν Ἰουδαίων τότε τοιαύτην εἶχε κατάστασιν.", "st": "7.6.6"}, {"sp": "N", "t": "Ἤδη δὲ ἔτος τέταρτον Οὐεσπασιανοῦ διέποντος τὴν ἡγεμονίαν συνέβη τὸν βασιλέα τῆς Κομμαγηνῆς Ἀντίοχον μεγάλαις συμφοραῖς πανοικεσίᾳ περιπεσεῖν ἀπὸ τοιαύτης αἰτίας· Καισέννιος Παῖτος, ὁ τῆς Συρίας ἡγεμὼν τότε καθεστηκώς, εἴτ’ οὖν ἀληθεύων εἴτε καὶ διὰ τὴν πρὸς Ἀντίοχον ἔχθραν, οὐ σφόδρα γὰρ τὸ σαφὲς ἠλέγχθη, γράμματα πρὸς Καίσαρα διεπέμψατο, λέγων τὸν Ἀντίοχον μετὰ τοῦ παιδὸς Ἐπιφανοῦς διεγνωκέναι Ῥωμαίων ἀφίστασθαι συνθήκας πρὸς τὸν βασιλέα τῶν Πάρθων πεποιημένον· δεῖν οὖν προκαταλαβεῖν αὐτούς, μὴ φθάσαντες τῶν πραγμάτων [ἄρξασθαι] πᾶσαν τὴν Ῥωμαίων ἀρχὴν πολέμῳ συνταράξωσιν. ἔμελλε Καῖσαρ τοιούτου μηνύματος αὐτῷ προσπεσόντος μὴ περιορᾶν· καὶ γὰρ ἡ γειτνίασις τῶν βασιλέων ἐποίει τὸ πρᾶγμα μείζονος ἄξιον προνοίας· τὰ γὰρ Σαμόσατα τῆς Κομμαγηνῆς μεγίστη πόλις κεῖται παρὰ τὸν Εὐφράτην, ὥστ’ εἶναι τοῖς Πάρθοις, εἴ τι τοιοῦτον διενενόηντο, ῥᾴστην μὲν τὴν διάβασιν βεβαίαν δὲ τὴν ὑποδοχήν. πιστευθεὶς οὖν Παῖτος καὶ λαβὼν ἐξουσίαν πράττειν ἃ δοκεῖ συμφέρειν οὐκ ἐμέλλησεν, ἐξαίφνης δὲ τῶν περὶ τὸν Ἀντίοχον οὐδὲν προσδοκώντων εἰς τὴν Κομμαγηνὴν ἐνέβαλεν, τῶν μὲν ταγμάτων ἄγων τὸ ἕκτον καὶ πρὸς τούτῳ λόχους καί τινας ἴλας ἱππέων· συνεμάχουν δὲ καὶ βασιλεῖς αὐτῷ τῆς μὲν Χαλκιδικῆς λεγομένης Ἀριστόβουλος, τῆς Ἐμέσης δὲ καλουμένης Σόαιμος. ἦν δ’ αὐτοῖς τὰ περὶ τὴν εἰσβολὴν ἀνανταγώνιστα· τῶν γὰρ κατὰ τὴν χώραν οὐδεὶς ἤθελε χεῖρας ἀνταίρειν. Ἀντίοχος δὲ τῆς ἀγγελίας ἀδοκήτως προσπεσούσης πολέμου μὲν οὐδὲ ἐπίνοιαν πρὸς Ῥωμαίους ἔσπασεν, ἔγνω δὲ πᾶσαν τὴν βασιλείαν ὡς εἶχεν ἐπὶ σχήματος καταλιπὼν μετὰ γυναικὸς καὶ τέκνων ὑπεξελθεῖν, οὕτως ἂν οἰόμενος καθαρὸν Ῥωμαίοις αὑτὸν ἀποδεῖξαι τῆς ἐπενηνεγμένης αἰτίας. καὶ προελθὼν ἀπὸ τῆς πόλεως ἑκατὸν σταδίους πρὸς τοῖς εἴκοσιν εἰς τὸ πεδίον ἐν αὐτῷ καταυλίζεται.", "st": "7.7.1"}, {"sp": "N", "t": "Παῖτος δὲ ἐπὶ μὲν τὰ Σαμόσατα τοὺς καταληψομένους ἀποστέλλει καὶ δι’ ἐκείνων εἶχε τὴν πόλιν, αὐτὸς δὲ μετὰ τῆς ἄλλης δυνάμεως ἐπ’ Ἀντίοχον ἐποιεῖτο τὴν ὁρμήν. οὐ μὴν ὁ βασιλεὺς οὐδ’ ὑπὸ τῆς ἀνάγκης προήχθη πρᾶξαί τι πρὸς Ῥωμαίους πολεμικόν, ἀλλὰ τὴν αὐτοῦ τύχην ὀδυρόμενος ὅ τι δέοι παθεῖν ὑπέμενε· νέοις δὲ καὶ πολέμων ἐμπείροις καὶ ῥώμῃ σωμάτων διαφέρουσιν οὐ ῥᾴδιον ἦν τοῖς παισὶν αὐτοῦ τὴν συμφορὰν ἀμαχεὶ καρτερεῖν· τρέπονται οὖν πρὸς ἀλκὴν Ἐπιφανής τε καὶ Καλλίνικος. σφοδρᾶς δὲ τῆς μάχης καὶ παρ’ ὅλην τὴν ἡμέραν γενομένης αὐτοὶ τὴν ἀνδρείαν διαπρεπῆ παρέσχον καὶ μηδὲν ἐλαττωθείσῃ τῇ σφετέρᾳ δυνάμει [ἑσπέρᾳ] διελύθησαν. Ἀντιόχῳ δ’ οὐδ’ ἐπὶ τῇ μάχῃ τοῦτον κεχωρηκυίᾳ τὸν τρόπον μένειν ἀνεκτὸν ἐδόκει, λαβὼν δὲ τὴν γυναῖκα καὶ τὰς θυγατέρας μετ’ ἐκείνων ἐποιεῖτο τὴν φυγὴν εἰς Κιλικίαν, καὶ τοῦτο πράξας τὰ φρονήματα τῶν οἰκείων στρατιωτῶν κατέκλασεν· ὡς γὰρ κατεγνωσμένης ὑπ’ αὐτοῦ τῆς βασιλείας ἀπέστησαν καὶ πρὸς τοὺς Ῥωμαίους μετεβάλοντο, καὶ πάντων πρόδηλος ἦν ἀπόγνωσις. πρὶν οὖν τελέως ἐρημωθῆναι τῶν συμμάχων τοῖς περὶ τὸν Ἐπιφανῆ σώζειν αὑτοὺς ἐκ τῶν πολεμίων ἦν ἀναγκαῖον, καὶ γίνονται δέκα σύμπαντες ἱππεῖς οἱ μετ’ αὐτῶν τὸν Εὐφράτην διαβαλόντες, ἔνθεν ἤδη μετ’ ἀδείας πρὸς τὸν βασιλέα τῶν Πάρθων Βολογέσην κομισθέντες οὐχ ὡς φυγάδες ὑπερηφανήθησαν, ἀλλ’ ὡς ἔτι τὴν παλαιὰν ἔχοντες εὐδαιμονίαν πάσης τιμῆς ἠξιώθησαν.", "st": "7.7.2"}, {"sp": "N", "t": "Ἀντιόχῳ δ’ εἰς Ταρσὸν ἀφιγμένῳ τῆς Κιλικίας ἑκατοντάρχην Παῖτος ἐπιπέμψας δεδεμένον αὐτὸν εἰς Ῥώμην ἀπέστειλεν. Οὐεσπασιανὸς δ’ οὕτως οὐχ ὑπέμεινεν πρὸς αὐτὸν ἀναχθῆναι τὸν βασιλέα, τῆς παλαιᾶς ἀξιῶν φιλίας μᾶλλον αἰδῶ λαβεῖν ἢ διὰ τὴν τοῦ πολέμου πρόφασιν ἀπαραίτητον ὀργὴν διαφυλάττειν. κελεύει δὴ καθ’ ὁδὸν ἔτ’ ὄντος αὐτοῦ τῶν δεσμῶν ἀφαιρεθῆναι καὶ παρέντα τὴν εἰς τὴν Ῥώμην ἄφιξιν τὸ νῦν ἐν Λακεδαίμονι διάγειν, δίδωσί τε μεγάλας αὐτῷ προσόδους χρημάτων, ὅπως μὴ μόνον ἄφθονον ἀλλὰ καὶ βασιλικὴν ἔχοι τὴν δίαιταν. ταῦτα τοῖς περὶ τὸν Ἐπιφανῆ πυθομένοις, πρότερον σφόδρα περὶ τοῦ πατρὸς δεδιόσιν ἀνείθησαν αἱ ψυχαὶ μεγάλης καὶ δυσδιαθέτου φροντίδος. ἐλπὶς δὲ καὶ αὐτοῖς τῶν παρὰ Καίσαρος διαλλαγῶν ἐγένετο Βολογέσου περὶ αὐτῶν ἐπιστείλαντος· οὐδὲ γὰρ εὐδαιμονοῦντες ὑπέμενον ἔξω τῆς Ῥωμαίων ζῆν ἡγεμονίας. δόντος δὲ Καίσαρος ἡμέρως αὐτοῖς τὴν ἄδειαν εἰς Ῥώμην παρεγένοντο, τοῦ τε πατρὸς ὡς αὐτοὺς ἐκ τῆς Λακεδαίμονος εὐθὺς ἐλθόντος πάσης ἀξιούμενοι τιμῆς κατέμενον ἐνταῦθα.", "st": "7.7.3"}, {"sp": "N", "t": "Τὸ δὲ τῶν Ἀλανῶν ἔθνος ὅτι μέν εἰσι Σκύθαι περὶ τὸν Τάναϊν καὶ τὴν Μαιῶτιν λίμνην κατοικοῦντες, πρότερόν που δεδηλώκαμεν, κατὰ τούτους δὲ τοὺς χρόνους διανοηθέντες εἰς τὴν Μηδίαν καὶ προσωτέρω ταύτης ἔτι καθ’ ἁρπαγὴν ἐμβαλεῖν τῷ βασιλεῖ τῶν Ὑρκανῶν διαλέγονται· τῆς παρόδου γὰρ οὗτος δεσπότης ἐστίν, ἣν ὁ βασιλεὺς Ἀλέξανδρος πύλαις σιδηραῖς κλειστὴν ἐποίησε. κἀκείνου τὴν εἴσοδον αὐτοῖς παρασχόντος ἀθρόοι καὶ μηδὲν προϋποπτεύσασι τοῖς Μήδοις ἐπιπεσόντες χώραν πολυάνθρωπον καὶ παντοίων ἀνάμεστον βοσκημάτων διήρπαζον μηδενὸς αὐτοῖς τολμῶντος ἀνθίστασθαι. καὶ γὰρ ὁ βασιλεύων τῆς χώρας Πάκορος ὑπὸ δέους εἰς τὰς δυσχωρίας ἀναφεύγων τῶν μὲν ἄλλων ἁπάντων παρακεχωρήκει, μόλις δὲ παρ’ αὐτῶν ἐρρύσατο τήν τε γυναῖκα καὶ τὰς παλλακὰς αἰχμαλώτους γενομένας ἑκατὸν δοὺς τάλαντα. μετὰ πολλῆς οὖν ῥᾳστώνης ἀμαχεὶ ποιούμενοι τὰς ἁρπαγὰς μέχρι τῆς Ἀρμενίας προῆλθον πάντα λεηλατοῦντες. Τιριδάτης δ’ αὐτῆς ἐβασίλευεν, ὃς ὑπαντιάσας αὐτοῖς καὶ ποιησάμενος μάχην παρὰ μικρὸν ἦλθεν ἐπ’ αὐτῆς ζωὸς ἁλῶναι τῆς παρατάξεως· βρόχον γὰρ αὐτῷ περιβαλών τις ἔμελλεν ἐπισπάσειν, εἰ μὴ τῷ ξίφει θᾶττον ἐκεῖνος τὸν τόνον κόψας ἔφθη διαφυγεῖν. οἱ δὲ καὶ διὰ τὴν μάχην ἔτι μᾶλλον ἀγριωθέντες τὴν μὲν χώραν ἐλυμήναντο, πολὺ δὲ πλῆθος ἀνθρώπων καὶ τῆς ἄλλης λείας ἄγοντες ἐξ ἀμφοῖν τῶν βασιλειῶν πάλιν εἰς τὴν οἰκείαν ἀνεκομίσθησαν.", "st": "7.7.4"}, {"sp": "N", "t": "Ἐπὶ δὲ τῆς Ἰουδαίας Βάσσου τελευτήσαντος Φλαύιος Σίλβας διαδέχεται τὴν ἡγεμονίαν, καὶ τὴν μὲν ἄλλην ὁρῶν ἅπασαν τῷ πολέμῳ κεχειρωμένην, ἓν δὲ μόνον ἔτι φρούριον ἀφεστηκός, ἐστράτευσεν ἐπὶ τοῦτο πᾶσαν τὴν ἐν τοῖς τόποις δύναμιν συναγαγών· καλεῖται δὲ τὸ φρούριον Μασάδα. προειστήκει δὲ τῶν κατειληφότων αὐτὸ σικαρίων δυνατὸς ἀνὴρ Ἐλεάζαρος, ἀπόγονος Ἰούδα τοῦ πείσαντος Ἰουδαίους οὐκ ὀλίγους, ὡς πρότερον δεδηλώκαμεν, μὴ ποιεῖσθαι τὰς ἀπογραφάς, ὅτε Κυρίνιος τιμητὴς εἰς τὴν Ἰουδαίαν ἐπέμφθη. τότε γὰρ οἱ σικάριοι συνέστησαν ἐπὶ τοὺς ὑπακούειν Ῥωμαίων θέλοντας καὶ πάντα τρόπον ὡς πολεμίοις προσεφέροντο, τὰς μὲν κτήσεις ἁρπάζοντες καὶ περιελαύνοντες, ταῖς δ’ οἰκήκεσιν αὐτῶν πῦρ ἐνιέντες· οὐδὲν γὰρ ἀλλοφύλων αὐτοὺς ἔφασκον διαφέρειν οὕτως ἀγεννῶς τὴν περιμάχητον Ἰουδαίοις ἐλευθερίαν προεμένους καὶ δουλείαν αἱρεῖσθαι τὴν ὑπὸ Ῥωμαίοις ἀνωμολογηκότας. ἦν δ’ ἄρα τοῦτο πρόφασις εἰς παρακάλυμμα τῆς ὠμότητος καὶ τῆς πλεονεξίας ὑπ’ αὐτῶν λεγόμενον· σαφὲς δὲ διὰ τῶν ἔργων ἐποίησαν. οἱ μὲν γὰρ αὐτοῖς τῆς ἀποστάσεως ἐκοινώνησαν καὶ τοῦ πρὸς Ῥωμαίους συνήραντο πολέμου καὶ παρ’ ἐκείνων δὲ τολμήματα χείρω πρὸς αὐτοὺς ἐγένετο, κἀπὶ τῷ ψεύδεσθαι πάλιν τὴν πρόφασιν ἐξελεγχόμενοι μᾶλλον ἐκάκουν τοὺς τὴν πονηρίαν αὐτῶν διὰ τῆς δικαιολογίας ὀνειδίζοντας. ἐγένετο γάρ πως ὁ χρόνος ἐκεῖνος παντοδαπῆς ἐν τοῖς Ἰουδαίοις πονηρίας πολύφορος, ὡς μηδὲν κακίας ἔργον ἄπρακτον καταλιπεῖν, μηδ’ εἴ τι ἐπίνοια διαπλάττειν ἐθελήσειεν, ἔχειν ἄν τι καινότερον ἐξευρεῖν. οὕτως ἰδίᾳ τε καὶ κοινῇ πάντες ἐνόσησαν, καὶ προσυπερβάλλειν ἀλλήλους ἔν τε ταῖς πρὸς θεὸν ἀσεβείαις καὶ ταῖς εἰς τοὺς πλησίον ἀδικίαις ἐφιλονείκησαν, οἱ μὲν δυνατοὶ τὰ πλήθη κακοῦντες, οἱ πολλοὶ δὲ τοὺς δυνατοὺς ἀπολλύναι σπεύδοντες· ἦν γὰρ ἐκείνοις μὲν ἐπιθυμία τοῦ τυραννεῖν, τοῖς δὲ τοῦ βιάζεσθαι καὶ τὰ τῶν εὐπόρων διαρπάζειν. πρῶτον οὖν οἱ σικάριοι τῆς παρανομίας καὶ τῆς πρὸς τοὺς συγγενεῖς ἤρξαντο ὠμότητος, μήτε λόγον ἄρρητον εἰς ὕβριν μήτ’ ἔργον ἀπείρατον εἰς ὄλεθρον τῶν ἐπιβουλευθέντων παραλιπόντες. ἀλλὰ καὶ τούτους Ἰωάννης ἀπέδειξεν αὐτοῦ μετριωτέρους· οὐ γὰρ μόνον ἀνῄρει πάντας ὅσοι τὰ δίκαια καὶ συμφέροντα συνεβούλευον, καθάπερ ἐχθίστοις μάλιστα δὴ τῶν πολιτῶν τοῖς τοιούτοις προσφερόμενος, ἀλλὰ καὶ κοινῇ τὴν πατρίδα μυρίων ἐνέπλησε κακῶν, οἷα πράξειν ἔμελλεν ἄνθρωπος ἤδη καὶ τὸν θεὸν ἀσεβεῖν τετολμηκώς· τράπεζάν τε γὰρ ἄθεσμον παρετίθετο καὶ τὴν νενομισμένην καὶ πάτριον ἐξεδιῄτησεν ἁγνείαν, ἵν’ ᾖ μηκέτι θαυμαστόν, εἰ τὴν πρὸς ἀνθρώπους ἡμερότητα καὶ κοινωνίαν οὐκ ἐτήρησεν ὁ τῆς πρὸς θεὸν εὐσεβείας οὕτω καταμανείς. πάλιν τοίνυν ὁ Γιώρα Σίμων τί κακὸν οὐκ ἔδρασεν; ἢ ποίας ὕβρεως ἐλευθέρων ἀπέσχοντο σωμάτων οἳ τοῦτον ἀνέδειξαν τύραννον; ποία δὲ αὐτοὺς φιλία, ποία δὲ συγγένεια πρὸς τοὺς ἐφ’ ἑκάστης ἡμέρας φόνους οὐχὶ θρασυτέρους ἐποίησε; τὸ μὲν γὰρ τοὺς ἀλλοτρίους κακῶς ποιεῖν ἀγεννοῦς ἔργον πονηρίας [εἶναι] ὑπελάμβανον, λαμπρὰν δὲ φέρειν ἐπίδειξιν ἡγοῦντο τὴν ἐν τοῖς οἰκειοτάτοις ὠμότητα. παρημιλλήσατο δὲ καὶ τὴν τούτων ἀπόνοιαν ἡ τῶν Ἰδουμαίων μανία· ἐκεῖνοι γὰρ οἱ μιαρώτατοι τοὺς ἀρχιερέας κατασφάξαντες, ὅπως μηδὲ μέρος τι τῆς πρὸς τὸν θεὸν εὐσεβείας διαφυλάττηται, πᾶν ὅσον ἦν λείψανον ἔτι πολιτικοῦ σχήματος ἐξέκοψαν, καὶ τὴν τελεωτάτην εἰσήγαγον διὰ πάντων ἀνομίαν, ἐν ᾗ τὸ τῶν ζηλωτῶν κληθέντων γένος ἤκμασεν, οἳ τὴν προσηγορίαν τοῖς ἔργοις ἐπηλήθευσαν· πᾶν γὰρ κακίας ἔργον ἐξεμιμήσαντο, μηδ’ εἴ τι πρότερον προϋπάρχον ἡ μνήμη παραδέδωκεν αὐτοὶ παραλιπόντες ἀζήλωτον. καίτοι τὴν προσηγορίαν αὑτοῖς ἀπὸ τῶν ἐπ’ ἀγαθῷ ζηλουμένων ἐπέθεσαν, ἢ κατειρωνευόμενοι τῶν ἀδικουμένων διὰ τὴν αὐτῶν θηριώδη φύσιν ἢ τὰ μέγιστα τῶν κακῶν ἀγαθὰ νομίζοντες. τοιγαροῦν προσῆκον ἕκαστοι τὸ τέλος εὕροντο τοῦ θεοῦ τὴν ἀξίαν ἐπὶ πᾶσιν αὐτοῖς τιμωρίαν βραβεύσαντος· ὅσας γὰρ ἀνθρώπου δύναται φύσις κολάσεις ὑπομεῖναι, πᾶσαι κατέσκηψαν εἰς αὐτοὺς μέχρι καὶ τῆς ἐσχάτης τοῦ βίου τελευτῆς, ἣν ὑπέμειναν ἐν πολυτρόποις αἰκίαις ἀποθανόντες. οὐ μὴν ἀλλὰ φαίη τις ἂν αὐτοὺς ἐλάττω παθεῖν ὧν ἔδρασαν· τὸ γὰρ δικαίως ἐπ’ αὐτῶν οὐ προσῆν. τοὺς δὲ ταῖς ἐκείνων ὠμότησι περιπεσόντας οὐ τοῦ παρόντος ἂν εἴη καιροῦ κατὰ τὴν ἀξίαν ὀδύρεσθαι· πάλιν οὖν ἐπάνειμι πρὸς τὸ καταλειπόμενον μέρος τῆς διηγήσεως.", "st": "7.8.1"}, {"sp": "N", "t": "Ἐπὶ γὰρ τὸν Ἐλεάζαρον καὶ τοὺς κατέχοντας σὺν αὐτῷ τὴν Μασάδαν σικαρίους ὁ τῶν Ῥωμαίων στρατηγὸς ἧκε τὰς δυνάμεις ἄγων, καὶ τῆς μὲν χώρας ἁπάσης εὐθὺς ἐκράτει φρουρὰς ἐν τοῖς ἐπικαιροτάτοις αὐτῆς μέρεσιν ἐγκαταστήσας, τεῖχος δὲ περιέβαλε κύκλῳ περὶ πᾶν τὸ φρούριον, ὅπως μηδενὶ τῶν πολιορκουμένων ᾖ ῥᾴδιον διαφυγεῖν, καὶ διανέμει τοὺς φυλάξοντας. αὐτὸς δὲ καταστρατοπεδεύει τόπον ὡς μὲν πρὸς τὴν πολιορκίαν ἐπιτηδειότατον ἐκλαβών, καθ’ ὃν αἱ τοῦ φρουρίου πέτραι τῷ πλησίον ὄρει συνήγγιζον, ἄλλως δὲ πρὸς ἀφθονίαν τῶν ἐπιτηδείων δύσκολον· οὐ γὰρ ἡ τροφὴ μόνον πόρρωθεν ἐκομίζετο καὶ σὺν μεγάλῃ ταλαιπωρίᾳ τῶν ἐπὶ τοῦτο τεταγμένων Ἰουδαίων, ἀλλὰ καὶ τὸ ποτὸν ἦν ἀγώγιμον [εἰς τὸ στρατόπεδον] τοῦ τόπου μηδεμίαν ἐγγὺς πηγὴν ἀναδιδόντος. ταῦτ’ οὖν προοικονομησάμενος ὁ Σίλβας ἐπὶ τὴν πολιορκίαν ἐτράπετο πολλῆς ἐπιτεχνήσεως καὶ ταλαιπωρίας δεομένην διὰ τὴν ὀχυρότητα τοῦ φρουρίου τοιοῦδε τὴν φύσιν ὑπάρχοντος·", "st": "7.8.2"}, {"sp": "N", "t": "Πέτραν οὐκ ὀλίγην τῇ περιόδῳ καὶ μῆκος ὑψηλὴν πανταχόθεν περιερρώγασι βαθεῖαι φάραγγες κάτωθεν ἐξ ἀοράτου τέρματος κρημνώδεις καὶ πάσῃ βάσει ζῴων ἀπρόσιτοι, πλὴν ὅσον κατὰ δύο τόπους τῆς πέτρας εἰς ἄνοδον οὐκ εὐμαρῆ παρεικούσης. ἔστι δὲ τῶν ὁδῶν ἡ μὲν ἀπὸ τῆς Ἀσφαλτίτιδος λίμνης πρὸς ἥλιον ἀνίσχοντα, καὶ πάλιν ἀπὸ τῆς δύσεως ᾗ ῥᾷον πορευθῆναι. καλοῦσι δὲ τὴν ἑτέραν ὄφιν, τῇ στενότητι προσεικάσαντες καὶ τοῖς συνεχέσιν ἑλιγμοῖς· κλᾶται γὰρ περὶ τὰς τῶν κρημνῶν ἐξοχὰς καὶ πολλάκις εἰς αὑτὴν ἀνατρέχουσα καὶ κατὰ μικρὸν αὖθις ἐκμηκυνομένη μόλις ψαύει τοῦ πρόσω. δεῖ δὲ παραλλὰξ τὸν δι’ αὐτῆς βαδίζοντα τὸν ἕτερον τῶν ποδῶν ἐρείδεσθαι. ἔστι δὲ πρόδηλος ὄλεθρος· ἑκατέρωθεν γὰρ βάθος κρημνῶν ὑποκέχηνε τῇ φοβερότητι πᾶσαν εὐτολμίαν ἐκπλῆξαι δυνάμενον. διὰ τοιαύτης οὖν ἐλθόντι σταδίους τριάκοντα κορυφὴ τὸ λοιπόν ἐστιν οὐκ εἰς ὀξὺ τέρμα συνηγμένη, ἀλλ’ ὥστ’ εἶναι κατ’ ἄκρας ἐπίπεδον. ἐπὶ ταύτῃ πρῶτον μὲν ὁ ἀρχιερεὺς ᾠκοδομήσατο φρούριον Ἰωνάθης καὶ προσηγόρευσε Μασάδαν, ὕστερον δ’ Ἡρώδῃ τῷ βασιλεῖ διὰ πολλῆς ἐγένετο σπουδῆς ἡ τοῦ χωρίου κατασκευή. τεῖχός τε γὰρ ἤγειρε περὶ πάντα τὸν κύκλον τῆς κορυφῆς ἑπτὰ σταδίων ὄντα λευκοῦ μὲν λίθου πεποιημένον, ὕψος δὲ δώδεκα καὶ πλάτος ὀκτὼ πήχεις ἔχον, τριάκοντα δὲ αὐτῷ καὶ ἑπτὰ πύργοι πεντηκονταπήχεις ἀνειστήκεσαν, ἐξ ὧν ἦν εἰς οἰκήματα διελθεῖν περὶ πᾶν τὸ τεῖχος ἔνδον ᾠκοδομημένα. τὴν γὰρ κορυφὴν πίονα καὶ πεδίου παντὸς οὖσαν μαλακωτέραν ἀνῆκεν εἰς γεωργίαν ὁ βασιλεύς, ἵν’ εἴ ποτε τῆς ἔξωθεν τροφῆς ἀπορία γένοιτο, μηδὲ ταύτῃ κάμοιεν οἱ τὴν αὐτῶν σωτηρίαν τῷ φρουρίῳ πεπιστευκότες. καὶ βασίλειον δὲ κατεσκεύασεν ἐν αὐτῷ κατὰ τὴν ἀπὸ τῆς ἑσπέρας ἀνάβασιν, ὑποκάτω μὲν τῶν τῆς ἄκρας τειχῶν, πρὸς δὲ τὴν ἄρκτον ἐκκλίνον. τοῦ δὲ βασιλείου τὸ τεῖχος ἦν ὕψει μέγα καὶ καρτερόν, πύργους ἔχον ἑξηκονταπήχεις ἐγγωνίους τέτταρας. ἥ τε τῶν οἰκημάτων ἔνδον καὶ στοῶν καὶ βαλανείων κατασκευὴ παντοία καὶ πολυτελὴς ἦν, κιόνων μὲν ἁπανταχοῦ μονολίθων ὑφεστηκότων, τοίχων δὲ καὶ τῶν ἐν τοῖς οἰκήμασιν ἐδάφων λίθου στρώσει πεποικιλμένων. πρὸς ἕκαστον δὲ τῶν οἰκουμένων τόπων ἄνω τε καὶ περὶ τὸ βασίλειον καὶ πρὸ τοῦ τείχους πολλοὺς καὶ μεγάλους ἐτετμήκει λάκκους ἐν ταῖς πέτραις φυλακτῆρας ὑδάτων, μηχανώμενος εἶναι χορηγίαν ὅση τῷ ἐκ πηγῶν ἐστι χρωμένοις. ὀρυκτὴ δ’ ὁδὸς ἐκ τοῦ βασιλείου πρὸς ἄκραν τὴν κορυφὴν ἀνέφερε τοῖς ἔξωθεν ἀφανής. οὐ μὴν οὐδὲ ταῖς φανεραῖς ὁδοῖς ἦν οἷόν τε χρήσασθαι ῥᾳδίως πολεμίους· ἡ μὲν γὰρ ἑῴα διὰ τὴν φύσιν, ὡς προείπαμεν, ἐστὶν ἄβατος, τὴν δ’ ἀπὸ τῆς ἑσπέρας μεγάλῳ κατὰ τὸ στενότατον πύργῳ διετείχισεν ἀπέχοντι τῆς ἄκρας πήχεων οὐκ ἔλαττον διάστημα χιλίων, ὃν οὔτε παρελθεῖν δυνατὸν ἦν οὔτε ῥᾴδιον ἑλεῖν· δυσέξοδος δὲ καὶ τοῖς μετὰ ἀδείας βαδίζουσιν ἐπεποίητο. οὕτως μὲν οὖν πρὸς τὰς τῶν πολεμίων ἐφόδους φύσει τε καὶ χειροποιήτως τὸ φρούριον ὠχύρωτο.", "st": "7.8.3"}, {"sp": "N", "t": "Τῶν δ’ ἔνδον ἀποκειμένων παρασκευῶν ἔτι μᾶλλον ἄν τις ἐθαύμασε τὴν λαμπρότητα καὶ τὴν διαμονήν· σῖτός τε γὰρ ἀπέκειτο πολὺς καὶ πολὺν χρόνον ἀρκεῖν ἱκανώτατος οἶνός τε πολὺς ἦν καὶ ἔλαιον, ἔτι δὲ παντοῖος ὀσπρίων καρπὸς καὶ φοίνικες ἐσεσώρευντο. πάντα δὲ εὗρεν ὁ Ἐλεάζαρος τοῦ φρουρίου μετὰ τῶν σικαρίων ἐγκρατὴς δόλῳ γενόμενος ἀκμαῖα καὶ μηδὲν τῶν νεωστὶ κειμένων ἀποδέοντα· καίτοι σχεδὸν ἀπὸ τῆς παρασκευῆς εἰς τὴν ὑπὸ Ῥωμαίοις ἅλωσιν ἑκατὸν ἦν χρόνος ἐτῶν· ἀλλὰ καὶ Ῥωμαῖοι τοὺς περιλειφθέντας τῶν καρπῶν εὗρον ἀδιαφθόρους. αἴτιον δ’ οὐκ ἂν ἁμάρτοι τις ὑπολαμβάνων εἶναι τὸν ἀέρα τῆς διαμονῆς ὕψει τῷ περὶ τὴν ἄκραν πάσης ὄντα γεώδους καὶ θολερᾶς ἀμιγῆ κράσεως. εὑρέθη δὲ καὶ παντοίων πλῆθος ὅπλων ὑπὸ τοῦ βασιλέως ἀποτεθησαυρισμένων, ὡς ἀνδράσιν ἀρκεῖν μυρίοις, ἀργός τε σίδηρος καὶ χαλκὸς ἔτι δὲ καὶ μόλιβος, ἅτε δὴ τῆς παρασκευῆς ἐπὶ μεγάλαις αἰτίαις γενομένης· λέγεται γὰρ αὑτῷ τὸν Ἡρώδην τοῦτο τὸ φρούριον εἰς ὑποφυγὴν ἑτοιμάζειν διπλοῦν ὑφορώμενον κίνδυνον, τὸν μὲν παρὰ τοῦ πλήθους τῶν Ἰουδαίων, μὴ καταλύσαντες ἐκεῖνον τοὺς πρὸ αὐτοῦ βασιλέας ἐπὶ τὴν ἀρχὴν καταγάγωσι, τὸν μείζω δὲ καὶ χαλεπώτερον ἐκ τῆς βασιλευούσης Αἰγύπτου Κλεοπάτρας. αὕτη γὰρ τὴν αὑτῆς γνώμην οὐκ ἐπεῖχεν, ἀλλὰ πολλάκις Ἀντωνίῳ λόγους προσέφερε τὸν μὲν Ἡρώδην ἀνελεῖν ἀξιοῦσα, χαρίσασθαι δ’ αὐτῇ τὴν βασιλείαν τῶν Ἰουδαίων δεομένη. καὶ μᾶλλον ἄν τις ἐθαύμασεν, ὅτι μηδέπω τοῖς προστάγμασιν Ἀντώνιος ὑπακηκόει κακῶς ὑπὸ τοῦ πρὸς αὐτὴν ἔρωτος δεδουλωμένος, οὐχ ὅτι περὶ τοῦ μὴ χαρίσασθαι προσεδόκησεν. διὰ τοιούτους μὲν φόβους Ἡρώδης Μασάδαν κατεσκευασμένος ἔμελλεν Ῥωμαίοις ἀπολείψειν ἔργον τοῦ πρὸς Ἰουδαίους πολέμου τελευταῖον.", "st": "7.8.4"}, {"sp": "N", "t": "Ἐπεὶ γὰρ ἔξωθεν ἤδη περιτετειχίκει πάντα τὸν τόπον ὁ τῶν Ῥωμαίων, ὡς προείπαμεν, ἡγεμών, καὶ τοῦ μή τινα ἀποδρᾶναι πρόνοιαν ἐπεποίητο τὴν ἀκριβεστάτην, ἐνεχείρει τῇ πολιορκίᾳ μόνον εὑρὼν ἕνα τόπον ἐπιβολὴν χωμάτων δέξασθαι δυνάμενον. μετὰ γὰρ τὸν διατειχίζοντα πύργον τὴν ἀπὸ τῆς δύσεως ὁδὸν ἄγουσαν εἴς τε τὸ βασίλειον καὶ τὴν ἀκρώρειαν ἦν τις ἐξοχὴ πέτρας εὐμεγέθης τῷ πλάτει καὶ πολὺ προκύπτουσα, τοῦ δὲ ὕψους τῆς Μασάδας τριακοσίους πήχεις ὑποκάτω· Λευκὴν δ’ αὐτὴν ὠνόμαζον. ἐπὶ ταύτην οὖν ἀναβὰς καὶ κατασχὼν αὐτὴν ὁ Σίλβας ἐκέλευε τὸν στρατὸν χοῦν ἐπιφέρειν. τῶν δὲ προθύμως καὶ μετὰ πολλῆς χειρὸς ἐργαζομένων στερεὸν εἰς διακοσίους πήχεις ὑψώθη τὸ χῶμα. οὐ μὴν οὔτε βέβαιον οὔτε αὔταρκες ἐδόκει τοῦτο τὸ μέτρον εἶναι τοῖς μηχανήμασιν εἰς ἐπιβάθραν, ἀλλ’ ἐπ’ αὐτοῦ βῆμα λίθων μεγάλων συνηρμοσμένων ἐποιήθη πεντήκοντα πήχεων εὖρός τε καὶ ὕψος. ἦν δὲ τῶν ἄλλων τε μηχανημάτων ἡ κατασκευὴ παραπλησία τοῖς ὑπὸ μὲν Οὐεσπασιανοῦ πρότερον, μετὰ ταῦτα δ’ ὑπὸ Τίτου πρὸς τὰς πολιορκίας ἐπινοηθεῖσι, καὶ πύργος ἑξηκοντάπηχυς συνετελέσθη σιδήρῳ καταπεφραγμένος ἅπας, ἐξ οὗ πολλοῖς ὀξυβελέσι καὶ πετροβόλοις βάλλοντες οἱ Ῥωμαῖοι τοὺς ἀπὸ τοῦ τείχους μαχομένους ταχέως ἀνέστειλαν καὶ προκύπτειν ἐκώλυσαν. ἐν ταὐτῷ δὲ καὶ κριὸν ὁ Σίλβας μέγαν κατασκευασάμενος, συνεχεῖς κελεύσας ποιεῖσθαι τῷ τείχει τὰς ἐμβολὰς μόλις μὲν ἀλλ’ οὖν ἀναρρήξας τι μέρος κατήρειψε. φθάνουσι δ’ οἱ σικάριοι ταχέως ἔνδοθεν οἰκοδομησάμενοι τεῖχος ἕτερον, ὃ μηδὲ ὑπὸ τῶν μηχανημάτων ἔμελλεν ὅμοιόν τι πείσεσθαι· μαλακὸν γὰρ αὐτὸ καὶ τὴν σφοδρότητα τῆς ἐμβολῆς ὑπεκλύειν δυνάμενον τοιῷδε τρόπῳ κατεσκεύασαν. δοκοὺς μεγάλας ἐπὶ μῆκος προσεχεῖς ἀλλήλαις κατὰ τὴν τομὴν συνέθεσαν. δύο δὲ ἦσαν τούτων στίχοι παράλληλοι τοσοῦτον διεστῶτες ὅσον εἶναι πλάτος τείχους, καὶ μέσον ἀμφοῖν τὸν χοῦν ἐνεφόρουν. ὅπως δὲ μηδὲ ὑψουμένου τοῦ χώματος ἡ γῆ διαχέοιτο, πάλιν ἑτέραις δοκοῖς ἐπικαρσίαις τὰς κατὰ μῆκος κειμένας διέδεον. ἦν οὖν ἐκείνοις μὲν οἰκοδομίᾳ τὸ ἔργον παραπλήσιον, τῶν μηχανημάτων δ’ αἱ πληγαὶ φερόμεναι πρὸς εἶκον ἐξελύοντο καὶ τῷ σάλῳ συνιζάνον ἐποίουν αὐτὸ στεριφώτερον. τοῦτο συνιδὼν ὁ Σίλβας πυρὶ μᾶλλον αἱρήσειν ἐνόμιζεν τὸ τεῖχος, καὶ τοῖς στρατιώταις προσέταττε λαμπάδας αἰθομένας ἀθρόους ἐσακοντίζειν. τὸ δὲ οἷα δὴ ξύλων τὸ πλέον πεποιημένον ταχὺ τοῦ πυρὸς ἀντελάβετο καὶ τῇ χαυνότητι πυρωθὲν διὰ βάθους φλόγα πολλὴν ἐξεπύρσευσεν. ἀρχομένου μὲν οὖν ἔτι τοῦ πυρὸς βορρᾶς ἐμπνέων τοῖς Ῥωμαίοις φοβερὸς ἦν· ἄνωθεν γὰρ ἀποστρέφων ἐπ’ ἐκείνους ἤλαυνε τὴν φλόγα, καὶ σχεδὸν ἤδη τῶν μηχανημάτων ὡς συμφλεγησομένων ἀπέγνωσαν· ἔπειτα δ’ αἰφνίδιον νότος μεταβαλὼν καθάπερ ἐκ δαιμονίου προνοίας καὶ πολὺς ἐναντίον πνεύσας τῷ τείχει φέρων αὐτὴν προσέβαλε, καὶ πᾶν ἤδη διὰ βάθους ἐφλέγετο. Ῥωμαῖοι μὲν οὖν τῇ παρὰ τοῦ θεοῦ συμμαχίᾳ κεχρημένοι χαίροντες εἰς τὸ στρατόπεδον ἀπηλλάττοντο μεθ’ ἡμέραν ἐπιχειρεῖν τοῖς πολεμίοις διεγνωκότες καὶ τὰς φυλακὰς νύκτωρ ἐπιμελεστέρας ἐποιήσαντο, μή τινες αὐτῶν λάθωσιν ἀποδράντες.", "st": "7.8.5"}, {"sp": "N", "t": "Οὐ μὴν οὔτε αὐτὸς Ἐλεάζαρος ἐν νῷ δρασμὸν ἔλαβεν οὔτε ἄλλῳ τινὶ τοῦτο ποιεῖν ἔμελλεν ἐπιτρέψειν. ὁρῶν δὲ τὸ μὲν τεῖχος ὑπὸ τοῦ πυρὸς ἀναλούμενον, ἄλλον δὲ οὐδένα σωτηρίας τρόπον οὐδ’ ἀλκῆς ἐπινοῶν, ἃ δὲ ἔμελλον Ῥωμαῖοι δράσειν αὐτοὺς καὶ τέκνα καὶ γυναῖκας [αὐτῶν], εἰ κρατήσειαν, ὑπ’ ὀφθαλμοὺς αὑτῷ τιθέμενος, θάνατον κατὰ πάντων ἐβουλεύσατο. καὶ τοῦτο κρίνας ἐκ τῶν παρόντων ἄριστον, τοὺς ἀνδρωδεστάτους τῶν ἑταίρων συναγαγὼν τοιούτοις ἐπὶ τὴν πρᾶξιν λόγοις παρεκάλει· πάλαι διεγνωκότας ἡμᾶς, ἄνδρες ἀγαθοί, μήτε Ῥωμαίοις μήτ’ ἄλλῳ τινὶ δουλεύειν ἢ θεῷ, μόνος γὰρ οὗτος ἀληθής ἐστι καὶ δίκαιος ἀνθρώπων δεσπότης, ἥκει νῦν καιρὸς ἐπαληθεῦσαι κελεύων τὸ φρόνημα τοῖς ἔργοις. πρὸς ὃν αὑτοὺς μὴ καταισχύνωμεν πρότερον μηδὲ δουλείαν ἀκίνδυνον ὑπομείναντες, νῦν δὲ μετὰ δουλείας ἑλόμενοι τιμωρίας ἀνηκέστους, εἰ ζῶντες ὑπὸ Ῥωμαίοις ἐσόμεθα· πρῶτοί τε γὰρ πάντων ἀπέστημεν καὶ πολεμοῦμεν αὐτοῖς τελευταῖοι. νομίζω δὲ καὶ παρὰ θεοῦ ταύτην δεδόσθαι χάριν τοῦ δύνασθαι καλῶς καὶ ἐλευθέρως ἀποθανεῖν, ὅπερ ἄλλοις οὐκ ἐγένετο παρ’ ἐλπίδα κρατηθεῖσιν. ἡμῖν δὲ πρόδηλος μέν ἐστιν ἡ γενησομένη μεθ’ ἡμέραν ἅλωσις, ἐλευθέρα δὲ ἡ τοῦ γενναίου θανάτου μετὰ τῶν φιλτάτων αἵρεσις. οὔτε γὰρ τοῦτ’ ἀποκωλύειν οἱ πολέμιοι δύνανται πάντως εὐχόμενοι ζῶντας ἡμᾶς παραλαβεῖν, οὔθ’ ἡμεῖς ἐκείνους ἔτι νικᾶν μαχόμενοι. ἔδει μὲν γὰρ εὐθὺς ἴσως ἐξ ἀρχῆς, ὅτε τῆς ἐλευθερίας ἡμῖν ἀντιποιεῖσθαι θελήσασι πάντα καὶ παρ’ ἀλλήλων ἀπέβαινε χαλεπὰ καὶ παρὰ τῶν πολεμίων χείρω, τῆς τοῦ θεοῦ γνώμης στοχάζεσθαι καὶ γινώσκειν, ὅτι τὸ πάλαι φίλον αὐτῷ φῦλον Ἰουδαίων κατέγνωστο· μένων γὰρ εὐμενὴς ἢ μετρίως γοῦν ἀπηχθημένος, οὐκ ἂν τοσούτων μὲν ἀνθρώπων περιεῖδεν ὄλεθρον, προήκατο δὲ τὴν ἱερωτάτην αὐτοῦ πόλιν πυρὶ καὶ κατασκαφαῖς πολεμίων. ἡμεῖς δ’ ἄρα καὶ μόνοι τοῦ παντὸς Ἰουδαίων γένους ἠλπίσαμεν περιέσεσθαι τὴν ἐλευθερίαν φυλάξαντες, ὥσπερ ἀναμάρτητοι πρὸς τὸν θεὸν γενόμενοι καὶ μηδεμιᾶς μετασχόντες, οἳ καὶ τοὺς ἄλλους ἐδιδάξαμεν; τοιγαροῦν ὁρᾶτε, πῶς ἡμᾶς ἐλέγχει μάταια προσδοκήσαντας κρείττονα τῶν ἐλπίδων τὴν ἐν τοῖς δεινοῖς ἀνάγκην ἐπαγαγών· οὐδὲ γὰρ ἡ τοῦ φρουρίου φύσις ἀνάλωτος οὖσα πρὸς σωτηρίαν ὠφέληκεν, ἀλλὰ καὶ τροφῆς ἀφθονίαν καὶ πλῆθος ὅπλων καὶ τὴν ἄλλην ἔχοντες παρασκευὴν περιττεύουσαν ὑπ’ αὐτοῦ περιφανῶς τοῦ θεοῦ τὴν ἐλπίδα τῆς σωτηρίας ἀφῃρήμεθα. τὸ γὰρ πῦρ εἰς τοὺς πολεμίους φερόμενον οὐκ αὐτομάτως ἐπὶ τὸ κατασκευασθὲν τεῖχος ὑφ’ ἡμῶν ἀνέστρεψεν, ἀλλ’ ἔστι ταῦτα χόλος πολλῶν ἀδικημάτων, ἃ μανέντες εἰς τοὺς ὁμοφύλους ἐτολμήσαμεν. ὑπὲρ ὧν μὴ τοῖς ἐχθίστοις Ῥωμαίοις δίκας ἀλλὰ τῷ θεῷ δι’ ἡμῶν αὐτῶν ὑπόσχωμεν· αὗται δέ εἰσιν ἐκείνων μετριώτεραι· θνησκέτωσαν γὰρ γυναῖκες ἀνύβριστοι καὶ παῖδες δουλείας ἀπείρατοι, μετὰ δ’ αὐτοὺς ἡμεῖς εὐγενῆ χάριν ἀλλήλοις παράσχωμεν καλὸν ἐντάφιον τὴν ἐλευθερίαν φυλάξαντες. πρότερον δὲ καὶ τὰ χρήματα καὶ τὸ φρούριον πυρὶ διαφθείρωμεν· λυπηθήσονται γὰρ Ῥωμαῖοι, σαφῶς οἶδα, μήτε τῶν ἡμετέρων σωμάτων κρατήσαντες καὶ τοῦ κέρδους ἁμαρτόντες. τὰς τροφὰς μόνας ἐάσωμεν· αὗται γὰρ ἡμῖν τεθνηκόσι μαρτυρήσουσιν ὅτι μὴ κατ’ ἔνδειαν ἐκρατήθημεν, ἀλλ’ ὥσπερ ἐξ ἀρχῆς διέγνωμεν, θάνατον ἑλόμενοι πρὸ δουλείας.", "st": "7.8.6"}, {"sp": "N", "t": "Ταῦτα Ἐλεάζαρος ἔλεγεν. οὐ μὴν κατ’ αὐτὸ ταῖς γνώμαις προσέπιπτε τῶν παρόντων, ἀλλ’ οἱ μὲν ἔσπευδον ὑπακούειν καὶ μόνον οὐχ ἡδονῆς ἐνεπίμπλαντο καλὸν εἶναι τὸν θάνατον νομίζοντες, τοὺς δ’ αὐτῶν μαλακωτέρους γυναικῶν καὶ γενεᾶς οἶκτος εἰσῄει, πάντως δὲ καὶ τῆς ἑαυτῶν προδήλου τελευτῆς εἰς ἀλλήλους ἀποβλέποντες τοῖς δακρύοις τὸ μὴ βουλόμενον τῆς γνώμης ἐσήμαινον. τούτους ἰδὼν Ἐλεάζαρος ἀποδειλιῶντας καὶ πρὸς τὸ μέγεθος τοῦ βουλεύματος τὰς ψυχὰς ὑποκλωμένους ἔδεισε, μή ποτε καὶ τοὺς ἐρρωμένως τῶν λόγων ἀκούσαντας αὐτοὶ συνεκθηλύνωσι ποτνιώμενοι καὶ δακρύοντες. οὔκουν ἀνῆκε τὴν παρακέλευσιν, ἀλλ’ αὑτὸν ἐπεγείρας καὶ πολλοῦ λήματος πλήρης γενόμενος λαμπροτέροις ἐνεχείρει λόγοις περὶ ψυχῆς ἀθανασίας, μέγα τε σχετλιάσας καὶ τοῖς δακρύουσιν ἀτενὲς ἐμβλέψας ἦ πλεῖστον, εἶπεν, ἐψεύσθην νομίζων ἀνδράσιν ἀγαθοῖς τῶν ὑπὲρ τῆς ἐλευθερίας ἀγώνων συναρεῖσθαι, ζῆν καλῶς ἢ τεθνάναι διεγνωκόσιν. ὑμεῖς δὲ ἦτε τῶν τυχόντων οὐδὲν εἰς ἀρετὴν οὐδ’ εὐτολμίαν διαφέροντες, οἵ γε καὶ τὸν ἐπὶ μεγίστων ἀπαλλαγῇ κακῶν φοβεῖσθε θάνατον δέον ὑπὲρ τούτου μήτε μελλῆσαι μήτε σύμβουλον ἀναμεῖναι. πάλαι γὰρ εὐθὺς ἀπὸ τῆς πρώτης αἰσθήσεως παιδεύοντες ἡμᾶς οἱ πάτριοι καὶ θεῖοι λόγοι διετέλουν ἔργοις τε καὶ φρονήμασι τῶν ἡμετέρων προγόνων αὐτοὺς βεβαιούντων, ὅτι συμφορὰ τὸ ζῆν ἐστιν ἀνθρώποις, οὐχὶ θάνατος. οὗτος μὲν γὰρ ἐλευθερίαν διδοὺς ψυχαῖς εἰς τὸν οἰκεῖον καὶ καθαρὸν ἀφίησι τόπον ἀπαλλάσσεσθαι πάσης συμφορᾶς ἀπαθεῖς ἐσομένας, ἕως δέ εἰσιν ἐν σώματι θνητῷ δεδεμέναι καὶ τῶν τούτου κακῶν συναναπίμπλανται, τἀληθέστατον εἰπεῖν, τεθνήκασι· κοινωνία γὰρ θείῳ πρὸς θνητὸν ἀπρεπής ἐστι. μέγα μὲν οὖν δύναται ψυχὴ καὶ σώματι συνδεδεμένη· ποιεῖ γὰρ αὐτῆς ὄργανον αἰσθανόμενον ἀοράτως αὐτὸ κινοῦσα καὶ θνητῆς φύσεως περαιτέρω προάγουσα ταῖς πράξεσιν· οὐ μὴν ἀλλ’ ἐπειδὰν ἀπολυθεῖσα τοῦ καθέλκοντος αὐτὴν βάρους ἐπὶ γῆν καὶ προσκρεμαμένου χῶρον ἀπολάβῃ τὸν οἰκεῖον, τότε δὴ μακαρίας ἰσχύος καὶ πανταχόθεν ἀκωλύτου μετέχει δυνάμεως, ἀόρατος μένουσα τοῖς ἀνθρωπίνοις ὄμμασιν ὥσπερ αὐτὸς ὁ θεός· οὐδὲ γὰρ ἕως ἐστὶν ἐν σώματι θεωρεῖται· πρόσεισι γὰρ ἀφανῶς καὶ μὴ βλεπομένη πάλιν ἀπαλλάττεται, μίαν μὲν αὐτὴ φύσιν ἔχουσα τὴν ἄφθαρτον, αἰτία δὲ σώματι γινομένη μεταβολῆς. ὅτου γὰρ ἂν ψυχὴ προσψαύσῃ, τοῦτο ζῇ καὶ τέθηλεν, ὅτου δ’ ἂν ἀπαλλαγῇ, μαρανθὲν ἀποθνήσκει· τοσοῦτον αὐτῇ περίεστιν ἀθανασίας. ὕπνος δὲ τεκμήριον ὑμῖν ἔστω τῶν λόγων ἐναργέστατον, ἐν ᾧ ψυχαὶ τοῦ σώματος αὐτὰς μὴ περισπῶντος ἡδίστην μὲν ἔχουσιν ἀνάπαυσιν ἐφ’ αὑτῶν γενόμεναι, θεῷ δ’ ὁμιλοῦσαι κατὰ συγγένειαν πάντη μὲν ἐπιφοιτῶσι, πολλὰ δὲ τῶν ἐσομένων προθεσπίζουσι. τί δὴ δεῖ δεδιέναι θάνατον τὴν ἐν ὕπνῳ γινομένην ἀνάπαυσιν ἀγαπῶντας; πῶς δ’ οὐκ ἀνόητόν ἐστιν τὴν ἐν τῷ ζῆν ἐλευθερίαν διώκοντας τῆς ἀιδίου φθονεῖν αὑτοῖς; ἔδει μὲν οὖν ἡμᾶς οἴκοθεν πεπαιδευμένους ἄλλοις εἶναι παράδειγμα τῆς πρὸς θάνατον ἑτοιμότητος· οὐ μὴν ἀλλ’ εἰ καὶ τῆς παρὰ τῶν ἀλλοφύλων δεόμεθα πίστεως, βλέψωμεν εἰς Ἰνδοὺς τοὺς σοφίαν ἀσκεῖν ὑπισχνουμένους. ἐκεῖνοί τε γὰρ ὄντες ἄνδρες ἀγαθοὶ τὸν μὲν τοῦ ζῆν χρόνον ὥσπερ ἀναγκαίαν τινὰ τῇ φύσει λειτουργίαν ἀκουσίως ὑπομένουσι, σπεύδουσι δὲ τὰς ψυχὰς ἀπολῦσαι τῶν σωμάτων, καὶ μηδενὸς αὐτοὺς ἐπείγοντος κακοῦ μηδ’ ἐξελαύνοντος πόθῳ τῆς ἀθανάτου διαίτης προλέγουσι μὲν τοῖς ἄλλοις ὅτι μέλλουσιν ἀπιέναι, καὶ ἔστιν ὁ κωλύσων οὐδείς, ἀλλὰ πάντες αὐτοὺς εὐδαιμονίζοντες πρὸς τοὺς οἰκείους ἕκαστοι διδόασιν ἐπιστολάς· οὕτως βεβαίαν καὶ ἀληθεστάτην ταῖς ψυχαῖς τὴν μετ’ ἀλλήλων εἶναι δίαιταν πεπιστεύκασιν. οἱ δ’ ἐπειδὰν ἐπακούσωσι τῶν ἐντεταλμένων αὐτοῖς, πυρὶ τὸ σῶμα παραδόντες, ὅπως δὴ καὶ καθαρωτάτην ἀποκρίνωσι τοῦ σώματος τὴν ψυχήν, ὑμνούμενοι τελευτῶσιν· ῥᾷον γὰρ ἐκείνους εἰς τὸν θάνατον οἱ φίλτατοι προπέμπουσιν ἢ τῶν ἄλλων ἀνθρώπων ἕκαστοι τοὺς πολίτας εἰς μηκίστην ἀποδημίαν, καὶ σφᾶς μὲν αὐτοὺς δακρύουσιν, ἐκείνους δὲ μακαρίζουσιν ἤδη τὴν ἀθάνατον τάξιν ἀπολαμβάνοντας. ἆρ’ οὖν οὐκ αἰδούμεθα χεῖρον Ἰνδῶν φρονοῦντες καὶ διὰ τῆς αὑτῶν ἀτολμίας τοὺς πατρίους νόμους, οἳ πᾶσιν ἀνθρώποις εἰς ζῆλον ἥκουσιν, αἰσχρῶς ὑβρίζοντες; ἀλλ’ εἴ γε καὶ τοὺς ἐναντίους ἐξ ἀρχῆς λόγους ἐπαιδεύθημεν, ὡς ἄρα μέγιστον ἀγαθὸν ἀνθρώποις ἐστὶ τὸ ζῆν συμφορὰ δ’ ὁ θάνατος, ὁ γοῦν καιρὸς ἡμᾶς παρακαλεῖ φέρειν εὐκαρδίως αὐτὸν θεοῦ γνώμῃ καὶ κατ’ ἀνάγκας τελευτήσαντας· πάλαι γάρ, ὡς ἔοικε, κατὰ τοῦ κοινοῦ παντὸς Ἰουδαίων γένους ταύτην ἔθετο τὴν ψῆφον ὁ θεός, ὥσθ’ ἡμᾶς τοῦ ζῆν ἀπηλλάχθαι μὴ μέλλοντας αὐτῷ χρῆσθαι κατὰ τρόπον. μὴ γὰρ αὐτοῖς ὑμῖν ἀνάπτετε τὰς αἰτίας μηδὲ χαρίζεσθε τοῖς Ῥωμαίοις, ὅτι πάντας ἡμᾶς ὁ πρὸς αὐτοὺς πόλεμος διέφθειρεν· οὐ γὰρ ἐκείνων ἰσχύι ταῦτα συμβέβηκεν, ἀλλὰ κρείττων αἰτία γενομένη τὸ δοκεῖν ἐκείνοις νικᾶν παρέσχηκε. ποίοις γὰρ ὅπλοις Ῥωμαίων τεθνήκασιν οἱ Καισάρειαν Ἰουδαῖοι κατοικοῦντες; ἀλλ’ οὐδὲ μελλήσαντας αὐτοὺς ἐκείνων ἀφίστασθαι, μεταξὺ δὲ τὴν ἑβδόμην ἑορτάζοντας τὸ πλῆθος τῶν Καισαρέων ἐπιδραμὸν μηδὲ χεῖρας ἀνταίροντας ἅμα γυναιξὶ καὶ τέκνοις κατέσφαξαν, οὐδ’ αὐτοὺς Ῥωμαίους ἐντραπέντες, οἳ μόνους ἡμᾶς ἡγοῦντο πολεμίους τοὺς ἀφεστηκότας. ἀλλὰ φήσει τις, ὅτι Καισαρεῦσιν ἦν ἀεὶ διαφορὰ πρὸς τοὺς παρ’ αὐτοῖς, καὶ τοῦ καιροῦ λαβόμενοι τὸ παλαιὸν μῖσος ἀπεπλήρωσαν. τί οὖν τοὺς ἐν Σκυθοπόλει φῶμεν; ἡμῖν γὰρ ἐκεῖνοι διὰ τοὺς Ἕλληνας πολεμεῖν ἐτόλμησαν, ἀλλ’ οὐ μετὰ τῶν συγγενῶν ἡμῶν Ῥωμαίους ἀμύνεσθαι. πολὺ τοίνυν ὤνησεν αὐτοὺς ἡ πρὸς ἐκείνους εὔνοια καὶ πίστις· ὑπ’ αὐτῶν μέντοι πανοικεσίᾳ πικρῶς κατεφονεύθησαν ταύτην τῆς συμμαχίας ἀπολαβόντες ἀμοιβήν· ἃ γὰρ ἐκείνους ὑφ’ ἡμῶν ἐκώλυσαν ταῦθ’ ὑπέμειναν ὡς αὐτοὶ δρᾶσαι θελήσαντες. μακρὸν ἂν εἴη νῦν ἰδίᾳ περὶ ἑκάστων λέγειν· ἴστε γὰρ ὅτι τῶν ἐν Συρίᾳ πόλεων οὐκ ἔστιν ἥτις τοὺς παρ’ αὐτῇ κατοικοῦντας Ἰουδαίους οὐκ ἀνῄρηκεν, ἡμῖν πλέον ἢ Ῥωμαίοις ὄντας πολεμίους· ὅπου γε Δαμασκηνοὶ μηδὲ πρόφασιν εὔλογον πλάσαι δυνηθέντες φόνου μιαρωτάτου τὴν αὐτῶν πόλιν ἐνέπλησαν ὀκτακισχιλίους πρὸς τοῖς μυρίοις Ἰουδαίους ἅμα γυναιξὶ καὶ γενεαῖς ἀποσφάξαντες. τὸ δ’ ἐν Αἰγύπτῳ πλῆθος τῶν μετ’ αἰκίας ἀνῃρημένων ἕξ που μυριάδας ὑπερβάλλειν ἐπυνθανόμεθα. κἀκεῖνοι μὲν ἴσως ἐπ’ ἀλλοτρίας γῆς οὐδὲν ἀντίπαλον εὑράμενοι τοῖς πολεμίοις οὕτως ἀπέθανον, τοῖς δ’ ἐπὶ τῆς οἰκείας τὸν πρὸς Ῥωμαίους πόλεμον ἀραμένοις ἅπασι τε τῶν ἐλπίδα νίκης ἐχυρᾶς παρασχεῖν δυναμένων οὐχ ὑπῆρξε; καὶ γὰρ ὅπλα καὶ τείχη καὶ φρουρίων δυσάλωτοι κατασκευαὶ καὶ φρόνημα πρὸς τοὺς ὑπὲρ τῆς ἐλευθερίας κινδύνους ἄτρεπτον πάντας πρὸς τὴν ἀπόστασιν ἐπέρρωσεν. ἀλλὰ ταῦτα πρὸς βραχὺν χρόνον ἀρκέσαντα καὶ ταῖς ἐλπίσιν ἡμᾶς ἐπάραντα μειζόνων ἀρχὴ κακῶν ἐφάνη· πάντα γὰρ ἥλω, καὶ πάντα τοῖς πολεμίοις ὑπέπεσεν, ὥσπερ εἰς τὴν ἐκείνων εὐκλεεστέραν νίκην, οὐκ εἰς τὴν τῶν παρασκευασαμένων σωτηρίαν εὐτρεπισθέντα. καὶ τοὺς μὲν ἐν ταῖς μάχαις ἀποθνήσκοντας εὐδαιμονίζειν προσῆκον· ἀμυνόμενοι γὰρ καὶ τὴν ἐλευθερίαν οὐ προέμενοι τεθνήκασι· τὸ δὲ πλῆθος τῶν ὑπὸ Ῥωμαίοις γενομένων τίς οὐκ ἂν ἐλεήσειε; τίς οὐκ ἂν ἐπειχθείη πρὸ τοῦ ταὐτὰ παθεῖν ἐκείνοις ἀποθανεῖν; ὧν οἱ μὲν στρεβλούμενοι καὶ πυρὶ καὶ μάστιξιν αἰκιζόμενοι τεθνήκασιν, οἱ δ’ ἀπὸ θηρίων ἡμίβρωτοι πρὸς δευτέραν αὐτοῖς τροφὴν ζῶντες ἐφυλάχθησαν, γέλωτα καὶ παίγνιον τοῖς πολεμίοις παρασχόντες. ἐκείνων μὲν οὖν ἀθλιωτάτους ὑποληπτέον τοὺς ἔτι ζῶντας, οἳ πολλάκις εὐχόμενοι τὸν θάνατον λαβεῖν οὐκ ἔχουσιν. ποῦ δ’ ἡ μεγάλη πόλις, ἡ τοῦ παντὸς Ἰουδαίων γένους μητρόπολις, ἡ τοσούτοις μὲν ἐρυμνὴ τειχῶν περιβόλοις, τοσαῦτα δ’ αὑτῆς φρούρια καὶ μεγέθη πύργων προβεβλημένη, μόλις δὲ χωροῦσα τὰς εἰς τὸν πόλεμον παρασκευάς, τοσαύτας δὲ μυριάδας ἀνδρῶν ἔχουσα τῶν ὑπὲρ αὐτῆς μαχομένων; ποῦ γέγονεν ἡμῖν ἡ τὸν θεὸν ἔχειν οἰκιστὴν πεπιστευμένη; πρόρριζος ἐκ βάθρων ἀνήρπασται, καὶ μόνον αὐτῆς μνημεῖον ἀπολείπεται τὸ τῶν ἀνῃρημένων ἔτι τοῖς λειψάνοις ἐποικοῦν. πρεσβῦται δὲ δύστηνοι τῇ σποδῷ τοῦ τεμένους παρακάθηνται καὶ γυναῖκες ὀλίγαι πρὸς ὕβριν αἰσχίστην ὑπὸ τῶν πολεμίων τετηρημέναι. ταῦτα τίς ἐν νῷ βαλλόμενος ἡμῶν καρτερήσει τὸν ἥλιον ὁρᾶν, κἂν δύνηται ζῆν ἀκινδύνως; τίς οὕτω τῆς πατρίδος ἐχθρός, ἢ τίς οὕτως ἄνανδρος καὶ φιλόψυχος, ὡς μὴ καὶ περὶ τοῦ μέχρι νῦν ζῆσαι μετανοεῖν; ἀλλ’ εἴθε πάντες ἐτεθνήκειμεν πρὶν τὴν ἱερὰν ἐκείνην πόλιν χερσὶν ἰδεῖν κατασκαπτομένην πολεμίων, πρὶν τὸν ναὸν τὸν ἅγιον οὕτως ἀνοσίως ἐξορωρυγμένον.", "st": "7.8.7"}, {"sp": "N", "t": "ἐπεὶ δὲ ἡμᾶς οὐκ ἀγεννὴς ἐλπὶς ἐβουκόλησεν, ὡς τάχα που δυνήσεσθαι τοὺς πολεμίους ὑπὲρ αὐτῆς ἀμύνασθαι, φρούδη δὲ γέγονε νῦν καὶ μόνους ἡμᾶς ἐπὶ τῆς ἀνάγκης καταλέλοιπεν, σπεύσωμεν καλῶς ἀποθανεῖν, ἐλεήσωμεν ἡμᾶς αὐτοὺς καὶ τὰ τέκνα καὶ τὰς γυναῖκας, ἕως ἡμῖν ἔξεστιν παρ’ ἡμῶν αὐτῶν λαβεῖν τὸν ἔλεον. ἐπὶ μὲν γὰρ θάνατον ἐγεννήθημεν καὶ τοὺς ἐξ αὑτῶν ἐγεννήσαμεν, καὶ τοῦτον οὐδὲ τοῖς εὐδαιμονοῦσιν ἔστι διαφυγεῖν· ὕβρις δὲ καὶ δουλεία καὶ τὸ βλέπειν γυναῖκας εἰς αἰσχύνην ἀγομένας μετὰ τέκνων οὐκ ἔστιν ἀνθρώποις κακὸν ἐκ φύσεως ἀναγκαῖον, ἀλλὰ ταῦτα διὰ τὴν αὐτῶν δειλίαν ὑπομένουσιν οἱ παρὸν πρὸ αὐτῶν ἀποθανεῖν μὴ θελήσαντες. ἡμεῖς δὲ ἐπ’ ἀνδρείᾳ μέγα φρονοῦντες Ῥωμαίων ἀπέστημεν καὶ τὰ τελευταῖα νῦν ἐπὶ σωτηρίᾳ προκαλουμένων ἡμᾶς οὐχ ὑπηκούσαμεν. τίνι τοίνυν οὐκ ἔστιν ὁ θυμὸς αὐτῶν πρόδηλος, εἰ ζώντων ἡμῶν κρατήσουσιν; ἄθλιοι μὲν οἱ νέοι τῆς ῥώμης τῶν σωμάτων εἰς πολλὰς αἰκίας ἀρκέσοντες, ἄθλιοι δὲ οἱ παρηβηκότες φέρειν τῆς ἡλικίας τὰς συμφορὰς οὐ δυναμένης. ὄψεταί τις γυναῖκα πρὸς βίαν ἀγομένην, φωνῆς ἐπακούσεται τέκνου πατέρα βοῶντος χεῖρας δεδεμένος. ἀλλ’ ἕως εἰσὶν ἐλεύθεραι καὶ ξίφος ἔχουσιν, καλὴν ὑπουργίαν ὑπουργησάτωσαν· ἀδούλωτοι μὲν ὑπὸ τῶν πολεμίων ἀποθάνωμεν, ἐλεύθεροι δὲ μετὰ τέκνων καὶ γυναικῶν τοῦ ζῆν συνεξέλθωμεν. ταῦθ’ ἡμᾶς οἱ νόμοι κελεύουσι, ταῦθ’ ἡμᾶς γυναῖκες καὶ παῖδες ἱκετεύουσι· τούτων τὴν ἀνάγκην θεὸς ἀπέσταλκε, τούτων Ῥωμαῖοι τἀναντία θέλουσι, καὶ μή τις ἡμῶν πρὸ τῆς ἁλώσεως ἀποθάνῃ δεδοίκασι. σπεύσωμεν οὖν ἀντὶ τῆς ἐλπιζομένης αὐτοῖς καθ’ ἡμῶν ἀπολαύσεως ἔκπληξιν τοῦ θανάτου καὶ θαῦμα τῆς τόλμης καταλιπεῖν.", "st": "7.8.7"}, {"sp": "N", "t": "Ἔτι βουλόμενον αὐτὸν παρακαλεῖν πάντες ὑπετέμνοντο καὶ πρὸς τὴν πρᾶξιν ἠπείγοντο ἀνεπισχέτου τινὸς ὁρμῆς πεπληρωμένοι, καὶ δαιμονῶντες ἀπῄεσαν ἄλλος πρὸ ἄλλου φθάσαι γλιχόμενος καὶ ταύτην ἐπίδειξιν εἶναι τῆς ἀνδρείας καὶ τῆς εὐβουλίας νομίζοντες, τὸ μή τις ἐν ὑστάτοις γενόμενος ὀφθῆναι· τοσοῦτος αὐτοῖς γυναικῶν καὶ παιδίων καὶ τῆς αὑτῶν σφαγῆς ἔρως ἐνέπεσεν. καὶ μὴν οὐδ’ ὅπερ ἄν τις ᾠήθη τῇ πράξει προσιόντες ἠμβλύνθησαν, ἀλλ’ ἀτενῆ τὴν γνώμην διεφύλαξαν οἵαν ἔσχον τῶν λόγων ἀκροώμενοι, τοῦ μὲν οἰκείου καὶ φιλοστόργου πάθους ἅπασι παραμένοντος, τοῦ λογισμοῦ δὲ ὡς τὰ κράτιστα βεβουλευκότος τοῖς φιλτάτοις ἐπικρατοῦντος. ὁμοῦ γὰρ ἠσπάζοντο γυναῖκας περιπτυσσόμενοι καὶ τέκνα προσηγκαλίζοντο τοῖς ὑστάτοις φιλήμασιν ἐμφυόμενοι καὶ δακρύοντες, ὁμοῦ δὲ καθάπερ ἀλλοτρίαις χερσὶν ὑπουργούμενοι συνετέλουν τὸ βούλευμα, τὴν ἐπίνοιαν ὧν πείσονται κακῶν ὑπὸ τοῖς πολεμίοις γενόμενοι παραμύθιον τῆς ἐν τῷ κτείνειν ἀνάγκης ἔχοντες. καὶ πέρας οὐδεὶς τηλικούτου τολμήματος ἥττων εὑρέθη, πάντες δὲ διὰ τῶν οἰκειοτάτων διεξῆλθον, ἄθλιοι τῆς ἀνάγκης, οἷς αὐτοχειρὶ γυναῖκας τὰς αὑτῶν καὶ τέκνα κτεῖναι κακῶν ἔδοξεν εἶναι τὸ κουφότατον. οὔτε δὴ τοίνυν τὴν ἐπὶ τοῖς πεπραγμένοις ὀδύνην ἔτι φέροντες καὶ τοὺς ἀνῃρημένους νομίζοντες ἀδικεῖν εἰ καὶ βραχὺν αὐτοῖς ἔτι χρόνον ἐπιζήσουσι, ταχὺ μὲν τὴν κτῆσιν ἅπασαν εἰς ταὐτὸ σωρεύσαντες πῦρ εἰς αὐτὴν ἐνέβαλον, κλήρῳ δ’ ἐξ αὑτῶν ἑλόμενοι δέκα τοὺς ἁπάντων σφαγεῖς ἐσομένους, καὶ γυναικί τις αὑτὸν καὶ παισὶ κειμένοις παραστρώσας καὶ τὰς χεῖρας περιβαλών, παρεῖχον ἑτοίμους τὰς σφαγὰς τοῖς τὴν δύστηνον ὑπουργίαν ἐκτελοῦσιν. οἱ δ’ ἀτρέπτως πάντας φονεύσαντες τὸν αὐτὸν ἐπ’ ἀλλήλοις τοῦ κλήρου νόμον ὥρισαν, ἵν’ ὁ λαχὼν τοὺς ἐννέα κτείνας ἑαυτὸν ἐπὶ πᾶσιν ἀνέλῃ· πάντες οὕτως αὑτοῖς ἐθάρρουν μήτ’ εἰς τὸ δρᾶν μήτ’ εἰς τὸ παθεῖν ἄλλος ἄλλου διαφέρειν. καὶ τέλος οἱ μὲν τὰς σφαγὰς ὑπέθεσαν, ὁ δ’ εἷς καὶ τελευταῖος τὸ πλῆθος τῶν κειμένων περιαθρήσας, μή πού τις ἔτ’ ἐν πολλῷ φόνῳ τῆς αὐτοῦ λείπεται χειρὸς δεόμενος, ὡς ἔγνω πάντας ἀνῃρημένους, πῦρ μὲν πολὺ τοῖς βασιλείοις ἐνίησιν, ἀθρόᾳ δὲ τῇ χειρὶ δι’ αὑτοῦ πᾶν ἐλάσας τὸ ξίφος πλησίον τῶν οἰκείων κατέπεσε. καὶ οἱ μὲν ἐτεθνήκεσαν ὑπειληφότες οὐδὲν ἔχον ψυχὴν ὑποχείριον ἐξ αὑτῶν Ῥωμαίοις καταλιπεῖν, ἔλαθεν δὲ γυνὴ πρεσβῦτις καὶ συγγενὴς ἑτέρα τις Ἐλεαζάρου, φρονήσει καὶ παιδείᾳ πλεῖστον γυναικῶν διαφέρουσα, καὶ πέντε παιδία τοῖς ὑπονόμοις, οἳ ποτὸν ἦγον ὕδωρ διὰ γῆς, ἐγκατακρυβῆναι τῶν ἄλλων πρὸς τῇ σφαγῇ τὰς διανοίας ἐχόντων, οἳ τὸν ἀριθμὸν ἦσαν ἑξήκοντα πρὸς τοῖς ἐνακοσίοις γυναικῶν ἅμα καὶ παίδων αὐτοῖς συναριθμουμένων. καὶ τὸ πάθος ἐπράχθη πεντεκαιδεκάτῃ Ξανθικοῦ μηνός.", "st": "7.9.1"}, {"sp": "N", "t": "Οἱ δὲ Ῥωμαῖοι μάχην ἔτι προσδοκῶντες, ὑπὸ τὴν ἕω διασκευασάμενοι καὶ τὰς ἀπὸ τῶν χωμάτων ἐφόδους ταῖς ἐπιβάθραις γεφυρώσαντες προσβολὴν ἐποιοῦντο. βλέποντες δ’ οὐδένα τῶν πολεμίων, ἀλλὰ δεινὴν πανταχόθεν ἐρημίαν καὶ πῦρ ἔνδον καὶ σιωπήν, ἀπόρως εἶχον τὸ γεγονὸς συμβαλεῖν, καὶ τέλος ὡς εἰς ἄφεσιν βολῆς ἠλάλαξαν, εἴ τινα τῶν ἔνδον προκαλέσαιντο. τῆς δὲ βοῆς αἴσθησις γίνεται τοῖς γυναίοις, κἀκ τῶν ὑπονόμων ἀναδῦσαι τὸ πραχθὲν ὡς εἶχε πρὸς τοὺς Ῥωμαίους ἐμήνυον, πάντα τῆς ἑτέρας ὡς ἐλέχθη τε καὶ τίνα τρόπον ἐπράχθη σαφῶς ἐκδιηγουμένης. οὐ μὴν ῥᾳδίως αὐτῇ προσεῖχον τῷ μεγέθει τοῦ τολμήματος ἀπιστοῦντες, ἐπεχείρουν τε τὸ πῦρ σβεννύναι καὶ ταχέως ὁδὸν δι’ αὐτοῦ τεμόντες τῶν βασιλείων ἐντὸς ἐγένοντο. καὶ τῷ πλήθει τῶν πεφονευμένων ἐπιτυχόντες οὐχ ὡς ἐπὶ πολεμίοις ἥσθησαν, τὴν δὲ γενναιότητα τοῦ βουλεύματος καὶ τὴν ἐν τοσούτοις ἄτρεπτον ἐπὶ τῶν ἔργων ἐθαύμασαν τοῦ θανάτου καταφρόνησιν.", "st": "7.9.2"}, {"sp": "N", "t": "Τοιαύτης δὲ τῆς ἁλώσεως γενομένης ἐπὶ μὲν τοῦ φρουρίου καταλείπει φυλακὴν ὁ στρατηγός, αὐτὸς δὲ μετὰ τῆς δυνάμεως ἀπῆλθεν εἰς Καισάρειαν. οὐδὲ γὰρ ὑπελείπετό τις τῶν κατὰ τὴν χώραν πολεμίων, ἀλλ’ ἤδη πᾶσα διὰ μακροῦ τοῦ πολέμου κατέστραπτο πολλοῖς καὶ τῶν ἀπωτάτω κατοικούντων αἴσθησιν καὶ κίνδυνον ταραχῆς παρασχόντος. ἔτι δὲ καὶ περὶ Ἀλεξάνδρειαν τὴν ἐν Αἰγύπτῳ μετὰ ταῦτα συνέβη πολλοὺς Ἰουδαίων ἀποθανεῖν· τοῖς γὰρ ἐκ τῆς στάσεως τῶν σικαρίων ἐκεῖ διαφυγεῖν δυνηθεῖσιν οὐκ ἀπέχρη τὸ σώζεσθαι, πάλιν δὲ καινοτέροις ἐνεχείρουν πράγμασι καὶ πολλοὺς τῶν ὑποδεξαμένων ἔπειθον τῆς ἐλευθερίας ἀντιποιεῖσθαι, καὶ Ῥωμαίους μὲν μηδὲν κρείττους αὑτῶν ὑπολαμβάνειν, θεὸν δὲ μόνον ἡγεῖσθαι δεσπότην. ἐπεὶ δὲ αὐτοῖς τῶν οὐκ ἀφανῶν τινες Ἰουδαίων ἀντέβαινον, τοὺς μὲν ἀπέσφαξαν, τοῖς δ’ ἄλλοις ἐνέκειντο πρὸς τὴν ἀπόστασιν παρακαλοῦντες. ὁρῶντες δ’ αὐτῶν τὴν ἀπόνοιαν οἱ πρωτεύοντες τῆς γερουσίας οὐκέτ’ ἀσφαλὲς αὐτοῖς ἐνόμιζον περιορᾶν, ἀλλὰ πάντας ἀθροίσαντες εἰς ἐκκλησίαν τοὺς Ἰουδαίους ἤλεγχον τὴν ἀπόνοιαν τῶν σικαρίων πάντων αἰτίους ἀποφαίνοντες ἐκείνους τῶν κακῶν· καὶ νῦν ἔφασαν αὐτούς, ἐπείπερ οὐδὲ πεφευγότες τῆς σωτηρίας ἐλπίδα βεβαίαν ἔχουσιν, γνωσθέντας γὰρ ὑπὸ Ῥωμαίων εὐθὺς ἀπολεῖσθαι, τῆς αὐτοῖς προσηκούσης συμφορᾶς ἀναπιμπλάναι τοὺς μηδενὸς τῶν ἁμαρτημάτων μετασχόντας. φυλάξασθαι τοίνυν τὸν ἐξ αὐτῶν ὄλεθρον τὸ πλῆθος παρεκάλουν καὶ περὶ αὑτῶν πρὸς Ῥωμαίους ἀπολογήσασθαι τῇ τούτων παραδόσει. συνιδόντες τοῦ κινδύνου τὸ μέγεθος ἐπείσθησαν τοῖς λεγομένοις, καὶ μετὰ πολλῆς ὁρμῆς ἐπὶ τοὺς σικαρίους ᾄξαντες συνήρπαζον αὐτούς. τῶν δ’ ἑξακόσιοι μὲν εὐθὺς ἑάλωσαν, ὅσοι δ’ εἰς τὴν Αἴγυπτον καὶ τὰς ἐκεῖ Θήβας διέφυγον, οὐκ εἰς μακρὰν συλληφθέντες ἐπανήχθησαν. ἐφ’ ὧν οὐκ ἔστιν ὃς οὐ τὴν καρτερίαν καὶ τὴν εἴτε ἀπόνοιαν εἴτε τῆς γνώμης ἰσχὺν χρὴ λέγειν οὐ κατεπλάγη· πάσης γὰρ ἐπ’ αὐτοὺς βασάνου καὶ λύμης τῶν σωμάτων ἐπινοηθείσης ἐφ’ ἓν τοῦτο μόνον, ὅπως αὐτῶν Καίσαρα δεσπότην ὁμολογήσωσιν, οὐδεὶς ἐνέδωκεν οὐδὲ ἐμέλλησεν εἰπεῖν, ἀλλὰ πάντες ὑπερτέραν τῆς ἀνάγκης τὴν αὐτῶν γνώμην διεφύλαξαν, ὥσπερ ἀναισθήτοις σώμασι χαιρούσῃ μόνον οὐχὶ τῇ ψυχῇ τὰς βασάνους καὶ τὸ πῦρ δεχόμενοι. μάλιστα δ’ ἡ τῶν παίδων ἡλικία τοὺς θεωμένους ἐξέπληξεν· οὐδὲ γὰρ ἐκείνων τις ἐξενικήθη Καίσαρα δεσπότην ἐξονομάσαι. τοσοῦτον ἄρα τῆς τῶν σωμάτων ἀσθενείας ἡ τῆς τόλμης ἰσχὺς ἐπεκράτει.", "st": "7.10.1"}, {"sp": "N", "t": "Λοῦπος τότε διῴκει τὴν Ἀλεξάνδρειαν καὶ περὶ τοῦ κινήματος τούτου Καίσαρι κατὰ τάχος ἐπέστειλεν. ὁ δὲ τῶν Ἰουδαίων τὴν ἀκατάπαυστον ὑφορώμενος νεωτεροποιίαν καὶ δείσας, μὴ πάλιν εἰς ἓν ἀθρόοι συλλεγῶσι καί τινας αὑτοῖς συνεπισπάσωνται, προσέταξε τῷ Λούππῳ τὸν ἐν τῇ Ὀνίου καλουμένῃ νεὼν καθελεῖν τῶν Ἰουδαίων. ὁ δ’ ἐστὶν ἐν Αἰγύπτῳ καὶ διὰ τοιαύτην αἰτίαν ᾠκίσθη τε καὶ τὴν ἐπίκλησιν ἔλαβεν· Ὀνίας Σίμωνος υἱός, εἷς τῶν ἐν Ἱεροσολύμοις ἀρχιερέων, φεύγων Ἀντίοχον τὸν Συρίας βασιλέα πολεμοῦντα τοῖς Ἰουδαίοις ἧκεν εἰς Ἀλεξάνδρειαν, καὶ δεξαμένου Πτολεμαίου φιλοφρόνως αὐτὸν διὰ τὴν πρὸς Ἀντίοχον ἀπέχθειαν ἔφη σύμμαχον αὐτῷ ποιήσειν τὸ τῶν Ἰουδαίων ἔθνος, εἰ πεισθείη τοῖς ὑπ’ αὐτοῦ λεγομένοις. ποιήσειν δὲ τὰ δυνατὰ τοῦ βασιλέως ὁμολογήσαντος ἠξίωσεν ἐπιτρέπειν αὐτῷ νεών τε που τῆς Αἰγύπτου κατασκευάσασθαι καὶ τοῖς πατρίοις ἔθεσι θεραπεύειν τὸν θεόν· οὕτως γὰρ Ἀντιόχῳ μὲν ἔτι μᾶλλον ἐκπολεμώσεσθαι τοὺς Ἰουδαίους τὸν ἐν Ἱεροσολύμοις νεὼν πεπορθηκότι, πρὸς αὐτὸν δ’ εὐνοϊκωτέρως ἕξειν καὶ πολλοὺς ἐπ’ ἀδείᾳ τῆς εὐσεβείας ἐπ’ αὐτὸν συλλεγήσεσθαι.", "st": "7.10.2"}, {"sp": "N", "t": "Πεισθεὶς Πτολεμαῖος τοῖς λεγομένοις δίδωσιν αὐτῷ χώραν ἑκατὸν ἐπὶ τοῖς ὀγδοήκοντα σταδίους ἀπέχουσαν Μέμφεως· νομὸς δ’ οὗτος Ἡλιοπολίτης καλεῖται. φρούριον ἔνθα κατασκευασάμενος Ὀνίας τὸν μὲν ναὸν οὐχ ὅμοιον ᾠκοδόμησε τῷ ἐν Ἱεροσολύμοις, ἀλλὰ πύργῳ παραπλήσιον λίθων μεγάλων εἰς ἑξήκοντα πήχεις ἀνεστηκότα· τοῦ βωμοῦ δὲ τὴν κατασκευὴν πρὸς τὸν οἰκεῖον ἐξεμιμήσατο καὶ τοῖς ἀναθήμασιν ὁμοίως ἐκόσμησεν χωρὶς τῆς περὶ τὴν λυχνίαν κατασκευῆς· οὐ γὰρ ἐποίησε λυχνίαν, αὐτὸν δὲ χαλκευσάμενος λύχνον χρυσοῦν ἐπιφαίνοντα σέλας χρυσῆς ἁλύσεως ἐξεκρέμασε. τὸ δὲ τέμενος πᾶν ὀπτῇ πλίνθῳ περιτετείχιστο πύλας ἔχον λιθίνας. ἀνῆκε δὲ καὶ χώραν πολλὴν ὁ βασιλεὺς εἰς χρημάτων πρόσοδον, ὅπως εἴη καὶ τοῖς ἱερεῦσιν ἀφθονία καὶ τῷ θεῷ πολλὰ τὰ πρὸς τὴν εὐσέβειαν. οὐ μὴν Ὀνίας ἐξ ὑγιοῦς γνώμης ταῦτα ἔπραττεν, ἀλλ’ ἦν αὐτῷ φιλονεικία πρὸς τοὺς ἐν τοῖς Ἱεροσολύμοις Ἰουδαίους ὀργὴν τῆς φυγῆς ἀπομνημονεύοντι, καὶ τοῦτο τὸ ἱερὸν ἐνόμιζε κατασκευάσας εἰς αὐτὸ περισπάσειν ἀπ’ ἐκείνων τὸ πλῆθος. ἐγεγόνει δέ τις καὶ παλαιὰ πρόρρησις ἔτεσί που πρόσθεν ἑξακοσίοις· Ἡσαΐας ὄνομα τῷ προαγορεύσαντι τοῦδε τοῦ ναοῦ τὴν ἐν Αἰγύπτῳ γενησομένην ὑπ’ ἀνδρὸς Ἰουδαίου κατασκευήν. τὸ μὲν οὖν ἱερὸν οὕτως ἐπεποίητο.", "st": "7.10.3"}, {"sp": "N", "t": "Λοῦππος δ’ ὁ τῆς Ἀλεξανδρείας ἡγεμὼν τὰ παρὰ Καίσαρος λαβὼν γράμματα καὶ παραγενόμενος εἰς τὸ ἱερὸν καί τινα τῶν ἀναθημάτων ἐκφορήσας τὸν ναὸν ἀπέκλεισε. Λούππου δὲ μετὰ βραχὺ τελευτήσαντος Παυλῖνος διαδεξάμενος τὴν ἡγεμονίαν οὔτε τῶν ἀναθημάτων οὐδὲν κατέλιπε, πολλὰ γὰρ διηπείλησε τοῖς ἱερεῦσιν εἰ μὴ πάντα προκομίσειαν, οὔτε προσιέναι τῷ τεμένει τοὺς θρησκεύειν βουλομένους ἐφῆκεν, ἀλλ’ ἀποκλείσας τὰς πύλας ἀπρόσιτον αὐτὸ παντελῶς ἐποίησεν, ὡς μηδ’ ἴχνος ἔτι τῆς εἰς τὸν θεὸν θεραπείας ἐν τῷ τόπῳ καταλιπεῖν. χρόνος ἦν εἰς τὴν ἀπόκλεισιν τοῦ ναοῦ γεγονὼς ἀπὸ τῆς κατασκευῆς ἔτη τρία καὶ τεσσαράκοντα καὶ τριακόσια.", "st": "7.10.4"}, {"sp": "N", "t": "Ἥψατο δὲ καὶ τῶν περὶ Κυρήνην πόλεων ἡ τῶν σικαρίων ἀπόνοια καθάπερ νόσος. διαπεσὼν γὰρ εἰς αὐτὴν Ἰωνάθης, πονηρότατος ἄνθρωπος καὶ τὴν τέχνην ὑφάντης, οὐκ ὀλίγους τῶν ἀπόρων ἀνέπεισε προσέχειν αὐτῷ καὶ προήγαγεν εἰς τὴν ἔρημον σημεῖα καὶ φάσματα δείξειν ὑπισχνούμενος. καὶ τοὺς μὲν ἄλλους ἐλάνθανε ταῦτα διαπραττόμενος καὶ φενακίζων, οἱ δὲ τοῖς ἀξιώμασι προύχοντες τῶν ἐπὶ τῆς Κυρήνης Ἰουδαίων τὴν ἔξοδον αὐτοῦ καὶ παρασκευὴν τῷ τῆς πενταπόλεως Λιβύης ἡγεμόνι Κατύλλῳ προσαγγέλλουσιν. ὁ δ’ ἱππέας τε καὶ πεζοὺς ἀποστείλας ῥᾳδίως ἐκράτησεν ἀνόπλων, καὶ τὸ μὲν πλέον ἐν χερσὶν ἀπώλετο, τινὲς δὲ καὶ ζωγρηθέντες ἀνήχθησαν πρὸς τὸν Κάτυλλον. ὁ δ’ ἡγεμὼν τοῦ βουλεύματος Ἰωνάθης τότε μὲν διέφυγε, πολλῆς δὲ καὶ λίαν ἐπιμελοῦς ἀνὰ πᾶσαν τὴν χώραν ζητήσεως γενομένης ἥλω, καὶ πρὸς τὸν ἡγεμόνα ἀναχθεὶς αὑτῷ μὲν ἐμηχανᾶτο τῆς τιμωρίας ἀπαλλαγήν, τῷ Κατύλλῳ δ’ ἔδωκεν ἀφορμὴν ἀδικημάτων. ὁ μὲν γὰρ τοὺς πλουσιωτάτους τῶν Ἰουδαίων ἔλεγε καταψευδόμενος διδασκάλους αὐτῷ τοῦ βουλεύματος γεγονέναι,", "st": "7.11.1"}, {"sp": "N", "t": "προθύμως δὲ τὰς διαβολὰς ἐκεῖνος ἐξεδέχετο καὶ τῷ πράγματι πολὺν ὄγκον περιετίθει μεγάλα προστραγῳδῶν, ἵνα δόξειε καὐτὸς Ἰουδαϊκόν τινα πόλεμον κατωρθωκέναι. τὸ δὲ δὴ τούτου χαλεπώτερον, πρὸς γὰρ τῷ πιστεύειν ῥᾳδίως ἔτι καὶ διδάσκαλος ἦν τῶν σικαρίων τῆς ψευδολογίας· κελεύσας γοῦν αὐτὸν ὀνομάσαι τινὰ τῶν Ἰουδαίων Ἀλέξανδρον, ᾧ πάλαι προσκεκρουκὼς φανερὸν ἐξενηνόχει τὸ μῖσος, τήν τε γυναῖκα τὴν ἐκείνου [Βερενίκην ταῖς αἰτίαις] συνεμπλέξας, τούτους μὲν πρῶτον ἀνεῖλεν, ἐπὶ δ’ αὐτοῖς ἅπαντας τοὺς εὐπορίᾳ χρημάτων διαφέροντας ὁμοῦ τι χιλίους ἐφόνευσεν ἄνδρας· καὶ ταῦτα πράττειν ἐνόμιζεν ἀσφαλῶς, ὅτι τὰς οὐσίας αὐτῶν εἰς τὰς τοῦ Καίσαρος προσόδους ἀνελάμβανεν.", "st": "7.11.2"}, {"sp": "N", "t": "Ὅπως δὲ μηδὲ ἀλλαχοῦ τινες τῶν Ἰουδαίων ἐλέγξωσιν αὐτοῦ τὴν ἀδικίαν, πορρωτέρω τὸ ψεῦδος ἐξέτεινε καὶ πείθει τὸν Ἰωνάθην καί τινας τῶν ἅμ’ ἐκείνῳ συνειλημμένων νεωτερισμοῦ κατηγορίαν ἐπιφέρειν τοῖς ἐν Ἀλεξανδρείᾳ τε καὶ Ῥώμῃ τῶν Ἰουδαίων δοκιμωτάτοις. τούτων εἷς τῶν ἐξ ἐπιβουλῆς αἰτιαθέντων ἦν Ἰώσηπος ὁ ταῦτα συγγραψάμενος. οὐ μὴν κατ’ ἐλπίδα τῷ Κατύλλῳ τὸ σκευώρημα προεχώρησεν· ἧκε μὲν γὰρ εἰς τὴν Ῥώμην τοὺς περὶ τὸν Ἰωνάθην ἄγων δεδεμένους καὶ πέρας ᾤετο τῆς ἐξετάσεως εἶναι τὴν ἐπ’ αὐτοῦ καὶ δι’ αὐτοῦ γενομένην ψευδολογίαν. Οὐεσπασιανὸς δὲ τὸ πρᾶγμα ὑποπτεύσας ἀναζητεῖ τὴν ἀλήθειαν καὶ γνοὺς ἄδικον τὴν αἰτίαν τοῖς ἀνδράσιν ἐπενηνεγμένην τοὺς μὲν ἀφίησι τῶν ἐγκλημάτων Τίτου σπουδάσαντος, δίκην δ’ ἐπέθηκεν Ἰωνάθῃ τὴν προσήκουσαν· ζῶν γὰρ κατεκαύθη πρότερον αἰκισθείς.", "st": "7.11.3"}, {"sp": "N", "t": "Κατύλλῳ δὲ τότε μὲν ὑπῆρξε διὰ τὴν πρᾳότητα τῶν αὐτοκρατόρων μηδὲν πλεῖον ὑπομεῖναι καταγνώσεως, οὐκ εἰς μακρὰν δὲ νόσῳ καταληφθεὶς πολυτρόπῳ καὶ δυσιάτῳ χαλεπῶς ἀπήλλαττεν, οὐ τὸ σῶμα μόνον κολαζόμενος, ἀλλ’ ἦν ἡ τῆς ψυχῆς αὐτῷ νόσος βαρυτέρα. δείμασι γὰρ ἐξεταράττετο καὶ συνεχῶς ἐβόα βλέπειν εἴδωλα τῶν ὑπ’ αὐτοῦ πεφονευμένων ἐφεστηκότα· καὶ κατέχειν αὑτὸν οὐ δυνάμενος ἐξήλλετο τῆς εὐνῆς ὡς βασάνων αὐτῷ καὶ πυρὸς προσφερομένων. τοῦ δὲ κακοῦ πολλὴν ἀεὶ τὴν ἐπίδοσιν λαμβάνοντος καὶ τῶν ἐντέρων αὐτῷ κατὰ διάβρωσιν ἐκπεσόντων, οὕτως ἀπέθανεν, οὐδενὸς ἧττον ἑτέρου τῆς προνοίας τοῦ θεοῦ τεκμήριον γενόμενος, ὅτι τοῖς πονηροῖς δίκην ἐπιτίθησιν.", "st": "7.11.4"}, {"sp": "N", "t": "Ἐνταῦθα τῆς ἱστορίας ἡμῖν τὸ πέρας ἐστίν, ἣν ἐπηγγειλάμεθα μετὰ πάσης ἀκριβείας παραδώσειν τοῖς βουλομένοις μαθεῖν, τίνα τρόπον οὗτος ὁ πόλεμος Ῥωμαίοις πρὸς Ἰουδαίους ἐπολεμήθη. καὶ πῶς μὲν ἡρμήνευται, τοῖς ἀναγνωσομένοις κρίνειν ἀπολελείφθω, περὶ τῆς ἀληθείας δὲ οὐκ ἂν ὀκνήσαιμι θαρρῶν λέγειν, ὅτι μόνης ταύτης παρὰ πᾶσαν τὴν ἀναγραφὴν ἐστοχασάμην.", "st": "7.11.5"}], []);})();
